insert into public.worlds (id, name, slug, description, theme, unlock_requirements) values
  ('little-steps', '{"en":"Little Steps","ru":"Маленькие шаги","uz":"Kichik qadamlar"}'::jsonb, 'little-steps', '{"en":"Flower meadows, rainbow bridges and friendly letters and numbers.","ru":"Цветочные луга, радужные мосты и дружелюбные буквы и цифры."}'::jsonb, '{"palette":{"from":"#7ED6A0","to":"#FFD76B","accent":"#FF967D","soft":"#E8F8EE"},"emoji":"🌼","guide":"foxy","mapPos":{"x":20,"y":70}}'::jsonb, '{"topics":[],"grade":null}'::jsonb),
  ('numberia', '{"en":"Numberia","ru":"Намбирия","uz":"Raqamlar oroli"}'::jsonb, 'numberia', '{"en":"Bridges of symbols, towers of geometry and rivers of digits.","ru":"Мосты из символов, башни геометрии и реки цифр."}'::jsonb, '{"palette":{"from":"#5799E8","to":"#8C6BE0","accent":"#FFD76B","soft":"#E6EEFC"},"emoji":"🔢","guide":"oli","mapPos":{"x":45,"y":42}}'::jsonb, '{"topics":["early.counting"],"grade":1}'::jsonb),
