  ('scientia', '{"en":"Scientia","ru":"Сциентия","uz":"Ilmiya"}'::jsonb, 'scientia', '{"en":"Explore nature, the body, energy and matter with Bruno.","ru":"Исследуй природу, тело, энергию и вещество вместе с Бруно."}'::jsonb, '{"palette":{"from":"#36C2B4","to":"#FF9F4A","accent":"#7ED67E","soft":"#E3F7F4"},"emoji":"🔬","guide":"bruno","mapPos":{"x":78,"y":28}}'::jsonb, '{"topics":["early.nature"],"grade":2}'::jsonb),
  ('lingua', '{"en":"Lingua","ru":"Лингва","uz":"Lingva"}'::jsonb, 'lingua', '{"en":"Cities of letters, floating words and international villages.","ru":"Города букв, плавающие слова и международные деревни."}'::jsonb, '{"palette":{"from":"#F59AC0","to":"#8FB8F5","accent":"#B8A5EF","soft":"#FCEAF3"},"emoji":"🌍","guide":"luna","mapPos":{"x":18,"y":30}}'::jsonb, '{"topics":["early.letters"],"grade":1}'::jsonb),
  ('techtown', '{"en":"TechTown","ru":"Техтаун","uz":"Texnoshahar"}'::jsonb, 'techtown', '{"en":"Build algorithms, program robots and learn digital safety.","ru":"Собирай алгоритмы, программируй роботов и изучай цифровую безопасность."}'::jsonb, '{"palette":{"from":"#3D5AFE","to":"#2EE6D6","accent":"#B388FF","soft":"#E5ECFF"},"emoji":"🤖","guide":"bruno","mapPos":{"x":48,"y":14}}'::jsonb, '{"topics":["early.patterns"],"grade":2}'::jsonb)
insert into public.topics (id, subject_id, grade_from, grade_to, title, description, prerequisites) values
  ('early.colors-shapes', 'early', -1, 0, '{"en":"Colours & Shapes","ru":"Цвета и формы"}'::jsonb, '{"en":"Name colours, recognise circles, squares and triangles, compare sizes.","ru":"Называем цвета, узнаём круг, квадрат и треугольник, сравниваем размеры."}'::jsonb, array[]::text[]),
  ('early.numbers', 'early', -1, 0, '{"en":"Numbers 0-10","ru":"Цифры 0-10"}'::jsonb, '{"en":"Recognise and name the digits from 0 to 10.","ru":"Узнаём и называем цифры от 0 до 10."}'::jsonb, array[]::text[]),
  ('early.counting', 'early', -1, 1, '{"en":"Counting Objects","ru":"Счёт предметов"}'::jsonb, '{"en":"Count objects up to 10 and match them to numbers.","ru":"Считаем предметы до 10 и сопоставляем с цифрами."}'::jsonb, array['early.numbers']::text[]),
  ('early.compare-quantities', 'early', -1, 1, '{"en":"More, Less, Equal","ru":"Больше, меньше, поровну"}'::jsonb, '{"en":"Compare groups of objects.","ru":"Сравниваем группы предметов."}'::jsonb, array['early.counting']::text[]),
  ('early.letters', 'early', -1, 0, '{"en":"Meet the Letters","ru":"Знакомство с буквами"}'::jsonb, '{"en":"Recognise letters, capital and small.","ru":"Узнаём буквы, заглавные и строчные."}'::jsonb, array[]::text[]),
  ('early.letter-sounds', 'early', -1, 1, '{"en":"Letter Sounds","ru":"Звуки и буквы"}'::jsonb, '{"en":"Connect letters with their sounds and first words.","ru":"Связываем буквы со звуками и первыми словами."}'::jsonb, array['early.letters']::text[]),
  ('early.patterns', 'early', -1, 1, '{"en":"Patterns & Memory","ru":"Закономерности и память"}'::jsonb, '{"en":"Continue sequences, sort objects, train attention.","ru":"Продолжаем последовательности, сортируем предметы, тренируем внимание."}'::jsonb, array['early.colors-shapes']::text[]),
  ('early.nature', 'early', -1, 1, '{"en":"The World Around Us","ru":"Окружающий мир"}'::jsonb, '{"en":"Animals, plants, seasons, weather and family.","ru":"Животные, растения, времена года, погода и семья."}'::jsonb, array[]::text[]),
  ('math.addition-20', 'math', 1, 2, '{"en":"Addition within 20","ru":"Сложение в пределах 20"}'::jsonb, '{"en":"Add numbers up to 20 using counting on and making ten.","ru":"Складываем числа до 20 с помощью досчитывания и «перехода через десяток»."}'::jsonb, array['early.counting']::text[]),
  ('math.subtraction-20', 'math', 1, 2, '{"en":"Subtraction within 20","ru":"Вычитание в пределах 20"}'::jsonb, '{"en":"Take away and find the difference up to 20.","ru":"Вычитаем и находим разность в пределах 20."}'::jsonb, array['math.addition-20']::text[]),
  ('math.compare-numbers', 'math', 1, 2, '{"en":"Comparing Numbers","ru":"Сравнение чисел"}'::jsonb, '{"en":"Use >, < and = to compare numbers.","ru":"Используем знаки >, < и = для сравнения чисел."}'::jsonb, array['early.compare-quantities']::text[]),
  ('math.place-value', 'math', 2, 3, '{"en":"Tens, Hundreds & Place Value","ru":"Разряды: десятки и сотни"}'::jsonb, '{"en":"Numbers up to 1000 and what each digit means.","ru":"Числа до 1000 и значение каждой цифры."}'::jsonb, array['math.compare-numbers','math.addition-20']::text[]),
  ('math.equal-groups', 'math', 2, 2, '{"en":"Equal Groups","ru":"Равные группы"}'::jsonb, '{"en":"Understand repeated addition with equal groups.","ru":"Понимаем сложение одинаковых слагаемых через равные группы."}'::jsonb, array['math.addition-20']::text[]),
  ('math.multiplication', 'math', 2, 3, '{"en":"Multiplication","ru":"Умножение"}'::jsonb, '{"en":"Multiplication as equal groups and the times tables.","ru":"Умножение как равные группы и таблица умножения."}'::jsonb, array['math.equal-groups']::text[]),
  ('math.division', 'math', 3, 4, '{"en":"Division","ru":"Деление"}'::jsonb, '{"en":"Sharing equally and division as the inverse of multiplication.","ru":"Деление поровну и деление как действие, обратное умножению."}'::jsonb, array['math.multiplication']::text[]),
  ('math.word-problems', 'math', 1, 4, '{"en":"Word Problems","ru":"Текстовые задачи"}'::jsonb, '{"en":"Read a story, find the question and choose the operation.","ru":"Читаем условие, находим вопрос и выбираем действие."}'::jsonb, array['math.addition-20','math.subtraction-20']::text[]),
  ('math.measurement', 'math', 2, 4, '{"en":"Measurement","ru":"Величины и измерения"}'::jsonb, '{"en":"Length, mass, time and money.","ru":"Длина, масса, время и деньги."}'::jsonb, array['math.place-value']::text[]),
  ('math.area-perimeter', 'math', 3, 5, '{"en":"Area & Perimeter","ru":"Площадь и периметр"}'::jsonb, '{"en":"Measure around and inside shapes.","ru":"Измеряем границу и внутреннюю часть фигур."}'::jsonb, array['math.multiplication','math.measurement']::text[]),
  ('math.fractions', 'math', 3, 5, '{"en":"Fractions","ru":"Обыкновенные дроби"}'::jsonb, '{"en":"Parts of a whole, equivalent and comparing fractions.","ru":"Части целого, равные дроби и сравнение дробей."}'::jsonb, array['math.division']::text[]),
  ('math.decimals', 'math', 5, 6, '{"en":"Decimals","ru":"Десятичные дроби"}'::jsonb, '{"en":"Tenths, hundredths and operations with decimals.","ru":"Десятые, сотые и действия с десятичными дробями."}'::jsonb, array['math.fractions','math.place-value']::text[]),
  ('math.percentages', 'math', 5, 6, '{"en":"Percentages","ru":"Проценты"}'::jsonb, '{"en":"Percent as parts of 100, finding a percentage of a number.","ru":"Процент как сотая часть, нахождение процента от числа."}'::jsonb, array['math.decimals']::text[]),
  ('math.ratios', 'math', 6, 6, '{"en":"Ratios & Proportions","ru":"Отношения и пропорции"}'::jsonb, '{"en":"Compare quantities with ratios and solve proportions.","ru":"Сравниваем величины с помощью отношений и решаем пропорции."}'::jsonb, array['math.fractions']::text[]),
  ('math.negative-numbers', 'math', 6, 6, '{"en":"Negative Numbers","ru":"Отрицательные числа"}'::jsonb, '{"en":"Numbers below zero on the number line.","ru":"Числа меньше нуля на числовой прямой."}'::jsonb, array['math.compare-numbers','math.subtraction-20']::text[]),
  ('math.coordinates', 'math', 6, 7, '{"en":"Coordinate Plane","ru":"Координатная плоскость"}'::jsonb, '{"en":"Plot and read points (x, y).","ru":"Отмечаем и читаем точки (x, y)."}'::jsonb, array['math.negative-numbers']::text[]),
  ('math.equations', 'math', 5, 7, '{"en":"Linear Equations","ru":"Линейные уравнения"}'::jsonb, '{"en":"Find the unknown using inverse operations.","ru":"Находим неизвестное с помощью обратных действий."}'::jsonb, array['math.negative-numbers','math.division']::text[]),
  ('math.powers', 'math', 7, 8, '{"en":"Powers & Roots","ru":"Степени и корни"}'::jsonb, '{"en":"Exponents, squares and square roots.","ru":"Показатели степени, квадраты и квадратные корни."}'::jsonb, array['math.multiplication']::text[]),
  ('math.probability', 'math', 7, 9, '{"en":"Probability","ru":"Вероятность"}'::jsonb, '{"en":"How likely is an event? Probability as a fraction.","ru":"Насколько вероятно событие? Вероятность как дробь."}'::jsonb, array['math.fractions']::text[]),
  ('math.statistics', 'math', 7, 9, '{"en":"Statistics","ru":"Статистика"}'::jsonb, '{"en":"Mean, median, mode and reading charts.","ru":"Среднее, медиана, мода и чтение диаграмм."}'::jsonb, array['math.decimals']::text[]),
  ('math.functions', 'math', 7, 9, '{"en":"Functions & Graphs","ru":"Функции и графики"}'::jsonb, '{"en":"Linear functions y = kx + b and their graphs.","ru":"Линейная функция y = kx + b и её график."}'::jsonb, array['math.equations','math.coordinates']::text[]),
  ('math.quadratics', 'math', 8, 9, '{"en":"Quadratic Equations","ru":"Квадратные уравнения"}'::jsonb, '{"en":"Solve ax² + bx + c = 0 with the discriminant.","ru":"Решаем ax² + bx + c = 0 через дискриминант."}'::jsonb, array['math.functions','math.powers']::text[]),
  ('math.geometry', 'math', 7, 9, '{"en":"Plane Geometry","ru":"Планиметрия"}'::jsonb, '{"en":"Angles, triangles, Pythagoras'' theorem.","ru":"Углы, треугольники, теорема Пифагора."}'::jsonb, array['math.area-perimeter','math.powers']::text[]),
  ('math.trigonometry', 'math', 9, 10, '{"en":"Trigonometry","ru":"Тригонометрия"}'::jsonb, '{"en":"Sine, cosine and tangent in right triangles.","ru":"Синус, косинус и тангенс в прямоугольном треугольнике."}'::jsonb, array['math.geometry']::text[]),
  ('math.solid-geometry', 'math', 10, 11, '{"en":"Solid Geometry","ru":"Стереометрия"}'::jsonb, '{"en":"Volumes and surface areas of 3D shapes.","ru":"Объёмы и площади поверхностей объёмных тел."}'::jsonb, array['math.geometry']::text[]),
  ('math.logarithms', 'math', 10, 11, '{"en":"Logarithms","ru":"Логарифмы"}'::jsonb, '{"en":"Logarithm as the inverse of a power.","ru":"Логарифм как действие, обратное возведению в степень."}'::jsonb, array['math.powers','math.functions']::text[]),
  ('math.calculus-intro', 'math', 10, 11, '{"en":"Introduction to Calculus","ru":"Начала анализа"}'::jsonb, '{"en":"Rate of change and derivatives of simple functions.","ru":"Скорость изменения и производные простых функций."}'::jsonb, array['math.functions','math.quadratics']::text[]),
