  ('reading.words', 'reading', 1, 1, '{"en":"Reading Words","ru":"Чтение слов"}'::jsonb, '{"en":"Read and build simple words.","ru":"Читаем и собираем простые слова."}'::jsonb, array['reading.syllables']::text[]),
  ('reading.sentences', 'reading', 1, 2, '{"en":"Sentences","ru":"Предложения"}'::jsonb, '{"en":"Build sentences, capital letters and full stops.","ru":"Составляем предложения: большая буква и точка."}'::jsonb, array['reading.words']::text[]),
  ('reading.spelling', 'reading', 2, 4, '{"en":"Spelling","ru":"Правописание"}'::jsonb, '{"en":"Common spelling rules and tricky words.","ru":"Основные правила правописания и словарные слова."}'::jsonb, array['reading.words']::text[]),
  ('reading.parts-of-speech', 'reading', 2, 4, '{"en":"Parts of Speech","ru":"Части речи"}'::jsonb, '{"en":"Nouns, verbs and adjectives.","ru":"Существительные, глаголы и прилагательные."}'::jsonb, array['reading.sentences']::text[]),
