  ('reading.vocabulary', 'reading', 2, 8, '{"en":"Vocabulary","ru":"Словарный запас"}'::jsonb, '{"en":"Synonyms, antonyms and word meanings.","ru":"Синонимы, антонимы и значения слов."}'::jsonb, array['reading.words']::text[]),
