  ('science.cells', 'science', 5, 8, '{"en":"Cells","ru":"Клетки"}'::jsonb, '{"en":"The building blocks of life.","ru":"Строительные блоки жизни."}'::jsonb, array['science.living-things']::text[]),
  ('science.energy', 'science', 5, 8, '{"en":"Energy & Electricity","ru":"Энергия и электричество"}'::jsonb, '{"en":"Forms of energy, circuits and conductors.","ru":"Виды энергии, электрические цепи и проводники."}'::jsonb, array['science.states-of-matter']::text[]),
  ('science.forces', 'science', 6, 9, '{"en":"Forces & Motion","ru":"Силы и движение"}'::jsonb, '{"en":"Gravity, friction and Newton''s laws.","ru":"Гравитация, трение и законы Ньютона."}'::jsonb, array['science.energy']::text[]),
  ('science.chemistry-basics', 'science', 7, 9, '{"en":"Atoms & Reactions","ru":"Атомы и реакции"}'::jsonb, '{"en":"Atoms, molecules and chemical reactions.","ru":"Атомы, молекулы и химические реакции."}'::jsonb, array['science.states-of-matter']::text[]),
  ('science.genetics', 'science', 9, 11, '{"en":"Genetics & Evolution","ru":"Генетика и эволюция"}'::jsonb, '{"en":"DNA, heredity and natural selection.","ru":"ДНК, наследственность и естественный отбор."}'::jsonb, array['science.cells']::text[]),
  ('science.electromagnetism', 'science', 9, 11, '{"en":"Electromagnetism","ru":"Электромагнетизм"}'::jsonb, '{"en":"Magnets, fields and electromagnets.","ru":"Магниты, поля и электромагниты."}'::jsonb, array['science.energy','science.forces']::text[]),
  ('languages.english-basics', 'languages', 0, 3, '{"en":"English: First Steps","ru":"Английский: первые шаги"}'::jsonb, '{"en":"Alphabet and greetings in English.","ru":"Английский алфавит и приветствия."}'::jsonb, array[]::text[]),
  ('languages.english-vocab', 'languages', 1, 4, '{"en":"English: Everyday Words","ru":"Английский: слова каждый день"}'::jsonb, '{"en":"Colours, numbers, animals and family.","ru":"Цвета, числа, животные и семья."}'::jsonb, array['languages.english-basics']::text[]),
  ('languages.english-grammar', 'languages', 3, 7, '{"en":"English: Grammar","ru":"Английский: грамматика"}'::jsonb, '{"en":"To be, plurals and Present Simple.","ru":"Глагол to be, множественное число и Present Simple."}'::jsonb, array['languages.english-vocab']::text[]),
  ('languages.english-dialogues', 'languages', 4, 9, '{"en":"English: Dialogues","ru":"Английский: диалоги"}'::jsonb, '{"en":"Ask and answer simple questions.","ru":"Задаём вопросы и отвечаем на них."}'::jsonb, array['languages.english-grammar']::text[]),
  ('languages.uzbek-basics', 'languages', 1, 6, '{"en":"Uzbek: First Steps","ru":"Узбекский: первые шаги"}'::jsonb, '{"en":"Uzbek Latin alphabet, greetings and numbers.","ru":"Узбекский латинский алфавит, приветствия и числа."}'::jsonb, array[]::text[]),
  ('languages.russian-basics', 'languages', 1, 6, '{"en":"Russian: First Steps","ru":"Русский как иностранный: первые шаги"}'::jsonb, '{"en":"Cyrillic letters, greetings and numbers.","ru":"Кириллица, приветствия и числа для изучающих русский."}'::jsonb, array[]::text[]),
  ('tech.computer-basics', 'tech', 1, 4, '{"en":"Computer Basics","ru":"Основы работы с компьютером"}'::jsonb, '{"en":"Parts of a computer, files and the keyboard.","ru":"Устройство компьютера, файлы и клавиатура."}'::jsonb, array[]::text[]),
  ('tech.internet-safety', 'tech', 1, 11, '{"en":"Internet Safety","ru":"Безопасность в интернете"}'::jsonb, '{"en":"Private information, strong passwords and kindness online.","ru":"Личные данные, надёжные пароли и доброта в сети."}'::jsonb, array[]::text[]),
  ('tech.algorithms', 'tech', 1, 4, '{"en":"Algorithms","ru":"Алгоритмы"}'::jsonb, '{"en":"Step-by-step instructions for a robot.","ru":"Пошаговые инструкции для робота."}'::jsonb, array['early.patterns']::text[]),
  ('tech.loops', 'tech', 2, 5, '{"en":"Loops","ru":"Циклы"}'::jsonb, '{"en":"Repeat blocks to write shorter programs.","ru":"Повторяем блоки, чтобы писать короче."}'::jsonb, array['tech.algorithms']::text[]),
  ('tech.conditions', 'tech', 3, 6, '{"en":"Conditions","ru":"Условия"}'::jsonb, '{"en":"If-then decisions in programs.","ru":"Решения «если - то» в программах."}'::jsonb, array['tech.loops']::text[]),
  ('tech.html', 'tech', 5, 9, '{"en":"HTML Basics","ru":"Основы HTML"}'::jsonb, '{"en":"Tags, headings, paragraphs and links.","ru":"Теги, заголовки, абзацы и ссылки."}'::jsonb, array['tech.computer-basics']::text[]),
  ('tech.css', 'tech', 6, 9, '{"en":"CSS Basics","ru":"Основы CSS"}'::jsonb, '{"en":"Colours, fonts and layout for web pages.","ru":"Цвета, шрифты и расположение элементов страницы."}'::jsonb, array['tech.html']::text[]),
  ('tech.javascript', 'tech', 7, 11, '{"en":"JavaScript Basics","ru":"Основы JavaScript"}'::jsonb, '{"en":"Variables, conditions and functions.","ru":"Переменные, условия и функции."}'::jsonb, array['tech.conditions']::text[]),
  ('tech.python', 'tech', 7, 11, '{"en":"Python for Beginners","ru":"Python для начинающих"}'::jsonb, '{"en":"print, variables, if and loops in Python.","ru":"print, переменные, if и циклы в Python."}'::jsonb, array['tech.conditions']::text[])
insert into public.lessons (id, topic_id, title, content, difficulty, duration, objectives, status) values
  ('early.colors-shapes.l1', 'early.colors-shapes', '{"en":"Colours All Around","ru":"Цвета вокруг нас"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.colors-shapes.l1","topicId":"early.colors-shapes","title":{"en":"Colours All Around","ru":"Цвета вокруг нас"},"subtopic":{"en":"Red, yellow, green, blue","ru":"Красный, жёлтый, зелёный, синий"},"objective":{"en":"Name and find the main colours.","ru":"Называть и находить основные цвета."},"grades":[-1,0],"difficulty":1,"durationMin":5,"intro":{"en":"Hi, I''m Foxy! Let''s go on a colour hunt!","ru":"Привет, я Фокси! Пойдём искать цвета!"},"explanation":[{"en":"The world is full of colours.","ru":"Мир полон цветов."},{"en":"A strawberry is red. A banana is yellow. Grass is green. The sky is blue.","ru":"Клубника красная. Банан жёлтый. Трава зелёная. Небо синее."}],"example":{"kind":"emoji","items":["🔴","🟡","🟢","🔵"],"caption":{"en":"Red, yellow, green, blue","ru":"Красный, жёлтый, зелёный, синий"}},"game":"memory-match","reviewTips":{"en":"Name the colours of things at home: your cup, your toys, your clothes.","ru":"Называй цвета вещей дома: чашки, игрушек, одежды."}}'::jsonb, 1, 5, '{"objective":{"en":"Name and find the main colours.","ru":"Называть и находить основные цвета."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.colors-shapes.l2', 'early.colors-shapes', '{"en":"Shapes and Sizes","ru":"Формы и размеры"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.colors-shapes.l2","topicId":"early.colors-shapes","title":{"en":"Shapes and Sizes","ru":"Формы и размеры"},"subtopic":{"en":"Circle, square, triangle; big and small","ru":"Круг, квадрат, треугольник; большой и маленький"},"objective":{"en":"Recognise circles, squares and triangles and compare sizes.","ru":"Узнавать круг, квадрат и треугольник и сравнивать размеры."},"grades":[-1,0],"difficulty":2,"durationMin":6,"intro":{"en":"Shapes are hiding everywhere. Let''s find them!","ru":"Фигуры прячутся повсюду. Давай их найдём!"},"explanation":[{"en":"A circle is round, like a ball. It has no corners.","ru":"Круг круглый, как мячик. У него нет углов."},{"en":"A square has 4 equal sides. A triangle has 3 sides and 3 corners.","ru":"У квадрата 4 одинаковые стороны. У треугольника 3 стороны и 3 угла."},{"en":"Things can be big or small. An elephant is big, a mouse is small.","ru":"Предметы бывают большими и маленькими. Слон большой, мышка маленькая."}],"example":{"kind":"emoji","items":["⚪","🟦","🔺"],"caption":{"en":"Circle, square, triangle","ru":"Круг, квадрат, треугольник"}},"game":"shape-builder","reviewTips":{"en":"Look for shapes at home: a plate is a circle, a window can be a square.","ru":"Ищи фигуры дома: тарелка - круг, окно бывает квадратным."}}'::jsonb, 2, 6, '{"objective":{"en":"Recognise circles, squares and triangles and compare sizes.","ru":"Узнавать круг, квадрат и треугольник и сравнивать размеры."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.numbers.l1', 'early.numbers', '{"en":"Numbers 0 to 5","ru":"Цифры от 0 до 5"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.numbers.l1","topicId":"early.numbers","title":{"en":"Numbers 0 to 5","ru":"Цифры от 0 до 5"},"subtopic":{"en":"Digits 0, 1, 2, 3, 4, 5","ru":"Цифры 0, 1, 2, 3, 4, 5"},"objective":{"en":"Recognise and name the digits from 0 to 5.","ru":"Узнавать и называть цифры от 0 до 5."},"grades":[-1,0],"difficulty":1,"durationMin":5,"intro":{"en":"Numbers are my friends. Let''s meet them!","ru":"Цифры - мои друзья. Давай познакомимся!"},"explanation":[{"en":"Numbers tell us how many.","ru":"Цифры говорят нам, сколько чего-то."},{"en":"1 duck, 2 ducks, 3 ducks. Zero means none at all.","ru":"1 утка, 2 утки, 3 утки. Ноль - значит совсем ничего."}],"example":{"kind":"numberline","from":0,"to":5,"marks":[0,1,2,3,4,5],"caption":{"en":"0, 1, 2, 3, 4, 5","ru":"0, 1, 2, 3, 4, 5"}},"game":"number-counting","reviewTips":{"en":"Count steps, spoons and toys up to 5 together with a grown-up.","ru":"Считай вместе со взрослым ступеньки, ложки и игрушки до 5."}}'::jsonb, 1, 5, '{"objective":{"en":"Recognise and name the digits from 0 to 5.","ru":"Узнавать и называть цифры от 0 до 5."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.numbers.l2', 'early.numbers', '{"en":"Numbers 6 to 10","ru":"Цифры от 6 до 10"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.numbers.l2","topicId":"early.numbers","title":{"en":"Numbers 6 to 10","ru":"Цифры от 6 до 10"},"subtopic":{"en":"Digits 6, 7, 8, 9 and the number 10","ru":"Цифры 6, 7, 8, 9 и число 10"},"objective":{"en":"Recognise and name the numbers from 6 to 10.","ru":"Узнавать и называть числа от 6 до 10."},"grades":[-1,0],"difficulty":2,"durationMin":6,"intro":{"en":"You know numbers up to 5. Let''s go further, up to 10!","ru":"Ты знаешь цифры до 5. Пойдём дальше, до 10!"},"explanation":[{"en":"After 5 come 6, 7, 8, 9 and 10.","ru":"После 5 идут 6, 7, 8, 9 и 10."},{"en":"10 is like all the fingers on two hands.","ru":"10 - это все пальчики на двух руках."}],"example":{"kind":"numberline","from":0,"to":10,"marks":[6,7,8,9,10],"caption":{"en":"6, 7, 8, 9, 10","ru":"6, 7, 8, 9, 10"}},"game":"number-counting","reviewTips":{"en":"Show numbers with your fingers: 6, 7, 8, 9, 10.","ru":"Показывай числа на пальчиках: 6, 7, 8, 9, 10."}}'::jsonb, 2, 6, '{"objective":{"en":"Recognise and name the numbers from 6 to 10.","ru":"Узнавать и называть числа от 6 до 10."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.counting.l1', 'early.counting', '{"en":"Let''s Count to 5","ru":"Считаем до 5"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.counting.l1","topicId":"early.counting","title":{"en":"Let''s Count to 5","ru":"Считаем до 5"},"subtopic":{"en":"Counting objects up to 5","ru":"Счёт предметов до 5"},"objective":{"en":"Count up to 5 objects and say how many.","ru":"Считать до 5 предметов и называть, сколько их."},"grades":[-1,1],"difficulty":1,"durationMin":5,"intro":{"en":"I love counting! Point at each thing and count with me.","ru":"Я обожаю считать! Показывай на каждый предмет и считай со мной."},"explanation":[{"en":"Touch each object once and say a number: 1, 2, 3.","ru":"Дотронься до каждого предмета один раз и скажи число: 1, 2, 3."},{"en":"The last number you say tells how many there are.","ru":"Последнее число, которое ты сказал, и есть ответ."}],"example":{"kind":"emoji","items":["🍎","🍎","🍎"],"caption":{"en":"1, 2, 3 - three apples","ru":"1, 2, 3 - три яблока"}},"game":"number-counting","reviewTips":{"en":"Count things on a walk: birds, trees, cars - up to 5.","ru":"Считай на прогулке птиц, деревья, машины - до 5."}}'::jsonb, 1, 5, '{"objective":{"en":"Count up to 5 objects and say how many.","ru":"Считать до 5 предметов и называть, сколько их."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.counting.l2', 'early.counting', '{"en":"Let''s Count to 10","ru":"Считаем до 10"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.counting.l2","topicId":"early.counting","title":{"en":"Let''s Count to 10","ru":"Считаем до 10"},"subtopic":{"en":"Counting objects up to 10","ru":"Счёт предметов до 10"},"objective":{"en":"Count up to 10 objects and match them to numbers.","ru":"Считать до 10 предметов и сопоставлять их с числами."},"grades":[-1,1],"difficulty":2,"durationMin":7,"intro":{"en":"Ready for bigger numbers? Let''s count all the way to 10!","ru":"Готов к числам побольше? Посчитаем до самого 10!"},"explanation":[{"en":"Count slowly and touch each object only once.","ru":"Считай не спеша и трогай каждый предмет только один раз."},{"en":"One hand has 5 fingers. Two hands have 10 fingers.","ru":"На одной руке 5 пальчиков. На двух руках - 10."}],"example":{"kind":"groups","emoji":"🖐️","groups":2,"per":1,"caption":{"en":"5 + 5 fingers = 10","ru":"5 + 5 пальчиков = 10"}},"game":"number-counting","reviewTips":{"en":"Count up to 10 every day: buttons, stairs, spoons.","ru":"Считай до 10 каждый день: пуговицы, ступеньки, ложки."}}'::jsonb, 2, 7, '{"objective":{"en":"Count up to 10 objects and match them to numbers.","ru":"Считать до 10 предметов и сопоставлять их с числами."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.compare-quantities.l1', 'early.compare-quantities', '{"en":"More or Less?","ru":"Больше или меньше?"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.compare-quantities.l1","topicId":"early.compare-quantities","title":{"en":"More or Less?","ru":"Больше или меньше?"},"subtopic":{"en":"Comparing two groups","ru":"Сравниваем две группы"},"objective":{"en":"Tell which group has more and which has fewer.","ru":"Определять, в какой группе больше, а в какой меньше."},"grades":[-1,1],"difficulty":1,"durationMin":5,"intro":{"en":"Which pile of berries is bigger? Let''s find out!","ru":"Какая кучка ягод больше? Давай узнаем!"},"explanation":[{"en":"Count both groups. The group with the bigger number has more.","ru":"Посчитай обе группы. Где число больше - там больше предметов."},{"en":"The group with the smaller number has fewer.","ru":"Где число меньше - там предметов меньше."}],"example":{"kind":"emoji","items":["🐟","🐟","🐟","🐟","⬅️","🐟","🐟"],"caption":{"en":"4 fish is more than 2 fish","ru":"4 рыбки - больше, чем 2 рыбки"}},"game":"number-counting","reviewTips":{"en":"Compare at the table: who has more spoons, who has fewer cups?","ru":"Сравнивай за столом: у кого больше ложек, у кого меньше чашек?"}}'::jsonb, 1, 5, '{"objective":{"en":"Tell which group has more and which has fewer.","ru":"Определять, в какой группе больше, а в какой меньше."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.compare-quantities.l2', 'early.compare-quantities', '{"en":"The Same Number","ru":"Поровну"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.compare-quantities.l2","topicId":"early.compare-quantities","title":{"en":"The Same Number","ru":"Поровну"},"subtopic":{"en":"Equal groups and ordering groups","ru":"Равные группы и порядок групп"},"objective":{"en":"Find equal groups and put groups in order from fewest to most.","ru":"Находить равные группы и ставить группы по порядку от меньшей к большей."},"grades":[-1,1],"difficulty":2,"durationMin":6,"intro":{"en":"Let''s share fairly so everyone gets the same!","ru":"Давай делить честно, чтобы всем досталось поровну!"},"explanation":[{"en":"Equal means the same number: 3 pears and 3 apples are equal.","ru":"Поровну - значит одинаковое число: 3 груши и 3 яблока - поровну."},{"en":"You can make pairs: if every object has a partner, the groups are equal.","ru":"Можно составить пары: если у каждого предмета есть пара - групп поровну."}],"example":{"kind":"emoji","items":["🍎","🍎","🍎","🟰","🍐","🍐","🍐"],"caption":{"en":"3 and 3 - equal","ru":"3 и 3 - поровну"}},"game":"memory-match","reviewTips":{"en":"Lay out toys in pairs to see if two groups are equal.","ru":"Раскладывай игрушки парами, чтобы увидеть, поровну ли их."}}'::jsonb, 2, 6, '{"objective":{"en":"Find equal groups and put groups in order from fewest to most.","ru":"Находить равные группы и ставить группы по порядку от меньшей к большей."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.letters.l1', 'early.letters', '{"en":"Hello, Letters!","ru":"Здравствуй, буква!"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.letters.l1","topicId":"early.letters","title":{"en":"Hello, Letters!","ru":"Здравствуй, буква!"},"subtopic":{"en":"First letters: A, B, C, O","ru":"Первые буквы: А, Б, В, О"},"objective":{"en":"Recognise the first letters of the alphabet.","ru":"Узнавать первые буквы алфавита."},"grades":[-1,0],"difficulty":1,"durationMin":5,"intro":{"en":"Letters make words. Let''s meet the first ones!","ru":"Из букв получаются слова. Давай познакомимся с первыми!"},"explanation":[{"en":"The alphabet starts with A, B, C.","ru":"Алфавит начинается с букв А, Б, В."},{"en":"Letters are different from numbers and pictures.","ru":"Буквы - это не цифры и не картинки."}],"example":{"kind":"text","text":{"en":"A  B  C","ru":"А  Б  В"}},"game":"alphabet-finder","reviewTips":{"en":"Look for the letters A and O in books and on signs.","ru":"Ищи буквы А и О в книжках и на вывесках."}}'::jsonb, 1, 5, '{"objective":{"en":"Recognise the first letters of the alphabet.","ru":"Узнавать первые буквы алфавита."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.letters.l2', 'early.letters', '{"en":"Big and Small Letters","ru":"Большие и маленькие буквы"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.letters.l2","topicId":"early.letters","title":{"en":"Big and Small Letters","ru":"Большие и маленькие буквы"},"subtopic":{"en":"Capital and small letters","ru":"Заглавные и строчные буквы"},"objective":{"en":"Match capital letters with small letters and know the order A-B-C-D.","ru":"Соединять заглавные и строчные буквы и знать порядок А-Б-В-Г."},"grades":[-1,0],"difficulty":2,"durationMin":7,"intro":{"en":"Every letter has a big sister and a little sister!","ru":"У каждой буквы есть большая и маленькая сестричка!"},"explanation":[{"en":"Each letter can be big (capital) or small: A and a.","ru":"Каждая буква бывает большой (заглавной) и маленькой (строчной): А и а."},{"en":"Big letters start names and sentences.","ru":"С большой буквы начинаются имена и предложения."}],"example":{"kind":"text","text":{"en":"Aa  Bb  Cc  Dd","ru":"Аа  Бб  Вв  Гг"}},"game":"alphabet-finder","reviewTips":{"en":"Find big and small letters in your favourite book.","ru":"Найди большие и маленькие буквы в любимой книжке."}}'::jsonb, 2, 7, '{"objective":{"en":"Match capital letters with small letters and know the order A-B-C-D.","ru":"Соединять заглавные и строчные буквы и знать порядок А-Б-В-Г."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.letter-sounds.l1', 'early.letter-sounds', '{"en":"What Sound Does It Start With?","ru":"С какого звука начинается?"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.letter-sounds.l1","topicId":"early.letter-sounds","title":{"en":"What Sound Does It Start With?","ru":"С какого звука начинается?"},"subtopic":{"en":"First sounds in words","ru":"Первый звук в слове"},"objective":{"en":"Hear the first sound of a word and find its letter.","ru":"Слышать первый звук в слове и находить его букву."},"grades":[-1,1],"difficulty":1,"durationMin":6,"intro":{"en":"Every word starts with a sound. Let''s listen carefully!","ru":"Каждое слово начинается со звука. Давай слушать внимательно!"},"explanation":[{"en":"Say a word slowly: b-b-banana. The first sound is B.","ru":"Скажи слово медленно: б-б-банан. Первый звук - Б."},{"en":"Each sound has a letter.","ru":"У каждого звука есть своя буква."}],"example":{"kind":"emoji","items":["🍌","➡️","🔤"],"caption":{"en":"Banana starts with B","ru":"Банан начинается на Б"}},"game":"alphabet-finder","reviewTips":{"en":"Play \"I spy\": name things at home and say their first sound.","ru":"Поиграй в «Угадай звук»: называй предметы дома и их первый звук."}}'::jsonb, 1, 6, '{"objective":{"en":"Hear the first sound of a word and find its letter.","ru":"Слышать первый звук в слове и находить его букву."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.letter-sounds.l2', 'early.letter-sounds', '{"en":"First Words","ru":"Первые слова"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.letter-sounds.l2","topicId":"early.letter-sounds","title":{"en":"First Words","ru":"Первые слова"},"subtopic":{"en":"From sounds to short words","ru":"От звуков к коротким словам"},"objective":{"en":"Match letters to pictures and build first short words.","ru":"Сопоставлять буквы и картинки и собирать первые короткие слова."},"grades":[-1,1],"difficulty":2,"durationMin":8,"intro":{"en":"Sounds join together to make words. Let''s build some!","ru":"Звуки соединяются в слова. Давай соберём несколько!"},"explanation":[{"en":"Put sounds one after another and you get a word: C-A-T, cat!","ru":"Поставь звуки друг за другом - и получится слово: К-О-Т, кот!"},{"en":"Say each sound, then say them quickly together.","ru":"Произнеси каждый звук, а потом быстро вместе."}],"example":{"kind":"text","text":{"en":"C + A + T = CAT 🐱","ru":"К + О + Т = КОТ 🐱"}},"game":"alphabet-finder","reviewTips":{"en":"Build short words from letter magnets or cards with a grown-up.","ru":"Собирай со взрослым короткие слова из магнитных букв или карточек."}}'::jsonb, 2, 8, '{"objective":{"en":"Match letters to pictures and build first short words.","ru":"Сопоставлять буквы и картинки и собирать первые короткие слова."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.patterns.l1', 'early.patterns', '{"en":"What Comes Next?","ru":"Что дальше?"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.patterns.l1","topicId":"early.patterns","title":{"en":"What Comes Next?","ru":"Что дальше?"},"subtopic":{"en":"Repeating patterns","ru":"Повторяющиеся узоры"},"objective":{"en":"Spot a repeating pattern and continue it.","ru":"Замечать повторяющийся узор и продолжать его."},"grades":[-1,1],"difficulty":1,"durationMin":5,"intro":{"en":"Patterns repeat again and again. Can you guess what comes next?","ru":"Узоры повторяются снова и снова. Угадаешь, что дальше?"},"explanation":[{"en":"A pattern is something that repeats: red, blue, red, blue...","ru":"Узор - это то, что повторяется: красный, синий, красный, синий..."},{"en":"Find the part that repeats, then say it again.","ru":"Найди повторяющуюся часть - и продолжи её."}],"example":{"kind":"emoji","items":["🔴","🔵","🔴","🔵","🔴","🔵"],"caption":{"en":"Red, blue, red, blue...","ru":"Красный, синий, красный, синий..."}},"game":"pattern-puzzle","reviewTips":{"en":"Make patterns with toys or beads: red, blue, red, blue.","ru":"Выкладывай узоры из игрушек или бусин: красный, синий, красный, синий."}}'::jsonb, 1, 5, '{"objective":{"en":"Spot a repeating pattern and continue it.","ru":"Замечать повторяющийся узор и продолжать его."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.patterns.l2', 'early.patterns', '{"en":"Sort and Remember","ru":"Сортируем и запоминаем"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.patterns.l2","topicId":"early.patterns","title":{"en":"Sort and Remember","ru":"Сортируем и запоминаем"},"subtopic":{"en":"Sorting, odd one out, sequences","ru":"Сортировка, лишний предмет, последовательности"},"objective":{"en":"Sort objects into groups, find the odd one out and order events.","ru":"Раскладывать предметы по группам, находить лишнее и ставить события по порядку."},"grades":[-1,1],"difficulty":2,"durationMin":7,"intro":{"en":"Let''s tidy up and sort everything into the right places!","ru":"Давай наведём порядок и разложим всё по местам!"},"explanation":[{"en":"Things that are alike go together: fruit with fruit, toys with toys.","ru":"Похожие вещи кладём вместе: фрукты к фруктам, игрушки к игрушкам."},{"en":"The odd one out is the one that is not like the others.","ru":"Лишний предмет - тот, что не похож на остальные."}],"example":{"kind":"emoji","items":["🍎","🍌","🍐","|","🧸","⚽","🪀"],"caption":{"en":"Fruit and toys","ru":"Фрукты и игрушки"}},"game":"memory-match","reviewTips":{"en":"Help tidy up: sort socks, toys and spoons into groups.","ru":"Помогай убираться: раскладывай носки, игрушки и ложки по группам."}}'::jsonb, 2, 7, '{"objective":{"en":"Sort objects into groups, find the odd one out and order events.","ru":"Раскладывать предметы по группам, находить лишнее и ставить события по порядку."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.nature.l1', 'early.nature', '{"en":"Animal Friends","ru":"Друзья-животные"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.nature.l1","topicId":"early.nature","title":{"en":"Animal Friends","ru":"Друзья-животные"},"subtopic":{"en":"Animals, their babies and homes","ru":"Животные, их детёныши и дома"},"objective":{"en":"Name animals, their babies and where they live.","ru":"Называть животных, их детёнышей и где они живут."},"grades":[-1,1],"difficulty":1,"durationMin":6,"intro":{"en":"Let''s visit the farm and the forest and meet the animals!","ru":"Давай заглянем на ферму и в лес и познакомимся с животными!"},"explanation":[{"en":"Some animals live on a farm: cows, hens, pigs.","ru":"Некоторые животные живут на ферме: коровы, курицы, свинки."},{"en":"Wild animals live in the forest: foxes, bears, wolves.","ru":"Дикие животные живут в лесу: лисы, медведи, волки."},{"en":"Animal babies have their own names: a cow has a calf, a cat has a kitten.","ru":"У детёнышей свои названия: у коровы - телёнок, у кошки - котёнок."}],"example":{"kind":"emoji","items":["🐄","🐔","🐖","🌲","🦊","🐻"],"caption":{"en":"Farm and forest animals","ru":"Животные фермы и леса"}},"game":"memory-match","reviewTips":{"en":"Look at a picture book about animals and name their babies.","ru":"Полистай книжку о животных и называй их детёнышей."}}'::jsonb, 1, 6, '{"objective":{"en":"Name animals, their babies and where they live.","ru":"Называть животных, их детёнышей и где они живут."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('early.nature.l2', 'early.nature', '{"en":"Seasons, Weather and Family","ru":"Времена года, погода и семья"}'::jsonb, '{"ageRange":[4,7],"character":"foxy","masteryScore":0.75,"status":"reviewed","id":"early.nature.l2","topicId":"early.nature","title":{"en":"Seasons, Weather and Family","ru":"Времена года, погода и семья"},"subtopic":{"en":"Four seasons, weather, plants, family","ru":"Четыре времени года, погода, растения, семья"},"objective":{"en":"Name the seasons in order, dress for the weather and know family members.","ru":"Называть времена года по порядку, одеваться по погоде и знать членов семьи."},"grades":[-1,1],"difficulty":2,"durationMin":7,"intro":{"en":"Look outside! What is the weather like today?","ru":"Посмотри в окно! Какая сегодня погода?"},"explanation":[{"en":"There are 4 seasons: winter, spring, summer, autumn.","ru":"Есть 4 времени года: зима, весна, лето, осень."},{"en":"In winter it is cold and snowy. In summer it is hot and sunny.","ru":"Зимой холодно и идёт снег. Летом жарко и светит солнце."},{"en":"Plants need water and sunlight to grow.","ru":"Растениям для роста нужны вода и солнечный свет."}],"example":{"kind":"emoji","items":["❄️","🌷","☀️","🍂"],"caption":{"en":"Winter, spring, summer, autumn","ru":"Зима, весна, лето, осень"}},"reviewTips":{"en":"Each morning, look at the weather together and choose what to wear.","ru":"Каждое утро смотри на погоду и выбирай, что надеть."}}'::jsonb, 2, 7, '{"objective":{"en":"Name the seasons in order, dress for the weather and know family members.","ru":"Называть времена года по порядку, одеваться по погоде и знать членов семьи."},"masteryScore":0.75}'::jsonb, 'reviewed'),
  ('math.addition-20.l1', 'math.addition-20', '{"en":"Adding up to 20","ru":"Складываем до 20"}'::jsonb, '{"id":"math.addition-20.l1","topicId":"math.addition-20","title":{"en":"Adding up to 20","ru":"Складываем до 20"},"subtopic":{"en":"Counting on and making ten","ru":"Досчитывание и переход через десяток"},"objective":{"en":"Add two numbers with a sum up to 20.","ru":"Складывать два числа с суммой до 20."},"ageRange":[6,10],"grades":[1,2],"difficulty":1,"durationMin":10,"character":"oli","intro":{"en":"Hi! I''m Oli. Let''s put numbers together!","ru":"Привет! Я Оли. Давай складывать числа!"},"explanation":[{"en":"To add, we put groups together. Start with the bigger number and count on.","ru":"Сложить — значит соединить группы. Начни с большего числа и считай дальше."},{"en":"Make ten! 8 + 5: take 2 from the 5 to make 10. Then 10 + 3 = 13.","ru":"Дополни до десяти! 8 + 5: возьми 2 из пятёрки — получится 10. А 10 + 3 = 13."}],"example":{"kind":"equation","text":"8 + 5 = 8 + 2 + 3 = 13","caption":{"en":"Make ten, then add the rest.","ru":"Сначала до десяти, потом остальное."}},"generated":[{"generator":"add-within-10","count":2},{"generator":"add-within-20","count":3}],"game":"math-challenge","masteryScore":0.8,"reviewTips":{"en":"Practise making ten with your fingers: 8 and 2, 7 and 3, 6 and 4.","ru":"Потренируйся дополнять до десяти на пальцах: 8 и 2, 7 и 3, 6 и 4."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Add two numbers with a sum up to 20.","ru":"Складывать два числа с суммой до 20."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.subtraction-20.l1', 'math.subtraction-20', '{"en":"Taking away up to 20","ru":"Вычитаем до 20"}'::jsonb, '{"id":"math.subtraction-20.l1","topicId":"math.subtraction-20","title":{"en":"Taking away up to 20","ru":"Вычитаем до 20"},"subtopic":{"en":"Counting back and fact families","ru":"Счёт назад и связь со сложением"},"objective":{"en":"Subtract numbers within 20.","ru":"Вычитать числа в пределах 20."},"ageRange":[6,10],"grades":[1,2],"difficulty":1,"durationMin":10,"character":"oli","intro":{"en":"Some birds fly away. How many stay? Let''s find out!","ru":"Птички улетают. Сколько осталось? Давай узнаем!"},"explanation":[{"en":"Subtraction means taking away. For 12 − 4, start at 12 and count back 4 steps.","ru":"Вычесть — значит убрать. Для 12 − 4 начни с 12 и сделай 4 шага назад."},{"en":"Adding helps! If 8 + 4 = 12, then 12 − 4 = 8.","ru":"Сложение помогает! Если 8 + 4 = 12, то 12 − 4 = 8."}],"example":{"kind":"numberline","from":5,"to":15,"marks":[8,12],"caption":{"en":"12 − 4 = 8: four jumps back.","ru":"12 − 4 = 8: четыре прыжка назад."}},"generated":[{"generator":"sub-within-20","count":4}],"game":"math-challenge","masteryScore":0.8,"reviewTips":{"en":"Use a number line and jump back. Check with adding.","ru":"Прыгай назад по числовой прямой и проверяй сложением."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Subtract numbers within 20.","ru":"Вычитать числа в пределах 20."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.compare-numbers.l1', 'math.compare-numbers', '{"en":"Bigger, smaller, equal","ru":"Больше, меньше, равно"}'::jsonb, '{"id":"math.compare-numbers.l1","topicId":"math.compare-numbers","title":{"en":"Bigger, smaller, equal","ru":"Больше, меньше, равно"},"subtopic":{"en":"The signs >, < and =","ru":"Знаки >, < и ="},"objective":{"en":"Compare numbers up to 100 with >, < and =.","ru":"Сравнивать числа до 100 с помощью >, < и =."},"ageRange":[6,10],"grades":[1,2],"difficulty":1,"durationMin":8,"character":"oli","intro":{"en":"The hungry sign always eats the bigger number!","ru":"Голодный знак всегда «ест» большее число!"},"explanation":[{"en":"> means greater than. < means less than. = means equal.","ru":"> значит «больше». < значит «меньше». = значит «равно»."},{"en":"The open side of the sign faces the bigger number: 7 > 3.","ru":"Открытая сторона знака смотрит на большее число: 7 > 3."},{"en":"For two-digit numbers, compare tens first: 23 > 19.","ru":"У двузначных чисел сначала сравни десятки: 23 > 19."}],"example":{"kind":"equation","text":"7 > 3    2 < 9    5 = 5","caption":{"en":"Greater, less, equal.","ru":"Больше, меньше, равно."}},"generated":[{"generator":"compare-numbers","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Look at the tens first, then the ones.","ru":"Сначала сравни десятки, потом единицы."},"status":"reviewed"}'::jsonb, 1, 8, '{"objective":{"en":"Compare numbers up to 100 with >, < and =.","ru":"Сравнивать числа до 100 с помощью >, < и =."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.place-value.l1', 'math.place-value', '{"en":"Ones, tens, hundreds","ru":"Единицы, десятки, сотни"}'::jsonb, '{"id":"math.place-value.l1","topicId":"math.place-value","title":{"en":"Ones, tens, hundreds","ru":"Единицы, десятки, сотни"},"subtopic":{"en":"What each digit means","ru":"Что значит каждая цифра"},"objective":{"en":"Read numbers up to 1000 and tell the value of each digit.","ru":"Читать числа до 1000 и называть значение каждой цифры."},"ageRange":[7,11],"grades":[2,3],"difficulty":2,"durationMin":10,"character":"oli","intro":{"en":"Every digit lives in its own house. Let''s visit them!","ru":"Каждая цифра живёт в своём домике. Пойдём в гости!"},"explanation":[{"en":"Each digit has a place: ones, tens, hundreds.","ru":"У каждой цифры своё место: единицы, десятки, сотни."},{"en":"In 346 there are 3 hundreds, 4 tens and 6 ones: 346 = 300 + 40 + 6.","ru":"В 346 три сотни, четыре десятка и шесть единиц: 346 = 300 + 40 + 6."},{"en":"10 ones make 1 ten. 10 tens make 1 hundred.","ru":"10 единиц — это 1 десяток. 10 десятков — это 1 сотня."}],"example":{"kind":"equation","text":"346 = 300 + 40 + 6","caption":{"en":"Hundreds + tens + ones","ru":"Сотни + десятки + единицы"}},"generated":[{"generator":"place-value","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Split a number into hundreds, tens and ones: 527 = 500 + 20 + 7.","ru":"Раскладывай число на сотни, десятки и единицы: 527 = 500 + 20 + 7."},"status":"reviewed"}'::jsonb, 2, 10, '{"objective":{"en":"Read numbers up to 1000 and tell the value of each digit.","ru":"Читать числа до 1000 и называть значение каждой цифры."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.equal-groups.l1', 'math.equal-groups', '{"en":"Equal groups","ru":"Равные группы"}'::jsonb, '{"id":"math.equal-groups.l1","topicId":"math.equal-groups","title":{"en":"Equal groups","ru":"Равные группы"},"subtopic":{"en":"Adding the same number again and again","ru":"Складываем одинаковые числа"},"objective":{"en":"Find the total of equal groups by repeated addition.","ru":"Находить общее количество в равных группах с помощью сложения."},"ageRange":[7,10],"grades":[2,2],"difficulty":2,"durationMin":8,"character":"oli","intro":{"en":"Look, every basket has the same number of berries!","ru":"Смотри, в каждой корзинке одинаково ягод!"},"explanation":[{"en":"Equal groups have the same number in each group.","ru":"В равных группах поровну предметов."},{"en":"3 groups of 4: 4 + 4 + 4 = 12.","ru":"3 группы по 4: 4 + 4 + 4 = 12."}],"example":{"kind":"groups","emoji":"🍓","groups":3,"per":4,"caption":{"en":"3 groups of 4 = 12","ru":"3 группы по 4 = 12"}},"masteryScore":0.8,"reviewTips":{"en":"Draw circles for groups and dots inside. Then count by the group size.","ru":"Нарисуй кружки-группы и точки внутри. Считай группами."},"status":"reviewed"}'::jsonb, 2, 8, '{"objective":{"en":"Find the total of equal groups by repeated addition.","ru":"Находить общее количество в равных группах с помощью сложения."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.multiplication.l1', 'math.multiplication', '{"en":"Multiplication","ru":"Умножение"}'::jsonb, '{"id":"math.multiplication.l1","topicId":"math.multiplication","title":{"en":"Multiplication","ru":"Умножение"},"subtopic":{"en":"Equal groups and times tables","ru":"Равные группы и таблица умножения"},"objective":{"en":"Understand 3 × 4 as 3 groups of 4 and recall times-table facts.","ru":"Понимать 3 × 4 как 3 группы по 4 и знать таблицу умножения."},"ageRange":[7,11],"grades":[2,3],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Adding the same number many times? Multiplication is the shortcut!","ru":"Много раз складываешь одно и то же? Умножение — короткий путь!"},"explanation":[{"en":"Multiplication is a fast way to add equal groups. 3 × 4 means 3 groups of 4: 4 + 4 + 4 = 12.","ru":"Умножение — быстрый способ сложить равные группы. 3 × 4 — это 3 группы по 4: 4 + 4 + 4 = 12."},{"en":"You can swap the numbers: 3 × 4 = 4 × 3 = 12.","ru":"Множители можно поменять местами: 3 × 4 = 4 × 3 = 12."},{"en":"Handy tricks: × 2 is doubling, × 5 ends in 0 or 5, × 10 adds a 0.","ru":"Подсказки: × 2 — это удвоение, × 5 оканчивается на 0 или 5, × 10 — дописываем 0."}],"example":{"kind":"groups","emoji":"🌸","groups":3,"per":4,"caption":{"en":"3 × 4 = 12","ru":"3 × 4 = 12"}},"generated":[{"generator":"mult-table","count":5}],"game":"math-challenge","masteryScore":0.8,"reviewTips":{"en":"Say one table a day out loud, and use swapping: if you know 3 × 7, you know 7 × 3.","ru":"Повторяй вслух по одному столбику в день и меняй множители местами: знаешь 3 × 7 — знаешь и 7 × 3."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Understand 3 × 4 as 3 groups of 4 and recall times-table facts.","ru":"Понимать 3 × 4 как 3 группы по 4 и знать таблицу умножения."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.division.l1', 'math.division', '{"en":"Division","ru":"Деление"}'::jsonb, '{"id":"math.division.l1","topicId":"math.division","title":{"en":"Division","ru":"Деление"},"subtopic":{"en":"Sharing equally and the link to multiplication","ru":"Деление поровну и связь с умножением"},"objective":{"en":"Divide using times tables and understand remainders.","ru":"Делить с помощью таблицы умножения и понимать остаток."},"ageRange":[8,12],"grades":[3,4],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Let''s share the sweets so everyone gets the same!","ru":"Разделим конфеты так, чтобы всем досталось поровну!"},"explanation":[{"en":"Division means sharing equally. 12 ÷ 3: share 12 sweets among 3 friends, and each gets 4.","ru":"Делить — значит раздавать поровну. 12 ÷ 3: делим 12 конфет на 3 друзей, каждому по 4."},{"en":"Division undoes multiplication: 3 × 4 = 12, so 12 ÷ 3 = 4 and 12 ÷ 4 = 3.","ru":"Деление обратно умножению: 3 × 4 = 12, значит 12 ÷ 3 = 4 и 12 ÷ 4 = 3."},{"en":"Sometimes some are left over: 13 ÷ 4 = 3, remainder 1. The remainder is always smaller than the divisor.","ru":"Иногда что-то остаётся: 13 : 4 = 3 (ост. 1). Остаток всегда меньше делителя."}],"example":{"kind":"groups","emoji":"🍬","groups":3,"per":4,"caption":{"en":"12 ÷ 3 = 4","ru":"12 : 3 = 4"}},"generated":[{"generator":"div-table","count":5}],"game":"math-challenge","masteryScore":0.8,"reviewTips":{"en":"For every division, ask: which multiplication fact helps here?","ru":"При делении спрашивай себя: какой пример из таблицы умножения поможет?"},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Divide using times tables and understand remainders.","ru":"Делить с помощью таблицы умножения и понимать остаток."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.word-problems.l1', 'math.word-problems', '{"en":"Story problems","ru":"Задачи-истории"}'::jsonb, '{"id":"math.word-problems.l1","topicId":"math.word-problems","title":{"en":"Story problems","ru":"Задачи-истории"},"subtopic":{"en":"Choosing the right operation","ru":"Выбираем нужное действие"},"objective":{"en":"Read a short story, find the question and choose +, −, × or ÷.","ru":"Читать короткую задачу, находить вопрос и выбирать +, −, × или :."},"ageRange":[6,12],"grades":[1,4],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Every story hides a math puzzle. Let''s be detectives!","ru":"В каждой истории спрятана задачка. Станем сыщиками!"},"explanation":[{"en":"Read the story. Find the question. What do we need to know?","ru":"Прочитай условие. Найди вопрос. Что нужно узнать?"},{"en":"\"In all\", \"altogether\" → add. \"Left\", \"how many more\" → subtract. Equal groups → multiply or divide.","ru":"«Всего», «вместе» — складываем. «Осталось», «на сколько больше» — вычитаем. Равные группы — умножаем или делим."},{"en":"At the end, check: does the answer make sense?","ru":"В конце проверь: подходит ли ответ к истории?"}],"example":{"kind":"emoji","items":["🍎","🍎","🍎","➕","🍎","🍎","🟰","❓"],"caption":{"en":"Tom has 3 apples and gets 2 more: 3 + 2 = 5.","ru":"У Тома 3 яблока, ему дали ещё 2: 3 + 2 = 5."}},"generated":[{"generator":"add-within-20","count":2},{"generator":"sub-within-20","count":2}],"masteryScore":0.8,"reviewTips":{"en":"Draw the story with little pictures, then write the number sentence.","ru":"Нарисуй историю маленькими картинками, а потом запиши пример."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Read a short story, find the question and choose +, −, × or ÷.","ru":"Читать короткую задачу, находить вопрос и выбирать +, −, × или :."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.measurement.l1', 'math.measurement', '{"en":"Measuring things","ru":"Измеряем величины"}'::jsonb, '{"id":"math.measurement.l1","topicId":"math.measurement","title":{"en":"Measuring things","ru":"Измеряем величины"},"subtopic":{"en":"Length, mass, time and money","ru":"Длина, масса, время и деньги"},"objective":{"en":"Use units of length, mass, time and money and convert between them.","ru":"Пользоваться единицами длины, массы, времени и денег и переводить одни в другие."},"ageRange":[7,12],"grades":[2,4],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"How long? How heavy? How much time? Let''s measure!","ru":"Какой длины? Сколько весит? Сколько времени? Давай измерять!"},"explanation":[{"en":"Length: 1 m = 100 cm, 1 km = 1000 m. Mass: 1 kg = 1000 g.","ru":"Длина: 1 м = 100 см, 1 км = 1000 м. Масса: 1 кг = 1000 г."},{"en":"Time: 1 hour = 60 minutes, 1 minute = 60 seconds, 1 day = 24 hours.","ru":"Время: 1 час = 60 минут, 1 минута = 60 секунд, сутки = 24 часа."},{"en":"Money: 1 dollar = 100 cents. Always write the unit next to the number!","ru":"Деньги: 1 рубль = 100 копеек. Всегда пиши единицу рядом с числом!"}],"example":{"kind":"text","text":{"en":"1 m = 100 cm · 1 kg = 1000 g · 1 h = 60 min","ru":"1 м = 100 см · 1 кг = 1000 г · 1 ч = 60 мин"}},"masteryScore":0.8,"reviewTips":{"en":"Learn the key facts: 100 cm in a metre, 1000 g in a kilogram, 60 minutes in an hour.","ru":"Запомни главное: в метре 100 см, в килограмме 1000 г, в часе 60 минут."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Use units of length, mass, time and money and convert between them.","ru":"Пользоваться единицами длины, массы, времени и денег и переводить одни в другие."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.area-perimeter.l1', 'math.area-perimeter', '{"en":"Area and perimeter","ru":"Площадь и периметр"}'::jsonb, '{"id":"math.area-perimeter.l1","topicId":"math.area-perimeter","title":{"en":"Area and perimeter","ru":"Площадь и периметр"},"subtopic":{"en":"Around the shape and inside the shape","ru":"Вокруг фигуры и внутри фигуры"},"objective":{"en":"Find the perimeter and area of rectangles and squares.","ru":"Находить периметр и площадь прямоугольника и квадрата."},"ageRange":[8,13],"grades":[3,5],"difficulty":3,"durationMin":12,"character":"oli","intro":{"en":"A fence goes around, a carpet covers inside. Let''s measure both!","ru":"Забор — вокруг, ковёр — внутри. Измерим и то, и другое!"},"explanation":[{"en":"Perimeter is the distance around a shape: add all the sides. For a rectangle P = 2 × (a + b).","ru":"Периметр — длина границы фигуры: сложи все стороны. У прямоугольника P = 2 · (a + b)."},{"en":"Area is how many unit squares cover the shape. For a rectangle S = a × b, measured in square units like cm².","ru":"Площадь — сколько единичных квадратов покрывает фигуру. У прямоугольника S = a · b, единицы — квадратные, например см²."},{"en":"A 5 cm by 3 cm rectangle: P = 2 × (5 + 3) = 16 cm, S = 5 × 3 = 15 cm².","ru":"Прямоугольник 5 см на 3 см: P = 2 · (5 + 3) = 16 см, S = 5 · 3 = 15 см²."}],"example":{"kind":"groups","emoji":"🟦","groups":3,"per":5,"caption":{"en":"3 rows of 5 squares: area = 15 cm²","ru":"3 ряда по 5 квадратов: площадь = 15 см²"}},"generated":[{"generator":"area-rect","count":2},{"generator":"perimeter-rect","count":2}],"masteryScore":0.8,"reviewTips":{"en":"Perimeter: add the sides. Area: multiply length by width. Check your units: cm or cm².","ru":"Периметр — складываем стороны. Площадь — умножаем длину на ширину. Следи за единицами: см или см²."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Find the perimeter and area of rectangles and squares.","ru":"Находить периметр и площадь прямоугольника и квадрата."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.fractions.l1', 'math.fractions', '{"en":"Fractions","ru":"Дроби"}'::jsonb, '{"id":"math.fractions.l1","topicId":"math.fractions","title":{"en":"Fractions","ru":"Дроби"},"subtopic":{"en":"Parts of a whole, equal fractions, comparing","ru":"Части целого, равные дроби, сравнение"},"objective":{"en":"Read, compare and find equivalent fractions.","ru":"Читать, сравнивать дроби и находить равные дроби."},"ageRange":[8,13],"grades":[3,5],"difficulty":3,"durationMin":12,"character":"oli","intro":{"en":"Let''s cut a pizza into equal slices and learn fractions!","ru":"Разрежем пиццу на равные кусочки и узнаем, что такое дроби!"},"explanation":[{"en":"A fraction shows parts of a whole. In 3/4 the whole is cut into 4 equal parts (the denominator) and we take 3 (the numerator).","ru":"Дробь показывает части целого. В 3/4 целое разрезали на 4 равные части (знаменатель) и взяли 3 (числитель)."},{"en":"Equivalent fractions: 1/2 = 2/4 = 3/6. Multiply top and bottom by the same number.","ru":"Равные дроби: 1/2 = 2/4 = 3/6. Числитель и знаменатель умножаем на одно и то же число."},{"en":"Same denominator: the bigger numerator wins, 3/5 > 2/5. Same numerator: fewer parts means bigger parts, 1/3 > 1/4.","ru":"Знаменатели одинаковые — больше та, у которой больше числитель: 3/5 > 2/5. Числители одинаковые — меньше частей значит крупнее части: 1/3 > 1/4."}],"example":{"kind":"fraction","num":3,"den":4,"caption":{"en":"3 of 4 equal parts: 3/4","ru":"3 из 4 равных частей: 3/4"}},"generated":[{"generator":"fraction-compare","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Draw a bar, cut it into equal parts and shade. Pictures make fractions easy.","ru":"Нарисуй полоску, раздели её на равные части и закрась. С рисунком дроби понятнее."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Read, compare and find equivalent fractions.","ru":"Читать, сравнивать дроби и находить равные дроби."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.decimals.l1', 'math.decimals', '{"en":"Decimals","ru":"Десятичные дроби"}'::jsonb, '{"id":"math.decimals.l1","topicId":"math.decimals","title":{"en":"Decimals","ru":"Десятичные дроби"},"subtopic":{"en":"Tenths, hundredths and calculations","ru":"Десятые, сотые и вычисления"},"objective":{"en":"Read, compare, add and subtract decimals.","ru":"Читать, сравнивать, складывать и вычитать десятичные дроби."},"ageRange":[10,14],"grades":[5,6],"difficulty":3,"durationMin":12,"character":"oli","intro":{"en":"Prices and measurements often have a point in them. Let''s master decimals!","ru":"В ценах и измерениях часто встречается запятая. Разберёмся с десятичными дробями!"},"explanation":[{"en":"Decimals are tenths and hundredths written with a point: 0.3 = 3/10, 0.07 = 7/100.","ru":"Десятичная дробь — это десятые и сотые, записанные через запятую: 0,3 = 3/10, 0,07 = 7/100."},{"en":"Place value continues after the point: 2.45 = 2 ones, 4 tenths, 5 hundredths.","ru":"Разряды продолжаются после запятой: 2,45 = 2 единицы, 4 десятых, 5 сотых."},{"en":"To add or subtract, line up the decimal points. You can add zeros at the end: 2.5 = 2.50.","ru":"При сложении и вычитании запятая пишется под запятой. Нули в конце можно дописывать: 2,5 = 2,50."}],"example":{"kind":"equation","text":"1.25 + 2.50 = 3.75","caption":{"en":"Line up the points.","ru":"Запятая под запятой."}},"generated":[{"generator":"decimal-add","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Always line up the decimal points and fill empty places with zeros.","ru":"Всегда пиши запятую под запятой и дописывай нули в пустые разряды."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Read, compare, add and subtract decimals.","ru":"Читать, сравнивать, складывать и вычитать десятичные дроби."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.percentages.l1', 'math.percentages', '{"en":"Percentages","ru":"Проценты"}'::jsonb, '{"id":"math.percentages.l1","topicId":"math.percentages","title":{"en":"Percentages","ru":"Проценты"},"subtopic":{"en":"Parts of 100 and percent of a number","ru":"Сотые части и процент от числа"},"objective":{"en":"Convert percents to fractions and decimals and find a percent of a number.","ru":"Переводить проценты в дроби и находить процент от числа."},"ageRange":[10,14],"grades":[5,6],"difficulty":3,"durationMin":10,"character":"oli","intro":{"en":"Sales, batteries, test scores: percents are everywhere!","ru":"Скидки, заряд батареи, оценки — проценты повсюду!"},"explanation":[{"en":"Percent means \"out of a hundred\": 25% = 25/100 = 0.25.","ru":"Процент — это одна сотая: 25% = 25/100 = 0,25."},{"en":"To find a percent of a number, multiply: 20% of 50 = 0.2 × 50 = 10.","ru":"Чтобы найти процент от числа, умножаем: 20% от 50 = 0,2 · 50 = 10."},{"en":"Handy facts: 50% is half, 25% is a quarter, 10% means divide by 10.","ru":"Полезно помнить: 50% — половина, 25% — четверть, 10% — делим на 10."}],"example":{"kind":"equation","text":"20% of 50 = 0.2 × 50 = 10","caption":{"en":"Percent → decimal → multiply","ru":"Проценты → десятичная дробь → умножение"}},"generated":[{"generator":"percent-of","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Start with 10% (divide by 10), then build other percents from it.","ru":"Начинай с 10% (раздели на 10), а из них собирай другие проценты."},"status":"reviewed"}'::jsonb, 3, 10, '{"objective":{"en":"Convert percents to fractions and decimals and find a percent of a number.","ru":"Переводить проценты в дроби и находить процент от числа."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.ratios.l1', 'math.ratios', '{"en":"Ratios and proportions","ru":"Отношения и пропорции"}'::jsonb, '{"id":"math.ratios.l1","topicId":"math.ratios","title":{"en":"Ratios and proportions","ru":"Отношения и пропорции"},"subtopic":{"en":"Comparing quantities and scaling","ru":"Сравнение величин и масштабирование"},"objective":{"en":"Write and simplify ratios and solve simple proportions.","ru":"Записывать и упрощать отношения и решать простые пропорции."},"ageRange":[11,14],"grades":[6,6],"difficulty":3,"durationMin":12,"character":"oli","intro":{"en":"Recipes, maps and mixing paint all use ratios. Let''s learn how!","ru":"Рецепты, карты, смешивание красок — везде отношения. Разберёмся!"},"explanation":[{"en":"A ratio compares two quantities. 2 cats and 3 dogs: cats to dogs is 2 : 3.","ru":"Отношение сравнивает две величины. 2 кошки и 3 собаки: кошек к собакам 2 : 3."},{"en":"Simplify ratios like fractions: divide both parts by the same number. 6 : 9 = 2 : 3.","ru":"Отношения упрощают как дроби: обе части делят на одно число. 6 : 9 = 2 : 3."},{"en":"A proportion says two ratios are equal: a/b = c/d. Then a · d = b · c, which helps find a missing number.","ru":"Пропорция — равенство двух отношений: a/b = c/d. Тогда a · d = b · c — так находят неизвестное."}],"example":{"kind":"emoji","items":["🐱","🐱","🐶","🐶","🐶"],"caption":{"en":"cats : dogs = 2 : 3","ru":"кошки : собаки = 2 : 3"}},"masteryScore":0.8,"reviewTips":{"en":"Find the value of one unit first, then scale up.","ru":"Сначала найди, сколько приходится на одну единицу, а потом умножай."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Write and simplify ratios and solve simple proportions.","ru":"Записывать и упрощать отношения и решать простые пропорции."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.negative-numbers.l1', 'math.negative-numbers', '{"en":"Negative numbers","ru":"Отрицательные числа"}'::jsonb, '{"id":"math.negative-numbers.l1","topicId":"math.negative-numbers","title":{"en":"Negative numbers","ru":"Отрицательные числа"},"subtopic":{"en":"Below zero on the number line","ru":"Ниже нуля на числовой прямой"},"objective":{"en":"Compare, add and subtract positive and negative numbers.","ru":"Сравнивать, складывать и вычитать положительные и отрицательные числа."},"ageRange":[11,14],"grades":[6,6],"difficulty":3,"durationMin":12,"character":"oli","intro":{"en":"Brr, it''s −5 °C outside! Let''s explore numbers below zero.","ru":"Брр, на улице −5 °C! Исследуем числа меньше нуля."},"explanation":[{"en":"Numbers below zero are negative: −1, −2, −3... You see them on thermometers.","ru":"Числа меньше нуля — отрицательные: −1, −2, −3... Их можно увидеть на термометре."},{"en":"On the number line, numbers further left are smaller: −5 < −2 < 0 < 3.","ru":"На числовой прямой левее — значит меньше: −5 < −2 < 0 < 3."},{"en":"Adding a positive moves right, subtracting moves left: 3 − 5 = −2. Subtracting a negative moves right: 2 − (−3) = 2 + 3 = 5.","ru":"Прибавляем положительное — идём вправо, вычитаем — влево: 3 − 5 = −2. Вычесть отрицательное — значит прибавить: 2 − (−3) = 2 + 3 = 5."}],"example":{"kind":"numberline","from":-5,"to":5,"marks":[-2,3],"caption":{"en":"3 − 5 = −2: five steps left","ru":"3 − 5 = −2: пять шагов влево"}},"generated":[{"generator":"negative-add","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Sketch a number line and move step by step: right for plus, left for minus.","ru":"Нарисуй числовую прямую и двигайся по шагам: плюс — вправо, минус — влево."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Compare, add and subtract positive and negative numbers.","ru":"Сравнивать, складывать и вычитать положительные и отрицательные числа."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.coordinates.l1', 'math.coordinates', '{"en":"The coordinate plane","ru":"Координатная плоскость"}'::jsonb, '{"id":"math.coordinates.l1","topicId":"math.coordinates","title":{"en":"The coordinate plane","ru":"Координатная плоскость"},"subtopic":{"en":"Plotting and reading points (x, y)","ru":"Отмечаем и читаем точки (x, y)"},"objective":{"en":"Plot and read points in all four quadrants.","ru":"Отмечать и читать точки во всех четырёх четвертях."},"ageRange":[11,15],"grades":[6,7],"difficulty":3,"durationMin":10,"character":"oli","intro":{"en":"Every point has an address. Let''s learn to read it!","ru":"У каждой точки есть адрес. Научимся его читать!"},"explanation":[{"en":"The plane has a horizontal x-axis and a vertical y-axis. They cross at the origin (0, 0).","ru":"На плоскости есть горизонтальная ось x и вертикальная ось y. Они пересекаются в начале координат (0; 0)."},{"en":"For a point (x, y), move along x first, then along y. (3, −2) means 3 right and 2 down.","ru":"Для точки (x; y) сначала двигаемся по x, потом по y. (3; −2) — 3 вправо и 2 вниз."},{"en":"The axes make four quadrants: I (+, +), II (−, +), III (−, −), IV (+, −).","ru":"Оси делят плоскость на четыре четверти: I (+; +), II (−; +), III (−; −), IV (+; −)."}],"example":{"kind":"text","text":{"en":"(3, 2): 3 steps right →, then 2 steps up ↑","ru":"(3; 2): 3 шага вправо →, затем 2 шага вверх ↑"}},"masteryScore":0.8,"reviewTips":{"en":"Remember: walk along the corridor (x) before going up the stairs (y).","ru":"Запомни: сначала идём по коридору (x), потом по лестнице (y)."},"status":"reviewed"}'::jsonb, 3, 10, '{"objective":{"en":"Plot and read points in all four quadrants.","ru":"Отмечать и читать точки во всех четырёх четвертях."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.equations.l1', 'math.equations', '{"en":"Solving equations","ru":"Решаем уравнения"}'::jsonb, '{"id":"math.equations.l1","topicId":"math.equations","title":{"en":"Solving equations","ru":"Решаем уравнения"},"subtopic":{"en":"Inverse operations and balance","ru":"Обратные действия и равновесие"},"objective":{"en":"Solve one- and two-step linear equations and check the answer.","ru":"Решать линейные уравнения в одно и два действия и проверять ответ."},"ageRange":[10,15],"grades":[5,7],"difficulty":3,"durationMin":12,"character":"oli","intro":{"en":"An equation is like a balance scale. Let''s keep it level and find x!","ru":"Уравнение похоже на весы. Сохраним равновесие и найдём x!"},"explanation":[{"en":"An equation is a balance: both sides are equal. Whatever you do to one side, do to the other.","ru":"Уравнение — это весы: обе части равны. Что делаешь с одной частью, делай и с другой."},{"en":"Undo with the inverse operation: x + 5 = 12 → x = 12 − 5 = 7. 3x = 21 → x = 21 ÷ 3 = 7.","ru":"Используй обратное действие: x + 5 = 12 → x = 12 − 5 = 7. 3x = 21 → x = 21 : 3 = 7."},{"en":"Two steps: 2x + 3 = 11 → 2x = 8 → x = 4. Check: 2 · 4 + 3 = 11.","ru":"В два шага: 2x + 3 = 11 → 2x = 8 → x = 4. Проверка: 2 · 4 + 3 = 11."}],"example":{"kind":"equation","text":"2x + 3 = 11 → 2x = 8 → x = 4","caption":{"en":"Subtract 3, then divide by 2.","ru":"Вычитаем 3, потом делим на 2."}},"generated":[{"generator":"linear-eq","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Undo operations in reverse order and always check by substituting your answer.","ru":"Отменяй действия в обратном порядке и всегда делай проверку подстановкой."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Solve one- and two-step linear equations and check the answer.","ru":"Решать линейные уравнения в одно и два действия и проверять ответ."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.powers.l1', 'math.powers', '{"en":"Powers and roots","ru":"Степени и корни"}'::jsonb, '{"id":"math.powers.l1","topicId":"math.powers","title":{"en":"Powers and roots","ru":"Степени и корни"},"subtopic":{"en":"Exponents, power rules and square roots","ru":"Показатели, свойства степеней и квадратные корни"},"objective":{"en":"Evaluate powers, apply power rules and find square roots.","ru":"Вычислять степени, применять их свойства и находить квадратные корни."},"ageRange":[12,16],"grades":[7,8],"difficulty":4,"durationMin":12,"character":"oli","intro":{"en":"Powers let us write huge numbers in a tiny way. Let''s power up!","ru":"Степени помогают коротко записывать огромные числа. Поехали!"},"explanation":[{"en":"A power is repeated multiplication: 2⁵ = 2 · 2 · 2 · 2 · 2 = 32. Here 2 is the base and 5 is the exponent.","ru":"Степень — это повторное умножение: 2⁵ = 2 · 2 · 2 · 2 · 2 = 32. Здесь 2 — основание, 5 — показатель."},{"en":"Rules: aᵐ · aⁿ = aᵐ⁺ⁿ, aᵐ ÷ aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, and a⁰ = 1 (a ≠ 0).","ru":"Свойства: aᵐ · aⁿ = aᵐ⁺ⁿ, aᵐ : aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁰ = 1 (a ≠ 0)."},{"en":"The square root √b is the non-negative number whose square is b: √49 = 7 because 7² = 49.","ru":"Квадратный корень √b — неотрицательное число, квадрат которого равен b: √49 = 7, так как 7² = 49."}],"example":{"kind":"equation","text":"3⁴ = 3 · 3 · 3 · 3 = 81","caption":{"en":"Base 3, exponent 4","ru":"Основание 3, показатель 4"}},"generated":[{"generator":"power","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Learn the squares from 1² to 15² by heart, and write out the rules on a card.","ru":"Выучи квадраты чисел от 1 до 15 и выпиши свойства степеней на карточку."},"status":"reviewed"}'::jsonb, 4, 12, '{"objective":{"en":"Evaluate powers, apply power rules and find square roots.","ru":"Вычислять степени, применять их свойства и находить квадратные корни."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.probability.l1', 'math.probability', '{"en":"Probability","ru":"Вероятность"}'::jsonb, '{"id":"math.probability.l1","topicId":"math.probability","title":{"en":"Probability","ru":"Вероятность"},"subtopic":{"en":"Chance as a number from 0 to 1","ru":"Шанс как число от 0 до 1"},"objective":{"en":"Find the probability of simple events with equally likely outcomes.","ru":"Находить вероятность простых событий с равновозможными исходами."},"ageRange":[12,17],"grades":[7,9],"difficulty":4,"durationMin":12,"character":"oli","intro":{"en":"Will the coin land on heads? Let''s measure chance with numbers!","ru":"Выпадет ли орёл? Давай измерим шансы числами!"},"explanation":[{"en":"Probability shows how likely an event is, from 0 (impossible) to 1 (certain).","ru":"Вероятность показывает, насколько возможно событие: от 0 (невозможно) до 1 (обязательно произойдёт)."},{"en":"With equally likely outcomes: P = favourable outcomes ÷ all outcomes. On a die, P(even) = 3/6 = 1/2.","ru":"При равновозможных исходах: P = благоприятные исходы : все исходы. На кубике P(чётное) = 3/6 = 1/2."},{"en":"The chance that an event does not happen: P(not A) = 1 − P(A).","ru":"Вероятность того, что событие не произойдёт: P(не A) = 1 − P(A)."}],"example":{"kind":"emoji","items":["🔴","🔴","🔴","🔵"],"caption":{"en":"P(red) = 3/4","ru":"P(красный) = 3/4"}},"masteryScore":0.8,"reviewTips":{"en":"List all outcomes first, then count the favourable ones.","ru":"Сначала выпиши все исходы, потом посчитай благоприятные."},"status":"reviewed"}'::jsonb, 4, 12, '{"objective":{"en":"Find the probability of simple events with equally likely outcomes.","ru":"Находить вероятность простых событий с равновозможными исходами."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.statistics.l1', 'math.statistics', '{"en":"Statistics","ru":"Статистика"}'::jsonb, '{"id":"math.statistics.l1","topicId":"math.statistics","title":{"en":"Statistics","ru":"Статистика"},"subtopic":{"en":"Mean, median, mode and range","ru":"Среднее, медиана, мода и размах"},"objective":{"en":"Calculate mean, median, mode and range and choose a suitable average.","ru":"Вычислять среднее, медиану, моду и размах и выбирать подходящую характеристику."},"ageRange":[12,17],"grades":[7,9],"difficulty":4,"durationMin":12,"character":"oli","intro":{"en":"Data tells stories. Let''s learn the numbers that summarise them!","ru":"Данные рассказывают истории. Узнаем, какие числа их описывают!"},"explanation":[{"en":"Mean = sum ÷ count. Median = the middle value after sorting (with two middles, take their mean). Mode = the most frequent value.","ru":"Среднее = сумма : количество. Медиана — середина упорядоченного ряда (если середин две — их среднее). Мода — самое частое значение."},{"en":"Range = largest − smallest. It shows how spread out the data is.","ru":"Размах = наибольшее − наименьшее. Он показывает разброс данных."},{"en":"Data 2, 3, 3, 5, 7: mean 4, median 3, mode 3, range 5.","ru":"Ряд 2, 3, 3, 5, 7: среднее 4, медиана 3, мода 3, размах 5."}],"example":{"kind":"text","text":{"en":"2, 3, 3, 5, 7 → mean = 20 ÷ 5 = 4, median = 3, mode = 3","ru":"2, 3, 3, 5, 7 → среднее = 20 : 5 = 4, медиана = 3, мода = 3"}},"generated":[{"generator":"mean","count":4}],"masteryScore":0.8,"reviewTips":{"en":"Always sort the data first: median, mode and range become easy to spot.","ru":"Всегда сначала упорядочи данные — так легко увидеть медиану, моду и размах."},"status":"reviewed"}'::jsonb, 4, 12, '{"objective":{"en":"Calculate mean, median, mode and range and choose a suitable average.","ru":"Вычислять среднее, медиану, моду и размах и выбирать подходящую характеристику."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.functions.l1', 'math.functions', '{"en":"Linear functions","ru":"Линейная функция"}'::jsonb, '{"id":"math.functions.l1","topicId":"math.functions","title":{"en":"Linear functions","ru":"Линейная функция"},"subtopic":{"en":"y = kx + b and its graph","ru":"y = kx + b и её график"},"objective":{"en":"Evaluate a linear function and read slope and intercept from its formula.","ru":"Вычислять значения линейной функции и определять k и b по формуле."},"ageRange":[12,17],"grades":[7,9],"difficulty":4,"durationMin":13,"character":"oli","intro":{"en":"Feed a number into a function machine and see what comes out!","ru":"Положи число в «машину-функцию» и посмотри, что получится!"},"explanation":[{"en":"A function gives exactly one output y for every input x.","ru":"Функция каждому значению x ставит в соответствие ровно одно значение y."},{"en":"A linear function y = kx + b has a straight-line graph. k is the slope (how much y changes when x grows by 1); b is where the line crosses the y-axis.","ru":"График линейной функции y = kx + b — прямая. k — угловой коэффициент (на сколько меняется y при увеличении x на 1), b — точка пересечения с осью y."},{"en":"y = 2x + 1: x = 0 → y = 1, x = 1 → y = 3, x = 2 → y = 5. k > 0: the line goes up; k < 0: it goes down.","ru":"y = 2x + 1: x = 0 → y = 1, x = 1 → y = 3, x = 2 → y = 5. Если k > 0, прямая идёт вверх, если k < 0 — вниз."}],"example":{"kind":"equation","text":"y = 2x + 1:  (0, 1), (1, 3), (2, 5)","caption":{"en":"Each step right, y goes up by 2.","ru":"Шаг вправо — y растёт на 2."}},"masteryScore":0.8,"reviewTips":{"en":"Make a small table of x and y values, then plot the points.","ru":"Составь небольшую таблицу значений x и y и отметь точки."},"status":"reviewed"}'::jsonb, 4, 13, '{"objective":{"en":"Evaluate a linear function and read slope and intercept from its formula.","ru":"Вычислять значения линейной функции и определять k и b по формуле."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.quadratics.l1', 'math.quadratics', '{"en":"Quadratic equations","ru":"Квадратные уравнения"}'::jsonb, '{"id":"math.quadratics.l1","topicId":"math.quadratics","title":{"en":"Quadratic equations","ru":"Квадратные уравнения"},"subtopic":{"en":"The discriminant and the root formula","ru":"Дискриминант и формула корней"},"objective":{"en":"Solve ax² + bx + c = 0 using the discriminant.","ru":"Решать уравнения ax² + bx + c = 0 через дискриминант."},"ageRange":[13,17],"grades":[8,9],"difficulty":4,"durationMin":15,"character":"oli","intro":{"en":"One formula solves every quadratic. Let''s learn it step by step!","ru":"Одна формула решает любое квадратное уравнение. Разберём её по шагам!"},"explanation":[{"en":"A quadratic equation has the form ax² + bx + c = 0 with a ≠ 0.","ru":"Квадратное уравнение имеет вид ax² + bx + c = 0, где a ≠ 0."},{"en":"Discriminant D = b² − 4ac. D > 0: two roots. D = 0: one root. D < 0: no real roots.","ru":"Дискриминант D = b² − 4ac. D > 0 — два корня, D = 0 — один корень, D < 0 — действительных корней нет."},{"en":"Roots: x = (−b ± √D) ÷ (2a). For x² − 5x + 6 = 0: D = 25 − 24 = 1, so x = 2 or x = 3.","ru":"Корни: x = (−b ± √D) / (2a). Для x² − 5x + 6 = 0: D = 25 − 24 = 1, значит x = 2 или x = 3."}],"example":{"kind":"equation","text":"x² − 5x + 6 = 0;  D = 1;  x = (5 ± 1) / 2 → 2, 3","caption":{"en":"Find D, then use the formula.","ru":"Находим D, затем применяем формулу."}},"generated":[{"generator":"quadratic-roots","count":3}],"masteryScore":0.8,"reviewTips":{"en":"Write a, b, c with their signs before computing D, and check the roots by substituting.","ru":"Выписывай a, b, c вместе со знаками до вычисления D и проверяй корни подстановкой."},"status":"reviewed"}'::jsonb, 4, 15, '{"objective":{"en":"Solve ax² + bx + c = 0 using the discriminant.","ru":"Решать уравнения ax² + bx + c = 0 через дискриминант."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.geometry.l1', 'math.geometry', '{"en":"Angles, triangles and Pythagoras","ru":"Углы, треугольники и Пифагор"}'::jsonb, '{"id":"math.geometry.l1","topicId":"math.geometry","title":{"en":"Angles, triangles and Pythagoras","ru":"Углы, треугольники и Пифагор"},"subtopic":{"en":"Angle sums and Pythagoras'' theorem","ru":"Сумма углов и теорема Пифагора"},"objective":{"en":"Use angle facts and Pythagoras'' theorem to find unknown angles and sides.","ru":"Находить неизвестные углы и стороны с помощью свойств углов и теоремы Пифагора."},"ageRange":[12,17],"grades":[7,9],"difficulty":4,"durationMin":13,"character":"oli","intro":{"en":"Triangles are everywhere, from bridges to roofs. Let''s discover their secrets!","ru":"Треугольники повсюду — в мостах и крышах. Раскроем их секреты!"},"explanation":[{"en":"The angles of a triangle add up to 180°. Angles on a straight line also add up to 180°; vertical angles are equal.","ru":"Сумма углов треугольника — 180°. Смежные углы в сумме тоже дают 180°, вертикальные углы равны."},{"en":"Angles: acute < 90°, right = 90°, obtuse between 90° and 180°.","ru":"Углы: острый < 90°, прямой = 90°, тупой — от 90° до 180°."},{"en":"Pythagoras: in a right triangle with legs a, b and hypotenuse c, a² + b² = c². Example: 3, 4, 5.","ru":"Теорема Пифагора: в прямоугольном треугольнике с катетами a, b и гипотенузой c a² + b² = c². Пример: 3, 4, 5."}],"example":{"kind":"equation","text":"3² + 4² = 9 + 16 = 25 = 5²","caption":{"en":"Legs 3 and 4, hypotenuse 5","ru":"Катеты 3 и 4, гипотенуза 5"}},"masteryScore":0.8,"reviewTips":{"en":"Sketch the figure and mark what you know. The hypotenuse is always the longest side.","ru":"Сделай чертёж и отметь известное. Гипотенуза всегда самая длинная сторона."},"status":"reviewed"}'::jsonb, 4, 13, '{"objective":{"en":"Use angle facts and Pythagoras'' theorem to find unknown angles and sides.","ru":"Находить неизвестные углы и стороны с помощью свойств углов и теоремы Пифагора."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.trigonometry.l1', 'math.trigonometry', '{"en":"Sine, cosine, tangent","ru":"Синус, косинус, тангенс"}'::jsonb, '{"id":"math.trigonometry.l1","topicId":"math.trigonometry","title":{"en":"Sine, cosine, tangent","ru":"Синус, косинус, тангенс"},"subtopic":{"en":"Trigonometric ratios in right triangles","ru":"Тригонометрические отношения в прямоугольном треугольнике"},"objective":{"en":"Find sin, cos and tan of an acute angle and use them to find sides.","ru":"Находить sin, cos и tg острого угла и вычислять с их помощью стороны."},"ageRange":[14,18],"grades":[9,10],"difficulty":5,"durationMin":14,"character":"oli","intro":{"en":"With trigonometry you can measure a tree without climbing it!","ru":"С тригонометрией можно измерить дерево, не залезая на него!"},"explanation":[{"en":"For an acute angle α in a right triangle: sin α = opposite ÷ hypotenuse, cos α = adjacent ÷ hypotenuse, tan α = opposite ÷ adjacent.","ru":"Для острого угла α прямоугольного треугольника: sin α = противолежащий катет / гипотенуза, cos α = прилежащий катет / гипотенуза, tg α = противолежащий / прилежащий."},{"en":"Key values: sin 30° = 1/2, cos 60° = 1/2, tan 45° = 1, sin 60° = √3/2.","ru":"Важные значения: sin 30° = 1/2, cos 60° = 1/2, tg 45° = 1, sin 60° = √3/2."},{"en":"For any angle: sin²α + cos²α = 1.","ru":"Для любого угла: sin²α + cos²α = 1."}],"example":{"kind":"text","text":{"en":"Triangle 3-4-5, angle α opposite side 3: sin α = 3/5, cos α = 4/5, tan α = 3/4","ru":"Треугольник 3-4-5, угол α напротив стороны 3: sin α = 3/5, cos α = 4/5, tg α = 3/4"}},"masteryScore":0.8,"reviewTips":{"en":"Label the sides opposite, adjacent and hypotenuse before writing any ratio.","ru":"Перед вычислением подпиши стороны: противолежащий катет, прилежащий катет, гипотенуза."},"status":"reviewed"}'::jsonb, 5, 14, '{"objective":{"en":"Find sin, cos and tan of an acute angle and use them to find sides.","ru":"Находить sin, cos и tg острого угла и вычислять с их помощью стороны."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.solid-geometry.l1', 'math.solid-geometry', '{"en":"Volumes and surface areas","ru":"Объёмы и площади поверхностей"}'::jsonb, '{"id":"math.solid-geometry.l1","topicId":"math.solid-geometry","title":{"en":"Volumes and surface areas","ru":"Объёмы и площади поверхностей"},"subtopic":{"en":"Prisms, cylinders, pyramids, cones and spheres","ru":"Призмы, цилиндры, пирамиды, конусы и шары"},"objective":{"en":"Calculate volumes and surface areas of common 3D shapes.","ru":"Вычислять объёмы и площади поверхностей основных тел."},"ageRange":[15,18],"grades":[10,11],"difficulty":5,"durationMin":15,"character":"oli","intro":{"en":"How much water fits in a tank? Let''s step into the third dimension!","ru":"Сколько воды поместится в бак? Шагнём в третье измерение!"},"explanation":[{"en":"Volume: cuboid V = abc; prism and cylinder V = S(base) · h, so a cylinder has V = πr²h.","ru":"Объём: прямоугольный параллелепипед V = abc; призма и цилиндр V = S(осн.) · h, для цилиндра V = πr²h."},{"en":"Pyramid and cone: V = ⅓ · S(base) · h. Sphere: V = 4/3 · πr³.","ru":"Пирамида и конус: V = ⅓ · S(осн.) · h. Шар: V = 4/3 · πr³."},{"en":"Surface area: cube 6a², sphere 4πr², cylinder 2πr² + 2πrh. Volume is in cubic units, area in square units.","ru":"Площадь поверхности: куб 6a², сфера 4πr², цилиндр 2πr² + 2πrh. Объём — в кубических единицах, площадь — в квадратных."}],"example":{"kind":"equation","text":"V = a · b · c = 2 · 3 · 4 = 24 cm³","caption":{"en":"Volume of a cuboid","ru":"Объём прямоугольного параллелепипеда"}},"masteryScore":0.8,"reviewTips":{"en":"Group formulas into families: ''base × height'' and ''one third of base × height''.","ru":"Объединяй формулы в семейства: «основание × высота» и «треть основания × высота»."},"status":"reviewed"}'::jsonb, 5, 15, '{"objective":{"en":"Calculate volumes and surface areas of common 3D shapes.","ru":"Вычислять объёмы и площади поверхностей основных тел."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.logarithms.l1', 'math.logarithms', '{"en":"Logarithms","ru":"Логарифмы"}'::jsonb, '{"id":"math.logarithms.l1","topicId":"math.logarithms","title":{"en":"Logarithms","ru":"Логарифмы"},"subtopic":{"en":"The inverse of a power and log rules","ru":"Обратное действие к степени и свойства логарифмов"},"objective":{"en":"Evaluate logarithms and apply the product, quotient and power rules.","ru":"Вычислять логарифмы и применять свойства логарифма произведения, частного и степени."},"ageRange":[15,18],"grades":[10,11],"difficulty":5,"durationMin":14,"character":"oli","intro":{"en":"Which power of 2 gives 8? The logarithm answers that question!","ru":"В какую степень возвести 2, чтобы получить 8? Ответ даёт логарифм!"},"explanation":[{"en":"logₐ b = c means aᶜ = b (a > 0, a ≠ 1, b > 0). log₂ 8 = 3 because 2³ = 8.","ru":"logₐ b = c означает aᶜ = b (a > 0, a ≠ 1, b > 0). log₂ 8 = 3, так как 2³ = 8."},{"en":"Rules: log(xy) = log x + log y, log(x/y) = log x − log y, log(xⁿ) = n · log x (same base).","ru":"Свойства (при одном основании): log(xy) = log x + log y, log(x/y) = log x − log y, log(xⁿ) = n · log x."},{"en":"Special values: logₐ 1 = 0, logₐ a = 1. lg means base 10, ln means base e.","ru":"Особые значения: logₐ 1 = 0, logₐ a = 1. lg — по основанию 10, ln — по основанию e."}],"example":{"kind":"equation","text":"log₂ 8 = 3  ⇔  2³ = 8","caption":{"en":"A log is an exponent.","ru":"Логарифм — это показатель степени."}},"masteryScore":0.8,"reviewTips":{"en":"Turn every logarithm into a power question: ''base to what power gives this number?''","ru":"Превращай логарифм в вопрос о степени: «в какую степень возвести основание, чтобы получить число?»"},"status":"reviewed"}'::jsonb, 5, 14, '{"objective":{"en":"Evaluate logarithms and apply the product, quotient and power rules.","ru":"Вычислять логарифмы и применять свойства логарифма произведения, частного и степени."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('math.calculus-intro.l1', 'math.calculus-intro', '{"en":"The derivative","ru":"Производная"}'::jsonb, '{"id":"math.calculus-intro.l1","topicId":"math.calculus-intro","title":{"en":"The derivative","ru":"Производная"},"subtopic":{"en":"Rate of change and basic rules","ru":"Скорость изменения и основные правила"},"objective":{"en":"Differentiate polynomials and use the derivative to find slopes and turning points.","ru":"Находить производные многочленов и с их помощью определять наклон и точки экстремума."},"ageRange":[15,18],"grades":[10,11],"difficulty":5,"durationMin":15,"character":"oli","intro":{"en":"How fast is something changing right now? The derivative knows!","ru":"Как быстро что-то меняется прямо сейчас? Это знает производная!"},"explanation":[{"en":"The derivative f′(x) shows how fast f changes at x. On the graph it is the slope of the tangent line.","ru":"Производная f′(x) показывает, как быстро меняется f в точке x. На графике это угловой коэффициент касательной."},{"en":"Rules: (c)′ = 0, (xⁿ)′ = n · xⁿ⁻¹, (k · f)′ = k · f′, (f + g)′ = f′ + g′.","ru":"Правила: (c)′ = 0, (xⁿ)′ = n · xⁿ⁻¹, (k · f)′ = k · f′, (f + g)′ = f′ + g′."},{"en":"f(x) = x² gives f′(x) = 2x, so at x = 3 the slope is 6. Where f′ > 0, f increases; where f′ < 0, it decreases; f′ = 0 can mark a maximum or minimum.","ru":"f(x) = x² даёт f′(x) = 2x, при x = 3 наклон равен 6. Где f′ > 0, функция возрастает, где f′ < 0 — убывает, f′ = 0 может указывать на максимум или минимум."}],"example":{"kind":"equation","text":"(x³)′ = 3x²","caption":{"en":"Bring the power down, then reduce it by 1.","ru":"Показатель выносим вперёд и уменьшаем на 1."}},"masteryScore":0.8,"reviewTips":{"en":"Practise the power rule on many terms, then evaluate at a point as a final step.","ru":"Отработай правило для степени на разных слагаемых, а значение в точке подставляй в самом конце."},"status":"reviewed"}'::jsonb, 5, 15, '{"objective":{"en":"Differentiate polynomials and use the derivative to find slopes and turning points.","ru":"Находить производные многочленов и с их помощью определять наклон и точки экстремума."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.syllables.l1', 'reading.syllables', '{"en":"Clap the Syllables","ru":"Хлопаем слоги"}'::jsonb, '{"id":"reading.syllables.l1","topicId":"reading.syllables","title":{"en":"Clap the Syllables","ru":"Хлопаем слоги"},"subtopic":{"en":"Splitting words into syllables","ru":"Деление слов на слоги"},"objective":{"en":"Split short words into syllables and count them by clapping.","ru":"Делить короткие слова на слоги и считать их хлопками."},"ageRange":[6,7],"grades":[0,1],"difficulty":1,"durationMin":8,"character":"oli","intro":{"en":"Hoo-hoo! Let''s clap our hands and discover the little parts hiding inside words!","ru":"Ух-ух! Давай похлопаем в ладоши и найдём маленькие части, которые прячутся в словах!"},"explanation":[{"en":"Words are made of small sound parts called syllables. Say a word slowly and clap once for each part: ap-ple has two claps.","ru":"Слова состоят из маленьких частей — слогов. Скажи слово медленно и хлопни на каждый слог: ма-ма — два хлопка."},{"en":"Every syllable has a vowel sound inside it. Cat has one syllable, ti-ger has two, ba-na-na has three.","ru":"Сколько в слове гласных, столько и слогов. В слове «кот» один слог, в слове «ры-ба» — два, в слове «мо-ло-ко» — три."},{"en":"Put your hand under your chin and say the word: each time your chin drops, that is a new syllable!","ru":"Положи ладошку под подбородок и скажи слово: сколько раз подбородок опустится, столько и слогов!"}],"example":{"kind":"text","text":{"en":"cat 👏   ap-ple 👏👏   ba-na-na 👏👏👏","ru":"кот 👏   ма-ма 👏👏   мо-ло-ко 👏👏👏"}},"masteryScore":0.8,"reviewTips":{"en":"Say words slowly and clap for every part. Count the vowel sounds — that is the number of syllables.","ru":"Произноси слова медленно и хлопай на каждый слог. Считай гласные — сколько гласных, столько и слогов."},"status":"reviewed"}'::jsonb, 1, 8, '{"objective":{"en":"Split short words into syllables and count them by clapping.","ru":"Делить короткие слова на слоги и считать их хлопками."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.words.l1', 'reading.words', '{"en":"Building Words","ru":"Собираем слова"}'::jsonb, '{"id":"reading.words.l1","topicId":"reading.words","title":{"en":"Building Words","ru":"Собираем слова"},"subtopic":{"en":"Blending sounds into words","ru":"Слияние звуков в слова"},"objective":{"en":"Blend letter sounds to read and build short words.","ru":"Сливать звуки и слоги, чтобы читать и составлять короткие слова."},"ageRange":[7,7],"grades":[1,1],"difficulty":1,"durationMin":10,"character":"oli","intro":{"en":"Letters are like building blocks. Let''s put them together and build real words!","ru":"Буквы — как кубики. Давай сложим их вместе и построим настоящие слова!"},"explanation":[{"en":"Every letter makes a sound. When we say the sounds one after another and glide them together, we read a word: c-a-t → cat.","ru":"Каждая буква обозначает звук. Сливаем согласный с гласным — получаем слог: к-о → ко. Из слогов складываются слова: ко-т → кот, ма-ма → мама."},{"en":"Read from left to right. If a word is long, read it in small parts first, then say it fast.","ru":"Читаем слева направо. Длинное слово сначала читаем по слогам, а потом говорим целиком."}],"example":{"kind":"text","text":{"en":"c + a + t = cat 🐱","ru":"к + о + т = кот 🐱"}},"game":"word-builder","masteryScore":0.8,"reviewTips":{"en":"Say each sound slowly, then glide them together faster and faster until you hear the word.","ru":"Читай по слогам: сначала медленно, потом быстрее, пока не услышишь целое слово."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Blend letter sounds to read and build short words.","ru":"Сливать звуки и слоги, чтобы читать и составлять короткие слова."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.sentences.l1', 'reading.sentences', '{"en":"My First Sentences","ru":"Мои первые предложения"}'::jsonb, '{"id":"reading.sentences.l1","topicId":"reading.sentences","title":{"en":"My First Sentences","ru":"Мои первые предложения"},"subtopic":{"en":"Capital letters and end marks","ru":"Большая буква и знак в конце"},"objective":{"en":"Build a sentence from words, start it with a capital letter and end it with a mark.","ru":"Составлять предложение из слов, начинать его с большой буквы и ставить знак в конце."},"ageRange":[7,8],"grades":[1,2],"difficulty":1,"durationMin":10,"character":"oli","intro":{"en":"Words love to hold hands and make sentences. Let''s help them line up!","ru":"Слова любят браться за руки и становиться предложениями. Давай поможем им встать по порядку!"},"explanation":[{"en":"A sentence is a group of words that tells a whole idea: The dog runs.","ru":"Предложение — это слова, которые выражают законченную мысль: Собака бежит."},{"en":"A sentence starts with a capital (big) letter and ends with a full stop (.), a question mark (?) or an exclamation mark (!).","ru":"Предложение начинается с большой (заглавной) буквы. В конце ставим точку (.), вопросительный (?) или восклицательный (!) знак. Слова пишем отдельно друг от друга."}],"example":{"kind":"text","text":{"en":"The dog runs. 🐶  Is it fast? 🤔  Yes! 🎉","ru":"Собака бежит. 🐶  Она быстрая? 🤔  Да! 🎉"}},"masteryScore":0.8,"reviewTips":{"en":"Check three things: Does it tell a whole idea? Does it start with a capital letter? Is there a mark at the end?","ru":"Проверь три вещи: есть ли законченная мысль? Начинается ли с большой буквы? Стоит ли знак в конце?"},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Build a sentence from words, start it with a capital letter and end it with a mark.","ru":"Составлять предложение из слов, начинать его с большой буквы и ставить знак в конце."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.spelling.l1', 'reading.spelling', '{"en":"Spelling Detectives","ru":"Детективы правописания"}'::jsonb, '{"id":"reading.spelling.l1","topicId":"reading.spelling","title":{"en":"Spelling Detectives","ru":"Детективы правописания"},"subtopic":{"en":"Magic e and tricky words","ru":"Проверяемые гласные и согласные, ЖИ-ШИ"},"objective":{"en":"Use the magic-e rule and remember common tricky words.","ru":"Проверять безударные гласные и парные согласные, писать ЖИ-ШИ с буквой И."},"ageRange":[8,10],"grades":[2,4],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Let''s become spelling detectives and crack the secret codes of words!","ru":"Давай станем детективами правописания и разгадаем тайны слов!"},"explanation":[{"en":"Magic e: an e at the end of a word is silent, but it makes the vowel before it say its name. cap → cape, kit → kite, hop → hope.","ru":"Безударную гласную проверяем ударением: измени слово так, чтобы гласная стала ударной. Вода́ — во́ды, гора́ — го́ры."},{"en":"Some words do not follow the rules — they are tricky words. We learn them by heart: said, because, friend.","ru":"Парную согласную на конце слова проверяем так, чтобы после неё стояла гласная: дуб — дубы́, лёд — льды. А словарные слова (корова, собака) запоминаем."},{"en":"Read the word, cover it, write it, then check it. Detectives always check!","ru":"Запомни правило: ЖИ-ШИ пиши с буквой И — жираф, шина, лыжи. Детективы всегда проверяют!"}],"example":{"kind":"text","text":{"en":"cap + e → cape 🧢   kit + e → kite 🪁   Tricky words: said, because, friend","ru":"гора́ → го́ры ⛰️   дуб → дубы́ 🌳   ЖИ-ШИ: жираф 🦒, шина 🛞"}},"game":"word-builder","masteryScore":0.8,"reviewTips":{"en":"Read the word, cover it, write it, check it. Remember: magic e makes the vowel say its name.","ru":"Ищи проверочное слово: для гласной — где она под ударением, для согласной — где после неё гласная."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Use the magic-e rule and remember common tricky words.","ru":"Проверять безударные гласные и парные согласные, писать ЖИ-ШИ с буквой И."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.parts-of-speech.l1', 'reading.parts-of-speech', '{"en":"Nouns, Verbs and Adjectives","ru":"Существительное, глагол, прилагательное"}'::jsonb, '{"id":"reading.parts-of-speech.l1","topicId":"reading.parts-of-speech","title":{"en":"Nouns, Verbs and Adjectives","ru":"Существительное, глагол, прилагательное"},"subtopic":{"en":"Three main parts of speech","ru":"Три главные части речи"},"objective":{"en":"Tell nouns, verbs and adjectives apart.","ru":"Различать существительные, глаголы и прилагательные по вопросам."},"ageRange":[8,10],"grades":[2,4],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Every word has a job! Some name things, some show actions, and some describe. Let''s meet them!","ru":"У каждого слова есть работа! Одни называют предметы, другие — действия, третьи — признаки. Давай познакомимся!"},"explanation":[{"en":"A noun names a person, place, animal or thing: girl, school, dog, ball.","ru":"Существительное обозначает предмет и отвечает на вопросы кто? что?: девочка, школа, кот, мяч."},{"en":"A verb is an action word — what someone does: run, eat, sing.","ru":"Глагол обозначает действие и отвечает на вопросы что делать? что сделать?: бежать, читает, спела."},{"en":"An adjective describes a noun — what it is like: big, red, happy.","ru":"Прилагательное обозначает признак предмета и отвечает на вопросы какой? какая? какое?: большой, красная, весёлое."}],"example":{"kind":"text","text":{"en":"The big 🐶 runs.  big = adjective · dog = noun · runs = verb","ru":"Большая 🐶 бежит.  большая — прилагательное · собака — существительное · бежит — глагол"}},"masteryScore":0.8,"reviewTips":{"en":"Ask about each word: Is it a thing (noun)? Something you do (verb)? Does it describe (adjective)?","ru":"Задавай вопрос к слову: кто? что? — существительное; что делать? — глагол; какой? — прилагательное."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Tell nouns, verbs and adjectives apart.","ru":"Различать существительные, глаголы и прилагательные по вопросам."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.punctuation.l1', 'reading.punctuation', '{"en":"Little Marks, Big Help","ru":"Маленькие знаки — большая помощь"}'::jsonb, '{"id":"reading.punctuation.l1","topicId":"reading.punctuation","title":{"en":"Little Marks, Big Help","ru":"Маленькие знаки — большая помощь"},"subtopic":{"en":"End marks and commas","ru":"Знаки в конце предложения и запятая"},"objective":{"en":"Choose the right end mark and use commas in lists and before «but».","ru":"Выбирать знак в конце предложения, ставить запятые между однородными словами и перед «а», «но»."},"ageRange":[8,11],"grades":[2,5],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Punctuation marks are like road signs for readers. They tell us when to stop, ask or shout hooray!","ru":"Знаки препинания — как дорожные знаки для читателя. Они подсказывают, где остановиться, спросить или крикнуть «ура»!"},"explanation":[{"en":"A full stop (.) ends a telling sentence. A question mark (?) ends a question. An exclamation mark (!) shows strong feeling.","ru":"Точка (.) ставится в конце повествовательного предложения, вопросительный знак (?) — в конце вопроса, восклицательный знак (!) — когда говорим с сильным чувством."},{"en":"A comma (,) separates things in a list: apples, pears and plums. It also goes before «but» when it joins two ideas: I wanted to play, but it rained.","ru":"Запятая (,) разделяет однородные слова: яблоки, груши и сливы (перед одиночным «и» запятую не ставим). Ещё запятая нужна перед «а» и «но»: Я хотел гулять, но пошёл дождь."}],"example":{"kind":"text","text":{"en":"I like cats. Do you like cats? I love cats! I have a cat, a dog and a fish.","ru":"Я люблю кошек. А ты любишь кошек? Я обожаю кошек! У меня есть кошка, собака и рыбка."}},"masteryScore":0.8,"reviewTips":{"en":"Read the sentence aloud. Does your voice stop, ask or get excited? Pause for commas in lists.","ru":"Прочитай предложение вслух. Голос понижается, спрашивает или радуется? Ищи однородные слова и союзы «а», «но»."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Choose the right end mark and use commas in lists and before «but».","ru":"Выбирать знак в конце предложения, ставить запятые между однородными словами и перед «а», «но»."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.comprehension.l1', 'reading.comprehension', '{"en":"Main Idea and Details","ru":"Главная мысль и детали"}'::jsonb, '{"id":"reading.comprehension.l1","topicId":"reading.comprehension","title":{"en":"Main Idea and Details","ru":"Главная мысль и детали"},"subtopic":{"en":"Reading a short story carefully","ru":"Внимательно читаем рассказ"},"objective":{"en":"Find the main idea and important details in a short story.","ru":"Находить главную мысль и важные детали в коротком рассказе."},"ageRange":[8,12],"grades":[2,6],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"I love a good story! Let''s read one together and become story explorers.","ru":"Обожаю хорошие истории! Давай прочитаем одну вместе и станем исследователями текста."},"explanation":[{"en":"The main idea is what the whole text is mostly about. Ask yourself: «What is this story about in one sentence?»","ru":"Главная мысль — это то, о чём весь текст. Спроси себя: «О чём этот рассказ, если сказать одним предложением?»"},{"en":"Details are small facts: who, where, when, what happened and why. You can find them in the text, so look back and re-read!","ru":"Детали — это мелкие факты: кто, где, когда, что случилось и почему. Их можно найти в тексте — не бойся перечитывать!"}],"example":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"game":"reading-adventure","masteryScore":0.8,"reviewTips":{"en":"Read the story twice. First ask «What is it mostly about?», then look back in the text to find each detail.","ru":"Прочитай рассказ дважды. Сначала спроси: «О чём он?», потом ищи каждую деталь в тексте."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Find the main idea and important details in a short story.","ru":"Находить главную мысль и важные детали в коротком рассказе."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.vocabulary.l1', 'reading.vocabulary', '{"en":"Synonyms and Antonyms","ru":"Синонимы и антонимы"}'::jsonb, '{"id":"reading.vocabulary.l1","topicId":"reading.vocabulary","title":{"en":"Synonyms and Antonyms","ru":"Синонимы и антонимы"},"subtopic":{"en":"Word meanings and context clues","ru":"Значение слова и подсказки контекста"},"objective":{"en":"Find synonyms and antonyms and work out word meanings from context.","ru":"Подбирать синонимы и антонимы и понимать значение слова по тексту."},"ageRange":[8,14],"grades":[2,8],"difficulty":2,"durationMin":12,"character":"oli","intro":{"en":"Words have friends and opposites! Let''s grow your word treasure chest.","ru":"У слов есть друзья и противоположности! Давай пополним твою копилку слов."},"explanation":[{"en":"Synonyms are words with nearly the same meaning: big — large, happy — glad.","ru":"Синонимы — слова одной части речи, близкие по значению: большой — огромный, весёлый — радостный."},{"en":"Antonyms are words with opposite meanings: hot — cold, day — night.","ru":"Антонимы — слова с противоположным значением: горячий — холодный, день — ночь."},{"en":"Meet a new word? Look at the words around it — they are clues to its meaning.","ru":"Встретил незнакомое слово? Посмотри на соседние слова — они подскажут его значение."}],"example":{"kind":"text","text":{"en":"big = large (synonyms)   big ↔ small (antonyms)","ru":"большой = огромный (синонимы)   большой ↔ маленький (антонимы)"}},"masteryScore":0.8,"reviewTips":{"en":"Synonyms are word friends (same meaning), antonyms are opposites. Use the words around a new word as clues.","ru":"Синонимы — слова-друзья (похожее значение), антонимы — противоположности. Ищи подсказки в соседних словах."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Find synonyms and antonyms and work out word meanings from context.","ru":"Подбирать синонимы и антонимы и понимать значение слова по тексту."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.morphology.l1', 'reading.morphology', '{"en":"How Words Are Built","ru":"Из чего состоит слово"}'::jsonb, '{"id":"reading.morphology.l1","topicId":"reading.morphology","title":{"en":"How Words Are Built","ru":"Из чего состоит слово"},"subtopic":{"en":"Roots, prefixes, suffixes and endings","ru":"Корень, приставка, суффикс, окончание"},"objective":{"en":"Identify the root, prefix, suffix and ending of a word and explain what they add.","ru":"Выделять в слове приставку, корень, суффикс, окончание и основу."},"ageRange":[11,13],"grades":[5,7],"difficulty":3,"durationMin":14,"character":"oli","intro":{"en":"Words are like LEGO models: snap on a piece and you get a new meaning. Let''s take some apart!","ru":"Слова — как конструктор: добавишь деталь — получишь новое значение. Давай разберём несколько слов!"},"explanation":[{"en":"The root (base) carries the main meaning: help, play, kind. Words with the same root are a word family: help, helper, helpful.","ru":"Корень — общая часть родственных слов, в нём главный смысл: лес, лесник, лесной. Приставка стоит перед корнем, суффикс — после корня, окончание — изменяемая часть, которая связывает слова в предложении."},{"en":"A prefix goes before the root and changes its meaning: un- = not (unhappy), re- = again (reread), pre- = before (preview). A suffix goes after the root: -er = a person who (teacher), -ful = full of (helpful), -ness makes a noun (kindness).","ru":"Основа — это слово без окончания. Пример разбора: под|снеж|ник|□ — приставка под-, корень -снеж-, суффикс -ник-, нулевое окончание. Лесн|ой: основа «лесн», окончание -ой."},{"en":"Endings like -s and -ed change the form, not the meaning: plays, played.","ru":"Окончание меняет форму слова, а не его смысл: лес — леса — в лесу."}],"example":{"kind":"text","text":{"en":"un + help + ful = unhelpful  (prefix + root + suffix)","ru":"под + снеж + ник + □ = подснежник  (приставка + корень + суффикс + нулевое окончание)"}},"game":"word-builder","masteryScore":0.8,"reviewTips":{"en":"Find the root first using word-family words, then look for parts added before (prefix) and after (suffix, ending).","ru":"Порядок разбора: окончание (измени форму слова) → основа → корень (подбери родственные слова) → приставка → суффикс."},"status":"reviewed"}'::jsonb, 3, 14, '{"objective":{"en":"Identify the root, prefix, suffix and ending of a word and explain what they add.","ru":"Выделять в слове приставку, корень, суффикс, окончание и основу."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.syntax.l1', 'reading.syntax', '{"en":"Inside a Sentence","ru":"Строение предложения"}'::jsonb, '{"id":"reading.syntax.l1","topicId":"reading.syntax","title":{"en":"Inside a Sentence","ru":"Строение предложения"},"subtopic":{"en":"Subject, predicate, simple and complex sentences","ru":"Грамматическая основа, простые и сложные предложения"},"objective":{"en":"Find the subject and predicate and tell simple, compound and complex sentences apart.","ru":"Находить подлежащее и сказуемое, отличать простое предложение от сложного."},"ageRange":[13,15],"grades":[7,9],"difficulty":4,"durationMin":15,"character":"oli","intro":{"en":"Every sentence has a skeleton. Let''s find the bones that hold it together!","ru":"У каждого предложения есть скелет. Давай найдём то, на чём оно держится!"},"explanation":[{"en":"The subject is who or what the sentence is about; the predicate tells what the subject does or is. Together they form a clause: [The old clock] [ticked loudly].","ru":"Подлежащее отвечает на вопросы кто? что? (подчёркиваем одной чертой), сказуемое — что делает? каков? (двумя чертами). Вместе они — грамматическая основа: Старые [часы] громко [тикали]."},{"en":"A simple sentence has one clause. A compound sentence joins two main clauses with and, but, or. A complex sentence has a main clause and a dependent clause starting with because, when, although, that, which.","ru":"В простом предложении одна грамматическая основа, в сложном — две и больше. Сложносочинённое связано союзами и, а, но; сложноподчинённое — союзами и союзными словами потому что, когда, что, который. Части сложного предложения разделяются запятой."}],"example":{"kind":"text","text":{"en":"[The rain]S [stopped]P, and [the children]S [ran]P outside. → compound sentence (two clauses)","ru":"[Дождь]подл. [закончился]сказ., и [дети]подл. [выбежали]сказ. на улицу. → сложное предложение (две основы)"}},"masteryScore":0.8,"reviewTips":{"en":"Find every subject + predicate pair first. One pair = simple sentence; two or more = compound or complex.","ru":"Сначала найди все грамматические основы. Одна основа — простое предложение, две и больше — сложное. Между частями ставь запятую."},"status":"reviewed"}'::jsonb, 4, 15, '{"objective":{"en":"Find the subject and predicate and tell simple, compound and complex sentences apart.","ru":"Находить подлежащее и сказуемое, отличать простое предложение от сложного."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.literature.l1', 'reading.literature', '{"en":"Literary Genres","ru":"Литературные жанры"}'::jsonb, '{"id":"reading.literature.l1","topicId":"reading.literature","title":{"en":"Literary Genres","ru":"Литературные жанры"},"subtopic":{"en":"Fairy tale, fable, poem, novel, drama","ru":"Сказка, басня, стихотворение, роман, драма"},"objective":{"en":"Recognise the main literary genres and find the moral of a fable.","ru":"Узнавать основные литературные жанры и находить мораль басни."},"ageRange":[11,15],"grades":[5,9],"difficulty":3,"durationMin":15,"character":"oli","intro":{"en":"Stories come in many shapes. Let''s visit the library of genres and read a brand-new fable!","ru":"Истории бывают разными. Давай заглянем в библиотеку жанров и прочитаем новую басню!"},"explanation":[{"en":"A fairy tale has magic and wonders, and good usually wins. A fable is a short story, often with animals that act like people, that ends with a moral — a lesson (Aesop wrote many fables).","ru":"Сказка — история с волшебством и чудесами, где добро обычно побеждает. Басня — короткий, часто стихотворный рассказ, где животные ведут себя как люди; в ней есть мораль — поучение (вспомни басни И. А. Крылова)."},{"en":"A poem uses rhythm and often rhyme; its lines are grouped into stanzas. A novel is a long story with many chapters and characters. A drama (play) is written as dialogue for actors on a stage.","ru":"Стихотворение написано с ритмом и часто с рифмой, строки объединяются в строфы. Роман — большое произведение со множеством героев и глав. Драма (пьеса) написана в виде реплик героев для сцены, с ремарками для актёров."}],"example":{"kind":"text","text":{"en":"A proud Magpie collected shiny things and boasted about them to the whole forest. One day she found a piece of glass and decided it was a diamond. She guarded it day and night and completely forgot to build her nest. When the cold autumn rains came, the other birds sat in their warm nests, while the Magpie shivered next to her «treasure». Moral: not everything that sparkles is what we truly need.","ru":"Гордая Сорока собирала блестящие вещицы и хвасталась ими перед всем лесом. Однажды она нашла осколок стекла и решила, что это алмаз. Она стерегла его день и ночь и совсем забыла свить гнездо. Когда пришли холодные осенние дожди, другие птицы сидели в тёплых гнёздах, а Сорока дрожала рядом со своим «сокровищем». Мораль: не всё то нужно, что блестит."}},"game":"reading-adventure","masteryScore":0.8,"reviewTips":{"en":"Ask: Is there magic? A moral? Rhyme? Many chapters? Dialogue for a stage? Each answer points to a genre.","ru":"Спроси себя: есть ли волшебство? мораль? рифма? много глав и героев? реплики для сцены? Каждый ответ подскажет жанр."},"status":"reviewed"}'::jsonb, 3, 15, '{"objective":{"en":"Recognise the main literary genres and find the moral of a fable.","ru":"Узнавать основные литературные жанры и находить мораль басни."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('reading.text-analysis.l1', 'reading.text-analysis', '{"en":"Thesis, Evidence, Essay","ru":"Тезис, аргументы, сочинение"}'::jsonb, '{"id":"reading.text-analysis.l1","topicId":"reading.text-analysis","title":{"en":"Thesis, Evidence, Essay","ru":"Тезис, аргументы, сочинение"},"subtopic":{"en":"Analysing an argument and planning an essay","ru":"Анализ рассуждения и план сочинения"},"objective":{"en":"Identify a text''s thesis and evidence and plan an argumentative essay.","ru":"Определять тему, основную мысль и тезис текста, подбирать аргументы и строить сочинение-рассуждение."},"ageRange":[14,17],"grades":[8,11],"difficulty":5,"durationMin":15,"character":"oli","intro":{"en":"Good readers don''t just read — they ask «What is the author claiming, and how do they prove it?» Let''s dig in.","ru":"Вдумчивый читатель не просто читает, а спрашивает: «Что утверждает автор и как он это доказывает?» Давай разберёмся."},"explanation":[{"en":"The topic is what a text is about (mistakes). The theme or main idea is the message about that topic (mistakes help us grow). The thesis is the author''s central claim.","ru":"Тема — о чём текст (об ошибках). Основная мысль (идея) — что автор хочет сказать (ошибки помогают расти). Тезис — главное утверждение, которое автор доказывает."},{"en":"Strong arguments are backed by evidence: facts, examples, quotations from the text. Opinions like «everyone knows» are not evidence.","ru":"Аргументы подтверждают тезис: примеры из прочитанного текста, из литературы, из жизни, факты. Фразы вроде «все это знают» аргументом не являются."},{"en":"An essay has an introduction (with the thesis), body paragraphs (point → evidence → explanation) and a conclusion that sums up.","ru":"Сочинение-рассуждение строится так: вступление (тезис) → основная часть (аргументы с примерами и пояснениями) → заключение (вывод)."}],"example":{"kind":"text","text":{"en":"Thesis: Mistakes help us grow. → Argument: Every inventor makes many attempts. → Evidence: a child learning to walk falls again and again. → Conclusion: treat mistakes as steps forward.","ru":"Тезис: ошибки помогают расти. → Аргумент: любой изобретатель делает много попыток. → Пример: ребёнок, который учится ходить, падает снова и снова. → Вывод: ошибки — это шаги вперёд."}},"masteryScore":0.8,"reviewTips":{"en":"Ask three questions of any text: What is the claim? What evidence supports it? Is that evidence convincing?","ru":"Задавай тексту три вопроса: какова основная мысль? чем автор её доказывает? убедительны ли аргументы?"},"status":"reviewed"}'::jsonb, 5, 15, '{"objective":{"en":"Identify a text''s thesis and evidence and plan an argumentative essay.","ru":"Определять тему, основную мысль и тезис текста, подбирать аргументы и строить сочинение-рассуждение."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.living-things.l1', 'science.living-things', '{"en":"What Living Things Need","ru":"Что нужно живым существам"}'::jsonb, '{"id":"science.living-things.l1","topicId":"science.living-things","title":{"en":"What Living Things Need","ru":"Что нужно живым существам"},"subtopic":{"en":"Living and non-living things","ru":"Живое и неживое"},"objective":{"en":"Tell living things from non-living things and name what plants and animals need to live.","ru":"Отличать живое от неживого и называть, что нужно растениям и животным для жизни."},"ageRange":[7,9],"grades":[1,3],"difficulty":1,"durationMin":8,"character":"bruno","intro":{"en":"Hi, I''m Bruno! Let''s explore the world of plants and animals together!","ru":"Привет, я Бруно! Давай вместе исследуем мир растений и животных!"},"explanation":[{"en":"Living things grow, need food and water, breathe and can have young ones. Animals, plants and people are all living things. A rock or a toy is not living.","ru":"Живые существа растут, питаются, пьют воду, дышат и могут давать потомство. Животные, растения и люди - живые. Камень или игрушка - неживые."},{"en":"Plants need sunlight, water, air and soil. They grow from a seed into a sprout and then into a big plant.","ru":"Растениям нужны солнечный свет, вода, воздух и почва. Они вырастают из семечка: сначала появляется росток, а потом большое растение."},{"en":"Animals need food, water, air and a safe home. A bird lives in a nest, a bee in a hive and a fish in water.","ru":"Животным нужны еда, вода, воздух и безопасный дом. Птица живёт в гнезде, пчела - в улье, а рыба - в воде."}],"example":{"kind":"emoji","items":["🌱","🐶","🐟","🌳","🪨"],"caption":{"en":"A sprout, a dog, a fish and a tree are living. A rock is not.","ru":"Росток, собака, рыба и дерево - живые. Камень - неживой."}},"masteryScore":0.8,"reviewTips":{"en":"Look around: find three living things and say what each one needs - food, water, air or sunlight.","ru":"Посмотри вокруг: найди три живых существа и скажи, что нужно каждому - еда, вода, воздух или свет."},"status":"reviewed"}'::jsonb, 1, 8, '{"objective":{"en":"Tell living things from non-living things and name what plants and animals need to live.","ru":"Отличать живое от неживого и называть, что нужно растениям и животным для жизни."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.human-body.l1', 'science.human-body', '{"en":"My Amazing Body","ru":"Моё удивительное тело"}'::jsonb, '{"id":"science.human-body.l1","topicId":"science.human-body","title":{"en":"My Amazing Body","ru":"Моё удивительное тело"},"subtopic":{"en":"Senses, organs and healthy habits","ru":"Органы чувств, органы тела и полезные привычки"},"objective":{"en":"Name the five senses, know what the heart, lungs and brain do, and choose healthy habits.","ru":"Называть пять чувств, знать, что делают сердце, лёгкие и мозг, и выбирать полезные привычки."},"ageRange":[7,10],"grades":[1,4],"difficulty":1,"durationMin":10,"character":"bruno","intro":{"en":"Your body is like a super team! Let''s meet the players.","ru":"Твоё тело - настоящая команда! Давай познакомимся с её участниками."},"explanation":[{"en":"We learn about the world with five senses: we see with our eyes, hear with our ears, smell with our nose, taste with our tongue and feel with our skin.","ru":"Мы узнаём мир с помощью пяти чувств: видим глазами, слышим ушами, чувствуем запахи носом, вкус - языком, а прикосновения - кожей."},{"en":"Inside the body, the heart pumps blood, the lungs breathe in air, and the brain thinks and tells the body what to do.","ru":"Внутри тела сердце качает кровь, лёгкие вдыхают воздух, а мозг думает и управляет всем телом."},{"en":"To stay healthy: sleep well, drink water, eat fruit and vegetables, play and move, and wash your hands.","ru":"Чтобы быть здоровым: хорошо высыпайся, пей воду, ешь фрукты и овощи, играй и двигайся, мой руки."}],"example":{"kind":"emoji","items":["👀","👂","👃","👅","✋"],"caption":{"en":"See, hear, smell, taste, touch - the five senses.","ru":"Зрение, слух, обоняние, вкус, осязание - пять чувств."}},"masteryScore":0.8,"reviewTips":{"en":"Play a game: touch your eyes, ears, nose, tongue and hand and say which sense each one gives you.","ru":"Сыграй в игру: коснись глаз, ушей, носа, языка и руки и назови чувство, за которое они отвечают."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Name the five senses, know what the heart, lungs and brain do, and choose healthy habits.","ru":"Называть пять чувств, знать, что делают сердце, лёгкие и мозг, и выбирать полезные привычки."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.water-cycle.l1', 'science.water-cycle', '{"en":"The Journey of a Water Drop","ru":"Путешествие капельки воды"}'::jsonb, '{"id":"science.water-cycle.l1","topicId":"science.water-cycle","title":{"en":"The Journey of a Water Drop","ru":"Путешествие капельки воды"},"subtopic":{"en":"Evaporation, condensation, precipitation","ru":"Испарение, конденсация, осадки"},"objective":{"en":"Describe the four steps of the water cycle and name kinds of precipitation.","ru":"Описывать четыре этапа круговорота воды и называть виды осадков."},"ageRange":[8,10],"grades":[2,4],"difficulty":1,"durationMin":10,"character":"bruno","intro":{"en":"Where does rain come from? Let''s follow a little water drop!","ru":"Откуда берётся дождь? Давай проследим за маленькой капелькой!"},"explanation":[{"en":"The Sun warms water in seas, lakes and puddles. Some water turns into invisible water vapour and rises into the air. This is evaporation.","ru":"Солнце нагревает воду в морях, озёрах и лужах. Часть воды превращается в невидимый водяной пар и поднимается в воздух. Это испарение."},{"en":"High up it is cold, so the vapour cools and turns into tiny droplets. Many droplets together make a cloud. This is condensation.","ru":"Высоко в небе холодно, пар остывает и превращается в крошечные капельки. Из множества капелек получается облако. Это конденсация."},{"en":"When drops get big and heavy, they fall as rain, snow or hail - precipitation. The water collects in rivers, lakes and seas, and the cycle starts again.","ru":"Когда капли становятся крупными и тяжёлыми, они падают дождём, снегом или градом - это осадки. Вода собирается в реках, озёрах и морях, и круговорот начинается снова."}],"example":{"kind":"emoji","items":["☀️","🌊","⬆️","☁️","🌧️","🏞️"],"caption":{"en":"Sun warms the sea → vapour rises → clouds form → rain falls → water collects.","ru":"Солнце греет море → пар поднимается → образуются облака → идёт дождь → вода собирается."}},"masteryScore":0.8,"reviewTips":{"en":"Draw a circle with four arrows: Sun warms water, clouds form, rain falls, water collects. Say each step aloud.","ru":"Нарисуй круг из четырёх стрелок: солнце греет воду, появляются облака, идёт дождь, вода собирается. Назови каждый шаг вслух."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Describe the four steps of the water cycle and name kinds of precipitation.","ru":"Описывать четыре этапа круговорота воды и называть виды осадков."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.solar-system.l1', 'science.solar-system', '{"en":"Our Home in Space","ru":"Наш дом в космосе"}'::jsonb, '{"id":"science.solar-system.l1","topicId":"science.solar-system","title":{"en":"Our Home in Space","ru":"Наш дом в космосе"},"subtopic":{"en":"The Sun, planets, the Moon, day and night","ru":"Солнце, планеты, Луна, день и ночь"},"objective":{"en":"Know that the Sun is a star, name the planets near it and explain day, night and a year.","ru":"Знать, что Солнце - звезда, называть ближайшие планеты и объяснять смену дня и ночи и что такое год."},"ageRange":[8,11],"grades":[2,5],"difficulty":1,"durationMin":10,"character":"bruno","intro":{"en":"3, 2, 1... blast off! Let''s fly around the Solar System!","ru":"3, 2, 1... пуск! Летим по Солнечной системе!"},"explanation":[{"en":"The Sun is a star - a huge ball of hot glowing gas. It gives us light and warmth. Eight planets travel around the Sun. Earth is the third planet from the Sun.","ru":"Солнце - это звезда, огромный шар раскалённого светящегося газа. Оно даёт нам свет и тепло. Вокруг Солнца движутся восемь планет. Земля - третья планета от Солнца."},{"en":"The Earth spins like a top. One full turn takes about 24 hours. The side facing the Sun has day, the other side has night.","ru":"Земля вращается, как волчок. Один полный оборот занимает около 24 часов. На стороне, повёрнутой к Солнцу, - день, на другой - ночь."},{"en":"The Earth also travels around the Sun. One trip takes a year - about 365 days. The Moon travels around the Earth.","ru":"А ещё Земля движется вокруг Солнца. Один оборот - это год, примерно 365 дней. Луна же движется вокруг Земли."}],"example":{"kind":"emoji","items":["☀️","🌍","🌙","🔴","🪐"],"caption":{"en":"The Sun, Earth with its Moon, red Mars... and ringed Saturn far away.","ru":"Солнце, Земля со своей Луной, красный Марс... и далёкий Сатурн с кольцами."}},"masteryScore":0.8,"reviewTips":{"en":"Remember: the Earth spins once a day and goes around the Sun once a year. Try saying the planets in order with a fun rhyme.","ru":"Запомни: Земля поворачивается вокруг себя за сутки, а вокруг Солнца - за год. Попробуй назвать планеты по порядку весёлой считалкой."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Know that the Sun is a star, name the planets near it and explain day, night and a year.","ru":"Знать, что Солнце - звезда, называть ближайшие планеты и объяснять смену дня и ночи и что такое год."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.scientific-method.l1', 'science.scientific-method', '{"en":"Think Like a Scientist","ru":"Думай как учёный"}'::jsonb, '{"id":"science.scientific-method.l1","topicId":"science.scientific-method","title":{"en":"Think Like a Scientist","ru":"Думай как учёный"},"subtopic":{"en":"Hypothesis and fair tests","ru":"Гипотеза и честный эксперимент"},"objective":{"en":"Follow the steps of the scientific method and plan a fair test that changes only one thing.","ru":"Выполнять шаги научного метода и планировать честный эксперимент, в котором меняется только одно условие."},"ageRange":[9,17],"grades":[3,11],"difficulty":2,"durationMin":12,"character":"bruno","intro":{"en":"Put on your virtual lab coat - today we''ll test ideas like real scientists!","ru":"Надевай виртуальный халат - сегодня мы проверяем идеи, как настоящие учёные!"},"explanation":[{"en":"Scientists start with a question, for example: \"Do bean plants grow taller with more light?\" Then they make a hypothesis - a guess that can be tested: \"Beans with more light will grow taller.\"","ru":"Учёные начинают с вопроса, например: «Растут ли бобы выше при большем количестве света?» Затем они выдвигают гипотезу - предположение, которое можно проверить: «Бобы на свету вырастут выше»."},{"en":"Next comes an experiment. In a fair test you change only one thing (the light) and keep everything else the same: the same seeds, soil and water. Then you observe and record the results, for example plant height in centimetres.","ru":"Дальше - эксперимент. В честном эксперименте меняют только одно условие (свет), а всё остальное оставляют одинаковым: те же семена, почву и полив. Затем наблюдают и записывают результаты, например высоту растений в сантиметрах."},{"en":"Finally you draw a conclusion: was the hypothesis supported? Good scientists repeat experiments to check. In EduWorld all experiments happen safely in our virtual lab.","ru":"В конце делают вывод: подтвердилась ли гипотеза? Хорошие учёные повторяют опыты, чтобы проверить себя. В EduWorld все эксперименты проходят безопасно в виртуальной лаборатории."}],"example":{"kind":"text","text":{"en":"Question → Hypothesis → Experiment → Results → Conclusion. Virtual test: pot A on a sunny windowsill, pot B in a dark cupboard - same seeds, same soil, same water.","ru":"Вопрос → Гипотеза → Эксперимент → Результаты → Вывод. Виртуальный опыт: горшок А на солнечном подоконнике, горшок Б в тёмном шкафу - одинаковые семена, почва и полив."}},"game":"science-lab","masteryScore":0.8,"reviewTips":{"en":"Remember the chain: question, hypothesis, experiment, results, conclusion - and change only one thing in a fair test.","ru":"Запомни цепочку: вопрос, гипотеза, эксперимент, результаты, вывод. В честном опыте меняется только одно условие."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Follow the steps of the scientific method and plan a fair test that changes only one thing.","ru":"Выполнять шаги научного метода и планировать честный эксперимент, в котором меняется только одно условие."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.states-of-matter.l1', 'science.states-of-matter', '{"en":"Solid, Liquid, Gas","ru":"Твёрдое, жидкое, газообразное"}'::jsonb, '{"id":"science.states-of-matter.l1","topicId":"science.states-of-matter","title":{"en":"Solid, Liquid, Gas","ru":"Твёрдое, жидкое, газообразное"},"subtopic":{"en":"States of matter and changes of state","ru":"Состояния вещества и их переходы"},"objective":{"en":"Sort materials into solids, liquids and gases and name the changes between states.","ru":"Распределять вещества на твёрдые, жидкие и газообразные и называть переходы между состояниями."},"ageRange":[9,12],"grades":[3,6],"difficulty":2,"durationMin":12,"character":"bruno","intro":{"en":"Ice, water and steam are all the same stuff! Let''s find out how.","ru":"Лёд, вода и пар - это одно и то же вещество! Давай узнаем, как так."},"explanation":[{"en":"Matter comes in three main states. A solid keeps its own shape because its tiny particles are packed tightly. A liquid flows and takes the shape of its container, but keeps the same volume. A gas spreads out to fill any space and can be squeezed.","ru":"Вещество бывает в трёх основных состояниях. Твёрдое тело сохраняет форму, потому что его крошечные частицы плотно упакованы. Жидкость течёт и принимает форму сосуда, но сохраняет объём. Газ заполняет всё доступное пространство, и его можно сжать."},{"en":"Heating can change the state: a solid melts into a liquid, and a liquid evaporates (or boils) into a gas. Cooling works the other way: a gas condenses into a liquid, and a liquid freezes into a solid. Pure water freezes at 0 °C and boils at 100 °C at normal air pressure.","ru":"Нагревание меняет состояние: твёрдое тело плавится и становится жидкостью, а жидкость испаряется (или кипит) и становится газом. При охлаждении всё наоборот: газ конденсируется в жидкость, а жидкость замерзает. Чистая вода замерзает при 0 °C и кипит при 100 °C при обычном давлении."},{"en":"Safety: we heat and cool things only in the virtual lab. Real hot water, steam and stoves can burn - only a grown-up should use them.","ru":"Безопасность: нагреваем и охлаждаем мы только в виртуальной лаборатории. Настоящие кипяток, пар и плита могут обжечь - с ними обращаются только взрослые."}],"example":{"kind":"emoji","items":["🧊","➡️","💧","➡️","♨️"],"caption":{"en":"Ice (solid) melts into water (liquid), which evaporates into vapour (gas).","ru":"Лёд (твёрдое) тает и становится водой (жидкость), которая испаряется в пар (газ)."}},"game":"science-lab","masteryScore":0.8,"reviewTips":{"en":"Think of water: ice (solid), water (liquid), vapour (gas). Heating moves it one way, cooling moves it back.","ru":"Вспомни воду: лёд (твёрдое), вода (жидкость), пар (газ). Нагревание ведёт в одну сторону, охлаждение - обратно."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Sort materials into solids, liquids and gases and name the changes between states.","ru":"Распределять вещества на твёрдые, жидкие и газообразные и называть переходы между состояниями."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.ecosystems.l1', 'science.ecosystems', '{"en":"Who Eats Whom?","ru":"Кто кого ест?"}'::jsonb, '{"id":"science.ecosystems.l1","topicId":"science.ecosystems","title":{"en":"Who Eats Whom?","ru":"Кто кого ест?"},"subtopic":{"en":"Producers, consumers, decomposers and food chains","ru":"Производители, потребители, разлагатели и пищевые цепи"},"objective":{"en":"Build a food chain and explain the roles of producers, consumers and decomposers.","ru":"Составлять пищевую цепь и объяснять роли производителей, потребителей и разлагателей."},"ageRange":[10,13],"grades":[4,7],"difficulty":2,"durationMin":12,"character":"bruno","intro":{"en":"Every living thing has a job in nature. Let''s discover the food chain!","ru":"У каждого живого существа есть своя роль в природе. Давай разберёмся в пищевых цепях!"},"explanation":[{"en":"An ecosystem is all the living things in a place together with their surroundings - water, soil, air and sunlight. A pond, a forest and a desert are ecosystems.","ru":"Экосистема - это все живые организмы какого-то места вместе с окружающей средой: водой, почвой, воздухом и солнечным светом. Пруд, лес и пустыня - это экосистемы."},{"en":"Producers (plants and algae) make their own food from sunlight by photosynthesis. Consumers eat other living things: herbivores eat plants, carnivores eat animals, and omnivores eat both. Decomposers such as fungi, bacteria and worms break down dead material and return nutrients to the soil.","ru":"Производители (растения и водоросли) сами создают пищу из солнечного света - это фотосинтез. Потребители питаются другими организмами: травоядные едят растения, хищники - животных, всеядные - и то и другое. Разлагатели - грибы, бактерии и черви - разлагают мёртвые остатки и возвращают питательные вещества в почву."},{"en":"A food chain shows how energy moves: grass → rabbit → fox. The arrows point from the food to the one who eats it.","ru":"Пищевая цепь показывает, как передаётся энергия: трава → заяц → лиса. Стрелки направлены от пищи к тому, кто её ест."}],"example":{"kind":"emoji","items":["☀️","➡️","🌿","➡️","🐰","➡️","🦊"],"caption":{"en":"Energy flows from the Sun to grass, to the rabbit, to the fox.","ru":"Энергия передаётся от Солнца к траве, к зайцу и к лисе."}},"masteryScore":0.8,"reviewTips":{"en":"Start every food chain with a plant (producer) and draw arrows toward the animal that eats it.","ru":"Начинай любую пищевую цепь с растения (производителя) и рисуй стрелки к тому, кто его ест."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Build a food chain and explain the roles of producers, consumers and decomposers.","ru":"Составлять пищевую цепь и объяснять роли производителей, потребителей и разлагателей."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.cells.l1', 'science.cells', '{"en":"Cells: Tiny Building Blocks","ru":"Клетки - крошечные кирпичики жизни"}'::jsonb, '{"id":"science.cells.l1","topicId":"science.cells","title":{"en":"Cells: Tiny Building Blocks","ru":"Клетки - крошечные кирпичики жизни"},"subtopic":{"en":"Parts of plant and animal cells","ru":"Строение растительной и животной клетки"},"objective":{"en":"Name the main parts of a cell and compare plant and animal cells.","ru":"Называть основные части клетки и сравнивать растительную и животную клетки."},"ageRange":[11,14],"grades":[5,8],"difficulty":3,"durationMin":12,"character":"bruno","intro":{"en":"Let''s zoom in with our virtual microscope - all life is made of cells!","ru":"Приблизим изображение виртуальным микроскопом - всё живое состоит из клеток!"},"explanation":[{"en":"All living things are made of cells. Some, like bacteria, are just one cell. Your body has trillions of cells. Most cells are so small that we need a microscope to see them.","ru":"Все живые организмы состоят из клеток. Некоторые, например бактерии, - всего из одной клетки. В твоём теле триллионы клеток. Большинство клеток настолько малы, что их видно только в микроскоп."},{"en":"The cell membrane controls what goes in and out. The nucleus holds the DNA and controls the cell. The cytoplasm is a jelly where chemical reactions happen, and mitochondria release energy from food.","ru":"Клеточная мембрана управляет тем, что входит в клетку и выходит из неё. Ядро хранит ДНК и управляет клеткой. Цитоплазма - это желеобразная среда, где идут химические реакции, а митохондрии высвобождают энергию из пищи."},{"en":"Plant cells also have a stiff cell wall for support, chloroplasts for photosynthesis and a large vacuole filled with cell sap. Cells group into tissues, tissues into organs, organs into organ systems, and these make an organism.","ru":"У растительных клеток есть ещё прочная клеточная стенка для опоры, хлоропласты для фотосинтеза и большая вакуоль с клеточным соком. Клетки образуют ткани, ткани - органы, органы - системы органов, а из них состоит организм."}],"example":{"kind":"emoji","items":["🔬","🦠","🟢","🌿"],"caption":{"en":"Through a microscope: one-celled bacteria and green chloroplasts inside leaf cells.","ru":"В микроскоп видны одноклеточные бактерии и зелёные хлоропласты в клетках листа."}},"masteryScore":0.8,"reviewTips":{"en":"Picture a cell as a factory: the nucleus is the boss, mitochondria are the power station, the membrane is the gate.","ru":"Представь клетку как фабрику: ядро - директор, митохондрии - электростанция, мембрана - проходная."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Name the main parts of a cell and compare plant and animal cells.","ru":"Называть основные части клетки и сравнивать растительную и животную клетки."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.energy.l1', 'science.energy', '{"en":"Energy and Circuits","ru":"Энергия и электрические цепи"}'::jsonb, '{"id":"science.energy.l1","topicId":"science.energy","title":{"en":"Energy and Circuits","ru":"Энергия и электрические цепи"},"subtopic":{"en":"Forms of energy, circuits, conductors and insulators","ru":"Виды энергии, цепи, проводники и изоляторы"},"objective":{"en":"Name forms of energy, describe energy changes and tell conductors from insulators in a simple circuit.","ru":"Называть виды энергии, описывать её превращения и отличать проводники от изоляторов в простой цепи."},"ageRange":[11,14],"grades":[5,8],"difficulty":3,"durationMin":13,"character":"bruno","intro":{"en":"Energy makes everything happen! Let''s build a circuit in our virtual lab.","ru":"Энергия - причина всех изменений! Соберём электрическую цепь в виртуальной лаборатории."},"explanation":[{"en":"Energy is what makes things move, heat up, light up or make sound. It comes in many forms: kinetic (movement), potential (stored), thermal (heat), light, sound, electrical and chemical energy.","ru":"Энергия заставляет предметы двигаться, нагреваться, светиться и звучать. Она бывает разной: кинетическая (движения), потенциальная (запасённая), тепловая, световая, звуковая, электрическая и химическая."},{"en":"Energy is never created or destroyed - it only changes form. In a torch, chemical energy in the battery becomes electrical energy, and the bulb turns it into light and some heat.","ru":"Энергия не появляется из ничего и не исчезает - она только переходит из одного вида в другой. В фонарике химическая энергия батарейки становится электрической, а лампочка превращает её в свет и немного в тепло."},{"en":"A circuit is a closed loop: battery, wires, a switch and a bulb. Conductors such as metals let electricity flow; insulators such as plastic, rubber and wood do not. Safety: build circuits only in the virtual lab. Never touch sockets, plugs with wet hands or damaged wires - mains electricity can seriously hurt you.","ru":"Электрическая цепь - это замкнутый контур: батарейка, провода, выключатель и лампочка. Проводники, например металлы, пропускают ток, а изоляторы - пластик, резина и дерево - нет. Безопасность: собирай цепи только в виртуальной лаборатории. Никогда не трогай розетки, вилки мокрыми руками и повреждённые провода - сетевое электричество очень опасно."}],"example":{"kind":"text","text":{"en":"Virtual circuit: 🔋 battery → wire → 🔘 switch (closed) → 💡 bulb → wire → back to 🔋. Open the switch and the loop breaks: the bulb goes out.","ru":"Виртуальная цепь: 🔋 батарейка → провод → 🔘 выключатель (замкнут) → 💡 лампочка → провод → обратно к 🔋. Разомкни выключатель - контур разорвётся, и лампочка погаснет."}},"game":"science-lab","masteryScore":0.8,"reviewTips":{"en":"Follow the energy: where does it start and what does it become? For circuits, check that the loop is closed. Real electricity is only for grown-ups.","ru":"Следи за энергией: откуда она берётся и во что превращается? В цепи проверь, замкнут ли контур. С настоящим электричеством работают только взрослые."},"status":"reviewed"}'::jsonb, 3, 13, '{"objective":{"en":"Name forms of energy, describe energy changes and tell conductors from insulators in a simple circuit.","ru":"Называть виды энергии, описывать её превращения и отличать проводники от изоляторов в простой цепи."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.forces.l1', 'science.forces', '{"en":"Pushes, Pulls and Newton''s Laws","ru":"Толчки, тяги и законы Ньютона"}'::jsonb, '{"id":"science.forces.l1","topicId":"science.forces","title":{"en":"Pushes, Pulls and Newton''s Laws","ru":"Толчки, тяги и законы Ньютона"},"subtopic":{"en":"Gravity, friction and F = m × a","ru":"Гравитация, трение и F = m × a"},"objective":{"en":"Explain gravity and friction, use F = m × a and recognise Newton''s three laws.","ru":"Объяснять гравитацию и трение, применять формулу F = m × a и узнавать три закона Ньютона."},"ageRange":[12,15],"grades":[6,9],"difficulty":3,"durationMin":14,"character":"bruno","intro":{"en":"Why does a ball stop rolling? Why do rockets fly? Let''s find out with forces!","ru":"Почему мяч перестаёт катиться? Почему летают ракеты? Разберёмся с силами!"},"explanation":[{"en":"A force is a push or a pull. Forces are measured in newtons (N). Gravity pulls everything toward the centre of the Earth. Friction acts between surfaces and slows moving things down; air resistance is friction with the air.","ru":"Сила - это толчок или тяга. Силу измеряют в ньютонах (Н). Сила тяжести притягивает все тела к центру Земли. Трение возникает между поверхностями и замедляет движение; сопротивление воздуха - это трение о воздух."},{"en":"Newton''s first law: an object stays still or keeps moving at a steady speed in a straight line unless an unbalanced force acts on it. Second law: F = m × a - a bigger force gives a bigger acceleration, and a heavier object needs more force.","ru":"Первый закон Ньютона: тело покоится или движется равномерно и прямолинейно, пока на него не действует неуравновешенная сила. Второй закон: F = m × a - чем больше сила, тем больше ускорение, а более массивному телу нужна большая сила."},{"en":"Third law: for every action there is an equal and opposite reaction. A rocket pushes hot gas down, and the gas pushes the rocket up.","ru":"Третий закон: на каждое действие есть равное по величине и противоположное по направлению противодействие. Ракета отталкивает газы вниз, а газы толкают ракету вверх."}],"example":{"kind":"equation","text":"F = m × a","caption":{"en":"Force (N) = mass (kg) × acceleration (m/s²). Example: 2 kg × 3 m/s² = 6 N.","ru":"Сила (Н) = масса (кг) × ускорение (м/с²). Пример: 2 кг × 3 м/с² = 6 Н."}},"masteryScore":0.8,"reviewTips":{"en":"Write F = m × a on a card. To find a, divide F by m; to find m, divide F by a.","ru":"Запиши F = m × a на карточку. Чтобы найти a, раздели F на m; чтобы найти m, раздели F на a."},"status":"reviewed"}'::jsonb, 3, 14, '{"objective":{"en":"Explain gravity and friction, use F = m × a and recognise Newton''s three laws.","ru":"Объяснять гравитацию и трение, применять формулу F = m × a и узнавать три закона Ньютона."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.chemistry-basics.l1', 'science.chemistry-basics', '{"en":"Atoms, Molecules and Reactions","ru":"Атомы, молекулы и реакции"}'::jsonb, '{"id":"science.chemistry-basics.l1","topicId":"science.chemistry-basics","title":{"en":"Atoms, Molecules and Reactions","ru":"Атомы, молекулы и реакции"},"subtopic":{"en":"Atomic structure and chemical vs physical change","ru":"Строение атома и химические и физические явления"},"objective":{"en":"Describe the parts of an atom, read a simple formula and tell chemical changes from physical ones.","ru":"Описывать строение атома, читать простую формулу и отличать химические явления от физических."},"ageRange":[13,15],"grades":[7,9],"difficulty":4,"durationMin":14,"character":"bruno","intro":{"en":"Everything around you is built from atoms. Let''s mix things - virtually and safely!","ru":"Всё вокруг состоит из атомов. Давай смешивать вещества - виртуально и безопасно!"},"explanation":[{"en":"Matter is made of atoms. An atom has a tiny nucleus with positive protons and neutral neutrons, and negative electrons moving around it. An element contains only one kind of atom; about 118 elements are known.","ru":"Вещество состоит из атомов. В центре атома - крошечное ядро из положительных протонов и нейтральных нейтронов, а вокруг движутся отрицательные электроны. Химический элемент - это вид атомов; известно около 118 элементов."},{"en":"Atoms join to form molecules. H₂O means one water molecule has 2 hydrogen atoms and 1 oxygen atom. In a chemical reaction atoms rearrange into new substances. Signs: gas bubbles, colour change, heat or light, a new smell or a solid forming. Mass is conserved - atoms are not lost, just rearranged.","ru":"Атомы соединяются в молекулы. H₂O означает, что в молекуле воды 2 атома водорода и 1 атом кислорода. При химической реакции атомы перестраиваются и образуются новые вещества. Признаки: пузырьки газа, изменение цвета, выделение тепла или света, новый запах, выпадение осадка. Масса сохраняется - атомы не исчезают, а лишь перегруппировываются."},{"en":"In a physical change (melting, cutting, dissolving) no new substance forms. Safety: real chemicals are used only in a school lab with a teacher, goggles and gloves. In EduWorld all reactions are virtual - never mix household chemicals at home.","ru":"При физическом явлении (плавление, резание, растворение) новые вещества не образуются. Безопасность: с настоящими реактивами работают только в школьной лаборатории с учителем, в очках и перчатках. В EduWorld все реакции виртуальные - никогда не смешивай бытовую химию дома."}],"example":{"kind":"equation","text":"2H₂ + O₂ → 2H₂O","caption":{"en":"Hydrogen and oxygen react to form water. 4 H and 2 O atoms on each side - mass is conserved.","ru":"Водород и кислород реагируют, образуя воду. По 4 атома H и 2 атома O с каждой стороны - масса сохраняется."}},"masteryScore":0.8,"reviewTips":{"en":"Ask yourself: is a new substance made? If yes, it is a chemical change. Count atoms on both sides of an equation - they must match.","ru":"Спроси себя: образовалось ли новое вещество? Если да - это химическое явление. Считай атомы в обеих частях уравнения - их число должно совпадать."},"status":"reviewed"}'::jsonb, 4, 14, '{"objective":{"en":"Describe the parts of an atom, read a simple formula and tell chemical changes from physical ones.","ru":"Описывать строение атома, читать простую формулу и отличать химические явления от физических."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.genetics.l1', 'science.genetics', '{"en":"DNA, Heredity and Evolution","ru":"ДНК, наследственность и эволюция"}'::jsonb, '{"id":"science.genetics.l1","topicId":"science.genetics","title":{"en":"DNA, Heredity and Evolution","ru":"ДНК, наследственность и эволюция"},"subtopic":{"en":"Genes, Punnett squares and natural selection","ru":"Гены, решётка Пеннета и естественный отбор"},"objective":{"en":"Explain how DNA carries genes, predict offspring with a Punnett square and describe natural selection.","ru":"Объяснять, как ДНК несёт гены, предсказывать потомство с помощью решётки Пеннета и описывать естественный отбор."},"ageRange":[15,17],"grades":[9,11],"difficulty":5,"durationMin":15,"character":"bruno","intro":{"en":"Why do you look a bit like your family? The answer is written in DNA!","ru":"Почему ты похож на своих родных? Ответ записан в ДНК!"},"explanation":[{"en":"DNA is a double helix made of four bases: A, T, G and C. A always pairs with T, and G with C. A gene is a section of DNA that codes for a protein. DNA is packed into chromosomes - a typical human body cell has 46 (23 pairs).","ru":"ДНК - это двойная спираль из четырёх азотистых оснований: A, T, G и C. A всегда соединяется с T, а G - с C. Ген - участок ДНК, кодирующий белок. ДНК упакована в хромосомы - в обычной клетке тела человека их 46 (23 пары)."},{"en":"Different versions of a gene are alleles. A dominant allele (A) shows its effect even with one copy; a recessive allele (a) shows only when there are two (aa). For Aa × Aa, a Punnett square gives AA : Aa : aa = 1 : 2 : 1, so 25% of offspring are expected to show the recessive trait.","ru":"Разные варианты гена называются аллелями. Доминантный аллель (A) проявляется даже в одной копии, рецессивный (a) - только в двух (aa). При скрещивании Aa × Aa решётка Пеннета даёт AA : Aa : aa = 1 : 2 : 1, то есть у 25% потомков ожидается рецессивный признак."},{"en":"Natural selection (Darwin): individuals vary, some variations help survival, those individuals reproduce more and pass their alleles on. Over many generations helpful traits become more common - populations evolve. Mutations are the original source of new variation.","ru":"Естественный отбор (Дарвин): особи различаются, некоторые различия помогают выжить, такие особи чаще оставляют потомство и передают ему свои аллели. За много поколений полезные признаки становятся чаще - популяции эволюционируют. Мутации - первоисточник новой изменчивости."}],"example":{"kind":"text","text":{"en":"Punnett square Aa × Aa:\n      A    a\nA   AA   Aa\na   Aa   aa\n→ 3 show the dominant trait, 1 shows the recessive trait (25%).","ru":"Решётка Пеннета Aa × Aa:\n      A    a\nA   AA   Aa\na   Aa   aa\n→ у 3 проявляется доминантный признак, у 1 - рецессивный (25%)."}},"masteryScore":0.8,"reviewTips":{"en":"Draw a 2×2 Punnett square for each cross and count the boxes. For evolution, remember: variation, selection, inheritance, time.","ru":"Рисуй решётку Пеннета 2×2 для каждого скрещивания и считай клетки. Для эволюции запомни: изменчивость, отбор, наследование, время."},"status":"reviewed"}'::jsonb, 5, 15, '{"objective":{"en":"Explain how DNA carries genes, predict offspring with a Punnett square and describe natural selection.","ru":"Объяснять, как ДНК несёт гены, предсказывать потомство с помощью решётки Пеннета и описывать естественный отбор."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('science.electromagnetism.l1', 'science.electromagnetism', '{"en":"Magnets, Fields and Electromagnets","ru":"Магниты, поля и электромагниты"}'::jsonb, '{"id":"science.electromagnetism.l1","topicId":"science.electromagnetism","title":{"en":"Magnets, Fields and Electromagnets","ru":"Магниты, поля и электромагниты"},"subtopic":{"en":"Magnetic fields, electromagnets and induction","ru":"Магнитные поля, электромагниты и индукция"},"objective":{"en":"Describe magnetic fields, explain how to make a stronger electromagnet and how generators and motors work.","ru":"Описывать магнитные поля, объяснять, как усилить электромагнит и как работают генераторы и двигатели."},"ageRange":[15,17],"grades":[9,11],"difficulty":5,"durationMin":15,"character":"bruno","intro":{"en":"Electricity and magnetism are two sides of one force. Let''s explore them in the virtual lab!","ru":"Электричество и магнетизм - две стороны одного явления. Исследуем их в виртуальной лаборатории!"},"explanation":[{"en":"Every magnet has a north and a south pole. Like poles repel and unlike poles attract. A magnetic field surrounds a magnet; outside the magnet its field lines run from N to S. Iron, nickel and cobalt are magnetic materials.","ru":"У каждого магнита есть северный и южный полюсы. Одноимённые полюсы отталкиваются, разноимённые - притягиваются. Вокруг магнита существует магнитное поле; снаружи магнита его линии идут от N к S. Железо, никель и кобальт - магнитные материалы."},{"en":"An electric current creates a magnetic field (Ørsted''s discovery). A coil of wire around an iron core is an electromagnet. It gets stronger with more turns, a bigger current and an iron core - and it can be switched off. Motors use this to turn electrical energy into motion.","ru":"Электрический ток создаёт магнитное поле (открытие Эрстеда). Катушка провода с железным сердечником - это электромагнит. Он сильнее, если больше витков, больше ток и есть железный сердечник, - и его можно выключить. Двигатели так превращают электрическую энергию в движение."},{"en":"Faraday found the reverse: a changing magnetic field near a coil induces a current. Generators spin coils and magnets to turn motion into electricity, and transformers change the voltage of alternating current. Safety: explore this only in the virtual lab - mains electricity and high voltages are dangerous.","ru":"Фарадей открыл обратное: изменяющееся магнитное поле возле катушки создаёт в ней ток (индукция). Генераторы вращают катушки и магниты и превращают движение в электричество, а трансформаторы изменяют напряжение переменного тока. Безопасность: исследуй это только в виртуальной лаборатории - сетевое и высокое напряжение опасны."}],"example":{"kind":"text","text":{"en":"Virtual electromagnet: 🔋 → coil of 50 turns around an iron nail → picks up 5 paper clips. Double the turns → picks up more clips. Switch off → clips drop.","ru":"Виртуальный электромагнит: 🔋 → катушка из 50 витков на железном гвозде → поднимает 5 скрепок. Вдвое больше витков → поднимает больше скрепок. Выключи ток → скрепки падают."}},"masteryScore":0.8,"reviewTips":{"en":"Remember the pair: current makes a magnetic field (motor, electromagnet); a changing magnetic field makes a current (generator).","ru":"Запомни пару: ток создаёт магнитное поле (двигатель, электромагнит), а изменяющееся магнитное поле создаёт ток (генератор)."},"status":"reviewed"}'::jsonb, 5, 15, '{"objective":{"en":"Describe magnetic fields, explain how to make a stronger electromagnet and how generators and motors work.","ru":"Описывать магнитные поля, объяснять, как усилить электромагнит и как работают генераторы и двигатели."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('languages.english-basics.l1', 'languages.english-basics', '{"en":"Hello, English!","ru":"Привет, английский!"}'::jsonb, '{"character":"luna","masteryScore":0.8,"status":"reviewed","id":"languages.english-basics.l1","topicId":"languages.english-basics","title":{"en":"Hello, English!","ru":"Привет, английский!"},"subtopic":{"en":"Greetings, polite words and the first letters","ru":"Приветствия, вежливые слова и первые буквы"},"objective":{"en":"Greet people, say goodbye and thank you in English, and know the start of the alphabet.","ru":"Здороваться, прощаться и благодарить по-английски и знать начало алфавита."},"ageRange":[5,9],"grades":[0,3],"difficulty":1,"durationMin":10,"intro":{"en":"Hello! I''m Luna. Let''s say our first English words together!","ru":"Hello! Я Луна. Давай скажем наши первые английские слова!"},"explanation":[{"en":"When we meet someone, we say Hello or Hi.","ru":"Когда встречаем кого-то, по-английски говорим Hello [хэлóу] или Hi [хай] - «привет»."},{"en":"When we leave, we say Goodbye or Bye.","ru":"Когда уходим, говорим Goodbye [гудбáй] или Bye [бай] - «до свидания», «пока»."},{"en":"When someone helps us, we say Thank you. In the morning we say Good morning.","ru":"Когда нам помогают, говорим Thank you [сэнк ю] - «спасибо». Утром говорим Good morning - «доброе утро»."},{"en":"The English alphabet has 26 letters. It starts A, B, C, D, E.","ru":"В английском алфавите 26 букв. Он начинается так: A, B, C, D, E."}],"example":{"kind":"text","text":{"en":"👋 Hello!   🎁 Thank you!   🚪 Goodbye!","ru":"👋 Hello! - Привет!   🎁 Thank you! - Спасибо!   🚪 Goodbye! - До свидания!"}},"game":"alphabet-finder","reviewTips":{"en":"Say Hello, Thank you and Goodbye in English at home every day.","ru":"Говори дома каждый день Hello, Thank you и Goodbye."}}'::jsonb, 1, 10, '{"objective":{"en":"Greet people, say goodbye and thank you in English, and know the start of the alphabet.","ru":"Здороваться, прощаться и благодарить по-английски и знать начало алфавита."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('languages.english-vocab.l1', 'languages.english-vocab', '{"en":"Colours, Numbers, Animals, Family","ru":"Цвета, числа, животные, семья"}'::jsonb, '{"character":"luna","masteryScore":0.8,"status":"reviewed","id":"languages.english-vocab.l1","topicId":"languages.english-vocab","title":{"en":"Colours, Numbers, Animals, Family","ru":"Цвета, числа, животные, семья"},"subtopic":{"en":"Everyday English words","ru":"Английские слова на каждый день"},"objective":{"en":"Recognise and use common English words for colours, numbers, animals and family.","ru":"Узнавать и использовать английские слова: цвета, числа, животные и семья."},"ageRange":[6,10],"grades":[1,4],"difficulty":1,"durationMin":10,"intro":{"en":"Let''s learn words you can use every day!","ru":"Давай выучим слова, которые пригодятся каждый день!"},"explanation":[{"en":"Colours: red, yellow, green, blue.","ru":"Цвета: red - красный, yellow - жёлтый, green - зелёный, blue - синий."},{"en":"Numbers: one, two, three, four, five.","ru":"Числа: one - 1, two - 2, three - 3, four - 4, five - 5."},{"en":"Animals: cat, dog, bird, fish.","ru":"Животные: cat - кошка, dog - собака, bird - птица, fish - рыба."},{"en":"Family: mother, father, sister, brother.","ru":"Семья: mother - мама, father - папа, sister - сестра, brother - брат."}],"example":{"kind":"text","text":{"en":"🔴 red  🐱 cat  3 three  👩 mother","ru":"🔴 red - красный  🐱 cat - кошка  3 three - три  👩 mother - мама"}},"game":"memory-match","reviewTips":{"en":"Name things around you in English: colours of toys, family photos, pets.","ru":"Называй по-английски то, что вокруг: цвета игрушек, родных на фото, питомцев."}}'::jsonb, 1, 10, '{"objective":{"en":"Recognise and use common English words for colours, numbers, animals and family.","ru":"Узнавать и использовать английские слова: цвета, числа, животные и семья."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('languages.english-grammar.l1', 'languages.english-grammar', '{"en":"Am, Is, Are and More","ru":"Am, is, are и не только"}'::jsonb, '{"character":"luna","masteryScore":0.8,"status":"reviewed","id":"languages.english-grammar.l1","topicId":"languages.english-grammar","title":{"en":"Am, Is, Are and More","ru":"Am, is, are и не только"},"subtopic":{"en":"To be, plurals, Present Simple","ru":"Глагол to be, множественное число, Present Simple"},"objective":{"en":"Use am/is/are, make plurals with -s/-es and add -s for he/she/it in the Present Simple.","ru":"Использовать am/is/are, образовывать множественное число с -s/-es и добавлять -s после he/she/it в Present Simple."},"ageRange":[8,13],"grades":[3,7],"difficulty":2,"durationMin":12,"intro":{"en":"Small words make big sentences. Let''s master them!","ru":"Маленькие слова строят большие предложения. Давай с ними разберёмся!"},"explanation":[{"en":"To be: I am, he/she/it is, we/you/they are. Example: I am happy. She is my friend.","ru":"Глагол to be (быть): I am, he/she/it is, we/you/they are. Пример: I am happy - Я счастлив. She is my friend - Она моя подруга."},{"en":"Plurals: add -s (cat → cats). After s, x, sh, ch add -es (box → boxes).","ru":"Множественное число: добавляем -s (cat → cats). После s, x, sh, ch добавляем -es (box → boxes)."},{"en":"Present Simple is for habits: I play, they play, but he plays, she plays (add -s).","ru":"Present Simple - для привычных действий: I play, they play, но he plays, she plays (добавляем -s)."}],"example":{"kind":"text","text":{"en":"I am · She is · They are · cat → cats · box → boxes · he plays","ru":"I am · She is · They are · cat → cats · box → boxes · he plays"}},"reviewTips":{"en":"Make three sentences about your family with am, is and are.","ru":"Составь три предложения о своей семье с am, is и are."}}'::jsonb, 2, 12, '{"objective":{"en":"Use am/is/are, make plurals with -s/-es and add -s for he/she/it in the Present Simple.","ru":"Использовать am/is/are, образовывать множественное число с -s/-es и добавлять -s после he/she/it в Present Simple."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('languages.english-dialogues.l1', 'languages.english-dialogues', '{"en":"Let''s Talk!","ru":"Давай поговорим!"}'::jsonb, '{"character":"luna","masteryScore":0.8,"status":"reviewed","id":"languages.english-dialogues.l1","topicId":"languages.english-dialogues","title":{"en":"Let''s Talk!","ru":"Давай поговорим!"},"subtopic":{"en":"Asking and answering simple questions","ru":"Простые вопросы и ответы"},"objective":{"en":"Ask and answer questions about name, age, home and likes.","ru":"Задавать вопросы и отвечать об имени, возрасте, родном городе и любимых вещах."},"ageRange":[9,15],"grades":[4,9],"difficulty":3,"durationMin":12,"intro":{"en":"A conversation is like a game of catch: a question, then an answer!","ru":"Разговор похож на игру в мяч: вопрос - ответ!"},"explanation":[{"en":"What''s your name? - My name is Anna.","ru":"What''s your name? (Как тебя зовут?) - My name is Anna. (Меня зовут Анна.)"},{"en":"How old are you? - I''m ten. Where are you from? - I''m from Tashkent.","ru":"How old are you? (Сколько тебе лет?) - I''m ten. Where are you from? (Откуда ты?) - I''m from Tashkent."},{"en":"Do you like pizza? - Yes, I do. / No, I don''t.","ru":"Do you like pizza? (Ты любишь пиццу?) - Yes, I do. / No, I don''t. (Да. / Нет.)"},{"en":"In questions the verb often comes before the subject: You are ten → Are you ten?","ru":"В вопросе глагол часто стоит перед подлежащим: You are ten → Are you ten?"}],"example":{"kind":"text","text":{"en":"— What''s your name?\n— My name is Tom.\n— Nice to meet you, Tom!\n— Nice to meet you too!","ru":"— What''s your name?\n— My name is Tom.\n— Nice to meet you, Tom!\n— Nice to meet you too!"}},"reviewTips":{"en":"Act out a short dialogue with a friend: name, age, where you are from.","ru":"Разыграй с другом короткий диалог: имя, возраст, откуда ты."}}'::jsonb, 3, 12, '{"objective":{"en":"Ask and answer questions about name, age, home and likes.","ru":"Задавать вопросы и отвечать об имени, возрасте, родном городе и любимых вещах."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('languages.uzbek-basics.l1', 'languages.uzbek-basics', '{"en":"Salom, Uzbek!","ru":"Salom, узбекский!"}'::jsonb, '{"character":"luna","masteryScore":0.8,"status":"reviewed","id":"languages.uzbek-basics.l1","topicId":"languages.uzbek-basics","title":{"en":"Salom, Uzbek!","ru":"Salom, узбекский!"},"subtopic":{"en":"Greetings, polite words and numbers 1-10","ru":"Приветствия, вежливые слова и числа 1-10"},"objective":{"en":"Greet, thank and say goodbye in Uzbek and count from 1 to 10.","ru":"Здороваться, благодарить и прощаться по-узбекски и считать от 1 до 10."},"ageRange":[6,12],"grades":[1,6],"difficulty":1,"durationMin":10,"intro":{"en":"Salom! That means hello in Uzbek. Let''s learn more!","ru":"Salom! По-узбекски это значит «привет». Давай узнаем больше!"},"explanation":[{"en":"Uzbek is written with Latin letters. Some special letters: oʻ, gʻ, sh, ch, ng. X sounds like h in \"loch\".","ru":"Узбекский язык пишется латиницей. Особые буквы: oʻ, gʻ, sh, ch, ng. Буква X читается как русское «х»."},{"en":"Salom - hello. Assalomu alaykum - a polite hello. Rahmat - thank you. Xayr - goodbye. Ha - yes. Yoʻq - no.","ru":"Salom - привет. Assalomu alaykum - вежливое «здравствуйте». Rahmat - спасибо. Xayr - до свидания. Ha - да. Yoʻq - нет."},{"en":"Numbers: bir 1, ikki 2, uch 3, toʻrt 4, besh 5, olti 6, yetti 7, sakkiz 8, toʻqqiz 9, oʻn 10.","ru":"Числа: bir 1, ikki 2, uch 3, toʻrt 4, besh 5, olti 6, yetti 7, sakkiz 8, toʻqqiz 9, oʻn 10."}],"example":{"kind":"text","text":{"en":"👋 Salom! - Hello!   🎁 Rahmat! - Thank you!   🚪 Xayr! - Goodbye!","ru":"👋 Salom! - Привет!   🎁 Rahmat! - Спасибо!   🚪 Xayr! - До свидания!"}},"reviewTips":{"en":"Greet your family with Salom and count your steps in Uzbek: bir, ikki, uch...","ru":"Здоровайся с родными словом Salom и считай шаги по-узбекски: bir, ikki, uch..."}}'::jsonb, 1, 10, '{"objective":{"en":"Greet, thank and say goodbye in Uzbek and count from 1 to 10.","ru":"Здороваться, благодарить и прощаться по-узбекски и считать от 1 до 10."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('languages.russian-basics.l1', 'languages.russian-basics', '{"en":"Privet, Russian!","ru":"Привет, русский!"}'::jsonb, '{"character":"luna","masteryScore":0.8,"status":"reviewed","id":"languages.russian-basics.l1","topicId":"languages.russian-basics","title":{"en":"Privet, Russian!","ru":"Привет, русский!"},"subtopic":{"en":"Cyrillic letters, greetings and numbers 1-5","ru":"Кириллица, приветствия и числа 1-5"},"objective":{"en":"Greet, thank and say goodbye in Russian, recognise some Cyrillic letters and count to 5.","ru":"Здороваться, благодарить и прощаться по-русски, узнавать буквы кириллицы и считать до 5."},"ageRange":[6,12],"grades":[1,6],"difficulty":1,"durationMin":10,"intro":{"en":"Привет! (Privet!) That means hi in Russian. Let''s begin!","ru":"Привет! Давай учить русский язык вместе!"},"explanation":[{"en":"Russian uses Cyrillic letters. Some look familiar but sound different: Р is R, Н is N, В is V. Д sounds like D.","ru":"Русский язык пишется кириллицей. Некоторые буквы похожи на латинские, но читаются иначе: Р - [р], Н - [н], В - [в]. Д - это звук [д]."},{"en":"Привет (privet) - hi. Здравствуйте (zdravstvuyte) - polite hello. Спасибо (spasibo) - thank you. Пока (poka) - bye. До свидания (do svidaniya) - goodbye.","ru":"Привет - так здороваются с друзьями. Здравствуйте - вежливое приветствие. Спасибо - когда благодарят. Пока и До свидания - когда прощаются."},{"en":"Numbers: один 1, два 2, три 3, четыре 4, пять 5.","ru":"Числа: один 1, два 2, три 3, четыре 4, пять 5."}],"example":{"kind":"text","text":{"en":"👋 Привет! - Hi!   🎁 Спасибо! - Thank you!   🚪 Пока! - Bye!","ru":"👋 Привет!   🎁 Спасибо!   🚪 Пока!"}},"reviewTips":{"en":"Say Привет, Спасибо and Пока every day and count to five in Russian.","ru":"Каждый день говори Привет, Спасибо и Пока и считай до пяти."}}'::jsonb, 1, 10, '{"objective":{"en":"Greet, thank and say goodbye in Russian, recognise some Cyrillic letters and count to 5.","ru":"Здороваться, благодарить и прощаться по-русски, узнавать буквы кириллицы и считать до 5."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.computer-basics.l1', 'tech.computer-basics', '{"en":"Meet the Computer","ru":"Знакомство с компьютером"}'::jsonb, '{"id":"tech.computer-basics.l1","topicId":"tech.computer-basics","title":{"en":"Meet the Computer","ru":"Знакомство с компьютером"},"subtopic":{"en":"Computer parts, input and output, files and folders","ru":"Части компьютера, ввод и вывод, файлы и папки"},"objective":{"en":"Name the main parts of a computer, tell input from output devices and know why we save files in folders.","ru":"Называть основные части компьютера, отличать устройства ввода от устройств вывода и понимать, зачем сохранять файлы в папки."},"ageRange":[7,10],"grades":[1,4],"difficulty":1,"durationMin":8,"character":"bruno","intro":{"en":"Beep boop! Let''s look inside the world of computers!","ru":"Бип-буп! Давай заглянем в мир компьютеров!"},"explanation":[{"en":"A computer has many parts. The screen (monitor) shows pictures and words. We type letters with the keyboard and point and click with the mouse. The processor is the computer''s \"brain\" that does the thinking.","ru":"У компьютера много частей. Экран (монитор) показывает картинки и слова. Клавиатурой мы печатаем буквы, а мышкой показываем и нажимаем. Процессор - это «мозг» компьютера, который всё обдумывает."},{"en":"Input devices put information into the computer: keyboard, mouse, microphone. Output devices give information back to us: screen, printer, speakers.","ru":"Устройства ввода передают информацию в компьютер: клавиатура, мышь, микрофон. Устройства вывода выдают её нам: экран, принтер, колонки."},{"en":"Your work is kept in files - a drawing or a story. Folders hold files, like boxes for toys. Remember to save your work so it is not lost!","ru":"Твоя работа хранится в файлах - например, рисунок или рассказ. Папки хранят файлы, как коробки - игрушки. Не забывай сохранять работу, чтобы она не потерялась!"}],"example":{"kind":"emoji","items":["🖥️","⌨️","🖱️","🖨️","🔊","📁"],"caption":{"en":"Screen, keyboard, mouse, printer, speakers and a folder.","ru":"Экран, клавиатура, мышь, принтер, колонки и папка."}},"masteryScore":0.8,"reviewTips":{"en":"Point to each part of a real or pictured computer and say: is it input or output?","ru":"Покажи на каждую часть компьютера (настоящего или на картинке) и скажи: это ввод или вывод?"},"status":"reviewed"}'::jsonb, 1, 8, '{"objective":{"en":"Name the main parts of a computer, tell input from output devices and know why we save files in folders.","ru":"Называть основные части компьютера, отличать устройства ввода от устройств вывода и понимать, зачем сохранять файлы в папки."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.internet-safety.l1', 'tech.internet-safety', '{"en":"Safe and Kind Online","ru":"Безопасно и по-доброму в сети"}'::jsonb, '{"id":"tech.internet-safety.l1","topicId":"tech.internet-safety","title":{"en":"Safe and Kind Online","ru":"Безопасно и по-доброму в сети"},"subtopic":{"en":"Private information, passwords and kindness online","ru":"Личные данные, пароли и доброта в интернете"},"objective":{"en":"Keep private information private, choose strong passwords, tell a trusted adult when something feels wrong and be kind online.","ru":"Хранить личные данные в тайне, выбирать надёжные пароли, рассказывать взрослому, если что-то тревожит, и быть добрым в сети."},"ageRange":[7,17],"grades":[1,11],"difficulty":1,"durationMin":10,"character":"bruno","intro":{"en":"The internet is full of fun - let''s learn to be safe and kind there!","ru":"В интернете много интересного - давай научимся быть там в безопасности и вести себя по-доброму!"},"explanation":[{"en":"Some information is private: your home address, phone number, passwords, school name and photos of you. Never share it with people you meet online - even if they seem friendly. People online are not always who they say they are.","ru":"Некоторые сведения - личные: домашний адрес, номер телефона, пароли, название школы и твои фотографии. Никогда не сообщай их тем, с кем познакомился в интернете, - даже если они кажутся дружелюбными. Люди в сети не всегда те, за кого себя выдают."},{"en":"A strong password is long and mixes words, numbers and symbols, like \"Blue!Tiger7Jumps\". Keep it secret - share it only with your parent or guardian.","ru":"Надёжный пароль длинный и сочетает слова, цифры и символы, например «Blue!Tiger7Jumps». Держи его в секрете - знать его могут только родители или опекуны."},{"en":"If something online makes you feel worried, scared or uncomfortable, stop and tell a trusted adult. Be kind: say nice things, think before you post, and help others by telling an adult about bullying.","ru":"Если что-то в интернете тебя тревожит, пугает или смущает, остановись и расскажи взрослому, которому доверяешь. Будь добрым: пиши приятные слова, думай, прежде чем публиковать, и помогай другим - рассказывай взрослым о травле."}],"example":{"kind":"emoji","items":["🔒","🏠","📱","🙅","🧑‍🤝‍🧑","💬","❤️"],"caption":{"en":"Lock away your address, phone and password. Talk to a trusted adult. Be kind!","ru":"Береги адрес, телефон и пароль. Говори со взрослыми, которым доверяешь. Будь добрым!"}},"masteryScore":0.8,"reviewTips":{"en":"Remember three rules: keep private info private, tell a trusted adult, be kind online.","ru":"Запомни три правила: береги личные данные, рассказывай взрослым, которым доверяешь, будь добрым в сети."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Keep private information private, choose strong passwords, tell a trusted adult when something feels wrong and be kind online.","ru":"Хранить личные данные в тайне, выбирать надёжные пароли, рассказывать взрослому, если что-то тревожит, и быть добрым в сети."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.algorithms.l1', 'tech.algorithms', '{"en":"Algorithms: Steps for a Robot","ru":"Алгоритмы: шаги для робота"}'::jsonb, '{"id":"tech.algorithms.l1","topicId":"tech.algorithms","title":{"en":"Algorithms: Steps for a Robot","ru":"Алгоритмы: шаги для робота"},"subtopic":{"en":"Step-by-step instructions and debugging","ru":"Пошаговые инструкции и исправление ошибок"},"objective":{"en":"Write a short sequence of commands that moves a robot to a goal and fix a program that has a bug.","ru":"Составлять короткую последовательность команд, которая приводит робота к цели, и исправлять ошибки в программе."},"ageRange":[7,10],"grades":[1,4],"difficulty":1,"durationMin":10,"character":"bruno","intro":{"en":"My robot friend only does exactly what we tell it. Let''s give it clear steps!","ru":"Мой друг-робот делает только то, что мы ему скажем. Давай дадим ему понятные шаги!"},"explanation":[{"en":"An algorithm is a list of steps in the right order, like a recipe or brushing your teeth. If the order is mixed up, the result will be different.","ru":"Алгоритм - это список шагов в правильном порядке, как рецепт или чистка зубов. Если перепутать порядок, получится совсем другой результат."},{"en":"Our robot knows three blocks: \"forward\" moves one square in the direction it faces, \"left\" and \"right\" turn it on the spot. Turning does not move the robot.","ru":"Наш робот знает три блока: «вперёд» - шаг на одну клетку туда, куда он смотрит, «налево» и «направо» - поворот на месте. При повороте робот не сдвигается."},{"en":"If the robot doesn''t reach the flag, that''s OK! Finding and fixing the mistake is called debugging - real programmers do it every day.","ru":"Если робот не дошёл до флажка - ничего страшного! Найти и исправить ошибку - это отладка, и настоящие программисты делают это каждый день."}],"example":{"kind":"emoji","items":["🤖","⬆️","⬆️","↪️","⬆️","🏁"],"caption":{"en":"forward, forward, turn right, forward - the robot reaches the flag!","ru":"вперёд, вперёд, направо, вперёд - робот дошёл до флажка!"}},"game":"robot-coder","masteryScore":0.8,"reviewTips":{"en":"Before you run the program, trace it with your finger on the grid: move for \"forward\", turn for \"left\" or \"right\".","ru":"Перед запуском пройди программу пальцем по клеткам: шаг на «вперёд», поворот на «налево» или «направо»."},"status":"reviewed"}'::jsonb, 1, 10, '{"objective":{"en":"Write a short sequence of commands that moves a robot to a goal and fix a program that has a bug.","ru":"Составлять короткую последовательность команд, которая приводит робота к цели, и исправлять ошибки в программе."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.loops.l1', 'tech.loops', '{"en":"Loops: Do It Again!","ru":"Циклы: повтори ещё раз!"}'::jsonb, '{"id":"tech.loops.l1","topicId":"tech.loops","title":{"en":"Loops: Do It Again!","ru":"Циклы: повтори ещё раз!"},"subtopic":{"en":"Repeat blocks and patterns","ru":"Блоки повтора и закономерности"},"objective":{"en":"Spot a repeating pattern and use a repeat block to write a shorter program.","ru":"Находить повторяющийся узор и использовать блок повтора, чтобы сделать программу короче."},"ageRange":[8,11],"grades":[2,5],"difficulty":1,"durationMin":12,"character":"bruno","intro":{"en":"Why say the same thing many times? A loop repeats it for you!","ru":"Зачем повторять одно и то же много раз? Цикл сделает это за тебя!"},"explanation":[{"en":"A loop repeats some steps. Instead of \"forward, forward, forward\" we can write \"repeat 3: forward\". Programs become shorter and easier to read.","ru":"Цикл повторяет шаги. Вместо «вперёд, вперёд, вперёд» можно написать «повторить 3 раза: вперёд». Программа становится короче и понятнее."},{"en":"In our robot game, put blocks between \"repeat2\" (or \"repeat3\") and \"end\". Everything inside is done 2 (or 3) times, in order.","ru":"В игре с роботом помести блоки между «повторить 2» (или «повторить 3») и «конец». Всё, что внутри, выполнится 2 (или 3) раза по порядку."},{"en":"Tip: look for a pattern in the path, like a staircase: up, turn, across, turn... That pattern goes inside the loop.","ru":"Совет: ищи узор на пути, например лесенку: вверх, поворот, вбок, поворот... Этот узор и помещают внутрь цикла."}],"example":{"kind":"code","code":"repeat 3:\n  forward\n  right\n  forward\n  left\nend","caption":{"en":"4 blocks inside the loop, done 3 times = 12 steps with just 6 blocks!","ru":"4 блока внутри цикла выполняются 3 раза = 12 действий всего из 6 блоков!"}},"game":"robot-coder","masteryScore":0.8,"reviewTips":{"en":"Find the part of the path that repeats, write it once, and put it inside a repeat block.","ru":"Найди повторяющуюся часть пути, запиши её один раз и помести в блок повтора."},"status":"reviewed"}'::jsonb, 1, 12, '{"objective":{"en":"Spot a repeating pattern and use a repeat block to write a shorter program.","ru":"Находить повторяющийся узор и использовать блок повтора, чтобы сделать программу короче."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.conditions.l1', 'tech.conditions', '{"en":"If This, Then That","ru":"Если так, то вот так"}'::jsonb, '{"id":"tech.conditions.l1","topicId":"tech.conditions","title":{"en":"If This, Then That","ru":"Если так, то вот так"},"subtopic":{"en":"If-then-else decisions","ru":"Решения «если - то - иначе»"},"objective":{"en":"Read if-then-else rules, decide whether a condition is true or false and plan the robot''s turns around walls.","ru":"Читать правила «если - то - иначе», определять, истинно ли условие, и планировать повороты робота у стен."},"ageRange":[9,12],"grades":[3,6],"difficulty":2,"durationMin":12,"character":"bruno","intro":{"en":"Programs make choices, just like you! Let''s learn how.","ru":"Программы умеют принимать решения - прямо как ты! Давай узнаем как."},"explanation":[{"en":"A condition is a question with a yes/no answer: \"Is it raining?\" If the answer is true, the program does one thing; else (if false) it does something else.","ru":"Условие - это вопрос, на который отвечают «да» или «нет»: «Идёт дождь?» Если ответ истинный, программа делает одно, иначе (если ложный) - другое."},{"en":"Example: if it is raining, then take an umbrella, else take sunglasses. Conditions often compare numbers: 5 > 3 is true, 2 > 7 is false.","ru":"Пример: если идёт дождь, то возьми зонт, иначе возьми солнечные очки. Условия часто сравнивают числа: 5 > 3 - истина, 2 > 7 - ложь."},{"en":"Robots use sensors to check conditions: \"if wall ahead, then turn, else move forward\". In the puzzles, check each square: is there a wall ahead? Then turn!","ru":"Роботы проверяют условия с помощью датчиков: «если впереди стена, то повернуть, иначе идти вперёд». В задачах проверяй каждую клетку: впереди стена? Тогда поворачивай!"}],"example":{"kind":"code","code":"if wall ahead:\n    turn right\nelse:\n    move forward","caption":{"en":"The robot checks the condition before every step.","ru":"Робот проверяет условие перед каждым шагом."}},"masteryScore":0.8,"reviewTips":{"en":"First decide: is the condition true or false? True → do the \"then\" part. False → do the \"else\" part.","ru":"Сначала реши: условие истинно или ложно? Истинно - выполняй часть «то». Ложно - часть «иначе»."},"status":"reviewed"}'::jsonb, 2, 12, '{"objective":{"en":"Read if-then-else rules, decide whether a condition is true or false and plan the robot''s turns around walls.","ru":"Читать правила «если - то - иначе», определять, истинно ли условие, и планировать повороты робота у стен."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.html.l1', 'tech.html', '{"en":"Build a Web Page with HTML","ru":"Создаём веб-страницу на HTML"}'::jsonb, '{"id":"tech.html.l1","topicId":"tech.html","title":{"en":"Build a Web Page with HTML","ru":"Создаём веб-страницу на HTML"},"subtopic":{"en":"Tags, headings, paragraphs, links and images","ru":"Теги, заголовки, абзацы, ссылки и изображения"},"objective":{"en":"Read and write basic HTML tags and predict how a browser will show them.","ru":"Читать и писать основные теги HTML и предсказывать, как браузер их покажет."},"ageRange":[11,15],"grades":[5,9],"difficulty":3,"durationMin":12,"character":"bruno","intro":{"en":"Every website is built with HTML. Let''s write our first page!","ru":"Каждый сайт построен на HTML. Давай напишем нашу первую страницу!"},"explanation":[{"en":"HTML (HyperText Markup Language) describes the structure of a web page. It uses tags in angle brackets. Most tags come in pairs: an opening tag <p> and a closing tag </p> with content between them.","ru":"HTML (язык гипертекстовой разметки) описывает структуру веб-страницы. В нём используются теги в угловых скобках. Большинство тегов парные: открывающий <p> и закрывающий </p>, а между ними - содержимое."},{"en":"Headings go from <h1> (biggest) to <h6> (smallest). <p> is a paragraph, <a href=\"...\"> is a link, <ul> with <li> items makes a bulleted list. <img src=\"...\" alt=\"...\"> shows an image and has no closing tag.","ru":"Заголовки бывают от <h1> (самый крупный) до <h6> (самый мелкий). <p> - абзац, <a href=\"...\"> - ссылка, <ul> с пунктами <li> - маркированный список. <img src=\"...\" alt=\"...\"> показывает картинку и не имеет закрывающего тега."},{"en":"A full page has a skeleton: <!DOCTYPE html>, then <html> containing <head> (page info, title) and <body> (everything you see).","ru":"У полной страницы есть каркас: <!DOCTYPE html>, затем <html>, внутри которого <head> (сведения о странице, заголовок) и <body> (всё, что видно на экране)."}],"example":{"kind":"code","code":"<h1>My Pets</h1>\n<p>I have a <b>cat</b> and a dog.</p>\n<ul>\n  <li>Cat: Luna</li>\n  <li>Dog: Rex</li>\n</ul>\n<a href=\"https://example.com\">Read more</a>","caption":{"en":"A heading, a paragraph, a list and a link.","ru":"Заголовок, абзац, список и ссылка."}},"masteryScore":0.8,"reviewTips":{"en":"Check that every opening tag has a matching closing tag (except <img>). Read code top to bottom like the browser does.","ru":"Проверь, что у каждого открывающего тега есть парный закрывающий (кроме <img>). Читай код сверху вниз, как браузер."},"status":"reviewed"}'::jsonb, 3, 12, '{"objective":{"en":"Read and write basic HTML tags and predict how a browser will show them.","ru":"Читать и писать основные теги HTML и предсказывать, как браузер их покажет."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.css.l1', 'tech.css', '{"en":"Style It with CSS","ru":"Оформляем с помощью CSS"}'::jsonb, '{"id":"tech.css.l1","topicId":"tech.css","title":{"en":"Style It with CSS","ru":"Оформляем с помощью CSS"},"subtopic":{"en":"Selectors, properties and the box model","ru":"Селекторы, свойства и блочная модель"},"objective":{"en":"Write CSS rules with element, class and id selectors and predict which rule wins.","ru":"Писать правила CSS с селекторами тегов, классов и id и предсказывать, какое правило сработает."},"ageRange":[12,15],"grades":[6,9],"difficulty":3,"durationMin":13,"character":"bruno","intro":{"en":"HTML builds the house, CSS paints and decorates it. Let''s add some style!","ru":"HTML строит дом, а CSS его красит и украшает. Добавим стиля!"},"explanation":[{"en":"CSS (Cascading Style Sheets) sets colours, fonts, sizes and layout. A rule has a selector and declarations: selector { property: value; }.","ru":"CSS (каскадные таблицы стилей) задаёт цвета, шрифты, размеры и расположение. Правило состоит из селектора и объявлений: селектор { свойство: значение; }."},{"en":"Selectors: p targets all paragraphs, .note targets elements with class=\"note\", #menu targets the element with id=\"menu\". Useful properties: color, background-color, font-size, margin, padding, border.","ru":"Селекторы: p выбирает все абзацы, .note - элементы с class=\"note\", #menu - элемент с id=\"menu\". Полезные свойства: color, background-color, font-size, margin, padding, border."},{"en":"Every element is a box: content, then padding, then border, then margin. When rules conflict, the more specific selector wins (id beats class, class beats element); if they are equal, the later rule wins.","ru":"Каждый элемент - это прямоугольник: содержимое, затем внутренний отступ (padding), рамка (border) и внешний отступ (margin). Если правила конфликтуют, побеждает более специфичный селектор (id сильнее класса, класс сильнее тега); при равенстве - правило, записанное позже."}],"example":{"kind":"code","code":"h1 {\n  color: blue;\n  font-size: 32px;\n}\n\n.note {\n  background-color: yellow;\n  padding: 10px;\n}","caption":{"en":"Blue 32px headings and yellow notes with padding.","ru":"Синие заголовки 32px и жёлтые заметки с внутренним отступом."}},"masteryScore":0.8,"reviewTips":{"en":"Remember: . = class, # = id. More specific wins; if equal, the last rule wins. Box width = content + padding + border.","ru":"Запомни: . - класс, # - id. Побеждает более специфичный селектор, при равенстве - последний. Ширина блока = содержимое + padding + border."},"status":"reviewed"}'::jsonb, 3, 13, '{"objective":{"en":"Write CSS rules with element, class and id selectors and predict which rule wins.","ru":"Писать правила CSS с селекторами тегов, классов и id и предсказывать, какое правило сработает."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.javascript.l1', 'tech.javascript', '{"en":"First Steps in JavaScript","ru":"Первые шаги в JavaScript"}'::jsonb, '{"id":"tech.javascript.l1","topicId":"tech.javascript","title":{"en":"First Steps in JavaScript","ru":"Первые шаги в JavaScript"},"subtopic":{"en":"Variables, conditions, functions and loops","ru":"Переменные, условия, функции и циклы"},"objective":{"en":"Trace short JavaScript programs with variables, if/else, functions and for loops and predict their output.","ru":"Прослеживать выполнение коротких программ на JavaScript с переменными, if/else, функциями и циклами for и предсказывать их вывод."},"ageRange":[13,17],"grades":[7,11],"difficulty":4,"durationMin":15,"character":"bruno","intro":{"en":"JavaScript brings web pages to life. Let''s read code like a computer!","ru":"JavaScript оживляет веб-страницы. Давай читать код, как компьютер!"},"explanation":[{"en":"Variables store values: let score = 5; can change later, const name = \"Bruno\"; cannot be reassigned. Values can be numbers, strings (text in quotes) or booleans (true/false). console.log() prints a value.","ru":"Переменные хранят значения: let score = 5; можно изменить позже, а const name = \"Bruno\"; переприсвоить нельзя. Значения бывают числами, строками (текст в кавычках) и логическими (true/false). console.log() выводит значение."},{"en":"if (condition) { ... } else { ... } chooses what to run. A function is a reusable block: function double(n) { return n * 2; }. A for loop repeats code: for (let i = 1; i <= 3; i++) { ... } runs for i = 1, 2, 3.","ru":"if (условие) { ... } else { ... } выбирает, что выполнить. Функция - многоразовый блок кода: function double(n) { return n * 2; }. Цикл for повторяет код: for (let i = 1; i <= 3; i++) { ... } выполняется при i = 1, 2, 3."},{"en":"Careful: + with a string joins text. \"3\" + 2 gives \"32\", but 3 + 2 gives 5. To trace code, go line by line and write down each variable''s value.","ru":"Осторожно: + со строкой склеивает текст. \"3\" + 2 даёт \"32\", а 3 + 2 даёт 5. Чтобы проследить код, иди строка за строкой и записывай значение каждой переменной."}],"example":{"kind":"code","code":"let score = 5;\nscore = score + 3;\nif (score > 7) {\n  console.log(\"Great!\");\n} else {\n  console.log(\"Keep going!\");\n}","caption":{"en":"score becomes 8, and 8 > 7, so it prints \"Great!\".","ru":"score становится 8, а 8 > 7, поэтому выводится \"Great!\"."}},"masteryScore":0.8,"reviewTips":{"en":"Trace code with a table: one column per variable, one row per line. Watch out for strings in quotes when using +.","ru":"Прослеживай код с помощью таблицы: столбец - переменная, строка - строка кода. Следи за строками в кавычках при использовании +."},"status":"reviewed"}'::jsonb, 4, 15, '{"objective":{"en":"Trace short JavaScript programs with variables, if/else, functions and for loops and predict their output.","ru":"Прослеживать выполнение коротких программ на JavaScript с переменными, if/else, функциями и циклами for и предсказывать их вывод."},"masteryScore":0.8}'::jsonb, 'reviewed'),
  ('tech.python.l1', 'tech.python', '{"en":"Hello, Python!","ru":"Привет, Python!"}'::jsonb, '{"id":"tech.python.l1","topicId":"tech.python","title":{"en":"Hello, Python!","ru":"Привет, Python!"},"subtopic":{"en":"print, variables, if and for loops","ru":"print, переменные, if и циклы for"},"objective":{"en":"Read short Python programs with print, variables, if/elif/else and for loops and predict their output.","ru":"Читать короткие программы на Python с print, переменными, if/elif/else и циклами for и предсказывать их вывод."},"ageRange":[13,17],"grades":[7,11],"difficulty":4,"durationMin":15,"character":"bruno","intro":{"en":"Python is friendly and powerful - scientists and game makers use it. Let''s code!","ru":"Python - дружелюбный и мощный язык, на нём пишут учёные и создатели игр. Поехали!"},"explanation":[{"en":"print() shows something on the screen. Variables are created by assigning: name = \"Bruno\", age = 12. No let or semicolons are needed.","ru":"print() выводит что-то на экран. Переменные создаются присваиванием: name = \"Bruno\", age = 12. Ни let, ни точка с запятой не нужны."},{"en":"Indentation (spaces at the start of a line) shows which lines belong to a block. if, elif and else make decisions; the first true condition runs and the rest are skipped.","ru":"Отступы (пробелы в начале строки) показывают, какие строки входят в блок. if, elif и else принимают решения: выполняется первое истинное условие, остальные пропускаются."},{"en":"for i in range(3): repeats 3 times with i = 0, 1, 2. range(1, 5) gives 1, 2, 3, 4 - the end number is not included. len(\"cat\") gives 3, and # starts a comment.","ru":"for i in range(3): повторяется 3 раза, i = 0, 1, 2. range(1, 5) даёт 1, 2, 3, 4 - конечное число не входит. len(\"cat\") даёт 3, а # начинает комментарий."}],"example":{"kind":"code","code":"name = \"Bruno\"\nage = 12\nprint(\"Hi,\", name)\nif age >= 12:\n    print(\"Teen coder!\")","caption":{"en":"Prints \"Hi, Bruno\" and then \"Teen coder!\".","ru":"Выводит \"Hi, Bruno\", а затем \"Teen coder!\"."}},"masteryScore":0.8,"reviewTips":{"en":"Remember: range(a, b) stops before b, and indentation matters. Trace each line and write down the variables.","ru":"Запомни: range(a, b) останавливается перед b, а отступы важны. Прослеживай каждую строку и записывай значения переменных."},"status":"reviewed"}'::jsonb, 4, 15, '{"objective":{"en":"Read short Python programs with print, variables, if/elif/else and for loops and predict their output.","ru":"Читать короткие программы на Python с print, переменными, if/elif/else и циклами for и предсказывать их вывод."},"masteryScore":0.8}'::jsonb, 'reviewed')
insert into public.questions (id, lesson_id, type, question_data, difficulty, explanation) values
  ('early.colors-shapes.l1.p1', 'early.colors-shapes.l1', 'image_selection', '{"id":"early.colors-shapes.l1.p1","type":"image_selection","prompt":{"en":"Tap the red circle.","ru":"Нажми на красный кружок."},"options":[{"emoji":"🔵","label":{"en":"blue","ru":"синий"}},{"emoji":"🔴","label":{"en":"red","ru":"красный"}},{"emoji":"🟡","label":{"en":"yellow","ru":"жёлтый"}}],"answer":1,"hint":{"en":"Red like a strawberry 🍓.","ru":"Красный, как клубника 🍓."},"explanation":{"en":"This circle is red, like a strawberry.","ru":"Этот кружок красный, как клубника."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"This circle is red, like a strawberry.","ru":"Этот кружок красный, как клубника."}'::jsonb),
  ('early.colors-shapes.l1.p2', 'early.colors-shapes.l1', 'true_false', '{"id":"early.colors-shapes.l1.p2","type":"true_false","prompt":{"en":"Grass is green. Yes or no?","ru":"Трава зелёная. Да или нет?"},"visual":{"kind":"emoji","items":["🌿","🌿","🌿"]},"answer":true,"hint":{"en":"Look at the picture of the grass.","ru":"Посмотри на травку на картинке."},"explanation":{"en":"Yes! Grass is green.","ru":"Да! Трава зелёная."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Yes! Grass is green.","ru":"Да! Трава зелёная."}'::jsonb),
  ('early.colors-shapes.l1.p3', 'early.colors-shapes.l1', 'drag_drop', '{"id":"early.colors-shapes.l1.p3","type":"drag_drop","prompt":{"en":"Put red things in the red box and yellow things in the yellow box.","ru":"Положи красное в красную коробку, а жёлтое - в жёлтую."},"items":[{"id":"strawberry","label":{"en":"🍓 strawberry","ru":"🍓 клубника"}},{"id":"banana","label":{"en":"🍌 banana","ru":"🍌 банан"}},{"id":"tomato","label":{"en":"🍅 tomato","ru":"🍅 помидор"}},{"id":"sunflower","label":{"en":"🌻 sunflower","ru":"🌻 подсолнух"}}],"buckets":[{"id":"red","label":{"en":"🔴 red","ru":"🔴 красный"}},{"id":"yellow","label":{"en":"🟡 yellow","ru":"🟡 жёлтый"}}],"answer":{"strawberry":"red","tomato":"red","banana":"yellow","sunflower":"yellow"},"hint":{"en":"A banana is yellow like the sun.","ru":"Банан жёлтый, как солнышко."},"explanation":{"en":"Strawberry and tomato are red. Banana and sunflower are yellow.","ru":"Клубника и помидор красные. Банан и подсолнух жёлтые."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Strawberry and tomato are red. Banana and sunflower are yellow.","ru":"Клубника и помидор красные. Банан и подсолнух жёлтые."}'::jsonb),
  ('early.colors-shapes.l1.c1', 'early.colors-shapes.l1', 'image_selection', '{"id":"early.colors-shapes.l1.c1","type":"image_selection","prompt":{"en":"Tap the yellow one.","ru":"Нажми на жёлтое."},"options":[{"emoji":"🍋","label":{"en":"lemon","ru":"лимон"}},{"emoji":"🍇","label":{"en":"grapes","ru":"виноград"}},{"emoji":"🥦","label":{"en":"broccoli","ru":"брокколи"}}],"answer":0,"explanation":{"en":"A lemon is yellow.","ru":"Лимон жёлтый."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"A lemon is yellow.","ru":"Лимон жёлтый."}'::jsonb),
  ('early.colors-shapes.l1.c2', 'early.colors-shapes.l1', 'audio_recognition', '{"id":"early.colors-shapes.l1.c2","type":"audio_recognition","prompt":{"en":"Listen and tap the colour.","ru":"Послушай и нажми на цвет."},"say":{"en":"blue","ru":"синий"},"options":[{"en":"🟢 green","ru":"🟢 зелёный"},{"en":"🔴 red","ru":"🔴 красный"},{"en":"🔵 blue","ru":"🔵 синий"}],"answer":2,"explanation":{"en":"Blue, like the sky.","ru":"Синий, как небо."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Blue, like the sky.","ru":"Синий, как небо."}'::jsonb),
  ('early.colors-shapes.l1.c3', 'early.colors-shapes.l1', 'single', '{"id":"early.colors-shapes.l1.c3","type":"single","prompt":{"en":"What colour is a carrot?","ru":"Какого цвета морковка?"},"visual":{"kind":"emoji","items":["🥕"]},"options":[{"en":"🟠 orange","ru":"🟠 оранжевая"},{"en":"🟣 purple","ru":"🟣 фиолетовая"},{"en":"🔵 blue","ru":"🔵 синяя"}],"answer":0,"explanation":{"en":"A carrot is orange.","ru":"Морковка оранжевая."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"A carrot is orange.","ru":"Морковка оранжевая."}'::jsonb),
  ('early.colors-shapes.l1.c4', 'early.colors-shapes.l1', 'image_selection', '{"id":"early.colors-shapes.l1.c4","type":"image_selection","prompt":{"en":"Which one is green?","ru":"Кто здесь зелёный?"},"options":[{"emoji":"🍎","label":{"en":"apple","ru":"яблоко"}},{"emoji":"🐸","label":{"en":"frog","ru":"лягушка"}},{"emoji":"🍊","label":{"en":"orange","ru":"апельсин"}}],"answer":1,"explanation":{"en":"The frog is green.","ru":"Лягушка зелёная."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"The frog is green.","ru":"Лягушка зелёная."}'::jsonb),
  ('early.colors-shapes.l2.p1', 'early.colors-shapes.l2', 'image_selection', '{"id":"early.colors-shapes.l2.p1","type":"image_selection","prompt":{"en":"Find the triangle.","ru":"Найди треугольник."},"options":[{"emoji":"🟦","label":{"en":"square","ru":"квадрат"}},{"emoji":"🔺","label":{"en":"triangle","ru":"треугольник"}},{"emoji":"⚪","label":{"en":"circle","ru":"круг"}}],"answer":1,"hint":{"en":"A triangle has 3 corners, like a roof.","ru":"У треугольника 3 угла, как у крыши."},"explanation":{"en":"This is a triangle: 3 sides and 3 corners.","ru":"Это треугольник: 3 стороны и 3 угла."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"This is a triangle: 3 sides and 3 corners.","ru":"Это треугольник: 3 стороны и 3 угла."}'::jsonb),
  ('early.colors-shapes.l2.p2', 'early.colors-shapes.l2', 'drawing', '{"id":"early.colors-shapes.l2.p2","type":"drawing","prompt":{"en":"Trace the circle with your finger.","ru":"Обведи круг пальчиком."},"label":{"en":"Circle","ru":"Круг"},"path":[[50,15],[67.5,19.7],[80.3,32.5],[85,50],[80.3,67.5],[67.5,80.3],[50,85],[32.5,80.3],[19.7,67.5],[15,50],[19.7,32.5],[32.5,19.7],[50,15]],"hint":{"en":"Go round and round, slowly.","ru":"Веди по кругу, не спеши."},"explanation":{"en":"Great - a circle is round, it has no corners.","ru":"Отлично - круг круглый, у него нет углов."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Great - a circle is round, it has no corners.","ru":"Отлично - круг круглый, у него нет углов."}'::jsonb),
  ('early.colors-shapes.l2.p3', 'early.colors-shapes.l2', 'ordering', '{"id":"early.colors-shapes.l2.p3","type":"ordering","prompt":{"en":"Put them in order from small to big.","ru":"Поставь по порядку от маленького к большому."},"items":[{"en":"🐭 mouse","ru":"🐭 мышка"},{"en":"🐱 cat","ru":"🐱 кошка"},{"en":"🐘 elephant","ru":"🐘 слон"}],"hint":{"en":"Start with the smallest animal.","ru":"Начни с самого маленького зверька."},"explanation":{"en":"Mouse is small, cat is bigger, elephant is the biggest.","ru":"Мышка маленькая, кошка больше, слон самый большой."},"difficulty":2,"audio":true,"role":"practice"}'::jsonb, 2, '{"en":"Mouse is small, cat is bigger, elephant is the biggest.","ru":"Мышка маленькая, кошка больше, слон самый большой."}'::jsonb),
  ('early.colors-shapes.l2.c1', 'early.colors-shapes.l2', 'image_selection', '{"id":"early.colors-shapes.l2.c1","type":"image_selection","prompt":{"en":"Which shape is round like a ball?","ru":"Какая фигура круглая, как мячик?"},"options":[{"emoji":"🟥","label":{"en":"square","ru":"квадрат"}},{"emoji":"🔺","label":{"en":"triangle","ru":"треугольник"}},{"emoji":"🔵","label":{"en":"circle","ru":"круг"}}],"answer":2,"explanation":{"en":"A circle is round, like a ball.","ru":"Круг круглый, как мячик."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"A circle is round, like a ball.","ru":"Круг круглый, как мячик."}'::jsonb),
  ('early.colors-shapes.l2.c2', 'early.colors-shapes.l2', 'number_input', '{"id":"early.colors-shapes.l2.c2","type":"number_input","prompt":{"en":"How many corners does a triangle have?","ru":"Сколько углов у треугольника?"},"visual":{"kind":"emoji","items":["🔺"]},"answer":3,"explanation":{"en":"A triangle has 3 corners.","ru":"У треугольника 3 угла."},"difficulty":2,"audio":true,"role":"check"}'::jsonb, 2, '{"en":"A triangle has 3 corners.","ru":"У треугольника 3 угла."}'::jsonb),
  ('early.colors-shapes.l2.c3', 'early.colors-shapes.l2', 'drawing', '{"id":"early.colors-shapes.l2.c3","type":"drawing","prompt":{"en":"Trace the square.","ru":"Обведи квадрат."},"label":{"en":"Square","ru":"Квадрат"},"path":[[20,20],[80,20],[80,80],[20,80],[20,20]],"explanation":{"en":"A square has 4 equal sides.","ru":"У квадрата 4 одинаковые стороны."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"A square has 4 equal sides.","ru":"У квадрата 4 одинаковые стороны."}'::jsonb),
  ('early.colors-shapes.l2.c4', 'early.colors-shapes.l2', 'true_false', '{"id":"early.colors-shapes.l2.c4","type":"true_false","prompt":{"en":"An elephant is bigger than a mouse. Yes or no?","ru":"Слон больше мышки. Да или нет?"},"visual":{"kind":"emoji","items":["🐘","🐭"]},"answer":true,"explanation":{"en":"Yes! An elephant is much bigger than a mouse.","ru":"Да! Слон намного больше мышки."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Yes! An elephant is much bigger than a mouse.","ru":"Да! Слон намного больше мышки."}'::jsonb),
  ('early.numbers.l1.p1', 'early.numbers.l1', 'audio_recognition', '{"id":"early.numbers.l1.p1","type":"audio_recognition","prompt":{"en":"Listen and tap the number.","ru":"Послушай и нажми на цифру."},"say":{"en":"three","ru":"три"},"options":[{"en":"1","ru":"1"},{"en":"3","ru":"3"},{"en":"5","ru":"5"}],"answer":1,"hint":{"en":"Three is like 3 fingers: 1, 2, 3.","ru":"Три - это 3 пальчика: 1, 2, 3."},"explanation":{"en":"This is 3, three.","ru":"Это 3, три."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"This is 3, three.","ru":"Это 3, три."}'::jsonb),
  ('early.numbers.l1.p2', 'early.numbers.l1', 'drawing', '{"id":"early.numbers.l1.p2","type":"drawing","prompt":{"en":"Trace the number 1.","ru":"Обведи цифру 1."},"label":{"en":"1","ru":"1"},"path":[[35,28],[55,10],[55,90]],"hint":{"en":"Go up a little, then straight down.","ru":"Сначала немного вверх, потом прямо вниз."},"explanation":{"en":"You wrote 1, one!","ru":"Ты написал 1, один!"},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"You wrote 1, one!","ru":"Ты написал 1, один!"}'::jsonb),
  ('early.numbers.l1.p3', 'early.numbers.l1', 'number_input', '{"id":"early.numbers.l1.p3","type":"number_input","prompt":{"en":"How many ducks?","ru":"Сколько уточек?"},"visual":{"kind":"emoji","items":["🦆","🦆"]},"answer":2,"hint":{"en":"Touch each duck and count.","ru":"Дотронься до каждой уточки и посчитай."},"explanation":{"en":"1, 2 - two ducks.","ru":"1, 2 - две уточки."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"1, 2 - two ducks.","ru":"1, 2 - две уточки."}'::jsonb),
  ('early.numbers.l1.c1', 'early.numbers.l1', 'audio_recognition', '{"id":"early.numbers.l1.c1","type":"audio_recognition","prompt":{"en":"Listen and tap the number.","ru":"Послушай и нажми на цифру."},"say":{"en":"five","ru":"пять"},"options":[{"en":"5","ru":"5"},{"en":"2","ru":"2"},{"en":"4","ru":"4"}],"answer":0,"explanation":{"en":"This is 5, five - like the fingers on one hand.","ru":"Это 5, пять - как пальчики на руке."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"This is 5, five - like the fingers on one hand.","ru":"Это 5, пять - как пальчики на руке."}'::jsonb),
  ('early.numbers.l1.c2', 'early.numbers.l1', 'ordering', '{"id":"early.numbers.l1.c2","type":"ordering","prompt":{"en":"Put the numbers in order.","ru":"Поставь цифры по порядку."},"items":[{"en":"1","ru":"1"},{"en":"2","ru":"2"},{"en":"3","ru":"3"},{"en":"4","ru":"4"}],"explanation":{"en":"1, 2, 3, 4 - well counted!","ru":"1, 2, 3, 4 - хорошо посчитал!"},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"1, 2, 3, 4 - well counted!","ru":"1, 2, 3, 4 - хорошо посчитал!"}'::jsonb),
  ('early.numbers.l1.c3', 'early.numbers.l1', 'matching', '{"id":"early.numbers.l1.c3","type":"matching","prompt":{"en":"Match the number with the stars.","ru":"Соедини цифру со звёздочками."},"pairs":[{"left":{"en":"1","ru":"1"},"right":{"en":"⭐","ru":"⭐"}},{"left":{"en":"2","ru":"2"},"right":{"en":"⭐⭐","ru":"⭐⭐"}},{"left":{"en":"3","ru":"3"},"right":{"en":"⭐⭐⭐","ru":"⭐⭐⭐"}}],"explanation":{"en":"1 star, 2 stars, 3 stars.","ru":"1 звёздочка, 2 звёздочки, 3 звёздочки."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"1 star, 2 stars, 3 stars.","ru":"1 звёздочка, 2 звёздочки, 3 звёздочки."}'::jsonb),
  ('early.numbers.l1.c4', 'early.numbers.l1', 'true_false', '{"id":"early.numbers.l1.c4","type":"true_false","prompt":{"en":"This is zero. Zero means none. Yes or no?","ru":"Это ноль. Ноль - значит ничего. Да или нет?"},"visual":{"kind":"text","text":{"en":"0","ru":"0"}},"answer":true,"explanation":{"en":"Yes! Zero means none at all.","ru":"Да! Ноль - значит совсем ничего."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Yes! Zero means none at all.","ru":"Да! Ноль - значит совсем ничего."}'::jsonb),
  ('early.numbers.l2.p1', 'early.numbers.l2', 'audio_recognition', '{"id":"early.numbers.l2.p1","type":"audio_recognition","prompt":{"en":"Listen and tap the number.","ru":"Послушай и нажми на цифру."},"say":{"en":"seven","ru":"семь"},"options":[{"en":"7","ru":"7"},{"en":"1","ru":"1"},{"en":"9","ru":"9"}],"answer":0,"hint":{"en":"Seven has a line on top and a line going down.","ru":"У семёрки чёрточка сверху и палочка вниз."},"explanation":{"en":"This is 7, seven.","ru":"Это 7, семь."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"This is 7, seven.","ru":"Это 7, семь."}'::jsonb),
