  ('math.functions.l1.c2', 'math.functions.l1', 'single', '{"type":"single","prompt":{"en":"Which line goes down from left to right?","ru":"Какая прямая идёт вниз слева направо?"},"options":[{"en":"y = 2x + 3","ru":"y = 2x + 3"},{"en":"y = −x + 4","ru":"y = −x + 4"},{"en":"y = 5","ru":"y = 5"}],"answer":1,"explanation":{"en":"k = −1 is negative, so the line goes down.","ru":"k = −1 отрицательный, поэтому прямая убывает."},"difficulty":4,"id":"math.functions.l1.c2","role":"check"}'::jsonb, 4, '{"en":"k = −1 is negative, so the line goes down.","ru":"k = −1 отрицательный, поэтому прямая убывает."}'::jsonb),
