  ('math.functions.l1.c5', 'math.functions.l1', 'math_input', '{"type":"math_input","prompt":{"en":"A line passes through (0, 1) and (2, 5). Find its slope k.","ru":"Прямая проходит через (0; 1) и (2; 5). Найди k."},"accepted":["2","k=2"],"explanation":{"en":"k = (5 − 1) ÷ (2 − 0) = 2.","ru":"k = (5 − 1) : (2 − 0) = 2."},"difficulty":4,"id":"math.functions.l1.c5","role":"check"}'::jsonb, 4, '{"en":"k = (5 − 1) ÷ (2 − 0) = 2.","ru":"k = (5 − 1) : (2 − 0) = 2."}'::jsonb),
