  ('math.quadratics.l1.p2', 'math.quadratics.l1', 'single', '{"type":"single","prompt":{"en":"How many real roots does x² + 2x + 5 = 0 have?","ru":"Сколько действительных корней у x² + 2x + 5 = 0?"},"options":[{"en":"2","ru":"2"},{"en":"1","ru":"1"},{"en":"0","ru":"0"}],"answer":2,"hint":{"en":"Find the sign of D.","ru":"Определи знак D."},"explanation":{"en":"D = 4 − 20 = −16 < 0, so there are no real roots.","ru":"D = 4 − 20 = −16 < 0, поэтому действительных корней нет."},"difficulty":4,"id":"math.quadratics.l1.p2","role":"practice"}'::jsonb, 4, '{"en":"D = 4 − 20 = −16 < 0, so there are no real roots.","ru":"D = 4 − 20 = −16 < 0, поэтому действительных корней нет."}'::jsonb),
  ('math.quadratics.l1.p3', 'math.quadratics.l1', 'math_input', '{"type":"math_input","prompt":{"en":"x² − 9 = 0. Find the positive root.","ru":"x² − 9 = 0. Найди положительный корень."},"accepted":["3","x=3"],"hint":{"en":"x² = 9.","ru":"x² = 9."},"explanation":{"en":"x² = 9 gives x = 3 or x = −3. The positive root is 3.","ru":"x² = 9, значит x = 3 или x = −3. Положительный корень — 3."},"difficulty":4,"id":"math.quadratics.l1.p3","role":"practice"}'::jsonb, 4, '{"en":"x² = 9 gives x = 3 or x = −3. The positive root is 3.","ru":"x² = 9, значит x = 3 или x = −3. Положительный корень — 3."}'::jsonb),
  ('math.quadratics.l1.c1', 'math.quadratics.l1', 'number_input', '{"type":"number_input","prompt":{"en":"x² − 7x + 10 = 0. Enter the larger root.","ru":"x² − 7x + 10 = 0. Введи больший корень."},"explanation":{"en":"D = 49 − 40 = 9, x = (7 ± 3) ÷ 2, so x = 2 or 5. The larger is 5.","ru":"D = 49 − 40 = 9, x = (7 ± 3) / 2, значит x = 2 или 5. Больший — 5."},"answer":5,"difficulty":4,"id":"math.quadratics.l1.c1","role":"check"}'::jsonb, 4, '{"en":"D = 49 − 40 = 9, x = (7 ± 3) ÷ 2, so x = 2 or 5. The larger is 5.","ru":"D = 49 − 40 = 9, x = (7 ± 3) / 2, значит x = 2 или 5. Больший — 5."}'::jsonb),
  ('math.quadratics.l1.c2', 'math.quadratics.l1', 'true_false', '{"type":"true_false","prompt":{"en":"x = −1 is a root of x² + 3x + 2 = 0.","ru":"x = −1 — корень уравнения x² + 3x + 2 = 0."},"explanation":{"en":"1 − 3 + 2 = 0. Yes!","ru":"1 − 3 + 2 = 0. Да!"},"answer":true,"difficulty":4,"id":"math.quadratics.l1.c2","role":"check"}'::jsonb, 4, '{"en":"1 − 3 + 2 = 0. Yes!","ru":"1 − 3 + 2 = 0. Да!"}'::jsonb),
  ('math.quadratics.l1.c3', 'math.quadratics.l1', 'single', '{"type":"single","prompt":{"en":"Solve x² − 6x + 9 = 0.","ru":"Реши x² − 6x + 9 = 0."},"options":[{"en":"Two roots","ru":"Два корня"},{"en":"One root: x = 3","ru":"Один корень: x = 3"},{"en":"No real roots","ru":"Нет действительных корней"}],"answer":1,"explanation":{"en":"D = 36 − 36 = 0, x = 6 ÷ 2 = 3. It is (x − 3)² = 0.","ru":"D = 36 − 36 = 0, x = 6 / 2 = 3. Это (x − 3)² = 0."},"difficulty":4,"id":"math.quadratics.l1.c3","role":"check"}'::jsonb, 4, '{"en":"D = 36 − 36 = 0, x = 6 ÷ 2 = 3. It is (x − 3)² = 0.","ru":"D = 36 − 36 = 0, x = 6 / 2 = 3. Это (x − 3)² = 0."}'::jsonb),
  ('math.quadratics.l1.c4', 'math.quadratics.l1', 'number_input', '{"type":"number_input","prompt":{"en":"x² − 8x + 15 = 0. What is the sum of the roots?","ru":"x² − 8x + 15 = 0. Чему равна сумма корней?"},"explanation":{"en":"The roots are 3 and 5, sum 8 (Vieta: x₁ + x₂ = −b/a).","ru":"Корни 3 и 5, сумма 8 (теорема Виета: x₁ + x₂ = −b/a)."},"answer":8,"difficulty":4,"id":"math.quadratics.l1.c4","role":"check"}'::jsonb, 4, '{"en":"The roots are 3 and 5, sum 8 (Vieta: x₁ + x₂ = −b/a).","ru":"Корни 3 и 5, сумма 8 (теорема Виета: x₁ + x₂ = −b/a)."}'::jsonb),
  ('math.quadratics.l1.c5', 'math.quadratics.l1', 'ordering', '{"type":"ordering","prompt":{"en":"Put the solving steps in order.","ru":"Расставь шаги решения по порядку."},"items":[{"en":"Write down a, b and c","ru":"Выписать a, b и c"},{"en":"Compute D = b² − 4ac","ru":"Вычислить D = b² − 4ac"},{"en":"Check the sign of D","ru":"Определить знак D"},{"en":"Use x = (−b ± √D) / (2a)","ru":"Применить x = (−b ± √D) / (2a)"}],"explanation":{"en":"Coefficients, discriminant, its sign, then the formula.","ru":"Коэффициенты, дискриминант, его знак, затем формула."},"difficulty":4,"id":"math.quadratics.l1.c5","role":"check"}'::jsonb, 4, '{"en":"Coefficients, discriminant, its sign, then the formula.","ru":"Коэффициенты, дискриминант, его знак, затем формула."}'::jsonb),
  ('math.geometry.l1.p1', 'math.geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"Two angles of a triangle are 50° and 60°. Find the third.","ru":"Два угла треугольника 50° и 60°. Найди третий."},"unit":{"en":"°","ru":"°"},"hint":{"en":"All three add up to 180°.","ru":"Сумма трёх углов — 180°."},"explanation":{"en":"180 − 50 − 60 = 70°.","ru":"180 − 50 − 60 = 70°."},"answer":70,"difficulty":4,"id":"math.geometry.l1.p1","role":"practice"}'::jsonb, 4, '{"en":"180 − 50 − 60 = 70°.","ru":"180 − 50 − 60 = 70°."}'::jsonb),
  ('math.geometry.l1.p2', 'math.geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"A right triangle has legs 6 and 8. Find the hypotenuse.","ru":"Катеты прямоугольного треугольника 6 и 8. Найди гипотенузу."},"hint":{"en":"c² = 6² + 8².","ru":"c² = 6² + 8²."},"explanation":{"en":"36 + 64 = 100, c = 10.","ru":"36 + 64 = 100, c = 10."},"answer":10,"difficulty":4,"id":"math.geometry.l1.p2","role":"practice"}'::jsonb, 4, '{"en":"36 + 64 = 100, c = 10.","ru":"36 + 64 = 100, c = 10."}'::jsonb),
  ('math.geometry.l1.p3', 'math.geometry.l1', 'single', '{"type":"single","prompt":{"en":"An angle on a straight line next to a 120° angle is:","ru":"Угол, смежный с углом 120°, равен:"},"options":[{"en":"60°","ru":"60°"},{"en":"80°","ru":"80°"},{"en":"240°","ru":"240°"}],"answer":0,"hint":{"en":"Angles on a straight line add up to 180°.","ru":"Смежные углы в сумме дают 180°."},"explanation":{"en":"180 − 120 = 60°.","ru":"180 − 120 = 60°."},"difficulty":4,"id":"math.geometry.l1.p3","role":"practice"}'::jsonb, 4, '{"en":"180 − 120 = 60°.","ru":"180 − 120 = 60°."}'::jsonb),
  ('math.geometry.l1.c1', 'math.geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"Hypotenuse 13, one leg 5. Find the other leg.","ru":"Гипотенуза 13, один катет 5. Найди другой катет."},"explanation":{"en":"169 − 25 = 144, so the leg is 12.","ru":"169 − 25 = 144, значит катет равен 12."},"answer":12,"difficulty":4,"id":"math.geometry.l1.c1","role":"check"}'::jsonb, 4, '{"en":"169 − 25 = 144, so the leg is 12.","ru":"169 − 25 = 144, значит катет равен 12."}'::jsonb),
  ('math.geometry.l1.c2', 'math.geometry.l1', 'true_false', '{"type":"true_false","prompt":{"en":"A triangle can have two right angles.","ru":"У треугольника может быть два прямых угла."},"explanation":{"en":"Two right angles already make 180°, so a triangle has at most one right angle.","ru":"Два прямых угла уже дают 180°, поэтому прямой угол в треугольнике может быть только один."},"answer":false,"difficulty":4,"id":"math.geometry.l1.c2","role":"check"}'::jsonb, 4, '{"en":"Two right angles already make 180°, so a triangle has at most one right angle.","ru":"Два прямых угла уже дают 180°, поэтому прямой угол в треугольнике может быть только один."}'::jsonb),
  ('math.geometry.l1.c3', 'math.geometry.l1', 'drag_drop', '{"type":"drag_drop","prompt":{"en":"Sort the angles by type.","ru":"Распредели углы по видам."},"items":[{"id":"a35","label":{"en":"35°","ru":"35°"}},{"id":"a90","label":{"en":"90°","ru":"90°"}},{"id":"a120","label":{"en":"120°","ru":"120°"}},{"id":"a89","label":{"en":"89°","ru":"89°"}}],"buckets":[{"id":"acute","label":{"en":"Acute","ru":"Острый"}},{"id":"right","label":{"en":"Right","ru":"Прямой"}},{"id":"obtuse","label":{"en":"Obtuse","ru":"Тупой"}}],"answer":{"a35":"acute","a89":"acute","a90":"right","a120":"obtuse"},"explanation":{"en":"Below 90° is acute, exactly 90° is right, between 90° and 180° is obtuse.","ru":"Меньше 90° — острый, ровно 90° — прямой, от 90° до 180° — тупой."},"difficulty":4,"id":"math.geometry.l1.c3","role":"check"}'::jsonb, 4, '{"en":"Below 90° is acute, exactly 90° is right, between 90° and 180° is obtuse.","ru":"Меньше 90° — острый, ровно 90° — прямой, от 90° до 180° — тупой."}'::jsonb),
  ('math.geometry.l1.c4', 'math.geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"An isosceles triangle has a top angle of 40°. Find each base angle.","ru":"Угол при вершине равнобедренного треугольника 40°. Найди угол при основании."},"unit":{"en":"°","ru":"°"},"explanation":{"en":"(180 − 40) ÷ 2 = 70°.","ru":"(180 − 40) : 2 = 70°."},"answer":70,"difficulty":4,"id":"math.geometry.l1.c4","role":"check"}'::jsonb, 4, '{"en":"(180 − 40) ÷ 2 = 70°.","ru":"(180 − 40) : 2 = 70°."}'::jsonb),
  ('math.geometry.l1.c5', 'math.geometry.l1', 'multiple', '{"type":"multiple","prompt":{"en":"Which could be the sides of a right triangle?","ru":"Какие тройки могут быть сторонами прямоугольного треугольника?"},"options":[{"en":"3, 4, 5","ru":"3, 4, 5"},{"en":"5, 12, 13","ru":"5, 12, 13"},{"en":"2, 3, 4","ru":"2, 3, 4"},{"en":"6, 8, 10","ru":"6, 8, 10"}],"answers":[0,1,3],"explanation":{"en":"9 + 16 = 25, 25 + 144 = 169, 36 + 64 = 100. For 2, 3, 4: 4 + 9 = 13, not 16.","ru":"9 + 16 = 25, 25 + 144 = 169, 36 + 64 = 100. Для 2, 3, 4: 4 + 9 = 13, а не 16."},"difficulty":4,"id":"math.geometry.l1.c5","role":"check"}'::jsonb, 4, '{"en":"9 + 16 = 25, 25 + 144 = 169, 36 + 64 = 100. For 2, 3, 4: 4 + 9 = 13, not 16.","ru":"9 + 16 = 25, 25 + 144 = 169, 36 + 64 = 100. Для 2, 3, 4: 4 + 9 = 13, а не 16."}'::jsonb),
  ('math.trigonometry.l1.p1', 'math.trigonometry.l1', 'math_input', '{"type":"math_input","prompt":{"en":"Right triangle with sides 3, 4, 5. Angle α is opposite side 3. Find sin α.","ru":"Прямоугольный треугольник со сторонами 3, 4, 5. Угол α лежит напротив стороны 3. Найди sin α."},"accepted":["3/5","0.6","0,6"],"hint":{"en":"Opposite ÷ hypotenuse.","ru":"Противолежащий катет / гипотенуза."},"explanation":{"en":"sin α = 3/5 = 0.6.","ru":"sin α = 3/5 = 0,6."},"difficulty":5,"id":"math.trigonometry.l1.p1","role":"practice"}'::jsonb, 5, '{"en":"sin α = 3/5 = 0.6.","ru":"sin α = 3/5 = 0,6."}'::jsonb),
  ('math.trigonometry.l1.p2', 'math.trigonometry.l1', 'math_input', '{"type":"math_input","prompt":{"en":"Same triangle. Find tan α.","ru":"Тот же треугольник. Найди tg α."},"accepted":["3/4","0.75","0,75"],"hint":{"en":"Opposite ÷ adjacent.","ru":"Противолежащий / прилежащий."},"explanation":{"en":"tan α = 3/4 = 0.75.","ru":"tg α = 3/4 = 0,75."},"difficulty":5,"id":"math.trigonometry.l1.p2","role":"practice"}'::jsonb, 5, '{"en":"tan α = 3/4 = 0.75.","ru":"tg α = 3/4 = 0,75."}'::jsonb),
  ('math.trigonometry.l1.p3', 'math.trigonometry.l1', 'single', '{"type":"single","prompt":{"en":"sin 30° = ?","ru":"sin 30° = ?"},"options":[{"en":"1/2","ru":"1/2"},{"en":"√3/2","ru":"√3/2"},{"en":"1","ru":"1"}],"answer":0,"hint":{"en":"Opposite a 30° angle is half the hypotenuse.","ru":"Катет напротив угла 30° равен половине гипотенузы."},"explanation":{"en":"sin 30° = 1/2.","ru":"sin 30° = 1/2."},"difficulty":5,"id":"math.trigonometry.l1.p3","role":"practice"}'::jsonb, 5, '{"en":"sin 30° = 1/2.","ru":"sin 30° = 1/2."}'::jsonb),
  ('math.trigonometry.l1.c1', 'math.trigonometry.l1', 'math_input', '{"type":"math_input","prompt":{"en":"cos 60° = ?","ru":"cos 60° = ?"},"accepted":["1/2","0.5","0,5"],"explanation":{"en":"cos 60° = 1/2.","ru":"cos 60° = 1/2."},"difficulty":5,"id":"math.trigonometry.l1.c1","role":"check"}'::jsonb, 5, '{"en":"cos 60° = 1/2.","ru":"cos 60° = 1/2."}'::jsonb),
  ('math.trigonometry.l1.c2', 'math.trigonometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"Hypotenuse 10, angle 30°. Find the leg opposite the 30° angle.","ru":"Гипотенуза 10, угол 30°. Найди катет, лежащий напротив этого угла."},"explanation":{"en":"10 · sin 30° = 10 · 1/2 = 5.","ru":"10 · sin 30° = 10 · 1/2 = 5."},"answer":5,"difficulty":5,"id":"math.trigonometry.l1.c2","role":"check"}'::jsonb, 5, '{"en":"10 · sin 30° = 10 · 1/2 = 5.","ru":"10 · sin 30° = 10 · 1/2 = 5."}'::jsonb),
  ('math.trigonometry.l1.c3', 'math.trigonometry.l1', 'true_false', '{"type":"true_false","prompt":{"en":"sin²α + cos²α = 1 for any angle α.","ru":"sin²α + cos²α = 1 для любого угла α."},"explanation":{"en":"This is the main trigonometric identity, based on Pythagoras.","ru":"Это основное тригонометрическое тождество, оно следует из теоремы Пифагора."},"answer":true,"difficulty":5,"id":"math.trigonometry.l1.c3","role":"check"}'::jsonb, 5, '{"en":"This is the main trigonometric identity, based on Pythagoras.","ru":"Это основное тригонометрическое тождество, оно следует из теоремы Пифагора."}'::jsonb),
  ('math.trigonometry.l1.c4', 'math.trigonometry.l1', 'matching', '{"type":"matching","prompt":{"en":"Match each ratio to its definition.","ru":"Соедини функцию и её определение."},"pairs":[{"left":{"en":"sin α","ru":"sin α"},"right":{"en":"opposite / hypotenuse","ru":"противолежащий / гипотенуза"}},{"left":{"en":"cos α","ru":"cos α"},"right":{"en":"adjacent / hypotenuse","ru":"прилежащий / гипотенуза"}},{"left":{"en":"tan α","ru":"tg α"},"right":{"en":"opposite / adjacent","ru":"противолежащий / прилежащий"}}],"explanation":{"en":"Remember SOH-CAH-TOA.","ru":"Запомни: синус — противолежащий, косинус — прилежащий."},"difficulty":5,"id":"math.trigonometry.l1.c4","role":"check"}'::jsonb, 5, '{"en":"Remember SOH-CAH-TOA.","ru":"Запомни: синус — противолежащий, косинус — прилежащий."}'::jsonb),
  ('math.trigonometry.l1.c5', 'math.trigonometry.l1', 'math_input', '{"type":"math_input","prompt":{"en":"α is acute and sin α = 0.8. Find cos α.","ru":"α — острый угол, sin α = 0,8. Найди cos α."},"accepted":["0.6","0,6","3/5"],"explanation":{"en":"cos α = √(1 − 0.64) = √0.36 = 0.6.","ru":"cos α = √(1 − 0,64) = √0,36 = 0,6."},"difficulty":5,"id":"math.trigonometry.l1.c5","role":"check"}'::jsonb, 5, '{"en":"cos α = √(1 − 0.64) = √0.36 = 0.6.","ru":"cos α = √(1 − 0,64) = √0,36 = 0,6."}'::jsonb),
  ('math.solid-geometry.l1.p1', 'math.solid-geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"A cuboid is 2 × 3 × 5. Find its volume.","ru":"Прямоугольный параллелепипед 2 × 3 × 5. Найди объём."},"hint":{"en":"Multiply all three edges.","ru":"Перемножь три измерения."},"explanation":{"en":"2 · 3 · 5 = 30.","ru":"2 · 3 · 5 = 30."},"answer":30,"difficulty":5,"id":"math.solid-geometry.l1.p1","role":"practice"}'::jsonb, 5, '{"en":"2 · 3 · 5 = 30.","ru":"2 · 3 · 5 = 30."}'::jsonb),
  ('math.solid-geometry.l1.p2', 'math.solid-geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"A cube has edge 3. Find its total surface area.","ru":"Ребро куба 3. Найди площадь полной поверхности."},"hint":{"en":"A cube has 6 square faces.","ru":"У куба 6 квадратных граней."},"explanation":{"en":"6 · 3² = 54.","ru":"6 · 3² = 54."},"answer":54,"difficulty":5,"id":"math.solid-geometry.l1.p2","role":"practice"}'::jsonb, 5, '{"en":"6 · 3² = 54.","ru":"6 · 3² = 54."}'::jsonb),
  ('math.solid-geometry.l1.p3', 'math.solid-geometry.l1', 'single', '{"type":"single","prompt":{"en":"A pyramid has base area 12 and height 5. Its volume is:","ru":"Площадь основания пирамиды 12, высота 5. Объём равен:"},"options":[{"en":"20","ru":"20"},{"en":"60","ru":"60"},{"en":"30","ru":"30"}],"answer":0,"hint":{"en":"Don''t forget the ⅓.","ru":"Не забудь множитель ⅓."},"explanation":{"en":"⅓ · 12 · 5 = 20.","ru":"⅓ · 12 · 5 = 20."},"difficulty":5,"id":"math.solid-geometry.l1.p3","role":"practice"}'::jsonb, 5, '{"en":"⅓ · 12 · 5 = 20.","ru":"⅓ · 12 · 5 = 20."}'::jsonb),
  ('math.solid-geometry.l1.c1', 'math.solid-geometry.l1', 'number_input', '{"type":"number_input","prompt":{"en":"A cube has edge 4. Find its volume.","ru":"Ребро куба 4. Найди объём."},"explanation":{"en":"4³ = 64.","ru":"4³ = 64."},"answer":64,"difficulty":5,"id":"math.solid-geometry.l1.c1","role":"check"}'::jsonb, 5, '{"en":"4³ = 64.","ru":"4³ = 64."}'::jsonb),
  ('math.solid-geometry.l1.c2', 'math.solid-geometry.l1', 'math_input', '{"type":"math_input","prompt":{"en":"A cylinder has r = 2 and h = 5. Its volume is kπ. Find k.","ru":"У цилиндра r = 2, h = 5. Его объём равен kπ. Найди k."},"accepted":["20","k=20"],"explanation":{"en":"V = π · 2² · 5 = 20π.","ru":"V = π · 2² · 5 = 20π."},"difficulty":5,"id":"math.solid-geometry.l1.c2","role":"check"}'::jsonb, 5, '{"en":"V = π · 2² · 5 = 20π.","ru":"V = π · 2² · 5 = 20π."}'::jsonb),
  ('math.solid-geometry.l1.c3', 'math.solid-geometry.l1', 'matching', '{"type":"matching","prompt":{"en":"Match each shape to its volume formula.","ru":"Соедини тело и формулу объёма."},"pairs":[{"left":{"en":"Cube","ru":"Куб"},"right":{"en":"a³","ru":"a³"}},{"left":{"en":"Cylinder","ru":"Цилиндр"},"right":{"en":"πr²h","ru":"πr²h"}},{"left":{"en":"Cone","ru":"Конус"},"right":{"en":"⅓πr²h","ru":"⅓πr²h"}},{"left":{"en":"Sphere","ru":"Шар"},"right":{"en":"4/3 πr³","ru":"4/3 πr³"}}],"explanation":{"en":"A cone holds one third of the cylinder with the same base and height.","ru":"Конус вмещает треть цилиндра с тем же основанием и высотой."},"difficulty":5,"id":"math.solid-geometry.l1.c3","role":"check"}'::jsonb, 5, '{"en":"A cone holds one third of the cylinder with the same base and height.","ru":"Конус вмещает треть цилиндра с тем же основанием и высотой."}'::jsonb),
  ('math.solid-geometry.l1.c4', 'math.solid-geometry.l1', 'true_false', '{"type":"true_false","prompt":{"en":"If every edge of a cube is doubled, its volume doubles.","ru":"Если каждое ребро куба увеличить в 2 раза, объём увеличится в 2 раза."},"explanation":{"en":"The volume grows 2³ = 8 times.","ru":"Объём увеличится в 2³ = 8 раз."},"answer":false,"difficulty":5,"id":"math.solid-geometry.l1.c4","role":"check"}'::jsonb, 5, '{"en":"The volume grows 2³ = 8 times.","ru":"Объём увеличится в 2³ = 8 раз."}'::jsonb),
  ('math.solid-geometry.l1.c5', 'math.solid-geometry.l1', 'math_input', '{"type":"math_input","prompt":{"en":"A sphere has r = 3. Its surface area is kπ. Find k.","ru":"Радиус сферы 3. Площадь её поверхности равна kπ. Найди k."},"accepted":["36","k=36"],"explanation":{"en":"4π · 3² = 36π.","ru":"4π · 3² = 36π."},"difficulty":5,"id":"math.solid-geometry.l1.c5","role":"check"}'::jsonb, 5, '{"en":"4π · 3² = 36π.","ru":"4π · 3² = 36π."}'::jsonb),
  ('math.logarithms.l1.p1', 'math.logarithms.l1', 'number_input', '{"type":"number_input","prompt":{"en":"log₃ 9 = ?","ru":"log₃ 9 = ?"},"hint":{"en":"3 to which power is 9?","ru":"В какую степень возвести 3, чтобы получить 9?"},"explanation":{"en":"3² = 9, so log₃ 9 = 2.","ru":"3² = 9, значит log₃ 9 = 2."},"answer":2,"difficulty":5,"id":"math.logarithms.l1.p1","role":"practice"}'::jsonb, 5, '{"en":"3² = 9, so log₃ 9 = 2.","ru":"3² = 9, значит log₃ 9 = 2."}'::jsonb),
