  ('math.logarithms.l1.c2', 'math.logarithms.l1', 'math_input', '{"type":"math_input","prompt":{"en":"log₂ x = 4. Find x.","ru":"log₂ x = 4. Найди x."},"accepted":["16","x=16"],"explanation":{"en":"x = 2⁴ = 16.","ru":"x = 2⁴ = 16."},"difficulty":5,"id":"math.logarithms.l1.c2","role":"check"}'::jsonb, 5, '{"en":"x = 2⁴ = 16.","ru":"x = 2⁴ = 16."}'::jsonb),
  ('math.logarithms.l1.c3', 'math.logarithms.l1', 'true_false', '{"type":"true_false","prompt":{"en":"log₆ 4 + log₆ 9 = 2","ru":"log₆ 4 + log₆ 9 = 2"},"explanation":{"en":"log₆ (4 · 9) = log₆ 36 = 2.","ru":"log₆ (4 · 9) = log₆ 36 = 2."},"answer":true,"difficulty":5,"id":"math.logarithms.l1.c3","role":"check"}'::jsonb, 5, '{"en":"log₆ (4 · 9) = log₆ 36 = 2.","ru":"log₆ (4 · 9) = log₆ 36 = 2."}'::jsonb),
