  ('math.logarithms.l1.c5', 'math.logarithms.l1', 'matching', '{"type":"matching","prompt":{"en":"Match each logarithm to its value.","ru":"Соедини логарифм и его значение."},"pairs":[{"left":{"en":"log₄ 16","ru":"log₄ 16"},"right":{"en":"2","ru":"2"}},{"left":{"en":"log₁₀ 0.1","ru":"lg 0,1"},"right":{"en":"−1","ru":"−1"}},{"left":{"en":"log₇ 7","ru":"log₇ 7"},"right":{"en":"1","ru":"1"}},{"left":{"en":"log₉ 3","ru":"log₉ 3"},"right":{"en":"1/2","ru":"1/2"}}],"explanation":{"en":"4² = 16, 10⁻¹ = 0.1, 7¹ = 7, 9^(1/2) = 3.","ru":"4² = 16, 10⁻¹ = 0,1, 7¹ = 7, 9^(1/2) = 3."},"difficulty":5,"id":"math.logarithms.l1.c5","role":"check"}'::jsonb, 5, '{"en":"4² = 16, 10⁻¹ = 0.1, 7¹ = 7, 9^(1/2) = 3.","ru":"4² = 16, 10⁻¹ = 0,1, 7¹ = 7, 9^(1/2) = 3."}'::jsonb),
  ('math.calculus-intro.l1.p1', 'math.calculus-intro.l1', 'single', '{"type":"single","prompt":{"en":"(x⁴)′ = ?","ru":"(x⁴)′ = ?"},"options":[{"en":"4x³","ru":"4x³"},{"en":"x³","ru":"x³"},{"en":"4x⁴","ru":"4x⁴"}],"answer":0,"hint":{"en":"(xⁿ)′ = n · xⁿ⁻¹","ru":"(xⁿ)′ = n · xⁿ⁻¹"},"explanation":{"en":"(x⁴)′ = 4x³.","ru":"(x⁴)′ = 4x³."},"difficulty":5,"id":"math.calculus-intro.l1.p1","role":"practice"}'::jsonb, 5, '{"en":"(x⁴)′ = 4x³.","ru":"(x⁴)′ = 4x³."}'::jsonb),
  ('math.calculus-intro.l1.p2', 'math.calculus-intro.l1', 'number_input', '{"type":"number_input","prompt":{"en":"f(x) = x². Find f′(5).","ru":"f(x) = x². Найди f′(5)."},"hint":{"en":"f′(x) = 2x.","ru":"f′(x) = 2x."},"explanation":{"en":"f′(5) = 2 · 5 = 10.","ru":"f′(5) = 2 · 5 = 10."},"answer":10,"difficulty":5,"id":"math.calculus-intro.l1.p2","role":"practice"}'::jsonb, 5, '{"en":"f′(5) = 2 · 5 = 10.","ru":"f′(5) = 2 · 5 = 10."}'::jsonb),
  ('math.calculus-intro.l1.p3', 'math.calculus-intro.l1', 'math_input', '{"type":"math_input","prompt":{"en":"f(x) = 3x + 7. Find f′(x).","ru":"f(x) = 3x + 7. Найди f′(x)."},"accepted":["3","f''(x)=3"],"hint":{"en":"The slope of a straight line is constant; a constant''s derivative is 0.","ru":"Наклон прямой постоянен, а производная константы равна 0."},"explanation":{"en":"(3x)′ = 3 and (7)′ = 0, so f′(x) = 3.","ru":"(3x)′ = 3 и (7)′ = 0, значит f′(x) = 3."},"difficulty":5,"id":"math.calculus-intro.l1.p3","role":"practice"}'::jsonb, 5, '{"en":"(3x)′ = 3 and (7)′ = 0, so f′(x) = 3.","ru":"(3x)′ = 3 и (7)′ = 0, значит f′(x) = 3."}'::jsonb),
  ('math.calculus-intro.l1.c1', 'math.calculus-intro.l1', 'number_input', '{"type":"number_input","prompt":{"en":"f(x) = x³ − 2x. Find f′(2).","ru":"f(x) = x³ − 2x. Найди f′(2)."},"explanation":{"en":"f′(x) = 3x² − 2, f′(2) = 12 − 2 = 10.","ru":"f′(x) = 3x² − 2, f′(2) = 12 − 2 = 10."},"answer":10,"difficulty":5,"id":"math.calculus-intro.l1.c1","role":"check"}'::jsonb, 5, '{"en":"f′(x) = 3x² − 2, f′(2) = 12 − 2 = 10.","ru":"f′(x) = 3x² − 2, f′(2) = 12 − 2 = 10."}'::jsonb),
  ('math.calculus-intro.l1.c2', 'math.calculus-intro.l1', 'true_false', '{"type":"true_false","prompt":{"en":"The derivative of a constant is 0.","ru":"Производная константы равна 0."},"explanation":{"en":"A constant does not change, so its rate of change is 0.","ru":"Константа не меняется, поэтому скорость её изменения равна 0."},"answer":true,"difficulty":5,"id":"math.calculus-intro.l1.c2","role":"check"}'::jsonb, 5, '{"en":"A constant does not change, so its rate of change is 0.","ru":"Константа не меняется, поэтому скорость её изменения равна 0."}'::jsonb),
