  ('math.calculus-intro.l1.c4', 'math.calculus-intro.l1', 'matching', '{"type":"matching","prompt":{"en":"Match each function to its derivative.","ru":"Соедини функцию и её производную."},"pairs":[{"left":{"en":"x²","ru":"x²"},"right":{"en":"2x","ru":"2x"}},{"left":{"en":"5x","ru":"5x"},"right":{"en":"5","ru":"5"}},{"left":{"en":"x³","ru":"x³"},"right":{"en":"3x²","ru":"3x²"}},{"left":{"en":"7","ru":"7"},"right":{"en":"0","ru":"0"}}],"explanation":{"en":"Use (xⁿ)′ = n · xⁿ⁻¹ and (c)′ = 0.","ru":"Используем (xⁿ)′ = n · xⁿ⁻¹ и (c)′ = 0."},"difficulty":5,"id":"math.calculus-intro.l1.c4","role":"check"}'::jsonb, 5, '{"en":"Use (xⁿ)′ = n · xⁿ⁻¹ and (c)′ = 0.","ru":"Используем (xⁿ)′ = n · xⁿ⁻¹ и (c)′ = 0."}'::jsonb),
