  ('reading.sentences.l1.p2', 'reading.sentences.l1', 'single', '{"id":"reading.sentences.l1.p2","type":"single","prompt":{"en":"Which sentence is written correctly?","ru":"Какое предложение записано правильно?"},"hint":{"en":"Look at the first letter and the end.","ru":"Посмотри на первую букву и на конец."},"explanation":{"en":"It begins with a capital letter and ends with a full stop.","ru":"Оно начинается с большой буквы и заканчивается точкой."},"difficulty":1,"audio":true,"options":[{"en":"the sun is hot.","ru":"солнце светит."},{"en":"The sun is hot.","ru":"Солнце светит."},{"en":"The sun is hot","ru":"Солнце светит"}],"answer":1,"role":"practice"}'::jsonb, 1, '{"en":"It begins with a capital letter and ends with a full stop.","ru":"Оно начинается с большой буквы и заканчивается точкой."}'::jsonb),
  ('reading.sentences.l1.p3', 'reading.sentences.l1', 'true_false', '{"id":"reading.sentences.l1.p3","type":"true_false","prompt":{"en":"A sentence begins with a small letter.","ru":"Предложение начинается с маленькой буквы."},"hint":{"en":"Think about the first word of a sentence.","ru":"Вспомни, как пишется первое слово в предложении."},"explanation":{"en":"A sentence begins with a capital letter.","ru":"Предложение начинается с большой буквы."},"difficulty":1,"audio":true,"answer":false,"role":"practice"}'::jsonb, 1, '{"en":"A sentence begins with a capital letter.","ru":"Предложение начинается с большой буквы."}'::jsonb),
  ('reading.sentences.l1.c1', 'reading.sentences.l1', 'ordering', '{"id":"reading.sentences.l1.c1","type":"ordering","prompt":{"en":"Make a sentence from the words.","ru":"Составь предложение из слов."},"explanation":{"en":"My mom reads a book.","ru":"Моя мама читает книгу."},"difficulty":1,"audio":true,"items":[{"en":"My","ru":"Моя"},{"en":"mom","ru":"мама"},{"en":"reads","ru":"читает"},{"en":"a book.","ru":"книгу."}],"role":"check"}'::jsonb, 1, '{"en":"My mom reads a book.","ru":"Моя мама читает книгу."}'::jsonb),
  ('reading.sentences.l1.c2', 'reading.sentences.l1', 'fill_blank', '{"id":"reading.sentences.l1.c2","type":"fill_blank","prompt":{"en":"Put the right mark at the end.","ru":"Поставь нужный знак в конце."},"hint":{"en":"This sentence asks something.","ru":"В этом предложении что-то спрашивают."},"explanation":{"en":"A question ends with a question mark: ?","ru":"В конце вопроса ставим вопросительный знак: ?"},"difficulty":1,"audio":true,"text":{"en":"Where is my hat___","ru":"Где моя шапка___"},"accepted":{"en":["?"],"ru":["?"]},"role":"check"}'::jsonb, 1, '{"en":"A question ends with a question mark: ?","ru":"В конце вопроса ставим вопросительный знак: ?"}'::jsonb),
  ('reading.sentences.l1.c3', 'reading.sentences.l1', 'multiple', '{"id":"reading.sentences.l1.c3","type":"multiple","prompt":{"en":"Which are whole sentences? Pick all.","ru":"Где целые предложения? Выбери все."},"explanation":{"en":"«Birds sing.» and «We play ball.» tell a whole idea.","ru":"«Птицы поют.» и «Мы играем в мяч.» выражают законченную мысль."},"difficulty":2,"audio":true,"options":[{"en":"Birds sing.","ru":"Птицы поют."},{"en":"big red","ru":"большой красный"},{"en":"We play ball.","ru":"Мы играем в мяч."},{"en":"under the","ru":"под столом"}],"answers":[0,2],"role":"check"}'::jsonb, 2, '{"en":"«Birds sing.» and «We play ball.» tell a whole idea.","ru":"«Птицы поют.» и «Мы играем в мяч.» выражают законченную мысль."}'::jsonb),
  ('reading.sentences.l1.c4', 'reading.sentences.l1', 'single', '{"id":"reading.sentences.l1.c4","type":"single","prompt":{"en":"What goes at the end of a telling sentence?","ru":"Что ставят в конце повествовательного предложения (когда просто сообщают)?"},"explanation":{"en":"A telling sentence ends with a full stop.","ru":"Когда мы просто сообщаем, ставим точку."},"difficulty":1,"audio":true,"options":[{"en":".","ru":"."},{"en":"?","ru":"?"},{"en":",","ru":","}],"answer":0,"role":"check"}'::jsonb, 1, '{"en":"A telling sentence ends with a full stop.","ru":"Когда мы просто сообщаем, ставим точку."}'::jsonb),
  ('reading.sentences.l1.c5', 'reading.sentences.l1', 'drag_drop', '{"id":"reading.sentences.l1.c5","type":"drag_drop","prompt":{"en":"Sort: is it a sentence or not?","ru":"Разложи: это предложение или нет?"},"explanation":{"en":"A sentence tells a whole idea and ends with a mark.","ru":"Предложение выражает законченную мысль и заканчивается знаком."},"difficulty":2,"audio":true,"items":[{"id":"a","label":{"en":"The fish swims.","ru":"Рыба плывёт."}},{"id":"b","label":{"en":"green tree","ru":"зелёное дерево"}},{"id":"c","label":{"en":"I can jump.","ru":"Я умею прыгать."}},{"id":"d","label":{"en":"on the","ru":"на столе"}}],"buckets":[{"id":"yes","label":{"en":"Sentence","ru":"Предложение"}},{"id":"no","label":{"en":"Not a sentence","ru":"Не предложение"}}],"answer":{"a":"yes","b":"no","c":"yes","d":"no"},"role":"check"}'::jsonb, 2, '{"en":"A sentence tells a whole idea and ends with a mark.","ru":"Предложение выражает законченную мысль и заканчивается знаком."}'::jsonb),
  ('reading.spelling.l1.p1', 'reading.spelling.l1', 'single', '{"id":"reading.spelling.l1.p1","type":"single","prompt":{"en":"Which word is spelled correctly?","ru":"Какое слово написано правильно?"},"hint":{"en":"This is a tricky word: f-r-i-e-n-d.","ru":"Вспомни правило: ЖИ-ШИ пиши с буквой И."},"explanation":{"en":"«Friend» is a tricky word: i comes before e.","ru":"«Шина» — ШИ пишем с буквой И."},"difficulty":2,"audio":true,"options":[{"en":"frend","ru":"шына"},{"en":"friend","ru":"шина"},{"en":"freind","ru":"шинна"}],"answer":1,"role":"practice"}'::jsonb, 2, '{"en":"«Friend» is a tricky word: i comes before e.","ru":"«Шина» — ШИ пишем с буквой И."}'::jsonb),
  ('reading.spelling.l1.p2', 'reading.spelling.l1', 'fill_blank', '{"id":"reading.spelling.l1.p2","type":"fill_blank","prompt":{"en":"Write the missing letter.","ru":"Вставь пропущенную букву."},"hint":{"en":"Magic e makes the i say its name: bike.","ru":"Измени слово, чтобы гласная стала ударной: во́ды."},"explanation":{"en":"bik + e → bike.","ru":"Вода — проверяем словом «во́ды», пишем О."},"difficulty":2,"audio":true,"text":{"en":"I ride my bik___ 🚲","ru":"В реке чистая в___да 💧"},"accepted":{"en":["e"],"ru":["о","o"]},"role":"practice"}'::jsonb, 2, '{"en":"bik + e → bike.","ru":"Вода — проверяем словом «во́ды», пишем О."}'::jsonb),
  ('reading.spelling.l1.p3', 'reading.spelling.l1', 'true_false', '{"id":"reading.spelling.l1.p3","type":"true_false","prompt":{"en":"In «hope», the e at the end is silent and makes the o say its name.","ru":"В слове «ёж» на конце пишем Ж, потому что можно проверить: ежи́."},"hint":{"en":"Say «hop» and «hope». What changed?","ru":"Скажи «ежи». Какой звук ты слышишь?"},"explanation":{"en":"Yes! That is the magic-e rule.","ru":"Да! Ежи́ — слышим Ж, значит, и в слове «ёж» пишем Ж."},"difficulty":2,"audio":true,"answer":true,"role":"practice"}'::jsonb, 2, '{"en":"Yes! That is the magic-e rule.","ru":"Да! Ежи́ — слышим Ж, значит, и в слове «ёж» пишем Ж."}'::jsonb),
  ('reading.spelling.l1.c1', 'reading.spelling.l1', 'single', '{"id":"reading.spelling.l1.c1","type":"single","prompt":{"en":"Which word is spelled correctly?","ru":"Какое словарное слово написано правильно?"},"explanation":{"en":"«Because» is a tricky word to remember.","ru":"«Корова» — словарное слово, его нужно запомнить."},"difficulty":2,"audio":true,"options":[{"en":"becos","ru":"карова"},{"en":"because","ru":"корова"},{"en":"becuz","ru":"каровва"}],"answer":1,"role":"check"}'::jsonb, 2, '{"en":"«Because» is a tricky word to remember.","ru":"«Корова» — словарное слово, его нужно запомнить."}'::jsonb),
  ('reading.spelling.l1.c2', 'reading.spelling.l1', 'multiple', '{"id":"reading.spelling.l1.c2","type":"multiple","prompt":{"en":"Which words have a magic e? Pick all.","ru":"Какие слова написаны правильно? Выбери все."},"hint":{"en":"Look for a silent e at the end.","ru":"Проверь: дубы, грибы, льды, зубы."},"explanation":{"en":"Cake and kite end with a silent magic e.","ru":"Дуб (дубы) и лёд (льды) написаны верно. Правильно: гриб, зуб."},"difficulty":2,"audio":true,"options":[{"en":"cake","ru":"дуб"},{"en":"cat","ru":"грип"},{"en":"kite","ru":"лёд"},{"en":"kit","ru":"зуп"}],"answers":[0,2],"role":"check"}'::jsonb, 2, '{"en":"Cake and kite end with a silent magic e.","ru":"Дуб (дубы) и лёд (льды) написаны верно. Правильно: гриб, зуб."}'::jsonb),
  ('reading.spelling.l1.c3', 'reading.spelling.l1', 'word_building', '{"id":"reading.spelling.l1.c3","type":"word_building","prompt":{"en":"Build the word: 🎂 (remember magic e!)","ru":"Собери слово: 🦒 (помни: ЖИ пиши с И!)"},"explanation":{"en":"c-a-k-e → cake.","ru":"ж-и-р-а-ф → жираф."},"difficulty":2,"audio":true,"word":{"en":"cake","ru":"жираф"},"role":"check"}'::jsonb, 2, '{"en":"c-a-k-e → cake.","ru":"ж-и-р-а-ф → жираф."}'::jsonb),
  ('reading.spelling.l1.c4', 'reading.spelling.l1', 'fill_blank', '{"id":"reading.spelling.l1.c4","type":"fill_blank","prompt":{"en":"Write the missing letters.","ru":"Вставь пропущенную букву."},"hint":{"en":"This tricky word sounds like «sed».","ru":"ЖИ-ШИ пиши с буквой И."},"explanation":{"en":"«Said» is spelled s-a-i-d.","ru":"Шли — ШИ пишем с буквой И."},"difficulty":3,"audio":true,"text":{"en":"She s___d hello to me.","ru":"Мы ш___ли домой."},"accepted":{"en":["ai"],"ru":["и"]},"role":"check"}'::jsonb, 3, '{"en":"«Said» is spelled s-a-i-d.","ru":"Шли — ШИ пишем с буквой И."}'::jsonb),
  ('reading.spelling.l1.c5', 'reading.spelling.l1', 'matching', '{"id":"reading.spelling.l1.c5","type":"matching","prompt":{"en":"Match each word with its magic-e partner.","ru":"Соедини слово с проверочным словом."},"explanation":{"en":"Adding e changes the vowel sound: cap → cape.","ru":"В проверочном слове гласная или согласная звучит ясно: зима — зи́мы."},"difficulty":3,"audio":true,"pairs":[{"left":{"en":"cap","ru":"з_ма"},"right":{"en":"cape","ru":"зи́мы"}},{"left":{"en":"hop","ru":"тр_ва"},"right":{"en":"hope","ru":"тра́вы"}},{"left":{"en":"kit","ru":"сне_ (г/к)"},"right":{"en":"kite","ru":"снега́"}}],"role":"check"}'::jsonb, 3, '{"en":"Adding e changes the vowel sound: cap → cape.","ru":"В проверочном слове гласная или согласная звучит ясно: зима — зи́мы."}'::jsonb),
  ('reading.parts-of-speech.l1.p1', 'reading.parts-of-speech.l1', 'drag_drop', '{"id":"reading.parts-of-speech.l1.p1","type":"drag_drop","prompt":{"en":"Sort the words into parts of speech.","ru":"Разложи слова по частям речи."},"hint":{"en":"Ask: Is it a thing? An action? Does it describe?","ru":"Задай вопрос: кто? что? / что делать? / какой?"},"explanation":{"en":"Cat, apple — nouns. Jump, sing — verbs. Happy, tall — adjectives.","ru":"Кот, яблоко — существительные. Прыгать, поёт — глаголы. Весёлый, высокий — прилагательные."},"difficulty":2,"audio":true,"items":[{"id":"a","label":{"en":"cat","ru":"кот"}},{"id":"b","label":{"en":"jump","ru":"прыгать"}},{"id":"c","label":{"en":"happy","ru":"весёлый"}},{"id":"d","label":{"en":"apple","ru":"яблоко"}},{"id":"e","label":{"en":"sing","ru":"поёт"}},{"id":"f","label":{"en":"tall","ru":"высокий"}}],"buckets":[{"id":"noun","label":{"en":"Noun","ru":"Существительное"}},{"id":"verb","label":{"en":"Verb","ru":"Глагол"}},{"id":"adj","label":{"en":"Adjective","ru":"Прилагательное"}}],"answer":{"a":"noun","b":"verb","c":"adj","d":"noun","e":"verb","f":"adj"},"role":"practice"}'::jsonb, 2, '{"en":"Cat, apple — nouns. Jump, sing — verbs. Happy, tall — adjectives.","ru":"Кот, яблоко — существительные. Прыгать, поёт — глаголы. Весёлый, высокий — прилагательные."}'::jsonb),
  ('reading.parts-of-speech.l1.p2', 'reading.parts-of-speech.l1', 'single', '{"id":"reading.parts-of-speech.l1.p2","type":"single","prompt":{"en":"Which word is a verb?","ru":"Какое слово — глагол?"},"hint":{"en":"A verb is something you can do.","ru":"Глагол отвечает на вопрос «что делать?»."},"explanation":{"en":"You can swim — it is an action.","ru":"Плавать — что делать? Это глагол."},"difficulty":1,"audio":true,"options":[{"en":"table","ru":"стол"},{"en":"swim","ru":"плавать"},{"en":"green","ru":"зелёный"}],"answer":1,"role":"practice"}'::jsonb, 1, '{"en":"You can swim — it is an action.","ru":"Плавать — что делать? Это глагол."}'::jsonb),
  ('reading.parts-of-speech.l1.p3', 'reading.parts-of-speech.l1', 'true_false', '{"id":"reading.parts-of-speech.l1.p3","type":"true_false","prompt":{"en":"«Happy» is a noun.","ru":"«Весёлый» — это существительное."},"hint":{"en":"Does «happy» name a thing or describe one?","ru":"Задай вопрос: весёлый — какой?"},"explanation":{"en":"«Happy» describes, so it is an adjective.","ru":"Весёлый — какой? Это прилагательное."},"difficulty":2,"audio":true,"answer":false,"role":"practice"}'::jsonb, 2, '{"en":"«Happy» describes, so it is an adjective.","ru":"Весёлый — какой? Это прилагательное."}'::jsonb),
  ('reading.parts-of-speech.l1.c1', 'reading.parts-of-speech.l1', 'single', '{"id":"reading.parts-of-speech.l1.c1","type":"single","prompt":{"en":"Find the adjective: «The red ball rolls.»","ru":"Найди прилагательное: «Красный мяч катится»."},"explanation":{"en":"«Red» describes the ball.","ru":"Мяч какой? Красный — это прилагательное."},"difficulty":2,"audio":true,"options":[{"en":"red","ru":"красный"},{"en":"ball","ru":"мяч"},{"en":"rolls","ru":"катится"}],"answer":0,"role":"check"}'::jsonb, 2, '{"en":"«Red» describes the ball.","ru":"Мяч какой? Красный — это прилагательное."}'::jsonb),
  ('reading.parts-of-speech.l1.c2', 'reading.parts-of-speech.l1', 'multiple', '{"id":"reading.parts-of-speech.l1.c2","type":"multiple","prompt":{"en":"Which words are nouns? Pick all.","ru":"Какие слова — существительные? Выбери все."},"explanation":{"en":"House and teacher name a thing and a person.","ru":"Дом — что? Учитель — кто? Это существительные."},"difficulty":2,"audio":true,"options":[{"en":"house","ru":"дом"},{"en":"run","ru":"бежать"},{"en":"teacher","ru":"учитель"},{"en":"soft","ru":"мягкий"}],"answers":[0,2],"role":"check"}'::jsonb, 2, '{"en":"House and teacher name a thing and a person.","ru":"Дом — что? Учитель — кто? Это существительные."}'::jsonb),
  ('reading.parts-of-speech.l1.c3', 'reading.parts-of-speech.l1', 'fill_blank', '{"id":"reading.parts-of-speech.l1.c3","type":"fill_blank","prompt":{"en":"Add a verb to finish the sentence.","ru":"Вставь глагол, чтобы закончить предложение."},"hint":{"en":"What can a bird do in the sky?","ru":"Что делает птица в небе?"},"explanation":{"en":"«Flies» is an action — a verb.","ru":"«Летит» — что делает? Это глагол."},"difficulty":2,"audio":true,"text":{"en":"The bird ___ in the sky.","ru":"Птица ___ в небе."},"accepted":{"en":["flies","sings","soars","glides","flaps","floats"],"ru":["летит","летает","парит","поёт","поет","кружит","кружится"]},"role":"check"}'::jsonb, 2, '{"en":"«Flies» is an action — a verb.","ru":"«Летит» — что делает? Это глагол."}'::jsonb),
  ('reading.parts-of-speech.l1.c4', 'reading.parts-of-speech.l1', 'matching', '{"id":"reading.parts-of-speech.l1.c4","type":"matching","prompt":{"en":"Match each part of speech with its job.","ru":"Соедини часть речи с её вопросами."},"explanation":{"en":"Nouns name, verbs act, adjectives describe.","ru":"Существительное — кто? что?; глагол — что делать?; прилагательное — какой?"},"difficulty":2,"audio":true,"pairs":[{"left":{"en":"noun","ru":"существительное"},"right":{"en":"names a person, place or thing","ru":"кто? что?"}},{"left":{"en":"verb","ru":"глагол"},"right":{"en":"an action word","ru":"что делать? что сделать?"}},{"left":{"en":"adjective","ru":"прилагательное"},"right":{"en":"a describing word","ru":"какой? какая? какое?"}}],"role":"check"}'::jsonb, 2, '{"en":"Nouns name, verbs act, adjectives describe.","ru":"Существительное — кто? что?; глагол — что делать?; прилагательное — какой?"}'::jsonb),
  ('reading.parts-of-speech.l1.c5', 'reading.parts-of-speech.l1', 'drag_drop', '{"id":"reading.parts-of-speech.l1.c5","type":"drag_drop","prompt":{"en":"Sort the words from «The small frog jumps into the pond.»","ru":"Разложи слова из предложения «Маленькая лягушка прыгает в пруд»."},"explanation":{"en":"small — adjective, frog and pond — nouns, jumps — verb.","ru":"маленькая — прилагательное, лягушка и пруд — существительные, прыгает — глагол."},"difficulty":3,"audio":true,"items":[{"id":"a","label":{"en":"small","ru":"маленькая"}},{"id":"b","label":{"en":"frog","ru":"лягушка"}},{"id":"c","label":{"en":"jumps","ru":"прыгает"}},{"id":"d","label":{"en":"pond","ru":"пруд"}}],"buckets":[{"id":"noun","label":{"en":"Noun","ru":"Существительное"}},{"id":"verb","label":{"en":"Verb","ru":"Глагол"}},{"id":"adj","label":{"en":"Adjective","ru":"Прилагательное"}}],"answer":{"a":"adj","b":"noun","c":"verb","d":"noun"},"role":"check"}'::jsonb, 3, '{"en":"small — adjective, frog and pond — nouns, jumps — verb.","ru":"маленькая — прилагательное, лягушка и пруд — существительные, прыгает — глагол."}'::jsonb),
  ('reading.punctuation.l1.p1', 'reading.punctuation.l1', 'single', '{"id":"reading.punctuation.l1.p1","type":"single","prompt":{"en":"Which mark ends this sentence: «What is your name_»","ru":"Какой знак нужен в конце: «Как тебя зовут_»"},"hint":{"en":"Is someone asking something?","ru":"Здесь о чём-то спрашивают?"},"explanation":{"en":"It is a question, so we use «?».","ru":"Это вопрос, поэтому ставим «?»."},"difficulty":1,"audio":true,"options":[{"en":".","ru":"."},{"en":"?","ru":"?"},{"en":"!","ru":"!"}],"answer":1,"role":"practice"}'::jsonb, 1, '{"en":"It is a question, so we use «?».","ru":"Это вопрос, поэтому ставим «?»."}'::jsonb),
  ('reading.punctuation.l1.p2', 'reading.punctuation.l1', 'fill_blank', '{"id":"reading.punctuation.l1.p2","type":"fill_blank","prompt":{"en":"Put in the missing mark.","ru":"Поставь пропущенный знак."},"hint":{"en":"This is a list of fruits.","ru":"Здесь перечисляются фрукты."},"explanation":{"en":"Items in a list are separated by commas.","ru":"Однородные слова разделяем запятыми."},"difficulty":2,"audio":true,"text":{"en":"I bought apples___ pears and plums.","ru":"Я купил яблоки___ груши и сливы."},"accepted":{"en":[","],"ru":[","]},"role":"practice"}'::jsonb, 2, '{"en":"Items in a list are separated by commas.","ru":"Однородные слова разделяем запятыми."}'::jsonb),
  ('reading.punctuation.l1.p3', 'reading.punctuation.l1', 'true_false', '{"id":"reading.punctuation.l1.p3","type":"true_false","prompt":{"en":"An exclamation mark shows strong feeling: Hooray!","ru":"Восклицательный знак ставят, когда говорят с сильным чувством: Ура!"},"hint":{"en":"Think about how you say «Hooray».","ru":"Вспомни, как ты говоришь «Ура»."},"explanation":{"en":"Yes! «!» shows joy, surprise or excitement.","ru":"Да! «!» передаёт радость, удивление, восторг."},"difficulty":1,"audio":true,"answer":true,"role":"practice"}'::jsonb, 1, '{"en":"Yes! «!» shows joy, surprise or excitement.","ru":"Да! «!» передаёт радость, удивление, восторг."}'::jsonb),
  ('reading.punctuation.l1.c1', 'reading.punctuation.l1', 'drag_drop', '{"id":"reading.punctuation.l1.c1","type":"drag_drop","prompt":{"en":"Which mark does each sentence need?","ru":"Какой знак нужен в конце каждого предложения?"},"explanation":{"en":"Telling — «.», asking — «?», strong feeling — «!».","ru":"Сообщаем — «.», спрашиваем — «?», сильное чувство — «!»."},"difficulty":2,"audio":true,"items":[{"id":"a","label":{"en":"The sky is blue","ru":"Небо голубое"}},{"id":"b","label":{"en":"Can you swim","ru":"Ты умеешь плавать"}},{"id":"c","label":{"en":"What a wonderful day","ru":"Какой чудесный день"}},{"id":"d","label":{"en":"Where do you live","ru":"Где ты живёшь"}}],"buckets":[{"id":"dot","label":{"en":".","ru":"."}},{"id":"q","label":{"en":"?","ru":"?"}},{"id":"ex","label":{"en":"!","ru":"!"}}],"answer":{"a":"dot","b":"q","c":"ex","d":"q"},"role":"check"}'::jsonb, 2, '{"en":"Telling — «.», asking — «?», strong feeling — «!».","ru":"Сообщаем — «.», спрашиваем — «?», сильное чувство — «!»."}'::jsonb),
  ('reading.punctuation.l1.c2', 'reading.punctuation.l1', 'single', '{"id":"reading.punctuation.l1.c2","type":"single","prompt":{"en":"Where are the commas in the right place?","ru":"Где запятые стоят правильно?"},"explanation":{"en":"Commas separate the items in the list: a cat, a dog and a cow.","ru":"Запятые разделяют однородные слова: кошку, собаку и корову. Перед одиночным «и» запятая не нужна."},"difficulty":3,"audio":true,"options":[{"en":"I saw a cat a dog, and a cow.","ru":"Я видел кошку собаку, и корову."},{"en":"I saw a cat, a dog and a cow.","ru":"Я видел кошку, собаку и корову."},{"en":"I saw, a cat a dog and a cow.","ru":"Я видел, кошку собаку и корову."}],"answer":1,"role":"check"}'::jsonb, 3, '{"en":"Commas separate the items in the list: a cat, a dog and a cow.","ru":"Запятые разделяют однородные слова: кошку, собаку и корову. Перед одиночным «и» запятая не нужна."}'::jsonb),
  ('reading.punctuation.l1.c3', 'reading.punctuation.l1', 'fill_blank', '{"id":"reading.punctuation.l1.c3","type":"fill_blank","prompt":{"en":"Put in the missing mark.","ru":"Поставь пропущенный знак."},"explanation":{"en":"A comma goes before «but» when it joins two ideas.","ru":"Перед союзом «но» ставится запятая."},"difficulty":3,"audio":true,"text":{"en":"I wanted to play outside___ but it was raining.","ru":"Я хотел гулять___ но пошёл дождь."},"accepted":{"en":[","],"ru":[","]},"role":"check"}'::jsonb, 3, '{"en":"A comma goes before «but» when it joins two ideas.","ru":"Перед союзом «но» ставится запятая."}'::jsonb),
  ('reading.punctuation.l1.c4', 'reading.punctuation.l1', 'multiple', '{"id":"reading.punctuation.l1.c4","type":"multiple","prompt":{"en":"Which sentences need a question mark? Pick all.","ru":"В конце каких предложений нужен вопросительный знак? Выбери все."},"explanation":{"en":"«Where is the cat» and «Do you like soup» are questions.","ru":"«Где кошка» и «Ты любишь суп» — это вопросы."},"difficulty":2,"audio":true,"options":[{"en":"Where is the cat","ru":"Где кошка"},{"en":"The cat is here","ru":"Кошка здесь"},{"en":"Do you like soup","ru":"Ты любишь суп"},{"en":"I like soup","ru":"Я люблю суп"}],"answers":[0,2],"role":"check"}'::jsonb, 2, '{"en":"«Where is the cat» and «Do you like soup» are questions.","ru":"«Где кошка» и «Ты любишь суп» — это вопросы."}'::jsonb),
  ('reading.punctuation.l1.c5', 'reading.punctuation.l1', 'true_false', '{"id":"reading.punctuation.l1.c5","type":"true_false","prompt":{"en":"A comma is used to end a sentence.","ru":"Запятую ставят в конце предложения."},"explanation":{"en":"A sentence ends with . ? or ! — a comma goes inside a sentence.","ru":"В конце предложения ставят . ? или ! — а запятая стоит внутри предложения."},"difficulty":1,"audio":true,"answer":false,"role":"check"}'::jsonb, 1, '{"en":"A sentence ends with . ? or ! — a comma goes inside a sentence.","ru":"В конце предложения ставят . ? или ! — а запятая стоит внутри предложения."}'::jsonb),
  ('reading.comprehension.l1.p1', 'reading.comprehension.l1', 'single', '{"id":"reading.comprehension.l1.p1","type":"single","prompt":{"en":"Where did Mila find the kitten?","ru":"Где Мила нашла котёнка?"},"hint":{"en":"Look at the first sentence.","ru":"Посмотри на первое предложение."},"explanation":{"en":"She found it under the old bench in the park.","ru":"Она нашла его под старой скамейкой в парке."},"difficulty":1,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"options":[{"en":"under a bench in the park","ru":"под скамейкой в парке"},{"en":"in a tree","ru":"на дереве"},{"en":"at school","ru":"в школе"}],"answer":0,"role":"practice"}'::jsonb, 1, '{"en":"She found it under the old bench in the park.","ru":"Она нашла его под старой скамейкой в парке."}'::jsonb),
  ('reading.comprehension.l1.p2', 'reading.comprehension.l1', 'true_false', '{"id":"reading.comprehension.l1.p2","type":"true_false","prompt":{"en":"The kitten was dry and warm when Mila found it.","ru":"Когда Мила нашла котёнка, он был сухой и тёплый."},"hint":{"en":"Read the second sentence again.","ru":"Перечитай второе предложение."},"explanation":{"en":"The kitten was wet and shaking.","ru":"Котёнок был мокрый и дрожал."},"difficulty":1,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"answer":false,"role":"practice"}'::jsonb, 1, '{"en":"The kitten was wet and shaking.","ru":"Котёнок был мокрый и дрожал."}'::jsonb),
  ('reading.comprehension.l1.p3', 'reading.comprehension.l1', 'single', '{"id":"reading.comprehension.l1.p3","type":"single","prompt":{"en":"Why did Mila name the kitten Button?","ru":"Почему Мила назвала котёнка Пуговкой?"},"hint":{"en":"Look for the word «because».","ru":"Найди слова «потому что»."},"explanation":{"en":"Because its nose was small and round, like a button.","ru":"Потому что носик у него был маленький и круглый, как пуговка."},"difficulty":2,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"options":[{"en":"it was black","ru":"он был чёрный"},{"en":"its nose was small and round","ru":"носик был маленький и круглый"},{"en":"it played with buttons","ru":"он играл с пуговицами"}],"answer":1,"role":"practice"}'::jsonb, 2, '{"en":"Because its nose was small and round, like a button.","ru":"Потому что носик у него был маленький и круглый, как пуговка."}'::jsonb),
  ('reading.comprehension.l1.c1', 'reading.comprehension.l1', 'single', '{"id":"reading.comprehension.l1.c1","type":"single","prompt":{"en":"What is the story mostly about?","ru":"О чём этот рассказ в целом?"},"explanation":{"en":"The whole story is about Mila helping a lost kitten and giving it a home.","ru":"Весь рассказ о том, как Мила помогла котёнку и подарила ему дом."},"difficulty":2,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"options":[{"en":"Grandma cooks dinner","ru":"Бабушка готовит ужин"},{"en":"Mila helps a lost kitten and gives it a home","ru":"Мила помогает котёнку и дарит ему дом"},{"en":"A fun day at the playground","ru":"Весёлый день на детской площадке"}],"answer":1,"role":"check"}'::jsonb, 2, '{"en":"The whole story is about Mila helping a lost kitten and giving it a home.","ru":"Весь рассказ о том, как Мила помогла котёнку и подарила ему дом."}'::jsonb),
  ('reading.comprehension.l1.c2', 'reading.comprehension.l1', 'ordering', '{"id":"reading.comprehension.l1.c2","type":"ordering","prompt":{"en":"Put the events in the order they happened.","ru":"Расставь события по порядку."},"explanation":{"en":"First she found it, then carried it home, then Grandma warmed milk, and at last it purred.","ru":"Сначала нашла, потом принесла домой, затем бабушка подогрела молоко, а в конце котёнок мурлыкал."},"difficulty":2,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"items":[{"en":"Mila finds the kitten.","ru":"Мила находит котёнка."},{"en":"Mila carries it home in her scarf.","ru":"Мила несёт его домой в шарфе."},{"en":"Grandma warms some milk.","ru":"Бабушка подогревает молоко."},{"en":"The kitten purrs on the windowsill.","ru":"Котёнок мурлычет на подоконнике."}],"role":"check"}'::jsonb, 2, '{"en":"First she found it, then carried it home, then Grandma warmed milk, and at last it purred.","ru":"Сначала нашла, потом принесла домой, затем бабушка подогрела молоко, а в конце котёнок мурлыкал."}'::jsonb),
  ('reading.comprehension.l1.c3', 'reading.comprehension.l1', 'multiple', '{"id":"reading.comprehension.l1.c3","type":"multiple","prompt":{"en":"Which details are in the story? Pick all.","ru":"Какие детали есть в рассказе? Выбери все."},"explanation":{"en":"The text says the kitten was wet and Grandma warmed milk. A dog and snow are not mentioned.","ru":"В тексте сказано, что котёнок был мокрый и бабушка подогрела молоко. О собаке и снеге там нет ни слова."},"difficulty":2,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"options":[{"en":"The kitten was wet.","ru":"Котёнок был мокрый."},{"en":"Mila had a dog.","ru":"У Милы была собака."},{"en":"Grandma warmed milk.","ru":"Бабушка подогрела молоко."},{"en":"It was snowing.","ru":"Шёл снег."}],"answers":[0,2],"role":"check"}'::jsonb, 2, '{"en":"The text says the kitten was wet and Grandma warmed milk. A dog and snow are not mentioned.","ru":"В тексте сказано, что котёнок был мокрый и бабушка подогрела молоко. О собаке и снеге там нет ни слова."}'::jsonb),
  ('reading.comprehension.l1.c4', 'reading.comprehension.l1', 'fill_blank', '{"id":"reading.comprehension.l1.c4","type":"fill_blank","prompt":{"en":"Finish the sentence with a word from the story.","ru":"Закончи предложение словом из рассказа."},"explanation":{"en":"Mila wrapped the kitten in her scarf.","ru":"Мила завернула котёнка в свой шарф."},"difficulty":2,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"text":{"en":"Mila wrapped the kitten in her ___.","ru":"Мила завернула котёнка в свой ___."},"accepted":{"en":["scarf"],"ru":["шарф"]},"role":"check"}'::jsonb, 2, '{"en":"Mila wrapped the kitten in her scarf.","ru":"Мила завернула котёнка в свой шарф."}'::jsonb),
  ('reading.comprehension.l1.c5', 'reading.comprehension.l1', 'single', '{"id":"reading.comprehension.l1.c5","type":"single","prompt":{"en":"How did the kitten feel at the end?","ru":"Как чувствовал себя котёнок в конце?"},"hint":{"en":"What does purring tell us?","ru":"Что значит, когда котёнок мурлычет?"},"explanation":{"en":"Purring on a warm windowsill shows it felt safe and happy.","ru":"Котёнок мурлыкал в тепле — значит, ему было спокойно и хорошо."},"difficulty":3,"audio":true,"visual":{"kind":"text","text":{"en":"Mila found a tiny kitten under the old bench in the park. It was wet and shaking. Mila wrapped it in her scarf and carried it home. Grandma warmed some milk, and the kitten drank every drop. Soon it was purring on the warm windowsill. Mila named it Button because its nose was small and round.","ru":"Мила нашла крошечного котёнка под старой скамейкой в парке. Он был мокрый и дрожал. Мила завернула его в свой шарф и принесла домой. Бабушка подогрела молоко, и котёнок выпил всё до капли. Вскоре он уже мурлыкал на тёплом подоконнике. Мила назвала его Пуговкой, потому что носик у него был маленький и круглый."}},"options":[{"en":"cold and scared","ru":"холодно и страшно"},{"en":"safe and happy","ru":"спокойно и радостно"},{"en":"very hungry","ru":"очень голодно"}],"answer":1,"role":"check"}'::jsonb, 3, '{"en":"Purring on a warm windowsill shows it felt safe and happy.","ru":"Котёнок мурлыкал в тепле — значит, ему было спокойно и хорошо."}'::jsonb),
  ('reading.vocabulary.l1.p1', 'reading.vocabulary.l1', 'matching', '{"id":"reading.vocabulary.l1.p1","type":"matching","prompt":{"en":"Match each word with its antonym (opposite).","ru":"Соедини слово с его антонимом."},"hint":{"en":"Think of the opposite.","ru":"Подумай о противоположном значении."},"explanation":{"en":"hot ↔ cold, up ↔ down, day ↔ night.","ru":"горячий ↔ холодный, высокий ↔ низкий, день ↔ ночь."},"difficulty":1,"audio":true,"pairs":[{"left":{"en":"hot","ru":"горячий"},"right":{"en":"cold","ru":"холодный"}},{"left":{"en":"up","ru":"высокий"},"right":{"en":"down","ru":"низкий"}},{"left":{"en":"day","ru":"день"},"right":{"en":"night","ru":"ночь"}}],"role":"practice"}'::jsonb, 1, '{"en":"hot ↔ cold, up ↔ down, day ↔ night.","ru":"горячий ↔ холодный, высокий ↔ низкий, день ↔ ночь."}'::jsonb),
  ('reading.vocabulary.l1.p2', 'reading.vocabulary.l1', 'single', '{"id":"reading.vocabulary.l1.p2","type":"single","prompt":{"en":"Which word is a synonym for «happy»?","ru":"Какое слово — синоним к слову «весёлый»?"},"hint":{"en":"Find the word that means almost the same.","ru":"Найди слово, близкое по значению."},"explanation":{"en":"«Glad» means almost the same as «happy».","ru":"«Радостный» близко по значению к «весёлый»."},"difficulty":1,"audio":true,"options":[{"en":"sad","ru":"грустный"},{"en":"glad","ru":"радостный"},{"en":"angry","ru":"сердитый"}],"answer":1,"role":"practice"}'::jsonb, 1, '{"en":"«Glad» means almost the same as «happy».","ru":"«Радостный» близко по значению к «весёлый»."}'::jsonb),
  ('reading.vocabulary.l1.p3', 'reading.vocabulary.l1', 'true_false', '{"id":"reading.vocabulary.l1.p3","type":"true_false","prompt":{"en":"«Fast» and «quick» are antonyms.","ru":"«Быстрый» и «скорый» — антонимы."},"hint":{"en":"Do they mean the same or the opposite?","ru":"Они похожи по значению или противоположны?"},"explanation":{"en":"They mean the same, so they are synonyms.","ru":"Они близки по значению — это синонимы."},"difficulty":2,"audio":true,"answer":false,"role":"practice"}'::jsonb, 2, '{"en":"They mean the same, so they are synonyms.","ru":"Они близки по значению — это синонимы."}'::jsonb),
  ('reading.vocabulary.l1.c1', 'reading.vocabulary.l1', 'matching', '{"id":"reading.vocabulary.l1.c1","type":"matching","prompt":{"en":"Match each word with its synonym.","ru":"Соедини слово с его синонимом."},"explanation":{"en":"small = little, begin = start, shout = yell.","ru":"друг = товарищ, смелый = храбрый, бежать = мчаться."},"difficulty":2,"audio":true,"pairs":[{"left":{"en":"small","ru":"друг"},"right":{"en":"little","ru":"товарищ"}},{"left":{"en":"begin","ru":"смелый"},"right":{"en":"start","ru":"храбрый"}},{"left":{"en":"shout","ru":"бежать"},"right":{"en":"yell","ru":"мчаться"}}],"role":"check"}'::jsonb, 2, '{"en":"small = little, begin = start, shout = yell.","ru":"друг = товарищ, смелый = храбрый, бежать = мчаться."}'::jsonb),
  ('reading.vocabulary.l1.c2', 'reading.vocabulary.l1', 'single', '{"id":"reading.vocabulary.l1.c2","type":"single","prompt":{"en":"Pick the antonym of «old» in «an old house».","ru":"Подбери антоним к слову «старый» в сочетании «старый дом»."},"explanation":{"en":"The opposite of an old house is a new house.","ru":"Противоположность старому дому — новый дом."},"difficulty":2,"audio":true,"options":[{"en":"ancient","ru":"древний"},{"en":"new","ru":"новый"},{"en":"big","ru":"большой"}],"answer":1,"role":"check"}'::jsonb, 2, '{"en":"The opposite of an old house is a new house.","ru":"Противоположность старому дому — новый дом."}'::jsonb),
  ('reading.vocabulary.l1.c3', 'reading.vocabulary.l1', 'fill_blank', '{"id":"reading.vocabulary.l1.c3","type":"fill_blank","prompt":{"en":"Write the antonym of «empty».","ru":"Напиши антоним к слову «пустой»."},"explanation":{"en":"The opposite of empty is full.","ru":"Противоположность слову «пустой» — «полный»."},"difficulty":2,"audio":true,"text":{"en":"The glass is not empty, it is ___.","ru":"Стакан не пустой, он ___."},"accepted":{"en":["full"],"ru":["полный"]},"role":"check"}'::jsonb, 2, '{"en":"The opposite of empty is full.","ru":"Противоположность слову «пустой» — «полный»."}'::jsonb),
  ('reading.vocabulary.l1.c4', 'reading.vocabulary.l1', 'single', '{"id":"reading.vocabulary.l1.c4","type":"single","prompt":{"en":"«The puppy was exhausted after the long walk, so it fell asleep at once.» What does «exhausted» mean?","ru":"«После долгой прогулки щенок был утомлён и сразу уснул». Что значит «утомлён»?"},"hint":{"en":"What happens after a long walk?","ru":"Что бывает после долгой прогулки?"},"explanation":{"en":"A long walk and falling asleep are clues: exhausted means very tired.","ru":"Долгая прогулка и сон — подсказки: «утомлён» значит «очень устал»."},"difficulty":3,"audio":true,"options":[{"en":"very tired","ru":"очень устал"},{"en":"very hungry","ru":"очень голоден"},{"en":"very noisy","ru":"очень шумный"}],"answer":0,"role":"check"}'::jsonb, 3, '{"en":"A long walk and falling asleep are clues: exhausted means very tired.","ru":"Долгая прогулка и сон — подсказки: «утомлён» значит «очень устал»."}'::jsonb),
  ('reading.vocabulary.l1.c5', 'reading.vocabulary.l1', 'drag_drop', '{"id":"reading.vocabulary.l1.c5","type":"drag_drop","prompt":{"en":"Sort the words: synonym or antonym of «big»?","ru":"Разложи слова: синоним или антоним к слову «большой»?"},"explanation":{"en":"Huge and giant mean big; tiny and little mean the opposite.","ru":"Огромный и громадный — синонимы; крошечный и маленький — антонимы."},"difficulty":2,"audio":true,"items":[{"id":"a","label":{"en":"huge","ru":"огромный"}},{"id":"b","label":{"en":"tiny","ru":"крошечный"}},{"id":"c","label":{"en":"giant","ru":"громадный"}},{"id":"d","label":{"en":"little","ru":"маленький"}}],"buckets":[{"id":"syn","label":{"en":"Synonym","ru":"Синоним"}},{"id":"ant","label":{"en":"Antonym","ru":"Антоним"}}],"answer":{"a":"syn","b":"ant","c":"syn","d":"ant"},"role":"check"}'::jsonb, 2, '{"en":"Huge and giant mean big; tiny and little mean the opposite.","ru":"Огромный и громадный — синонимы; крошечный и маленький — антонимы."}'::jsonb),
  ('reading.morphology.l1.p1', 'reading.morphology.l1', 'single', '{"id":"reading.morphology.l1.p1","type":"single","prompt":{"en":"What is the root of «unhelpful»?","ru":"Найди корень в слове «подснежник»."},"hint":{"en":"Remove the parts at the start and the end.","ru":"Подбери родственные слова: снег, снежный."},"explanation":{"en":"un- is a prefix, -ful is a suffix, help is the root.","ru":"под- — приставка, -ник — суффикс, -снеж- — корень (снег, снежный)."},"difficulty":2,"options":[{"en":"un","ru":"под"},{"en":"help","ru":"снеж"},{"en":"ful","ru":"ник"}],"answer":1,"role":"practice"}'::jsonb, 2, '{"en":"un- is a prefix, -ful is a suffix, help is the root.","ru":"под- — приставка, -ник — суффикс, -снеж- — корень (снег, снежный)."}'::jsonb),
  ('reading.morphology.l1.p2', 'reading.morphology.l1', 'matching', '{"id":"reading.morphology.l1.p2","type":"matching","prompt":{"en":"Match each word part with its description.","ru":"Соедини часть слова с её описанием."},"hint":{"en":"Where does each part stand in the word?","ru":"Где стоит каждая часть в слове?"},"explanation":{"en":"Prefix — before the root, suffix — after it, root — the main meaning.","ru":"Приставка — перед корнем, суффикс — после корня, корень — общая часть родственных слов."},"difficulty":2,"pairs":[{"left":{"en":"prefix","ru":"приставка"},"right":{"en":"comes before the root","ru":"стоит перед корнем"}},{"left":{"en":"suffix","ru":"суффикс"},"right":{"en":"comes after the root","ru":"стоит после корня"}},{"left":{"en":"root","ru":"корень"},"right":{"en":"carries the main meaning","ru":"общая часть родственных слов"}}],"role":"practice"}'::jsonb, 2, '{"en":"Prefix — before the root, suffix — after it, root — the main meaning.","ru":"Приставка — перед корнем, суффикс — после корня, корень — общая часть родственных слов."}'::jsonb),
  ('reading.morphology.l1.p3', 'reading.morphology.l1', 'true_false', '{"id":"reading.morphology.l1.p3","type":"true_false","prompt":{"en":"In «teacher», -er is a suffix that means «a person who».","ru":"В слове «лесной» окончание — -ой."},"hint":{"en":"A teacher is a person who teaches.","ru":"Измени слово: лесной — лесная — лесного. Что меняется?"},"explanation":{"en":"Yes: teach + -er = a person who teaches.","ru":"Да: лес|н|ой — корень -лес-, суффикс -н-, окончание -ой."},"difficulty":2,"answer":true,"role":"practice"}'::jsonb, 2, '{"en":"Yes: teach + -er = a person who teaches.","ru":"Да: лес|н|ой — корень -лес-, суффикс -н-, окончание -ой."}'::jsonb),
  ('reading.morphology.l1.c1', 'reading.morphology.l1', 'single', '{"id":"reading.morphology.l1.c1","type":"single","prompt":{"en":"Which word has a prefix?","ru":"В каком слове есть приставка?"},"explanation":{"en":"re- (again) + read = reread.","ru":"пере- + ход = переход."},"difficulty":2,"options":[{"en":"reread","ru":"переход"},{"en":"reader","ru":"ходок"},{"en":"read","ru":"ход"}],"answer":0,"role":"check"}'::jsonb, 2, '{"en":"re- (again) + read = reread.","ru":"пере- + ход = переход."}'::jsonb),
  ('reading.morphology.l1.c2', 'reading.morphology.l1', 'drag_drop', '{"id":"reading.morphology.l1.c2","type":"drag_drop","prompt":{"en":"Sort the parts of «disagreements» (dis-agree-ment-s).","ru":"Разбери по составу слово «загадка» (за-гад-к-а)."},"explanation":{"en":"dis- prefix, agree root, -ment suffix, -s ending.","ru":"за- — приставка, -гад- — корень (гадать), -к- — суффикс, -а — окончание."},"difficulty":3,"items":[{"id":"a","label":{"en":"dis","ru":"за"}},{"id":"b","label":{"en":"agree","ru":"гад"}},{"id":"c","label":{"en":"ment","ru":"к"}},{"id":"d","label":{"en":"s","ru":"а"}}],"buckets":[{"id":"pre","label":{"en":"Prefix","ru":"Приставка"}},{"id":"root","label":{"en":"Root","ru":"Корень"}},{"id":"suf","label":{"en":"Suffix","ru":"Суффикс"}},{"id":"end","label":{"en":"Ending","ru":"Окончание"}}],"answer":{"a":"pre","b":"root","c":"suf","d":"end"},"role":"check"}'::jsonb, 3, '{"en":"dis- prefix, agree root, -ment suffix, -s ending.","ru":"за- — приставка, -гад- — корень (гадать), -к- — суффикс, -а — окончание."}'::jsonb),
  ('reading.morphology.l1.c3', 'reading.morphology.l1', 'fill_blank', '{"id":"reading.morphology.l1.c3","type":"fill_blank","prompt":{"en":"Add a prefix that means «not».","ru":"Вставь приставку со значением «внутрь»."},"hint":{"en":"un- … unkind, unfair","ru":"Куда прыгнула кошка? Внутрь."},"explanation":{"en":"un + happy = unhappy (not happy).","ru":"в- (за-) + прыгнула = впрыгнула (запрыгнула) — внутрь."},"difficulty":3,"text":{"en":"The sad clown looked ___happy.","ru":"Кошка ___прыгнула в окно."},"accepted":{"en":["un","un-"],"ru":["в","за","в-","за-"]},"role":"check"}'::jsonb, 3, '{"en":"un + happy = unhappy (not happy).","ru":"в- (за-) + прыгнула = впрыгнула (запрыгнула) — внутрь."}'::jsonb),
  ('reading.morphology.l1.c4', 'reading.morphology.l1', 'multiple', '{"id":"reading.morphology.l1.c4","type":"multiple","prompt":{"en":"Which words share a root with «act»? Pick all.","ru":"Какие слова однокоренные со словом «лес»? Выбери все."},"hint":{"en":"Same root = same family of meaning.","ru":"У однокоренных слов общий корень и близкий смысл."},"explanation":{"en":"Actor and react are in the «act» family. Apple and attic only look similar.","ru":"Лесник и лесной — однокоренные. «Лестница» и «лесть» только похожи по звучанию."},"difficulty":3,"options":[{"en":"actor","ru":"лесник"},{"en":"apple","ru":"лестница"},{"en":"react","ru":"лесной"},{"en":"attic","ru":"лесть"}],"answers":[0,2],"role":"check"}'::jsonb, 3, '{"en":"Actor and react are in the «act» family. Apple and attic only look similar.","ru":"Лесник и лесной — однокоренные. «Лестница» и «лесть» только похожи по звучанию."}'::jsonb),
  ('reading.morphology.l1.c5', 'reading.morphology.l1', 'single', '{"id":"reading.morphology.l1.c5","type":"single","prompt":{"en":"What is the base (stem) of «played»?","ru":"Выдели основу в слове «лесной»."},"explanation":{"en":"Remove the ending -ed: the base is «play».","ru":"Основа — слово без окончания: «лесн»."},"difficulty":3,"options":[{"en":"play","ru":"лесн"},{"en":"pla","ru":"лес"},{"en":"ed","ru":"ой"}],"answer":0,"role":"check"}'::jsonb, 3, '{"en":"Remove the ending -ed: the base is «play».","ru":"Основа — слово без окончания: «лесн»."}'::jsonb),
  ('reading.syntax.l1.p1', 'reading.syntax.l1', 'single', '{"id":"reading.syntax.l1.p1","type":"single","prompt":{"en":"Find the subject: «The old clock ticked loudly.»","ru":"Найди подлежащее: «Старые часы громко тикали»."},"hint":{"en":"Who or what ticked?","ru":"Кто? Что? тикали?"},"explanation":{"en":"The clock is what the sentence is about.","ru":"Что тикали? Часы — это подлежащее."},"difficulty":3,"options":[{"en":"clock","ru":"часы"},{"en":"ticked","ru":"тикали"},{"en":"loudly","ru":"громко"}],"answer":0,"role":"practice"}'::jsonb, 3, '{"en":"The clock is what the sentence is about.","ru":"Что тикали? Часы — это подлежащее."}'::jsonb),
  ('reading.syntax.l1.p2', 'reading.syntax.l1', 'true_false', '{"id":"reading.syntax.l1.p2","type":"true_false","prompt":{"en":"«I stayed home because it was raining.» is a complex sentence.","ru":"«Я остался дома, потому что шёл дождь» — сложное предложение."},"hint":{"en":"Count the subject + predicate pairs.","ru":"Посчитай грамматические основы."},"explanation":{"en":"Two clauses (I stayed / it was raining), joined by «because» — complex.","ru":"Две основы (я остался / дождь шёл), связаны союзом «потому что» — сложноподчинённое."},"difficulty":3,"answer":true,"role":"practice"}'::jsonb, 3, '{"en":"Two clauses (I stayed / it was raining), joined by «because» — complex.","ru":"Две основы (я остался / дождь шёл), связаны союзом «потому что» — сложноподчинённое."}'::jsonb),
  ('reading.syntax.l1.p3', 'reading.syntax.l1', 'single', '{"id":"reading.syntax.l1.p3","type":"single","prompt":{"en":"How many clauses are in: «The sun rose, and the birds began to sing.»","ru":"Сколько грамматических основ в предложении: «Взошло солнце, и запели птицы»?"},"hint":{"en":"Find each subject and its verb.","ru":"Найди каждое подлежащее и его сказуемое."},"explanation":{"en":"The sun rose + the birds began to sing = 2 clauses.","ru":"Солнце взошло + птицы запели = 2 основы."},"difficulty":3,"options":[{"en":"1","ru":"1"},{"en":"2","ru":"2"},{"en":"3","ru":"3"}],"answer":1,"role":"practice"}'::jsonb, 3, '{"en":"The sun rose + the birds began to sing = 2 clauses.","ru":"Солнце взошло + птицы запели = 2 основы."}'::jsonb),
  ('reading.syntax.l1.c1', 'reading.syntax.l1', 'drag_drop', '{"id":"reading.syntax.l1.c1","type":"drag_drop","prompt":{"en":"Sort the sentences: one clause or two?","ru":"Разложи предложения: простое или сложное?"},"explanation":{"en":"Two subjects with ONE verb is still one clause. Two subject + verb pairs make two clauses.","ru":"Однородные подлежащие при одном сказуемом — всё равно одна основа. Две основы — сложное предложение."},"difficulty":4,"items":[{"id":"a","label":{"en":"The cat slept on the sofa.","ru":"Кот спал на диване."}},{"id":"b","label":{"en":"I called, but nobody answered.","ru":"Я позвонил, но никто не ответил."}},{"id":"c","label":{"en":"When spring came, the snow melted.","ru":"Когда пришла весна, растаял снег."}},{"id":"d","label":{"en":"My brother and sister play chess.","ru":"Брат и сестра играют в шахматы."}}],"buckets":[{"id":"one","label":{"en":"Simple (one clause)","ru":"Простое (одна основа)"}},{"id":"two","label":{"en":"Two or more clauses","ru":"Сложное (две и более основы)"}}],"answer":{"a":"one","b":"two","c":"two","d":"one"},"role":"check"}'::jsonb, 4, '{"en":"Two subjects with ONE verb is still one clause. Two subject + verb pairs make two clauses.","ru":"Однородные подлежащие при одном сказуемом — всё равно одна основа. Две основы — сложное предложение."}'::jsonb),
  ('reading.syntax.l1.c2', 'reading.syntax.l1', 'single', '{"id":"reading.syntax.l1.c2","type":"single","prompt":{"en":"Find the predicate: «The students wrote an essay.»","ru":"Найди сказуемое: «Ученики написали сочинение»."},"explanation":{"en":"«Wrote» tells what the students did.","ru":"Ученики что сделали? Написали — это сказуемое."},"difficulty":3,"options":[{"en":"students","ru":"ученики"},{"en":"wrote","ru":"написали"},{"en":"essay","ru":"сочинение"}],"answer":1,"role":"check"}'::jsonb, 3, '{"en":"«Wrote» tells what the students did.","ru":"Ученики что сделали? Написали — это сказуемое."}'::jsonb),
  ('reading.syntax.l1.c3', 'reading.syntax.l1', 'multiple', '{"id":"reading.syntax.l1.c3","type":"multiple","prompt":{"en":"Which sentences are complex (have a dependent clause)? Pick all.","ru":"Какие предложения сложноподчинённые? Выбери все."},"explanation":{"en":"«that you are right» and «that I read» are dependent clauses.","ru":"Части связаны союзом «что» и союзным словом «которую» — это сложноподчинённые предложения."},"difficulty":4,"options":[{"en":"I know that you are right.","ru":"Я знаю, что ты прав."},{"en":"We sang and danced.","ru":"Мы пели и танцевали."},{"en":"The book that I read was funny.","ru":"Книга, которую я прочитал, была смешной."},{"en":"Tom ate an apple.","ru":"Том съел яблоко."}],"answers":[0,2],"role":"check"}'::jsonb, 4, '{"en":"«that you are right» and «that I read» are dependent clauses.","ru":"Части связаны союзом «что» и союзным словом «которую» — это сложноподчинённые предложения."}'::jsonb),
  ('reading.syntax.l1.c4', 'reading.syntax.l1', 'fill_blank', '{"id":"reading.syntax.l1.c4","type":"fill_blank","prompt":{"en":"Add a conjunction to make a complex sentence.","ru":"Вставь союз, чтобы получилось сложноподчинённое предложение."},"hint":{"en":"The second part gives a reason.","ru":"Вторая часть называет причину."},"explanation":{"en":"«Because» introduces a reason.","ru":"Союз «потому что» (или «так как») указывает на причину."},"difficulty":3,"text":{"en":"We stayed inside ___ it was cold.","ru":"Мы остались дома, ___ было холодно."},"accepted":{"en":["because","since","as"],"ru":["потому что","так как","поскольку","ведь","оттого что"]},"role":"check"}'::jsonb, 3, '{"en":"«Because» introduces a reason.","ru":"Союз «потому что» (или «так как») указывает на причину."}'::jsonb),
  ('reading.syntax.l1.c5', 'reading.syntax.l1', 'ordering', '{"id":"reading.syntax.l1.c5","type":"ordering","prompt":{"en":"Put the parts in order to build a complex sentence.","ru":"Расставь части по порядку, чтобы получилось сложное предложение."},"explanation":{"en":"When the bell rang, the students left the classroom.","ru":"Когда прозвенел звонок, ученики вышли из класса."},"difficulty":3,"items":[{"en":"When","ru":"Когда"},{"en":"the bell rang,","ru":"прозвенел звонок,"},{"en":"the students","ru":"ученики"},{"en":"left","ru":"вышли"},{"en":"the classroom.","ru":"из класса."}],"role":"check"}'::jsonb, 3, '{"en":"When the bell rang, the students left the classroom.","ru":"Когда прозвенел звонок, ученики вышли из класса."}'::jsonb),
  ('reading.literature.l1.p1', 'reading.literature.l1', 'single', '{"id":"reading.literature.l1.p1","type":"single","prompt":{"en":"What genre is this text?","ru":"К какому жанру относится этот текст?"},"hint":{"en":"Look at the characters and the last sentence.","ru":"Посмотри на героев и на последнее предложение."},"explanation":{"en":"A short story with an animal character and a moral is a fable.","ru":"Короткий рассказ о животном с моралью в конце — это басня."},"difficulty":2,"visual":{"kind":"text","text":{"en":"A proud Magpie collected shiny things and boasted about them to the whole forest. One day she found a piece of glass and decided it was a diamond. She guarded it day and night and completely forgot to build her nest. When the cold autumn rains came, the other birds sat in their warm nests, while the Magpie shivered next to her «treasure». Moral: not everything that sparkles is what we truly need.","ru":"Гордая Сорока собирала блестящие вещицы и хвасталась ими перед всем лесом. Однажды она нашла осколок стекла и решила, что это алмаз. Она стерегла его день и ночь и совсем забыла свить гнездо. Когда пришли холодные осенние дожди, другие птицы сидели в тёплых гнёздах, а Сорока дрожала рядом со своим «сокровищем». Мораль: не всё то нужно, что блестит."}},"options":[{"en":"novel","ru":"роман"},{"en":"fable","ru":"басня"},{"en":"drama","ru":"драма"}],"answer":1,"role":"practice"}'::jsonb, 2, '{"en":"A short story with an animal character and a moral is a fable.","ru":"Короткий рассказ о животном с моралью в конце — это басня."}'::jsonb),
  ('reading.literature.l1.p2', 'reading.literature.l1', 'matching', '{"id":"reading.literature.l1.p2","type":"matching","prompt":{"en":"Match each genre with its feature.","ru":"Соедини жанр с его особенностью."},"hint":{"en":"Which one is written for actors?","ru":"Какой жанр пишут для актёров?"},"explanation":{"en":"Fairy tale — magic; poem — rhythm and rhyme; drama — dialogue for the stage.","ru":"Сказка — волшебство; стихотворение — ритм и рифма; драма — реплики для сцены."},"difficulty":3,"pairs":[{"left":{"en":"fairy tale","ru":"сказка"},"right":{"en":"magic and wonders","ru":"волшебство и чудеса"}},{"left":{"en":"poem","ru":"стихотворение"},"right":{"en":"rhythm and rhyme","ru":"ритм и рифма"}},{"left":{"en":"drama","ru":"драма"},"right":{"en":"dialogue for the stage","ru":"реплики героев для сцены"}}],"role":"practice"}'::jsonb, 3, '{"en":"Fairy tale — magic; poem — rhythm and rhyme; drama — dialogue for the stage.","ru":"Сказка — волшебство; стихотворение — ритм и рифма; драма — реплики для сцены."}'::jsonb),
  ('reading.literature.l1.p3', 'reading.literature.l1', 'true_false', '{"id":"reading.literature.l1.p3","type":"true_false","prompt":{"en":"A moral is the lesson a story teaches.","ru":"Мораль — это поучение, которое содержит произведение."},"hint":{"en":"Look at the last sentence of the fable.","ru":"Посмотри на последнее предложение басни."},"explanation":{"en":"Yes, a fable''s moral tells us what to learn.","ru":"Да, мораль басни говорит, чему нас учит история."},"difficulty":2,"answer":true,"role":"practice"}'::jsonb, 2, '{"en":"Yes, a fable''s moral tells us what to learn.","ru":"Да, мораль басни говорит, чему нас учит история."}'::jsonb),
  ('reading.literature.l1.c1', 'reading.literature.l1', 'single', '{"id":"reading.literature.l1.c1","type":"single","prompt":{"en":"What is the moral of the fable?","ru":"В чём мораль басни?"},"explanation":{"en":"The Magpie chased something shiny and forgot what she really needed.","ru":"Сорока погналась за блестящим и забыла о действительно нужном."},"difficulty":3,"visual":{"kind":"text","text":{"en":"A proud Magpie collected shiny things and boasted about them to the whole forest. One day she found a piece of glass and decided it was a diamond. She guarded it day and night and completely forgot to build her nest. When the cold autumn rains came, the other birds sat in their warm nests, while the Magpie shivered next to her «treasure». Moral: not everything that sparkles is what we truly need.","ru":"Гордая Сорока собирала блестящие вещицы и хвасталась ими перед всем лесом. Однажды она нашла осколок стекла и решила, что это алмаз. Она стерегла его день и ночь и совсем забыла свить гнездо. Когда пришли холодные осенние дожди, другие птицы сидели в тёплых гнёздах, а Сорока дрожала рядом со своим «сокровищем». Мораль: не всё то нужно, что блестит."}},"options":[{"en":"Shiny things are always valuable.","ru":"Всё блестящее — ценное."},{"en":"Don''t let pretty things distract you from what really matters.","ru":"Не позволяй красивым пустякам отвлечь тебя от важного."},{"en":"Magpies cannot build nests.","ru":"Сороки не умеют вить гнёзда."}],"answer":1,"role":"check"}'::jsonb, 3, '{"en":"The Magpie chased something shiny and forgot what she really needed.","ru":"Сорока погналась за блестящим и забыла о действительно нужном."}'::jsonb),
  ('reading.literature.l1.c2', 'reading.literature.l1', 'multiple', '{"id":"reading.literature.l1.c2","type":"multiple","prompt":{"en":"Which features does a fable usually have? Pick all.","ru":"Какие черты обычно есть у басни? Выбери все."},"explanation":{"en":"Fables are short, have animals that act like people, and teach a moral.","ru":"Басня короткая, в ней животные ведут себя как люди, и в ней есть мораль."},"difficulty":3,"options":[{"en":"animals that act like people","ru":"животные ведут себя как люди"},{"en":"a moral","ru":"мораль (поучение)"},{"en":"hundreds of pages","ru":"сотни страниц"},{"en":"stage directions for actors","ru":"ремарки для актёров"}],"answers":[0,1],"role":"check"}'::jsonb, 3, '{"en":"Fables are short, have animals that act like people, and teach a moral.","ru":"Басня короткая, в ней животные ведут себя как люди, и в ней есть мораль."}'::jsonb),
  ('reading.literature.l1.c3', 'reading.literature.l1', 'single', '{"id":"reading.literature.l1.c3","type":"single","prompt":{"en":"Why was the Magpie cold when the rains came?","ru":"Почему Сороке было холодно, когда пошли дожди?"},"explanation":{"en":"She was guarding the glass and forgot to build a nest.","ru":"Она стерегла стекло и забыла свить гнездо."},"difficulty":2,"visual":{"kind":"text","text":{"en":"A proud Magpie collected shiny things and boasted about them to the whole forest. One day she found a piece of glass and decided it was a diamond. She guarded it day and night and completely forgot to build her nest. When the cold autumn rains came, the other birds sat in their warm nests, while the Magpie shivered next to her «treasure». Moral: not everything that sparkles is what we truly need.","ru":"Гордая Сорока собирала блестящие вещицы и хвасталась ими перед всем лесом. Однажды она нашла осколок стекла и решила, что это алмаз. Она стерегла его день и ночь и совсем забыла свить гнездо. Когда пришли холодные осенние дожди, другие птицы сидели в тёплых гнёздах, а Сорока дрожала рядом со своим «сокровищем». Мораль: не всё то нужно, что блестит."}},"options":[{"en":"She forgot to build a nest.","ru":"Она забыла свить гнездо."},{"en":"She lost the glass.","ru":"Она потеряла стекло."},{"en":"The other birds chased her away.","ru":"Другие птицы прогнали её."}],"answer":0,"role":"check"}'::jsonb, 2, '{"en":"She was guarding the glass and forgot to build a nest.","ru":"Она стерегла стекло и забыла свить гнездо."}'::jsonb),
  ('reading.literature.l1.c4', 'reading.literature.l1', 'drag_drop', '{"id":"reading.literature.l1.c4","type":"drag_drop","prompt":{"en":"Sort the works by genre.","ru":"Распредели произведения по жанрам."},"explanation":{"en":"Cinderella — fairy tale, The Tortoise and the Hare — fable, Treasure Island — novel, Romeo and Juliet — drama.","ru":"«Морозко» — сказка, «Стрекоза и Муравей» — басня, «Война и мир» — роман, «Ревизор» — драма (пьеса)."},"difficulty":4,"items":[{"id":"a","label":{"en":"Cinderella","ru":"«Морозко»"}},{"id":"b","label":{"en":"The Tortoise and the Hare (Aesop)","ru":"«Стрекоза и Муравей» (И. А. Крылов)"}},{"id":"c","label":{"en":"Treasure Island (R. L. Stevenson)","ru":"«Война и мир» (Л. Н. Толстой)"}},{"id":"d","label":{"en":"Romeo and Juliet (W. Shakespeare)","ru":"«Ревизор» (Н. В. Гоголь)"}}],"buckets":[{"id":"tale","label":{"en":"Fairy tale","ru":"Сказка"}},{"id":"fable","label":{"en":"Fable","ru":"Басня"}},{"id":"novel","label":{"en":"Novel","ru":"Роман"}},{"id":"drama","label":{"en":"Drama","ru":"Драма"}}],"answer":{"a":"tale","b":"fable","c":"novel","d":"drama"},"role":"check"}'::jsonb, 4, '{"en":"Cinderella — fairy tale, The Tortoise and the Hare — fable, Treasure Island — novel, Romeo and Juliet — drama.","ru":"«Морозко» — сказка, «Стрекоза и Муравей» — басня, «Война и мир» — роман, «Ревизор» — драма (пьеса)."}'::jsonb),
  ('reading.literature.l1.c5', 'reading.literature.l1', 'single', '{"id":"reading.literature.l1.c5","type":"single","prompt":{"en":"In the fable, what does the piece of glass stand for?","ru":"Что символизирует осколок стекла в басне?"},"hint":{"en":"Was the glass really useful to the Magpie?","ru":"Была ли от стекла настоящая польза Сороке?"},"explanation":{"en":"The glass stands for things that look valuable but do not really help us.","ru":"Стекло — символ того, что кажется ценным, но не приносит пользы."},"difficulty":4,"visual":{"kind":"text","text":{"en":"A proud Magpie collected shiny things and boasted about them to the whole forest. One day she found a piece of glass and decided it was a diamond. She guarded it day and night and completely forgot to build her nest. When the cold autumn rains came, the other birds sat in their warm nests, while the Magpie shivered next to her «treasure». Moral: not everything that sparkles is what we truly need.","ru":"Гордая Сорока собирала блестящие вещицы и хвасталась ими перед всем лесом. Однажды она нашла осколок стекла и решила, что это алмаз. Она стерегла его день и ночь и совсем забыла свить гнездо. Когда пришли холодные осенние дожди, другие птицы сидели в тёплых гнёздах, а Сорока дрожала рядом со своим «сокровищем». Мораль: не всё то нужно, что блестит."}},"options":[{"en":"things that look valuable but are not useful","ru":"то, что кажется ценным, но бесполезно"},{"en":"a real diamond","ru":"настоящий алмаз"},{"en":"the cold rain","ru":"холодный дождь"}],"answer":0,"role":"check"}'::jsonb, 4, '{"en":"The glass stands for things that look valuable but do not really help us.","ru":"Стекло — символ того, что кажется ценным, но не приносит пользы."}'::jsonb),
  ('reading.text-analysis.l1.p1', 'reading.text-analysis.l1', 'single', '{"id":"reading.text-analysis.l1.p1","type":"single","prompt":{"en":"What is the thesis (main claim) of the passage?","ru":"Какой тезис (главное утверждение) у этого текста?"},"hint":{"en":"Look for the sentence the author is trying to prove — often near the end.","ru":"Найди мысль, которую автор доказывает, — часто она в конце."},"explanation":{"en":"The author argues that mistakes are steps toward growth, not reasons for shame.","ru":"Автор доказывает, что ошибки — это шаги к росту, а не повод для стыда."},"difficulty":4,"visual":{"kind":"text","text":{"en":"Many people think that mistakes are something to be ashamed of. However, every inventor, athlete and scientist has made thousands of them. A child learning to walk falls again and again, and no one calls this a failure. Mistakes show us where we still need to grow. That is why we should treat them not as defeats but as steps forward.","ru":"Многие считают, что ошибок нужно стыдиться. Однако каждый изобретатель, спортсмен и учёный совершил их тысячи. Ребёнок, который учится ходить, падает снова и снова, и никто не называет это неудачей. Ошибки показывают, где нам ещё нужно расти. Вот почему к ним стоит относиться не как к поражениям, а как к шагам вперёд."}},"options":[{"en":"Inventors are very clever.","ru":"Изобретатели очень умные."},{"en":"Mistakes are steps toward growth, not reasons for shame.","ru":"Ошибки — это шаги к росту, а не повод для стыда."},{"en":"Children learn to walk early.","ru":"Дети рано учатся ходить."}],"answer":1,"role":"practice"}'::jsonb, 4, '{"en":"The author argues that mistakes are steps toward growth, not reasons for shame.","ru":"Автор доказывает, что ошибки — это шаги к росту, а не повод для стыда."}'::jsonb),
  ('reading.text-analysis.l1.p2', 'reading.text-analysis.l1', 'drag_drop', '{"id":"reading.text-analysis.l1.p2","type":"drag_drop","prompt":{"en":"Which part of an essay does each job?","ru":"В какой части сочинения это делается?"},"hint":{"en":"Where do we state the claim, prove it and sum up?","ru":"Где мы заявляем тезис, где доказываем, где подводим итог?"},"explanation":{"en":"Introduction — thesis; body — arguments, evidence, explanation; conclusion — summary.","ru":"Вступление — тезис; основная часть — аргументы, примеры, пояснения; заключение — вывод."},"difficulty":4,"items":[{"id":"a","label":{"en":"states the thesis","ru":"формулирует тезис"}},{"id":"b","label":{"en":"gives an argument with evidence","ru":"приводит аргумент с примером"}},{"id":"c","label":{"en":"explains how the evidence supports the point","ru":"поясняет, как пример доказывает тезис"}},{"id":"d","label":{"en":"sums up and restates the main idea","ru":"подводит итог и повторяет главную мысль"}}],"buckets":[{"id":"intro","label":{"en":"Introduction","ru":"Вступление"}},{"id":"body","label":{"en":"Body","ru":"Основная часть"}},{"id":"concl","label":{"en":"Conclusion","ru":"Заключение"}}],"answer":{"a":"intro","b":"body","c":"body","d":"concl"},"role":"practice"}'::jsonb, 4, '{"en":"Introduction — thesis; body — arguments, evidence, explanation; conclusion — summary.","ru":"Вступление — тезис; основная часть — аргументы, примеры, пояснения; заключение — вывод."}'::jsonb),
  ('reading.text-analysis.l1.p3', 'reading.text-analysis.l1', 'true_false', '{"id":"reading.text-analysis.l1.p3","type":"true_false","prompt":{"en":"The theme of a text is the same as its topic.","ru":"Тема и основная мысль текста — это одно и то же."},"hint":{"en":"«Mistakes» vs «mistakes help us grow».","ru":"«Об ошибках» и «ошибки помогают расти» — одно и то же?"},"explanation":{"en":"The topic is what the text is about; the theme is the message about it.","ru":"Тема — о чём текст, а основная мысль — что автор хочет сказать об этом."},"difficulty":4,"answer":false,"role":"practice"}'::jsonb, 4, '{"en":"The topic is what the text is about; the theme is the message about it.","ru":"Тема — о чём текст, а основная мысль — что автор хочет сказать об этом."}'::jsonb),
  ('reading.text-analysis.l1.c1', 'reading.text-analysis.l1', 'single', '{"id":"reading.text-analysis.l1.c1","type":"single","prompt":{"en":"Which sentence from the passage is an example used as evidence?","ru":"Какое предложение текста — пример, подтверждающий тезис?"},"explanation":{"en":"The child learning to walk is a concrete example that supports the claim.","ru":"Ребёнок, который учится ходить, — конкретный пример, подтверждающий мысль автора."},"difficulty":4,"visual":{"kind":"text","text":{"en":"Many people think that mistakes are something to be ashamed of. However, every inventor, athlete and scientist has made thousands of them. A child learning to walk falls again and again, and no one calls this a failure. Mistakes show us where we still need to grow. That is why we should treat them not as defeats but as steps forward.","ru":"Многие считают, что ошибок нужно стыдиться. Однако каждый изобретатель, спортсмен и учёный совершил их тысячи. Ребёнок, который учится ходить, падает снова и снова, и никто не называет это неудачей. Ошибки показывают, где нам ещё нужно расти. Вот почему к ним стоит относиться не как к поражениям, а как к шагам вперёд."}},"options":[{"en":"A child learning to walk falls again and again…","ru":"Ребёнок, который учится ходить, падает снова и снова…"},{"en":"That is why we should treat them…","ru":"Вот почему к ним стоит относиться…"},{"en":"Many people think that mistakes…","ru":"Многие считают, что ошибок…"}],"answer":0,"role":"check"}'::jsonb, 4, '{"en":"The child learning to walk is a concrete example that supports the claim.","ru":"Ребёнок, который учится ходить, — конкретный пример, подтверждающий мысль автора."}'::jsonb),
  ('reading.text-analysis.l1.c2', 'reading.text-analysis.l1', 'ordering', '{"id":"reading.text-analysis.l1.c2","type":"ordering","prompt":{"en":"Put the parts of an argumentative essay in order.","ru":"Расставь части сочинения-рассуждения по порядку."},"explanation":{"en":"Introduction and thesis → arguments with evidence → conclusion.","ru":"Вступление и тезис → аргументы с примерами → вывод."},"difficulty":4,"items":[{"en":"Introduction with thesis","ru":"Вступление и тезис"},{"en":"First argument with evidence","ru":"Первый аргумент с примером"},{"en":"Second argument with evidence","ru":"Второй аргумент с примером"},{"en":"Conclusion","ru":"Заключение (вывод)"}],"role":"check"}'::jsonb, 4, '{"en":"Introduction and thesis → arguments with evidence → conclusion.","ru":"Вступление и тезис → аргументы с примерами → вывод."}'::jsonb),
  ('reading.text-analysis.l1.c3', 'reading.text-analysis.l1', 'multiple', '{"id":"reading.text-analysis.l1.c3","type":"multiple","prompt":{"en":"Which are strong pieces of evidence? Pick all.","ru":"Что можно использовать как сильный аргумент? Выбери все."},"explanation":{"en":"Facts from reliable sources and quotations from the text can be checked; feelings and «everyone knows» cannot.","ru":"Факты из надёжных источников и цитаты из текста можно проверить, а «все знают» и «мне так кажется» — нет."},"difficulty":4,"options":[{"en":"a fact from a reliable source","ru":"факт из надёжного источника"},{"en":"«everyone knows it»","ru":"«это все знают»"},{"en":"a quotation from the text","ru":"цитата из текста"},{"en":"«I just feel it»","ru":"«мне так кажется»"}],"answers":[0,2],"role":"check"}'::jsonb, 4, '{"en":"Facts from reliable sources and quotations from the text can be checked; feelings and «everyone knows» cannot.","ru":"Факты из надёжных источников и цитаты из текста можно проверить, а «все знают» и «мне так кажется» — нет."}'::jsonb),
  ('reading.text-analysis.l1.c4', 'reading.text-analysis.l1', 'single', '{"id":"reading.text-analysis.l1.c4","type":"single","prompt":{"en":"What is the role of «However» at the start of the second sentence?","ru":"Какую роль играет слово «Однако» в начале второго предложения?"},"explanation":{"en":"«However» signals a contrast: the author disagrees with the common opinion.","ru":"«Однако» вводит противопоставление: автор спорит с распространённым мнением."},"difficulty":5,"visual":{"kind":"text","text":{"en":"Many people think that mistakes are something to be ashamed of. However, every inventor, athlete and scientist has made thousands of them. A child learning to walk falls again and again, and no one calls this a failure. Mistakes show us where we still need to grow. That is why we should treat them not as defeats but as steps forward.","ru":"Многие считают, что ошибок нужно стыдиться. Однако каждый изобретатель, спортсмен и учёный совершил их тысячи. Ребёнок, который учится ходить, падает снова и снова, и никто не называет это неудачей. Ошибки показывают, где нам ещё нужно расти. Вот почему к ним стоит относиться не как к поражениям, а как к шагам вперёд."}},"options":[{"en":"It introduces a contrast with a common opinion.","ru":"Вводит противопоставление распространённому мнению."},{"en":"It gives an example.","ru":"Приводит пример."},{"en":"It concludes the text.","ru":"Завершает текст."}],"answer":0,"role":"check"}'::jsonb, 5, '{"en":"«However» signals a contrast: the author disagrees with the common opinion.","ru":"«Однако» вводит противопоставление: автор спорит с распространённым мнением."}'::jsonb),
  ('reading.text-analysis.l1.c5', 'reading.text-analysis.l1', 'fill_blank', '{"id":"reading.text-analysis.l1.c5","type":"fill_blank","prompt":{"en":"Finish the sentence.","ru":"Закончи предложение."},"explanation":{"en":"The conclusion sums up the argument and restates the thesis.","ru":"В заключении подводят итог и делают вывод."},"difficulty":3,"text":{"en":"The final part of an essay that sums up the argument is called the ___.","ru":"Последняя часть сочинения, где подводится итог, называется ___."},"accepted":{"en":["conclusion"],"ru":["заключение","вывод","заключением"]},"role":"check"}'::jsonb, 3, '{"en":"The conclusion sums up the argument and restates the thesis.","ru":"В заключении подводят итог и делают вывод."}'::jsonb),
  ('science.living-things.l1.p1', 'science.living-things.l1', 'image_selection', '{"id":"science.living-things.l1.p1","type":"image_selection","prompt":{"en":"Which one is a living thing?","ru":"Что из этого живое?"},"options":[{"emoji":"🪨","label":{"en":"Rock","ru":"Камень"}},{"emoji":"🌻","label":{"en":"Sunflower","ru":"Подсолнух"}},{"emoji":"🧸","label":{"en":"Teddy bear","ru":"Плюшевый мишка"}}],"answer":1,"hint":{"en":"Which one grows and needs water?","ru":"Что из этого растёт и пьёт воду?"},"explanation":{"en":"A sunflower grows, drinks water and needs sunlight, so it is living.","ru":"Подсолнух растёт, пьёт воду и тянется к солнцу - значит, он живой."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"A sunflower grows, drinks water and needs sunlight, so it is living.","ru":"Подсолнух растёт, пьёт воду и тянется к солнцу - значит, он живой."}'::jsonb),
  ('science.living-things.l1.p2', 'science.living-things.l1', 'true_false', '{"id":"science.living-things.l1.p2","type":"true_false","prompt":{"en":"Plants need sunlight to grow.","ru":"Растениям нужен солнечный свет, чтобы расти."},"answer":true,"hint":{"en":"Think of a plant on a sunny windowsill.","ru":"Вспомни цветок на солнечном подоконнике."},"explanation":{"en":"Yes! Plants use sunlight to make their food.","ru":"Да! С помощью солнечного света растения делают себе пищу."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Yes! Plants use sunlight to make their food.","ru":"Да! С помощью солнечного света растения делают себе пищу."}'::jsonb),
  ('science.living-things.l1.p3', 'science.living-things.l1', 'drag_drop', '{"id":"science.living-things.l1.p3","type":"drag_drop","prompt":{"en":"Sort: living or non-living?","ru":"Разложи: живое или неживое?"},"items":[{"id":"cat","label":{"en":"🐱 Cat","ru":"🐱 Кошка"}},{"id":"tree","label":{"en":"🌳 Tree","ru":"🌳 Дерево"}},{"id":"fish","label":{"en":"🐟 Fish","ru":"🐟 Рыба"}},{"id":"stone","label":{"en":"🪨 Stone","ru":"🪨 Камень"}},{"id":"car","label":{"en":"🚗 Toy car","ru":"🚗 Игрушечная машинка"}}],"buckets":[{"id":"living","label":{"en":"Living","ru":"Живое"}},{"id":"nonliving","label":{"en":"Non-living","ru":"Неживое"}}],"answer":{"cat":"living","tree":"living","fish":"living","stone":"nonliving","car":"nonliving"},"hint":{"en":"Does it grow and need food or water?","ru":"Оно растёт и нуждается в еде или воде?"},"explanation":{"en":"The cat, the tree and the fish grow and need food or water. The stone and the toy car do not.","ru":"Кошка, дерево и рыба растут и нуждаются в пище или воде. Камень и машинка - нет."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"The cat, the tree and the fish grow and need food or water. The stone and the toy car do not.","ru":"Кошка, дерево и рыба растут и нуждаются в пище или воде. Камень и машинка - нет."}'::jsonb),
  ('science.living-things.l1.c1', 'science.living-things.l1', 'multiple', '{"id":"science.living-things.l1.c1","type":"multiple","prompt":{"en":"What do plants need to grow? Choose all.","ru":"Что нужно растениям, чтобы расти? Выбери всё."},"options":[{"en":"Sunlight","ru":"Солнечный свет"},{"en":"Water","ru":"Вода"},{"en":"Candy","ru":"Конфеты"},{"en":"Air","ru":"Воздух"}],"answers":[0,1,3],"explanation":{"en":"Plants need sunlight, water and air (and soil). Candy is for parties, not plants!","ru":"Растениям нужны свет, вода и воздух (и почва). Конфеты растениям не нужны!"},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Plants need sunlight, water and air (and soil). Candy is for parties, not plants!","ru":"Растениям нужны свет, вода и воздух (и почва). Конфеты растениям не нужны!"}'::jsonb),
