  ('science.water-cycle.l1.p1', 'science.water-cycle.l1', 'ordering', '{"id":"science.water-cycle.l1.p1","type":"ordering","prompt":{"en":"Put the water cycle steps in order.","ru":"Расставь этапы круговорота воды по порядку."},"items":[{"en":"Evaporation: water rises as vapour","ru":"Испарение: вода поднимается паром"},{"en":"Condensation: clouds form","ru":"Конденсация: образуются облака"},{"en":"Precipitation: rain or snow falls","ru":"Осадки: идёт дождь или снег"},{"en":"Collection: water gathers in rivers and seas","ru":"Сбор: вода собирается в реках и морях"}],"hint":{"en":"Start with the Sun warming the water.","ru":"Начни с того, что Солнце нагревает воду."},"explanation":{"en":"Evaporation, condensation, precipitation, collection - and round again!","ru":"Испарение, конденсация, осадки, сбор воды - и всё по кругу!"},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Evaporation, condensation, precipitation, collection - and round again!","ru":"Испарение, конденсация, осадки, сбор воды - и всё по кругу!"}'::jsonb),
