  ('science.solar-system.l1.p1', 'science.solar-system.l1', 'number_input', '{"id":"science.solar-system.l1.p1","type":"number_input","prompt":{"en":"How many planets travel around the Sun?","ru":"Сколько планет движется вокруг Солнца?"},"answer":8,"hint":{"en":"Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune - count them!","ru":"Меркурий, Венера, Земля, Марс, Юпитер, Сатурн, Уран, Нептун - посчитай!"},"explanation":{"en":"There are 8 planets in our Solar System.","ru":"В Солнечной системе 8 планет."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"There are 8 planets in our Solar System.","ru":"В Солнечной системе 8 планет."}'::jsonb),
  ('science.solar-system.l1.p2', 'science.solar-system.l1', 'single', '{"id":"science.solar-system.l1.p2","type":"single","prompt":{"en":"Why do we have day and night?","ru":"Почему бывают день и ночь?"},"options":[{"en":"The Earth spins around","ru":"Земля вращается вокруг своей оси"},{"en":"The Sun switches off at night","ru":"Солнце ночью выключается"},{"en":"The Moon covers the Sun every evening","ru":"Луна каждый вечер закрывает Солнце"}],"answer":0,"hint":{"en":"Shine a torch on a spinning ball in our virtual space lab.","ru":"Посвети фонариком на вращающийся мяч в нашей виртуальной космической лаборатории."},"explanation":{"en":"The Earth spins, so each place turns toward the Sun (day) and away from it (night).","ru":"Земля вращается, и каждое место поворачивается то к Солнцу (день), то от него (ночь)."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"The Earth spins, so each place turns toward the Sun (day) and away from it (night).","ru":"Земля вращается, и каждое место поворачивается то к Солнцу (день), то от него (ночь)."}'::jsonb),
  ('science.solar-system.l1.p3', 'science.solar-system.l1', 'true_false', '{"id":"science.solar-system.l1.p3","type":"true_false","prompt":{"en":"The Sun is a star.","ru":"Солнце - это звезда."},"answer":true,"hint":{"en":"Stars are giant balls of glowing gas.","ru":"Звёзды - огромные шары светящегося газа."},"explanation":{"en":"Yes! The Sun is our closest star. Other stars look tiny because they are very far away.","ru":"Да! Солнце - ближайшая к нам звезда. Другие звёзды кажутся маленькими, потому что они очень далеко."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Yes! The Sun is our closest star. Other stars look tiny because they are very far away.","ru":"Да! Солнце - ближайшая к нам звезда. Другие звёзды кажутся маленькими, потому что они очень далеко."}'::jsonb),
  ('science.solar-system.l1.c1', 'science.solar-system.l1', 'ordering', '{"id":"science.solar-system.l1.c1","type":"ordering","prompt":{"en":"Put the first four planets in order, starting nearest the Sun.","ru":"Расставь первые четыре планеты по порядку, начиная с ближайшей к Солнцу."},"items":[{"en":"Mercury","ru":"Меркурий"},{"en":"Venus","ru":"Венера"},{"en":"Earth","ru":"Земля"},{"en":"Mars","ru":"Марс"}],"explanation":{"en":"Mercury, Venus, Earth, Mars. Earth is number three!","ru":"Меркурий, Венера, Земля, Марс. Земля - третья!"},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Mercury, Venus, Earth, Mars. Earth is number three!","ru":"Меркурий, Венера, Земля, Марс. Земля - третья!"}'::jsonb),
  ('science.solar-system.l1.c2', 'science.solar-system.l1', 'matching', '{"id":"science.solar-system.l1.c2","type":"matching","prompt":{"en":"Match each space object with its description.","ru":"Соедини космический объект с его описанием."},"pairs":[{"left":{"en":"Sun","ru":"Солнце"},"right":{"en":"A star that gives light and heat","ru":"Звезда, дающая свет и тепло"}},{"left":{"en":"Moon","ru":"Луна"},"right":{"en":"Travels around the Earth","ru":"Движется вокруг Земли"}},{"left":{"en":"Earth","ru":"Земля"},"right":{"en":"Our home planet","ru":"Наша родная планета"}},{"left":{"en":"Saturn","ru":"Сатурн"},"right":{"en":"Planet with bright rings","ru":"Планета с яркими кольцами"}}],"explanation":{"en":"Great space knowledge! Saturn''s rings are made of ice and rock.","ru":"Отличные знания о космосе! Кольца Сатурна состоят изо льда и камней."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Great space knowledge! Saturn''s rings are made of ice and rock.","ru":"Отличные знания о космосе! Кольца Сатурна состоят изо льда и камней."}'::jsonb),
  ('science.solar-system.l1.c3', 'science.solar-system.l1', 'image_selection', '{"id":"science.solar-system.l1.c3","type":"image_selection","prompt":{"en":"Which one is the planet with big rings?","ru":"Какая из них - планета с большими кольцами?"},"options":[{"emoji":"🪐","label":{"en":"Saturn","ru":"Сатурн"}},{"emoji":"🌍","label":{"en":"Earth","ru":"Земля"}},{"emoji":"🌙","label":{"en":"Moon","ru":"Луна"}}],"answer":0,"explanation":{"en":"Saturn is famous for its rings.","ru":"Сатурн знаменит своими кольцами."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Saturn is famous for its rings.","ru":"Сатурн знаменит своими кольцами."}'::jsonb),
  ('science.solar-system.l1.c4', 'science.solar-system.l1', 'fill_blank', '{"id":"science.solar-system.l1.c4","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"The Earth goes once around the Sun in one ___.","ru":"Земля делает один оборот вокруг Солнца за один ___."},"accepted":{"en":["year"],"ru":["год"]},"explanation":{"en":"One trip around the Sun is one year - about 365 days.","ru":"Один оборот вокруг Солнца - это год, около 365 дней."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"One trip around the Sun is one year - about 365 days.","ru":"Один оборот вокруг Солнца - это год, около 365 дней."}'::jsonb),
  ('science.solar-system.l1.c5', 'science.solar-system.l1', 'multiple', '{"id":"science.solar-system.l1.c5","type":"multiple","prompt":{"en":"Which of these are planets? Choose all.","ru":"Что из этого - планеты? Выбери все."},"options":[{"en":"Mars","ru":"Марс"},{"en":"Jupiter","ru":"Юпитер"},{"en":"The Moon","ru":"Луна"},{"en":"Venus","ru":"Венера"}],"answers":[0,1,3],"explanation":{"en":"Mars, Jupiter and Venus are planets. The Moon is Earth''s natural satellite.","ru":"Марс, Юпитер и Венера - планеты. Луна - естественный спутник Земли."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Mars, Jupiter and Venus are planets. The Moon is Earth''s natural satellite.","ru":"Марс, Юпитер и Венера - планеты. Луна - естественный спутник Земли."}'::jsonb),
  ('science.scientific-method.l1.p1', 'science.scientific-method.l1', 'ordering', '{"id":"science.scientific-method.l1.p1","type":"ordering","prompt":{"en":"Put the steps of the scientific method in order.","ru":"Расставь шаги научного метода по порядку."},"items":[{"en":"Ask a question","ru":"Задать вопрос"},{"en":"Make a hypothesis","ru":"Выдвинуть гипотезу"},{"en":"Do an experiment","ru":"Провести эксперимент"},{"en":"Record the results","ru":"Записать результаты"},{"en":"Draw a conclusion","ru":"Сделать вывод"}],"hint":{"en":"You can''t test a guess before you have a question.","ru":"Нельзя проверить догадку, пока нет вопроса."},"explanation":{"en":"Question, hypothesis, experiment, results, conclusion.","ru":"Вопрос, гипотеза, эксперимент, результаты, вывод."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Question, hypothesis, experiment, results, conclusion.","ru":"Вопрос, гипотеза, эксперимент, результаты, вывод."}'::jsonb),
  ('science.scientific-method.l1.p2', 'science.scientific-method.l1', 'single', '{"id":"science.scientific-method.l1.p2","type":"single","prompt":{"en":"What is a hypothesis?","ru":"Что такое гипотеза?"},"options":[{"en":"A guess that can be tested","ru":"Предположение, которое можно проверить"},{"en":"The final proven answer","ru":"Окончательный доказанный ответ"},{"en":"A tool for measuring","ru":"Измерительный прибор"}],"answer":0,"hint":{"en":"It comes before the experiment.","ru":"Она появляется до эксперимента."},"explanation":{"en":"A hypothesis is a testable idea. The experiment shows if it is supported.","ru":"Гипотеза - это проверяемая идея. Эксперимент покажет, подтвердится ли она."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"A hypothesis is a testable idea. The experiment shows if it is supported.","ru":"Гипотеза - это проверяемая идея. Эксперимент покажет, подтвердится ли она."}'::jsonb),
  ('science.scientific-method.l1.p3', 'science.scientific-method.l1', 'true_false', '{"id":"science.scientific-method.l1.p3","type":"true_false","prompt":{"en":"In a fair test you change only one thing at a time.","ru":"В честном эксперименте меняют только одно условие за раз."},"answer":true,"hint":{"en":"If you change two things, can you tell which one made the difference?","ru":"Если поменять два условия, поймёшь ли ты, какое из них повлияло?"},"explanation":{"en":"Right! Changing one thing shows exactly what caused the result.","ru":"Верно! Когда меняется одно условие, ясно, что именно повлияло на результат."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Right! Changing one thing shows exactly what caused the result.","ru":"Верно! Когда меняется одно условие, ясно, что именно повлияло на результат."}'::jsonb),
  ('science.scientific-method.l1.c1', 'science.scientific-method.l1', 'matching', '{"id":"science.scientific-method.l1.c1","type":"matching","prompt":{"en":"Match each step with an example.","ru":"Соедини шаг с примером."},"pairs":[{"left":{"en":"Question","ru":"Вопрос"},"right":{"en":"Does salt help ice melt faster?","ru":"Помогает ли соль льду таять быстрее?"}},{"left":{"en":"Hypothesis","ru":"Гипотеза"},"right":{"en":"Ice with salt will melt faster.","ru":"Лёд с солью растает быстрее."}},{"left":{"en":"Experiment","ru":"Эксперимент"},"right":{"en":"Time two equal ice cubes, one with salt","ru":"Засечь время для двух одинаковых кубиков льда, один - с солью"}},{"left":{"en":"Conclusion","ru":"Вывод"},"right":{"en":"The salted cube melted first, so the idea was supported.","ru":"Кубик с солью растаял первым - гипотеза подтвердилась."}}],"explanation":{"en":"Each step builds on the one before it.","ru":"Каждый шаг опирается на предыдущий."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Each step builds on the one before it.","ru":"Каждый шаг опирается на предыдущий."}'::jsonb),
  ('science.scientific-method.l1.c2', 'science.scientific-method.l1', 'multiple', '{"id":"science.scientific-method.l1.c2","type":"multiple","prompt":{"en":"You test if light helps beans grow. What must stay the SAME in both pots? Choose all.","ru":"Ты проверяешь, помогает ли свет росту бобов. Что должно быть ОДИНАКОВЫМ в обоих горшках? Выбери всё."},"options":[{"en":"Amount of water","ru":"Количество воды"},{"en":"Type of soil","ru":"Вид почвы"},{"en":"Amount of light","ru":"Количество света"},{"en":"Type of seed","ru":"Сорт семян"}],"answers":[0,1,3],"explanation":{"en":"Light is the one thing we change. Water, soil and seeds stay the same.","ru":"Свет - единственное, что мы меняем. Вода, почва и семена остаются одинаковыми."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Light is the one thing we change. Water, soil and seeds stay the same.","ru":"Свет - единственное, что мы меняем. Вода, почва и семена остаются одинаковыми."}'::jsonb),
  ('science.scientific-method.l1.c3', 'science.scientific-method.l1', 'single', '{"id":"science.scientific-method.l1.c3","type":"single","prompt":{"en":"In the bean test, which thing are you changing?","ru":"Что ты меняешь в опыте с бобами?"},"options":[{"en":"Amount of water","ru":"Количество воды"},{"en":"Amount of light","ru":"Количество света"},{"en":"Colour of the pot","ru":"Цвет горшка"}],"answer":1,"explanation":{"en":"The light is the changed variable - the thing we test.","ru":"Свет - это изменяемая переменная, то, что мы проверяем."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"The light is the changed variable - the thing we test.","ru":"Свет - это изменяемая переменная, то, что мы проверяем."}'::jsonb),
  ('science.scientific-method.l1.c4', 'science.scientific-method.l1', 'fill_blank', '{"id":"science.scientific-method.l1.c4","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"A guess that can be tested is called a ___.","ru":"Предположение, которое можно проверить, называется ___."},"accepted":{"en":["hypothesis"],"ru":["гипотеза","гипотезой"]},"explanation":{"en":"A hypothesis is tested by an experiment.","ru":"Гипотезу проверяют с помощью эксперимента."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"A hypothesis is tested by an experiment.","ru":"Гипотезу проверяют с помощью эксперимента."}'::jsonb),
  ('science.scientific-method.l1.c5', 'science.scientific-method.l1', 'number_input', '{"id":"science.scientific-method.l1.c5","type":"number_input","prompt":{"en":"A virtual bean plant was 4 cm tall on Monday and 10 cm tall on Friday. How many centimetres did it grow?","ru":"В понедельник виртуальный боб был высотой 4 см, а в пятницу - 10 см. На сколько сантиметров он вырос?"},"answer":6,"unit":{"en":"cm","ru":"см"},"explanation":{"en":"10 - 4 = 6 cm. Recording numbers helps us compare results.","ru":"10 - 4 = 6 см. Записанные числа помогают сравнивать результаты."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"10 - 4 = 6 cm. Recording numbers helps us compare results.","ru":"10 - 4 = 6 см. Записанные числа помогают сравнивать результаты."}'::jsonb),
  ('science.states-of-matter.l1.p1', 'science.states-of-matter.l1', 'drag_drop', '{"id":"science.states-of-matter.l1.p1","type":"drag_drop","prompt":{"en":"Sort into solid, liquid or gas.","ru":"Распредели: твёрдое, жидкость или газ."},"items":[{"id":"ice","label":{"en":"🧊 Ice cube","ru":"🧊 Кубик льда"}},{"id":"rock","label":{"en":"🪨 Rock","ru":"🪨 Камень"}},{"id":"milk","label":{"en":"🥛 Milk","ru":"🥛 Молоко"}},{"id":"juice","label":{"en":"🧃 Juice","ru":"🧃 Сок"}},{"id":"steam","label":{"en":"♨️ Water vapour","ru":"♨️ Водяной пар"}},{"id":"air","label":{"en":"🎈 Air in a balloon","ru":"🎈 Воздух в шарике"}}],"buckets":[{"id":"solid","label":{"en":"Solid","ru":"Твёрдое"}},{"id":"liquid","label":{"en":"Liquid","ru":"Жидкость"}},{"id":"gas","label":{"en":"Gas","ru":"Газ"}}],"answer":{"ice":"solid","rock":"solid","milk":"liquid","juice":"liquid","steam":"gas","air":"gas"},"hint":{"en":"Does it keep its shape, flow, or spread out everywhere?","ru":"Сохраняет форму, течёт или разлетается во все стороны?"},"explanation":{"en":"Ice and rock keep their shape, milk and juice flow, vapour and air spread out.","ru":"Лёд и камень держат форму, молоко и сок текут, пар и воздух заполняют всё пространство."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Ice and rock keep their shape, milk and juice flow, vapour and air spread out.","ru":"Лёд и камень держат форму, молоко и сок текут, пар и воздух заполняют всё пространство."}'::jsonb),
  ('science.states-of-matter.l1.p2', 'science.states-of-matter.l1', 'single', '{"id":"science.states-of-matter.l1.p2","type":"single","prompt":{"en":"What happens when ice melts?","ru":"Что происходит, когда лёд тает?"},"options":[{"en":"A solid becomes a liquid","ru":"Твёрдое становится жидким"},{"en":"A liquid becomes a gas","ru":"Жидкость становится газом"},{"en":"A gas becomes a solid","ru":"Газ становится твёрдым"}],"answer":0,"hint":{"en":"Ice is solid; melted ice is water.","ru":"Лёд - твёрдый, а растаявший лёд - это вода."},"explanation":{"en":"Melting turns a solid into a liquid.","ru":"При плавлении твёрдое вещество становится жидким."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Melting turns a solid into a liquid.","ru":"При плавлении твёрдое вещество становится жидким."}'::jsonb),
  ('science.states-of-matter.l1.p3', 'science.states-of-matter.l1', 'true_false', '{"id":"science.states-of-matter.l1.p3","type":"true_false","prompt":{"en":"A liquid takes the shape of its container.","ru":"Жидкость принимает форму сосуда."},"answer":true,"hint":{"en":"Pour virtual juice into a round glass, then a square box.","ru":"Перелей виртуальный сок из круглого стакана в квадратную коробку."},"explanation":{"en":"Yes! A liquid flows to fit its container but its volume stays the same.","ru":"Да! Жидкость растекается по форме сосуда, а её объём не меняется."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Yes! A liquid flows to fit its container but its volume stays the same.","ru":"Да! Жидкость растекается по форме сосуда, а её объём не меняется."}'::jsonb),
  ('science.states-of-matter.l1.c1', 'science.states-of-matter.l1', 'matching', '{"id":"science.states-of-matter.l1.c1","type":"matching","prompt":{"en":"Match each change with what happens.","ru":"Соедини название перехода с тем, что происходит."},"pairs":[{"left":{"en":"Melting","ru":"Плавление"},"right":{"en":"Solid → liquid","ru":"Твёрдое → жидкость"}},{"left":{"en":"Freezing","ru":"Замерзание"},"right":{"en":"Liquid → solid","ru":"Жидкость → твёрдое"}},{"left":{"en":"Evaporation","ru":"Испарение"},"right":{"en":"Liquid → gas","ru":"Жидкость → газ"}},{"left":{"en":"Condensation","ru":"Конденсация"},"right":{"en":"Gas → liquid","ru":"Газ → жидкость"}}],"explanation":{"en":"Heating melts and evaporates; cooling condenses and freezes.","ru":"При нагревании - плавление и испарение, при охлаждении - конденсация и замерзание."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Heating melts and evaporates; cooling condenses and freezes.","ru":"При нагревании - плавление и испарение, при охлаждении - конденсация и замерзание."}'::jsonb),
  ('science.states-of-matter.l1.c2', 'science.states-of-matter.l1', 'number_input', '{"id":"science.states-of-matter.l1.c2","type":"number_input","prompt":{"en":"At what temperature does pure water boil at normal air pressure?","ru":"При какой температуре кипит чистая вода при обычном давлении?"},"answer":100,"unit":{"en":"°C","ru":"°C"},"explanation":{"en":"Water boils at 100 °C (and freezes at 0 °C).","ru":"Вода кипит при 100 °C (а замерзает при 0 °C)."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Water boils at 100 °C (and freezes at 0 °C).","ru":"Вода кипит при 100 °C (а замерзает при 0 °C)."}'::jsonb),
  ('science.states-of-matter.l1.c3', 'science.states-of-matter.l1', 'ordering', '{"id":"science.states-of-matter.l1.c3","type":"ordering","prompt":{"en":"In the virtual lab we slowly heat an ice cube. Put the states in order.","ru":"В виртуальной лаборатории мы медленно нагреваем кубик льда. Расставь состояния по порядку."},"items":[{"en":"Ice (solid)","ru":"Лёд (твёрдое)"},{"en":"Water (liquid)","ru":"Вода (жидкость)"},{"en":"Water vapour (gas)","ru":"Водяной пар (газ)"}],"explanation":{"en":"Ice melts into water, then water evaporates into vapour.","ru":"Лёд тает и становится водой, а вода испаряется и становится паром."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Ice melts into water, then water evaporates into vapour.","ru":"Лёд тает и становится водой, а вода испаряется и становится паром."}'::jsonb),
  ('science.states-of-matter.l1.c4', 'science.states-of-matter.l1', 'multiple', '{"id":"science.states-of-matter.l1.c4","type":"multiple","prompt":{"en":"Which are true about gases? Choose all.","ru":"Что верно про газы? Выбери всё."},"options":[{"en":"They spread out to fill a container","ru":"Они заполняют весь сосуд"},{"en":"They keep a fixed shape","ru":"Они сохраняют постоянную форму"},{"en":"They can be squeezed into less space","ru":"Их можно сжать"},{"en":"Their particles are far apart","ru":"Их частицы находятся далеко друг от друга"}],"answers":[0,2,3],"explanation":{"en":"Gas particles are far apart and move freely, so gases spread out and can be squeezed.","ru":"Частицы газа далеко друг от друга и свободно двигаются, поэтому газ заполняет сосуд и сжимается."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Gas particles are far apart and move freely, so gases spread out and can be squeezed.","ru":"Частицы газа далеко друг от друга и свободно двигаются, поэтому газ заполняет сосуд и сжимается."}'::jsonb),
  ('science.states-of-matter.l1.c5', 'science.states-of-matter.l1', 'fill_blank', '{"id":"science.states-of-matter.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"When liquid water turns into ice, we call it ___.","ru":"Превращение жидкой воды в лёд называется ___."},"accepted":{"en":["freezing","solidification"],"ru":["замерзание","замерзанием","кристаллизация","кристаллизацией","отвердевание"]},"explanation":{"en":"Freezing: a liquid cools down and becomes a solid.","ru":"Замерзание: жидкость остывает и становится твёрдой."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Freezing: a liquid cools down and becomes a solid.","ru":"Замерзание: жидкость остывает и становится твёрдой."}'::jsonb),
  ('science.ecosystems.l1.p1', 'science.ecosystems.l1', 'ordering', '{"id":"science.ecosystems.l1.p1","type":"ordering","prompt":{"en":"Build the food chain, starting with the producer.","ru":"Составь пищевую цепь, начиная с производителя."},"items":[{"en":"Grass","ru":"Трава"},{"en":"Grasshopper","ru":"Кузнечик"},{"en":"Frog","ru":"Лягушка"},{"en":"Snake","ru":"Змея"}],"hint":{"en":"Which one makes food from sunlight?","ru":"Кто создаёт пищу из солнечного света?"},"explanation":{"en":"Grass → grasshopper → frog → snake. Energy passes along the chain.","ru":"Трава → кузнечик → лягушка → змея. Энергия передаётся по цепи."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Grass → grasshopper → frog → snake. Energy passes along the chain.","ru":"Трава → кузнечик → лягушка → змея. Энергия передаётся по цепи."}'::jsonb),
  ('science.ecosystems.l1.p2', 'science.ecosystems.l1', 'single', '{"id":"science.ecosystems.l1.p2","type":"single","prompt":{"en":"Which one is a producer?","ru":"Кто из них производитель?"},"options":[{"en":"Oak tree","ru":"Дуб"},{"en":"Owl","ru":"Сова"},{"en":"Mushroom","ru":"Гриб"}],"answer":0,"hint":{"en":"Producers use sunlight to make food.","ru":"Производители создают пищу с помощью солнечного света."},"explanation":{"en":"An oak tree makes food by photosynthesis. A mushroom is a decomposer, an owl is a consumer.","ru":"Дуб создаёт пищу путём фотосинтеза. Гриб - разлагатель, сова - потребитель."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"An oak tree makes food by photosynthesis. A mushroom is a decomposer, an owl is a consumer.","ru":"Дуб создаёт пищу путём фотосинтеза. Гриб - разлагатель, сова - потребитель."}'::jsonb),
  ('science.ecosystems.l1.p3', 'science.ecosystems.l1', 'drag_drop', '{"id":"science.ecosystems.l1.p3","type":"drag_drop","prompt":{"en":"Sort the animals by what they eat.","ru":"Распредели животных по тому, чем они питаются."},"items":[{"id":"cow","label":{"en":"🐄 Cow","ru":"🐄 Корова"}},{"id":"rabbit","label":{"en":"🐰 Rabbit","ru":"🐰 Кролик"}},{"id":"lion","label":{"en":"🦁 Lion","ru":"🦁 Лев"}},{"id":"wolf","label":{"en":"🐺 Wolf","ru":"🐺 Волк"}},{"id":"bear","label":{"en":"🐻 Brown bear","ru":"🐻 Бурый медведь"}},{"id":"raccoon","label":{"en":"🦝 Raccoon","ru":"🦝 Енот"}}],"buckets":[{"id":"herb","label":{"en":"Herbivore","ru":"Травоядное"}},{"id":"carn","label":{"en":"Carnivore","ru":"Хищник"}},{"id":"omni","label":{"en":"Omnivore","ru":"Всеядное"}}],"answer":{"cow":"herb","rabbit":"herb","lion":"carn","wolf":"carn","bear":"omni","raccoon":"omni"},"hint":{"en":"Bears eat berries and fish. Raccoons eat almost anything!","ru":"Медведи едят ягоды и рыбу. Еноты едят почти всё!"},"explanation":{"en":"Cows and rabbits eat plants, lions and wolves eat meat, bears and raccoons eat both.","ru":"Коровы и кролики едят растения, львы и волки - мясо, медведи и еноты - и то и другое."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Cows and rabbits eat plants, lions and wolves eat meat, bears and raccoons eat both.","ru":"Коровы и кролики едят растения, львы и волки - мясо, медведи и еноты - и то и другое."}'::jsonb),
  ('science.ecosystems.l1.c1', 'science.ecosystems.l1', 'matching', '{"id":"science.ecosystems.l1.c1","type":"matching","prompt":{"en":"Match each role with its meaning.","ru":"Соедини роль с её описанием."},"pairs":[{"left":{"en":"Producer","ru":"Производитель"},"right":{"en":"Makes food from sunlight","ru":"Создаёт пищу из солнечного света"}},{"left":{"en":"Consumer","ru":"Потребитель"},"right":{"en":"Eats other living things","ru":"Питается другими организмами"}},{"left":{"en":"Decomposer","ru":"Разлагатель"},"right":{"en":"Breaks down dead material","ru":"Разлагает мёртвые остатки"}},{"left":{"en":"Herbivore","ru":"Травоядное"},"right":{"en":"Eats only plants","ru":"Ест только растения"}}],"explanation":{"en":"Together these roles keep an ecosystem working.","ru":"Вместе эти роли поддерживают работу экосистемы."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Together these roles keep an ecosystem working.","ru":"Вместе эти роли поддерживают работу экосистемы."}'::jsonb),
  ('science.ecosystems.l1.c2', 'science.ecosystems.l1', 'multiple', '{"id":"science.ecosystems.l1.c2","type":"multiple","prompt":{"en":"Which are decomposers? Choose all.","ru":"Кто из них разлагатели? Выбери всех."},"options":[{"en":"Mushrooms","ru":"Грибы"},{"en":"Earthworms","ru":"Дождевые черви"},{"en":"Bacteria","ru":"Бактерии"},{"en":"Eagles","ru":"Орлы"}],"answers":[0,1,2],"explanation":{"en":"Fungi, worms and bacteria recycle dead material. Eagles are consumers.","ru":"Грибы, черви и бактерии перерабатывают мёртвые остатки. Орлы - потребители."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Fungi, worms and bacteria recycle dead material. Eagles are consumers.","ru":"Грибы, черви и бактерии перерабатывают мёртвые остатки. Орлы - потребители."}'::jsonb),
  ('science.ecosystems.l1.c3', 'science.ecosystems.l1', 'true_false', '{"id":"science.ecosystems.l1.c3","type":"true_false","prompt":{"en":"In a food chain, the arrows show which way energy flows.","ru":"В пищевой цепи стрелки показывают направление передачи энергии."},"answer":true,"explanation":{"en":"Yes! Grass → rabbit means energy goes from the grass into the rabbit.","ru":"Да! Трава → заяц означает, что энергия переходит от травы к зайцу."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Yes! Grass → rabbit means energy goes from the grass into the rabbit.","ru":"Да! Трава → заяц означает, что энергия переходит от травы к зайцу."}'::jsonb),
  ('science.ecosystems.l1.c4', 'science.ecosystems.l1', 'single', '{"id":"science.ecosystems.l1.c4","type":"single","prompt":{"en":"In the chain grass → rabbit → fox, what happens if the rabbits disappear?","ru":"Что будет в цепи трава → заяц → лиса, если исчезнут зайцы?"},"options":[{"en":"Foxes have less food","ru":"Лисам станет не хватать еды"},{"en":"The grass disappears too","ru":"Трава тоже исчезнет"},{"en":"Nothing changes","ru":"Ничего не изменится"}],"answer":0,"explanation":{"en":"Foxes lose their food, and the grass may grow more because nobody eats it. Every link matters!","ru":"Лисы лишатся пищи, а травы может стать больше, ведь её никто не ест. Важно каждое звено!"},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Foxes lose their food, and the grass may grow more because nobody eats it. Every link matters!","ru":"Лисы лишатся пищи, а травы может стать больше, ведь её никто не ест. Важно каждое звено!"}'::jsonb),
  ('science.ecosystems.l1.c5', 'science.ecosystems.l1', 'fill_blank', '{"id":"science.ecosystems.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"Plants make their own food from sunlight by ___.","ru":"Растения создают себе пищу из солнечного света путём ___."},"accepted":{"en":["photosynthesis"],"ru":["фотосинтеза","фотосинтез"]},"explanation":{"en":"Photosynthesis uses light, water and carbon dioxide to make sugar and oxygen.","ru":"При фотосинтезе из света, воды и углекислого газа образуются сахар и кислород."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Photosynthesis uses light, water and carbon dioxide to make sugar and oxygen.","ru":"При фотосинтезе из света, воды и углекислого газа образуются сахар и кислород."}'::jsonb),
  ('science.cells.l1.p1', 'science.cells.l1', 'matching', '{"id":"science.cells.l1.p1","type":"matching","prompt":{"en":"Match each cell part with its job.","ru":"Соедини часть клетки с её функцией."},"pairs":[{"left":{"en":"Nucleus","ru":"Ядро"},"right":{"en":"Holds DNA and controls the cell","ru":"Хранит ДНК и управляет клеткой"}},{"left":{"en":"Cell membrane","ru":"Клеточная мембрана"},"right":{"en":"Controls what enters and leaves","ru":"Контролирует, что входит и выходит"}},{"left":{"en":"Mitochondria","ru":"Митохондрии"},"right":{"en":"Release energy from food","ru":"Высвобождают энергию из пищи"}},{"left":{"en":"Chloroplast","ru":"Хлоропласт"},"right":{"en":"Carries out photosynthesis","ru":"Осуществляет фотосинтез"}}],"hint":{"en":"\"Chloro-\" means green - like leaves.","ru":"«Хлоро-» значит «зелёный» - как листья."},"explanation":{"en":"Each part has a special job, like workers in a factory.","ru":"У каждой части своя работа, как у работников на фабрике."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Each part has a special job, like workers in a factory.","ru":"У каждой части своя работа, как у работников на фабрике."}'::jsonb),
  ('science.cells.l1.p2', 'science.cells.l1', 'true_false', '{"id":"science.cells.l1.p2","type":"true_false","prompt":{"en":"Animal cells have a cell wall.","ru":"У животных клеток есть клеточная стенка."},"answer":false,"hint":{"en":"The cell wall makes plants stiff.","ru":"Клеточная стенка делает растения прочными."},"explanation":{"en":"Only plant cells (and fungi and bacteria) have a cell wall. Animal cells have just a membrane.","ru":"Клеточная стенка есть только у растений (а также у грибов и бактерий). У животных клеток - только мембрана."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Only plant cells (and fungi and bacteria) have a cell wall. Animal cells have just a membrane.","ru":"Клеточная стенка есть только у растений (а также у грибов и бактерий). У животных клеток - только мембрана."}'::jsonb),
  ('science.cells.l1.p3', 'science.cells.l1', 'single', '{"id":"science.cells.l1.p3","type":"single","prompt":{"en":"Which tool do we use to see cells?","ru":"С помощью какого прибора рассматривают клетки?"},"options":[{"en":"Microscope","ru":"Микроскоп"},{"en":"Telescope","ru":"Телескоп"},{"en":"Thermometer","ru":"Термометр"}],"answer":0,"hint":{"en":"\"Micro\" means very small.","ru":"«Микро» значит «очень маленький»."},"explanation":{"en":"A microscope magnifies tiny things. A telescope is for faraway things.","ru":"Микроскоп увеличивает крошечные объекты. Телескоп - для далёких."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"A microscope magnifies tiny things. A telescope is for faraway things.","ru":"Микроскоп увеличивает крошечные объекты. Телескоп - для далёких."}'::jsonb),
  ('science.cells.l1.c1', 'science.cells.l1', 'drag_drop', '{"id":"science.cells.l1.c1","type":"drag_drop","prompt":{"en":"Which parts are found only in plant cells, and which in both plant and animal cells?","ru":"Какие части есть только в растительных клетках, а какие - и в растительных, и в животных?"},"items":[{"id":"wall","label":{"en":"Cell wall","ru":"Клеточная стенка"}},{"id":"chloro","label":{"en":"Chloroplasts","ru":"Хлоропласты"}},{"id":"nucleus","label":{"en":"Nucleus","ru":"Ядро"}},{"id":"membrane","label":{"en":"Cell membrane","ru":"Клеточная мембрана"}},{"id":"mito","label":{"en":"Mitochondria","ru":"Митохондрии"}}],"buckets":[{"id":"plant","label":{"en":"Only plant cells","ru":"Только растительные"}},{"id":"both","label":{"en":"Both","ru":"Обе"}}],"answer":{"wall":"plant","chloro":"plant","nucleus":"both","membrane":"both","mito":"both"},"explanation":{"en":"Plants need a cell wall and chloroplasts; nucleus, membrane and mitochondria are in both.","ru":"Растениям нужны клеточная стенка и хлоропласты; ядро, мембрана и митохондрии есть в обеих клетках."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Plants need a cell wall and chloroplasts; nucleus, membrane and mitochondria are in both.","ru":"Растениям нужны клеточная стенка и хлоропласты; ядро, мембрана и митохондрии есть в обеих клетках."}'::jsonb),
  ('science.cells.l1.c2', 'science.cells.l1', 'multiple', '{"id":"science.cells.l1.c2","type":"multiple","prompt":{"en":"Which of these are made of cells? Choose all.","ru":"Что из этого состоит из клеток? Выбери всё."},"options":[{"en":"A tree","ru":"Дерево"},{"en":"A mushroom","ru":"Гриб"},{"en":"A stone","ru":"Камень"},{"en":"A person","ru":"Человек"}],"answers":[0,1,3],"explanation":{"en":"Trees, mushrooms and people are living, so they are made of cells. A stone is not alive.","ru":"Дерево, гриб и человек - живые, значит, состоят из клеток. Камень неживой."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Trees, mushrooms and people are living, so they are made of cells. A stone is not alive.","ru":"Дерево, гриб и человек - живые, значит, состоят из клеток. Камень неживой."}'::jsonb),
  ('science.cells.l1.c3', 'science.cells.l1', 'fill_blank', '{"id":"science.cells.l1.c3","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"The cell''s DNA is kept in the ___.","ru":"ДНК клетки хранится в ___."},"accepted":{"en":["nucleus"],"ru":["ядре","ядро"]},"explanation":{"en":"The nucleus is the control centre and stores the DNA.","ru":"Ядро - центр управления клетки, в нём хранится ДНК."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"The nucleus is the control centre and stores the DNA.","ru":"Ядро - центр управления клетки, в нём хранится ДНК."}'::jsonb),
  ('science.cells.l1.c4', 'science.cells.l1', 'ordering', '{"id":"science.cells.l1.c4","type":"ordering","prompt":{"en":"Order from smallest to largest.","ru":"Расставь от меньшего к большему."},"items":[{"en":"Cell","ru":"Клетка"},{"en":"Tissue","ru":"Ткань"},{"en":"Organ","ru":"Орган"},{"en":"Organ system","ru":"Система органов"},{"en":"Organism","ru":"Организм"}],"explanation":{"en":"Cells → tissues → organs → organ systems → organism.","ru":"Клетки → ткани → органы → системы органов → организм."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Cells → tissues → organs → organ systems → organism.","ru":"Клетки → ткани → органы → системы органов → организм."}'::jsonb),
  ('science.cells.l1.c5', 'science.cells.l1', 'image_selection', '{"id":"science.cells.l1.c5","type":"image_selection","prompt":{"en":"Which living thing is made of just one cell?","ru":"Какой организм состоит всего из одной клетки?"},"options":[{"emoji":"🦠","label":{"en":"Bacterium","ru":"Бактерия"}},{"emoji":"🐘","label":{"en":"Elephant","ru":"Слон"}},{"emoji":"🌳","label":{"en":"Tree","ru":"Дерево"}}],"answer":0,"explanation":{"en":"A bacterium is a single cell that does everything it needs to live.","ru":"Бактерия - это одна клетка, которая сама выполняет всё, что нужно для жизни."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"A bacterium is a single cell that does everything it needs to live.","ru":"Бактерия - это одна клетка, которая сама выполняет всё, что нужно для жизни."}'::jsonb),
  ('science.energy.l1.p1', 'science.energy.l1', 'drag_drop', '{"id":"science.energy.l1.p1","type":"drag_drop","prompt":{"en":"In the virtual lab, sort the materials: conductor or insulator?","ru":"В виртуальной лаборатории распредели материалы: проводник или изолятор?"},"items":[{"id":"copper","label":{"en":"Copper wire","ru":"Медная проволока"}},{"id":"nail","label":{"en":"Iron nail","ru":"Железный гвоздь"}},{"id":"foil","label":{"en":"Aluminium foil","ru":"Алюминиевая фольга"}},{"id":"ruler","label":{"en":"Plastic ruler","ru":"Пластиковая линейка"}},{"id":"rubber","label":{"en":"Rubber band","ru":"Резинка"}},{"id":"spoon","label":{"en":"Wooden spoon","ru":"Деревянная ложка"}}],"buckets":[{"id":"cond","label":{"en":"Conductor","ru":"Проводник"}},{"id":"ins","label":{"en":"Insulator","ru":"Изолятор"}}],"answer":{"copper":"cond","nail":"cond","foil":"cond","ruler":"ins","rubber":"ins","spoon":"ins"},"hint":{"en":"Metals are usually good conductors.","ru":"Металлы обычно хорошие проводники."},"explanation":{"en":"Copper, iron and aluminium are metals, so they conduct. Plastic, rubber and dry wood are insulators.","ru":"Медь, железо и алюминий - металлы, они проводят ток. Пластик, резина и сухое дерево - изоляторы."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Copper, iron and aluminium are metals, so they conduct. Plastic, rubber and dry wood are insulators.","ru":"Медь, железо и алюминий - металлы, они проводят ток. Пластик, резина и сухое дерево - изоляторы."}'::jsonb),
  ('science.energy.l1.p2', 'science.energy.l1', 'single', '{"id":"science.energy.l1.p2","type":"single","prompt":{"en":"A battery, wires and a bulb form a closed loop. What does the bulb do?","ru":"Батарейка, провода и лампочка образуют замкнутую цепь. Что происходит с лампочкой?"},"options":[{"en":"It lights up","ru":"Она загорается"},{"en":"It stays dark","ru":"Она не горит"},{"en":"It turns into a battery","ru":"Она превращается в батарейку"}],"answer":0,"hint":{"en":"Electricity needs a complete path.","ru":"Току нужен замкнутый путь."},"explanation":{"en":"In a closed circuit, current flows through the bulb and it lights up.","ru":"В замкнутой цепи ток проходит через лампочку, и она светится."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"In a closed circuit, current flows through the bulb and it lights up.","ru":"В замкнутой цепи ток проходит через лампочку, и она светится."}'::jsonb),
  ('science.energy.l1.p3', 'science.energy.l1', 'true_false', '{"id":"science.energy.l1.p3","type":"true_false","prompt":{"en":"A switch opens and closes a circuit.","ru":"Выключатель размыкает и замыкает цепь."},"answer":true,"hint":{"en":"What happens to the light when you press a switch?","ru":"Что происходит со светом, когда нажимаешь на выключатель?"},"explanation":{"en":"Yes! A closed switch completes the loop; an open switch breaks it.","ru":"Да! Замкнутый выключатель замыкает контур, а разомкнутый - разрывает его."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Yes! A closed switch completes the loop; an open switch breaks it.","ru":"Да! Замкнутый выключатель замыкает контур, а разомкнутый - разрывает его."}'::jsonb),
  ('science.energy.l1.c1', 'science.energy.l1', 'matching', '{"id":"science.energy.l1.c1","type":"matching","prompt":{"en":"Match each device with its main energy change.","ru":"Соедини устройство с главным превращением энергии."},"pairs":[{"left":{"en":"Light bulb","ru":"Лампочка"},"right":{"en":"Electrical → light","ru":"Электрическая → световая"}},{"left":{"en":"Solar panel","ru":"Солнечная панель"},"right":{"en":"Light → electrical","ru":"Световая → электрическая"}},{"left":{"en":"Loudspeaker","ru":"Динамик"},"right":{"en":"Electrical → sound","ru":"Электрическая → звуковая"}},{"left":{"en":"Battery in use","ru":"Работающая батарейка"},"right":{"en":"Chemical → electrical","ru":"Химическая → электрическая"}}],"explanation":{"en":"Devices are energy changers: they turn one form into another.","ru":"Устройства - преобразователи энергии: они превращают один её вид в другой."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Devices are energy changers: they turn one form into another.","ru":"Устройства - преобразователи энергии: они превращают один её вид в другой."}'::jsonb),
  ('science.energy.l1.c2', 'science.energy.l1', 'multiple', '{"id":"science.energy.l1.c2","type":"multiple","prompt":{"en":"Which of these are forms of energy? Choose all.","ru":"Что из этого - виды энергии? Выбери всё."},"options":[{"en":"Light","ru":"Свет"},{"en":"Sound","ru":"Звук"},{"en":"Heat","ru":"Тепло"},{"en":"Cardboard","ru":"Картон"}],"answers":[0,1,2],"explanation":{"en":"Light, sound and heat are forms of energy. Cardboard is a material.","ru":"Свет, звук и тепло - виды энергии. Картон - это материал."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Light, sound and heat are forms of energy. Cardboard is a material.","ru":"Свет, звук и тепло - виды энергии. Картон - это материал."}'::jsonb),
  ('science.energy.l1.c3', 'science.energy.l1', 'true_false', '{"id":"science.energy.l1.c3","type":"true_false","prompt":{"en":"Energy can be created out of nothing.","ru":"Энергию можно создать из ничего."},"answer":false,"explanation":{"en":"Energy cannot be created or destroyed - it only changes from one form to another.","ru":"Энергию нельзя создать или уничтожить - она только переходит из одного вида в другой."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Energy cannot be created or destroyed - it only changes from one form to another.","ru":"Энергию нельзя создать или уничтожить - она только переходит из одного вида в другой."}'::jsonb),
  ('science.energy.l1.c4', 'science.energy.l1', 'ordering', '{"id":"science.energy.l1.c4","type":"ordering","prompt":{"en":"Put the energy changes in a torch in order.","ru":"Расставь по порядку превращения энергии в фонарике."},"items":[{"en":"Chemical energy in the battery","ru":"Химическая энергия в батарейке"},{"en":"Electrical energy in the wires","ru":"Электрическая энергия в проводах"},{"en":"Light and heat from the bulb","ru":"Свет и тепло от лампочки"}],"explanation":{"en":"Chemical → electrical → light (and a little heat).","ru":"Химическая → электрическая → световая (и немного тепловой)."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Chemical → electrical → light (and a little heat).","ru":"Химическая → электрическая → световая (и немного тепловой)."}'::jsonb),
  ('science.energy.l1.c5', 'science.energy.l1', 'fill_blank', '{"id":"science.energy.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"Materials that let electricity flow easily are called ___.","ru":"Материалы, которые хорошо пропускают электрический ток, называются ___."},"accepted":{"en":["conductors","conductor"],"ru":["проводники","проводниками"]},"explanation":{"en":"Conductors, like metals, let current flow. Remember: test materials only in the virtual lab.","ru":"Проводники, например металлы, пропускают ток. Помни: проверяй материалы только в виртуальной лаборатории."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Conductors, like metals, let current flow. Remember: test materials only in the virtual lab.","ru":"Проводники, например металлы, пропускают ток. Помни: проверяй материалы только в виртуальной лаборатории."}'::jsonb),
  ('science.forces.l1.p1', 'science.forces.l1', 'number_input', '{"id":"science.forces.l1.p1","type":"number_input","prompt":{"en":"A 2 kg cart speeds up at 3 m/s². What force acts on it? (F = m × a)","ru":"Тележка массой 2 кг разгоняется с ускорением 3 м/с². Какая сила на неё действует? (F = m × a)"},"answer":6,"unit":{"en":"N","ru":"Н"},"hint":{"en":"Multiply mass by acceleration.","ru":"Умножь массу на ускорение."},"explanation":{"en":"F = 2 × 3 = 6 N.","ru":"F = 2 × 3 = 6 Н."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"F = 2 × 3 = 6 N.","ru":"F = 2 × 3 = 6 Н."}'::jsonb),
  ('science.forces.l1.p2', 'science.forces.l1', 'single', '{"id":"science.forces.l1.p2","type":"single","prompt":{"en":"Which force slows down a book sliding across a table?","ru":"Какая сила замедляет книгу, скользящую по столу?"},"options":[{"en":"Friction","ru":"Трение"},{"en":"Magnetism","ru":"Магнетизм"},{"en":"Buoyancy","ru":"Выталкивающая сила"}],"answer":0,"hint":{"en":"It acts where two surfaces rub together.","ru":"Она возникает, когда поверхности трутся друг о друга."},"explanation":{"en":"Friction between the book and the table slows it down.","ru":"Трение между книгой и столом замедляет её."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Friction between the book and the table slows it down.","ru":"Трение между книгой и столом замедляет её."}'::jsonb),
  ('science.forces.l1.p3', 'science.forces.l1', 'true_false', '{"id":"science.forces.l1.p3","type":"true_false","prompt":{"en":"If the forces on an object are balanced, its motion does not change.","ru":"Если силы, действующие на тело, уравновешены, его движение не меняется."},"answer":true,"hint":{"en":"Think of Newton''s first law.","ru":"Вспомни первый закон Ньютона."},"explanation":{"en":"Balanced forces mean no change: still things stay still, moving things keep moving steadily.","ru":"Уравновешенные силы ничего не меняют: покоящееся тело покоится, движущееся - движется равномерно."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Balanced forces mean no change: still things stay still, moving things keep moving steadily.","ru":"Уравновешенные силы ничего не меняют: покоящееся тело покоится, движущееся - движется равномерно."}'::jsonb),
  ('science.forces.l1.c1', 'science.forces.l1', 'matching', '{"id":"science.forces.l1.c1","type":"matching","prompt":{"en":"Match each idea with its description.","ru":"Соедини понятие с его описанием."},"pairs":[{"left":{"en":"Newton''s 1st law","ru":"1-й закон Ньютона"},"right":{"en":"No unbalanced force - no change in motion","ru":"Нет неуравновешенной силы - нет изменения движения"}},{"left":{"en":"Newton''s 2nd law","ru":"2-й закон Ньютона"},"right":{"en":"F = m × a","ru":"F = m × a"}},{"left":{"en":"Newton''s 3rd law","ru":"3-й закон Ньютона"},"right":{"en":"Equal and opposite reaction","ru":"Равное и противоположное противодействие"}},{"left":{"en":"Gravity","ru":"Сила тяжести"},"right":{"en":"Pulls objects toward Earth''s centre","ru":"Притягивает тела к центру Земли"}}],"explanation":{"en":"These ideas explain almost every motion around us.","ru":"Эти идеи объясняют почти любое движение вокруг нас."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"These ideas explain almost every motion around us.","ru":"Эти идеи объясняют почти любое движение вокруг нас."}'::jsonb),
  ('science.forces.l1.c2', 'science.forces.l1', 'number_input', '{"id":"science.forces.l1.c2","type":"number_input","prompt":{"en":"A 20 N push acts on a 4 kg box on ice (no friction). What is its acceleration?","ru":"На ящик массой 4 кг на льду (без трения) действует сила 20 Н. Каково его ускорение?"},"answer":5,"unit":{"en":"m/s²","ru":"м/с²"},"explanation":{"en":"a = F ÷ m = 20 ÷ 4 = 5 m/s².","ru":"a = F : m = 20 : 4 = 5 м/с²."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"a = F ÷ m = 20 ÷ 4 = 5 m/s².","ru":"a = F : m = 20 : 4 = 5 м/с²."}'::jsonb),
  ('science.forces.l1.c3', 'science.forces.l1', 'multiple', '{"id":"science.forces.l1.c3","type":"multiple","prompt":{"en":"Which of these reduce friction? Choose all.","ru":"Что из этого уменьшает трение? Выбери всё."},"options":[{"en":"Oil on moving parts","ru":"Смазка на движущихся деталях"},{"en":"Wheels and ball bearings","ru":"Колёса и подшипники"},{"en":"Smooth, polished surfaces","ru":"Гладкие, отполированные поверхности"},{"en":"Sandpaper","ru":"Наждачная бумага"}],"answers":[0,1,2],"explanation":{"en":"Oil, wheels and smooth surfaces reduce friction. Sandpaper increases it.","ru":"Смазка, колёса и гладкие поверхности уменьшают трение. Наждачная бумага его увеличивает."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Oil, wheels and smooth surfaces reduce friction. Sandpaper increases it.","ru":"Смазка, колёса и гладкие поверхности уменьшают трение. Наждачная бумага его увеличивает."}'::jsonb),
  ('science.forces.l1.c4', 'science.forces.l1', 'single', '{"id":"science.forces.l1.c4","type":"single","prompt":{"en":"A rocket pushes gas down and the gas pushes the rocket up. Which law is this?","ru":"Ракета толкает газы вниз, а газы толкают ракету вверх. Какой это закон?"},"options":[{"en":"Newton''s 1st law","ru":"1-й закон Ньютона"},{"en":"Newton''s 2nd law","ru":"2-й закон Ньютона"},{"en":"Newton''s 3rd law","ru":"3-й закон Ньютона"}],"answer":2,"explanation":{"en":"Action and reaction - Newton''s 3rd law.","ru":"Действие и противодействие - третий закон Ньютона."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Action and reaction - Newton''s 3rd law.","ru":"Действие и противодействие - третий закон Ньютона."}'::jsonb),
  ('science.forces.l1.c5', 'science.forces.l1', 'fill_blank', '{"id":"science.forces.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"Force is measured in ___.","ru":"Силу измеряют в ___."},"accepted":{"en":["newtons","newton","n"],"ru":["ньютонах","ньютоны","н"]},"explanation":{"en":"The unit of force is the newton (N), named after Isaac Newton.","ru":"Единица силы - ньютон (Н), названная в честь Исаака Ньютона."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"The unit of force is the newton (N), named after Isaac Newton.","ru":"Единица силы - ньютон (Н), названная в честь Исаака Ньютона."}'::jsonb),
  ('science.chemistry-basics.l1.p1', 'science.chemistry-basics.l1', 'number_input', '{"id":"science.chemistry-basics.l1.p1","type":"number_input","prompt":{"en":"How many atoms are in one H₂O molecule?","ru":"Сколько атомов в одной молекуле H₂O?"},"answer":3,"hint":{"en":"H₂ means two hydrogen atoms; O means one oxygen atom.","ru":"H₂ - два атома водорода, O - один атом кислорода."},"explanation":{"en":"2 hydrogen + 1 oxygen = 3 atoms.","ru":"2 атома водорода + 1 атом кислорода = 3 атома."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"2 hydrogen + 1 oxygen = 3 atoms.","ru":"2 атома водорода + 1 атом кислорода = 3 атома."}'::jsonb),
  ('science.chemistry-basics.l1.p2', 'science.chemistry-basics.l1', 'matching', '{"id":"science.chemistry-basics.l1.p2","type":"matching","prompt":{"en":"Match each particle with its description.","ru":"Соедини частицу с её описанием."},"pairs":[{"left":{"en":"Proton","ru":"Протон"},"right":{"en":"Positive charge, in the nucleus","ru":"Положительный заряд, в ядре"}},{"left":{"en":"Neutron","ru":"Нейтрон"},"right":{"en":"No charge, in the nucleus","ru":"Без заряда, в ядре"}},{"left":{"en":"Electron","ru":"Электрон"},"right":{"en":"Negative charge, moves around the nucleus","ru":"Отрицательный заряд, движется вокруг ядра"}}],"hint":{"en":"\"Neutral\" sounds like neutron.","ru":"«Нейтральный» похоже на «нейтрон»."},"explanation":{"en":"Protons (+) and neutrons (0) are in the nucleus; electrons (−) move around it.","ru":"Протоны (+) и нейтроны (0) - в ядре, электроны (−) движутся вокруг."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"Protons (+) and neutrons (0) are in the nucleus; electrons (−) move around it.","ru":"Протоны (+) и нейтроны (0) - в ядре, электроны (−) движутся вокруг."}'::jsonb),
  ('science.chemistry-basics.l1.p3', 'science.chemistry-basics.l1', 'drag_drop', '{"id":"science.chemistry-basics.l1.p3","type":"drag_drop","prompt":{"en":"Physical change or chemical change?","ru":"Физическое или химическое явление?"},"items":[{"id":"melt","label":{"en":"Ice melting","ru":"Таяние льда"}},{"id":"cut","label":{"en":"Cutting paper","ru":"Разрезание бумаги"}},{"id":"dissolve","label":{"en":"Sugar dissolving in tea","ru":"Растворение сахара в чае"}},{"id":"rust","label":{"en":"Iron rusting","ru":"Ржавление железа"}},{"id":"burn","label":{"en":"Wood burning","ru":"Горение дерева"}},{"id":"bake","label":{"en":"Baking a cake","ru":"Выпекание торта"}}],"buckets":[{"id":"phys","label":{"en":"Physical","ru":"Физическое"}},{"id":"chem","label":{"en":"Chemical","ru":"Химическое"}}],"answer":{"melt":"phys","cut":"phys","dissolve":"phys","rust":"chem","burn":"chem","bake":"chem"},"hint":{"en":"Is a new substance made?","ru":"Образуется ли новое вещество?"},"explanation":{"en":"Rust, ash and cake are new substances, so those are chemical changes.","ru":"Ржавчина, зола и торт - новые вещества, значит, это химические явления."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"Rust, ash and cake are new substances, so those are chemical changes.","ru":"Ржавчина, зола и торт - новые вещества, значит, это химические явления."}'::jsonb),
  ('science.chemistry-basics.l1.c1', 'science.chemistry-basics.l1', 'multiple', '{"id":"science.chemistry-basics.l1.c1","type":"multiple","prompt":{"en":"Which are signs of a chemical reaction? Choose all.","ru":"Какие признаки указывают на химическую реакцию? Выбери все."},"options":[{"en":"Gas bubbles appear","ru":"Появляются пузырьки газа"},{"en":"The colour changes","ru":"Меняется цвет"},{"en":"Heat or light is given off","ru":"Выделяется тепло или свет"},{"en":"A jar is moved to another shelf","ru":"Банку переставили на другую полку"}],"answers":[0,1,2],"explanation":{"en":"Bubbles, colour change and heat or light suggest new substances. Moving a jar changes nothing chemically.","ru":"Пузырьки, смена цвета, тепло или свет говорят о новых веществах. Перестановка банки ничего не меняет."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"Bubbles, colour change and heat or light suggest new substances. Moving a jar changes nothing chemically.","ru":"Пузырьки, смена цвета, тепло или свет говорят о новых веществах. Перестановка банки ничего не меняет."}'::jsonb),
  ('science.chemistry-basics.l1.c2', 'science.chemistry-basics.l1', 'single', '{"id":"science.chemistry-basics.l1.c2","type":"single","prompt":{"en":"Which of these is an element?","ru":"Что из этого - химический элемент?"},"options":[{"en":"Oxygen (O)","ru":"Кислород (O)"},{"en":"Water (H₂O)","ru":"Вода (H₂O)"},{"en":"Table salt (NaCl)","ru":"Поваренная соль (NaCl)"}],"answer":0,"explanation":{"en":"Oxygen has only one kind of atom. Water and salt are compounds of two elements.","ru":"Кислород состоит из атомов одного вида. Вода и соль - соединения двух элементов."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"Oxygen has only one kind of atom. Water and salt are compounds of two elements.","ru":"Кислород состоит из атомов одного вида. Вода и соль - соединения двух элементов."}'::jsonb),
  ('science.chemistry-basics.l1.c3', 'science.chemistry-basics.l1', 'true_false', '{"id":"science.chemistry-basics.l1.c3","type":"true_false","prompt":{"en":"In a chemical reaction, the total mass stays the same.","ru":"При химической реакции общая масса веществ не меняется."},"answer":true,"explanation":{"en":"Yes - the law of conservation of mass. Atoms are rearranged, not lost.","ru":"Да - закон сохранения массы. Атомы перегруппировываются, а не исчезают."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"Yes - the law of conservation of mass. Atoms are rearranged, not lost.","ru":"Да - закон сохранения массы. Атомы перегруппировываются, а не исчезают."}'::jsonb),
  ('science.chemistry-basics.l1.c4', 'science.chemistry-basics.l1', 'number_input', '{"id":"science.chemistry-basics.l1.c4","type":"number_input","prompt":{"en":"In 2H₂ + O₂ → 2H₂O, how many hydrogen atoms are on the left side?","ru":"Сколько атомов водорода в левой части уравнения 2H₂ + O₂ → 2H₂O?"},"answer":4,"visual":{"kind":"equation","text":"2H₂ + O₂ → 2H₂O"},"explanation":{"en":"2 molecules × 2 atoms = 4 hydrogen atoms - and there are 4 on the right too.","ru":"2 молекулы × 2 атома = 4 атома водорода - и справа их тоже 4."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"2 molecules × 2 atoms = 4 hydrogen atoms - and there are 4 on the right too.","ru":"2 молекулы × 2 атома = 4 атома водорода - и справа их тоже 4."}'::jsonb),
  ('science.chemistry-basics.l1.c5', 'science.chemistry-basics.l1', 'fill_blank', '{"id":"science.chemistry-basics.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"The smallest particle of a chemical element is called an ___.","ru":"Мельчайшая частица химического элемента называется ___."},"accepted":{"en":["atom"],"ru":["атом","атомом"]},"explanation":{"en":"Atoms are the building blocks of all matter.","ru":"Атомы - строительные блоки любого вещества."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"Atoms are the building blocks of all matter.","ru":"Атомы - строительные блоки любого вещества."}'::jsonb),
  ('science.genetics.l1.p1', 'science.genetics.l1', 'matching', '{"id":"science.genetics.l1.p1","type":"matching","prompt":{"en":"Match each term with its meaning.","ru":"Соедини термин с его значением."},"pairs":[{"left":{"en":"Gene","ru":"Ген"},"right":{"en":"A section of DNA that codes for a protein","ru":"Участок ДНК, кодирующий белок"}},{"left":{"en":"Allele","ru":"Аллель"},"right":{"en":"A version of a gene","ru":"Вариант гена"}},{"left":{"en":"Chromosome","ru":"Хромосома"},"right":{"en":"A long, packed DNA molecule","ru":"Длинная упакованная молекула ДНК"}},{"left":{"en":"Genotype","ru":"Генотип"},"right":{"en":"The alleles an organism has, e.g. Aa","ru":"Набор аллелей организма, например Aa"}}],"hint":{"en":"Think big to small: chromosome contains genes; genes come in alleles.","ru":"От большого к малому: хромосома содержит гены, гены бывают в разных аллелях."},"explanation":{"en":"Chromosomes carry genes, and each gene can have different alleles.","ru":"Хромосомы несут гены, а у каждого гена могут быть разные аллели."},"difficulty":5,"role":"practice"}'::jsonb, 5, '{"en":"Chromosomes carry genes, and each gene can have different alleles.","ru":"Хромосомы несут гены, а у каждого гена могут быть разные аллели."}'::jsonb),
  ('science.genetics.l1.p2', 'science.genetics.l1', 'number_input', '{"id":"science.genetics.l1.p2","type":"number_input","prompt":{"en":"How many chromosomes are in a typical human body cell?","ru":"Сколько хромосом в обычной клетке тела человека?"},"answer":46,"hint":{"en":"There are 23 pairs.","ru":"Их 23 пары."},"explanation":{"en":"23 pairs = 46 chromosomes. Egg and sperm cells have 23.","ru":"23 пары = 46 хромосом. В яйцеклетках и сперматозоидах - по 23."},"difficulty":5,"role":"practice"}'::jsonb, 5, '{"en":"23 pairs = 46 chromosomes. Egg and sperm cells have 23.","ru":"23 пары = 46 хромосом. В яйцеклетках и сперматозоидах - по 23."}'::jsonb),
  ('science.genetics.l1.p3', 'science.genetics.l1', 'single', '{"id":"science.genetics.l1.p3","type":"single","prompt":{"en":"In DNA, adenine (A) pairs with...","ru":"В ДНК аденин (A) соединяется с..."},"options":[{"en":"Thymine (T)","ru":"тимином (T)"},{"en":"Guanine (G)","ru":"гуанином (G)"},{"en":"Cytosine (C)","ru":"цитозином (C)"}],"answer":0,"hint":{"en":"The pairs are A-T and G-C.","ru":"Пары: A-T и G-C."},"explanation":{"en":"A pairs with T, and G pairs with C.","ru":"A соединяется с T, а G - с C."},"difficulty":5,"role":"practice"}'::jsonb, 5, '{"en":"A pairs with T, and G pairs with C.","ru":"A соединяется с T, а G - с C."}'::jsonb),
  ('science.genetics.l1.c1', 'science.genetics.l1', 'number_input', '{"id":"science.genetics.l1.c1","type":"number_input","prompt":{"en":"Two Aa parents have offspring. What percentage is expected to be aa?","ru":"У двух родителей Aa появляется потомство. Какой процент потомков ожидается с генотипом aa?"},"answer":25,"unit":{"en":"%","ru":"%"},"explanation":{"en":"The Punnett square has 4 boxes and one is aa: 1/4 = 25%.","ru":"В решётке 4 клетки, и одна из них aa: 1/4 = 25%."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"The Punnett square has 4 boxes and one is aa: 1/4 = 25%.","ru":"В решётке 4 клетки, и одна из них aa: 1/4 = 25%."}'::jsonb),
  ('science.genetics.l1.c2', 'science.genetics.l1', 'ordering', '{"id":"science.genetics.l1.c2","type":"ordering","prompt":{"en":"Put the steps of natural selection in order.","ru":"Расставь этапы естественного отбора по порядку."},"items":[{"en":"Individuals in a population vary","ru":"Особи в популяции различаются"},{"en":"Some variations help survival in the environment","ru":"Некоторые различия помогают выжить в этой среде"},{"en":"Those individuals survive and reproduce more","ru":"Такие особи чаще выживают и размножаются"},{"en":"They pass the helpful alleles to their offspring","ru":"Они передают полезные аллели потомству"},{"en":"Over many generations the trait becomes common","ru":"За много поколений признак становится распространённым"}],"explanation":{"en":"Variation → selection → reproduction → inheritance → change over generations.","ru":"Изменчивость → отбор → размножение → наследование → изменения через поколения."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Variation → selection → reproduction → inheritance → change over generations.","ru":"Изменчивость → отбор → размножение → наследование → изменения через поколения."}'::jsonb),
  ('science.genetics.l1.c3', 'science.genetics.l1', 'multiple', '{"id":"science.genetics.l1.c3","type":"multiple","prompt":{"en":"Which statements about mutations are true? Choose all.","ru":"Какие утверждения о мутациях верны? Выбери все."},"options":[{"en":"They are changes in the DNA sequence","ru":"Это изменения последовательности ДНК"},{"en":"They can be harmful, neutral or helpful","ru":"Они бывают вредными, нейтральными или полезными"},{"en":"They are a source of new variation","ru":"Они - источник новой изменчивости"},{"en":"They always make an organism stronger","ru":"Они всегда делают организм сильнее"}],"answers":[0,1,2],"explanation":{"en":"Most mutations are neutral, some harmful, a few helpful - not always good.","ru":"Большинство мутаций нейтральны, некоторые вредны, немногие полезны - не всегда к лучшему."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Most mutations are neutral, some harmful, a few helpful - not always good.","ru":"Большинство мутаций нейтральны, некоторые вредны, немногие полезны - не всегда к лучшему."}'::jsonb),
  ('science.genetics.l1.c4', 'science.genetics.l1', 'true_false', '{"id":"science.genetics.l1.c4","type":"true_false","prompt":{"en":"A single animal evolves during its own lifetime by trying hard.","ru":"Отдельное животное эволюционирует в течение жизни, если очень старается."},"answer":false,"explanation":{"en":"Populations evolve over many generations; one individual''s genes do not change by effort.","ru":"Эволюционируют популяции на протяжении многих поколений; гены отдельной особи от стараний не меняются."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Populations evolve over many generations; one individual''s genes do not change by effort.","ru":"Эволюционируют популяции на протяжении многих поколений; гены отдельной особи от стараний не меняются."}'::jsonb),
  ('science.genetics.l1.c5', 'science.genetics.l1', 'fill_blank', '{"id":"science.genetics.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"A section of DNA that carries the instructions for a protein is called a ___.","ru":"Участок ДНК, несущий информацию о белке, называется ___."},"accepted":{"en":["gene"],"ru":["ген","геном"]},"explanation":{"en":"Genes are the instructions; proteins do the work in cells.","ru":"Гены - это инструкции, а белки выполняют работу в клетках."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Genes are the instructions; proteins do the work in cells.","ru":"Гены - это инструкции, а белки выполняют работу в клетках."}'::jsonb),
  ('science.electromagnetism.l1.p1', 'science.electromagnetism.l1', 'single', '{"id":"science.electromagnetism.l1.p1","type":"single","prompt":{"en":"Two north poles are brought close together. They will...","ru":"Два северных полюса сближают. Они будут..."},"options":[{"en":"Repel","ru":"Отталкиваться"},{"en":"Attract","ru":"Притягиваться"},{"en":"Do nothing","ru":"Никак не взаимодействовать"}],"answer":0,"hint":{"en":"Like poles behave the same way as like charges.","ru":"Одноимённые полюсы ведут себя как одноимённые заряды."},"explanation":{"en":"Like poles repel, unlike poles attract.","ru":"Одноимённые полюсы отталкиваются, разноимённые - притягиваются."},"difficulty":5,"role":"practice"}'::jsonb, 5, '{"en":"Like poles repel, unlike poles attract.","ru":"Одноимённые полюсы отталкиваются, разноимённые - притягиваются."}'::jsonb),
  ('science.electromagnetism.l1.p2', 'science.electromagnetism.l1', 'multiple', '{"id":"science.electromagnetism.l1.p2","type":"multiple","prompt":{"en":"How can you make an electromagnet stronger? Choose all.","ru":"Как сделать электромагнит сильнее? Выбери все варианты."},"options":[{"en":"Add more turns of wire","ru":"Добавить витков провода"},{"en":"Increase the current","ru":"Увеличить силу тока"},{"en":"Use an iron core","ru":"Использовать железный сердечник"},{"en":"Use a plastic core","ru":"Использовать пластиковый сердечник"}],"answers":[0,1,2],"hint":{"en":"Plastic is not a magnetic material.","ru":"Пластик - немагнитный материал."},"explanation":{"en":"More turns, more current and an iron core all strengthen the field.","ru":"Больше витков, больший ток и железный сердечник усиливают поле."},"difficulty":5,"role":"practice"}'::jsonb, 5, '{"en":"More turns, more current and an iron core all strengthen the field.","ru":"Больше витков, больший ток и железный сердечник усиливают поле."}'::jsonb),
  ('science.electromagnetism.l1.p3', 'science.electromagnetism.l1', 'true_false', '{"id":"science.electromagnetism.l1.p3","type":"true_false","prompt":{"en":"An electric current in a wire creates a magnetic field around it.","ru":"Электрический ток в проводе создаёт вокруг него магнитное поле."},"answer":true,"hint":{"en":"Ørsted saw a compass needle move near a wire.","ru":"Эрстед увидел, как стрелка компаса отклоняется возле провода."},"explanation":{"en":"Yes - this is the basis of electromagnets and motors.","ru":"Да - на этом основаны электромагниты и двигатели."},"difficulty":5,"role":"practice"}'::jsonb, 5, '{"en":"Yes - this is the basis of electromagnets and motors.","ru":"Да - на этом основаны электромагниты и двигатели."}'::jsonb),
  ('science.electromagnetism.l1.c1', 'science.electromagnetism.l1', 'matching', '{"id":"science.electromagnetism.l1.c1","type":"matching","prompt":{"en":"Match each device with what it does.","ru":"Соедини устройство с тем, что оно делает."},"pairs":[{"left":{"en":"Generator","ru":"Генератор"},"right":{"en":"Kinetic energy → electrical energy","ru":"Кинетическая энергия → электрическая"}},{"left":{"en":"Electric motor","ru":"Электродвигатель"},"right":{"en":"Electrical energy → kinetic energy","ru":"Электрическая энергия → кинетическая"}},{"left":{"en":"Transformer","ru":"Трансформатор"},"right":{"en":"Changes the voltage of alternating current","ru":"Изменяет напряжение переменного тока"}},{"left":{"en":"Compass","ru":"Компас"},"right":{"en":"Shows the direction of a magnetic field","ru":"Показывает направление магнитного поля"}}],"explanation":{"en":"Generators and motors are opposites; transformers and compasses rely on magnetic fields too.","ru":"Генератор и двигатель - противоположности; трансформатор и компас тоже работают благодаря магнитным полям."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Generators and motors are opposites; transformers and compasses rely on magnetic fields too.","ru":"Генератор и двигатель - противоположности; трансформатор и компас тоже работают благодаря магнитным полям."}'::jsonb),
  ('science.electromagnetism.l1.c2', 'science.electromagnetism.l1', 'single', '{"id":"science.electromagnetism.l1.c2","type":"single","prompt":{"en":"Outside a bar magnet, the magnetic field lines go...","ru":"Снаружи полосового магнита линии магнитного поля идут..."},"options":[{"en":"From N to S","ru":"от N к S"},{"en":"From S to N","ru":"от S к N"},{"en":"Nowhere - there are no lines","ru":"никуда - линий нет"}],"answer":0,"explanation":{"en":"By convention, field lines leave the north pole and enter the south pole.","ru":"По договорённости линии выходят из северного полюса и входят в южный."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"By convention, field lines leave the north pole and enter the south pole.","ru":"По договорённости линии выходят из северного полюса и входят в южный."}'::jsonb),
  ('science.electromagnetism.l1.c3', 'science.electromagnetism.l1', 'true_false', '{"id":"science.electromagnetism.l1.c3","type":"true_false","prompt":{"en":"A magnet held perfectly still inside a coil keeps inducing a current.","ru":"Неподвижный магнит внутри катушки постоянно создаёт в ней ток."},"answer":false,"explanation":{"en":"Induction needs a changing field - the magnet or coil must move (or the field must change).","ru":"Для индукции нужно изменяющееся поле - магнит или катушка должны двигаться (или поле должно меняться)."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Induction needs a changing field - the magnet or coil must move (or the field must change).","ru":"Для индукции нужно изменяющееся поле - магнит или катушка должны двигаться (или поле должно меняться)."}'::jsonb),
  ('science.electromagnetism.l1.c4', 'science.electromagnetism.l1', 'drag_drop', '{"id":"science.electromagnetism.l1.c4","type":"drag_drop","prompt":{"en":"Sort: attracted by a magnet or not?","ru":"Распредели: притягивается к магниту или нет?"},"items":[{"id":"nail","label":{"en":"Iron nail","ru":"Железный гвоздь"}},{"id":"clip","label":{"en":"Steel paper clip","ru":"Стальная скрепка"}},{"id":"nickel","label":{"en":"Piece of nickel","ru":"Кусочек никеля"}},{"id":"copper","label":{"en":"Copper wire","ru":"Медная проволока"}},{"id":"can","label":{"en":"Aluminium can","ru":"Алюминиевая банка"}},{"id":"cup","label":{"en":"Plastic cup","ru":"Пластиковый стакан"}}],"buckets":[{"id":"mag","label":{"en":"Magnetic","ru":"Магнитное"}},{"id":"non","label":{"en":"Not magnetic","ru":"Немагнитное"}}],"answer":{"nail":"mag","clip":"mag","nickel":"mag","copper":"non","can":"non","cup":"non"},"explanation":{"en":"Iron, steel and nickel are attracted. Copper and aluminium are metals but not magnetic.","ru":"Железо, сталь и никель притягиваются. Медь и алюминий - металлы, но немагнитные."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Iron, steel and nickel are attracted. Copper and aluminium are metals but not magnetic.","ru":"Железо, сталь и никель притягиваются. Медь и алюминий - металлы, но немагнитные."}'::jsonb),
  ('science.electromagnetism.l1.c5', 'science.electromagnetism.l1', 'fill_blank', '{"id":"science.electromagnetism.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"A device that changes kinetic energy into electrical energy is called a ___.","ru":"Устройство, превращающее кинетическую энергию в электрическую, называется ___."},"accepted":{"en":["generator","dynamo"],"ru":["генератор","генератором","динамо"]},"explanation":{"en":"Generators in power stations and wind turbines use electromagnetic induction.","ru":"Генераторы на электростанциях и в ветряках работают на электромагнитной индукции."},"difficulty":5,"role":"check"}'::jsonb, 5, '{"en":"Generators in power stations and wind turbines use electromagnetic induction.","ru":"Генераторы на электростанциях и в ветряках работают на электромагнитной индукции."}'::jsonb),
