  ('languages.english-grammar.l1.p2', 'languages.english-grammar.l1', 'single', '{"id":"languages.english-grammar.l1.p2","type":"single","prompt":{"en":"Choose the right word.","ru":"Выбери правильное слово."},"visual":{"kind":"text","text":{"en":"She ___ my friend.","ru":"She ___ my friend."}},"options":[{"en":"am","ru":"am"},{"en":"is","ru":"is"},{"en":"are","ru":"are"}],"answer":1,"hint":{"en":"he, she, it → is","ru":"he, she, it → is"},"explanation":{"en":"She is my friend.","ru":"She is my friend - Она моя подруга."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"She is my friend.","ru":"She is my friend - Она моя подруга."}'::jsonb),
  ('languages.english-grammar.l1.p3', 'languages.english-grammar.l1', 'fill_blank', '{"id":"languages.english-grammar.l1.p3","type":"fill_blank","prompt":{"en":"Write the plural.","ru":"Напиши множественное число."},"text":{"en":"one cat, two ___","ru":"one cat, two ___"},"accepted":{"en":["cats"],"ru":["cats"]},"hint":{"en":"Add -s to the end.","ru":"Добавь -s в конце."},"explanation":{"en":"cat → cats.","ru":"cat → cats (кошка → кошки)."},"difficulty":1,"role":"practice"}'::jsonb, 1, '{"en":"cat → cats.","ru":"cat → cats (кошка → кошки)."}'::jsonb),
  ('languages.english-grammar.l1.c1', 'languages.english-grammar.l1', 'single', '{"id":"languages.english-grammar.l1.c1","type":"single","prompt":{"en":"Choose the right word.","ru":"Выбери правильное слово."},"visual":{"kind":"text","text":{"en":"They ___ at school.","ru":"They ___ at school."}},"options":[{"en":"is","ru":"is"},{"en":"am","ru":"am"},{"en":"are","ru":"are"}],"answer":2,"explanation":{"en":"we, you, they → are: They are at school.","ru":"we, you, they → are: They are at school - Они в школе."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"we, you, they → are: They are at school.","ru":"we, you, they → are: They are at school - Они в школе."}'::jsonb),
  ('languages.english-grammar.l1.c2', 'languages.english-grammar.l1', 'fill_blank', '{"id":"languages.english-grammar.l1.c2","type":"fill_blank","prompt":{"en":"Write the plural.","ru":"Напиши множественное число."},"text":{"en":"one box, three ___","ru":"one box, three ___"},"accepted":{"en":["boxes"],"ru":["boxes"]},"explanation":{"en":"After x we add -es: box → boxes.","ru":"После x добавляем -es: box → boxes (коробки)."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"After x we add -es: box → boxes.","ru":"После x добавляем -es: box → boxes (коробки)."}'::jsonb),
