  ('languages.english-grammar.l1.c5', 'languages.english-grammar.l1', 'audio_recognition', '{"id":"languages.english-grammar.l1.c5","type":"audio_recognition","prompt":{"en":"Listen to the sentence (your device''s voice says it). Which one is it?","ru":"Послушай предложение (его произнесёт голос твоего устройства). Какое это предложение?"},"say":{"en":"We are friends.","ru":"We are friends."},"options":[{"en":"We is friends.","ru":"We is friends."},{"en":"We are friends.","ru":"We are friends."},{"en":"We am friends.","ru":"We am friends."}],"answer":1,"explanation":{"en":"we → are: We are friends.","ru":"we → are: We are friends - Мы друзья."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"we → are: We are friends.","ru":"we → are: We are friends - Мы друзья."}'::jsonb),
  ('languages.english-dialogues.l1.p1', 'languages.english-dialogues.l1', 'matching', '{"id":"languages.english-dialogues.l1.p1","type":"matching","prompt":{"en":"Match each question with its answer.","ru":"Соедини вопрос с ответом."},"pairs":[{"left":{"en":"What''s your name?","ru":"What''s your name?"},"right":{"en":"My name is Tom.","ru":"My name is Tom."}},{"left":{"en":"How old are you?","ru":"How old are you?"},"right":{"en":"I''m nine.","ru":"I''m nine."}},{"left":{"en":"How are you?","ru":"How are you?"},"right":{"en":"I''m fine, thank you.","ru":"I''m fine, thank you."}}],"hint":{"en":"How old asks about age - look for a number.","ru":"How old - вопрос о возрасте, ищи число."},"explanation":{"en":"Name → My name is..., age → I''m nine, How are you? → I''m fine.","ru":"Имя → My name is..., возраст → I''m nine, «Как дела?» → I''m fine, thank you."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Name → My name is..., age → I''m nine, How are you? → I''m fine.","ru":"Имя → My name is..., возраст → I''m nine, «Как дела?» → I''m fine, thank you."}'::jsonb),
