  ('languages.english-dialogues.l1.p3', 'languages.english-dialogues.l1', 'audio_recognition', '{"id":"languages.english-dialogues.l1.p3","type":"audio_recognition","prompt":{"en":"Listen to the question (your device''s voice says it). Choose the best answer.","ru":"Послушай вопрос (его произнесёт голос твоего устройства). Выбери подходящий ответ."},"say":{"en":"Where are you from?","ru":"Where are you from?"},"options":[{"en":"I''m from Tashkent.","ru":"I''m from Tashkent."},{"en":"I''m ten.","ru":"I''m ten."},{"en":"I like cats.","ru":"I like cats."}],"answer":0,"hint":{"en":"Where asks about a place.","ru":"Where - вопрос о месте."},"explanation":{"en":"Where are you from? - I''m from Tashkent.","ru":"Where are you from? (Откуда ты?) - I''m from Tashkent. (Я из Ташкента.)"},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Where are you from? - I''m from Tashkent.","ru":"Where are you from? (Откуда ты?) - I''m from Tashkent. (Я из Ташкента.)"}'::jsonb),
