  ('languages.uzbek-basics.l1.p2', 'languages.uzbek-basics.l1', 'matching', '{"id":"languages.uzbek-basics.l1.p2","type":"matching","prompt":{"en":"Match the Uzbek word with its meaning.","ru":"Соедини узбекское слово с переводом."},"pairs":[{"left":{"en":"Salom","ru":"Salom"},"right":{"en":"Hello","ru":"Привет"}},{"left":{"en":"Rahmat","ru":"Rahmat"},"right":{"en":"Thank you","ru":"Спасибо"}},{"left":{"en":"Xayr","ru":"Xayr"},"right":{"en":"Goodbye","ru":"До свидания"}}],"hint":{"en":"Rahmat is a polite word for when someone helps you.","ru":"Rahmat говорят, когда тебе помогли."},"explanation":{"en":"Salom - hello, Rahmat - thank you, Xayr - goodbye.","ru":"Salom - привет, Rahmat - спасибо, Xayr - до свидания."},"difficulty":1,"role":"practice"}'::jsonb, 1, '{"en":"Salom - hello, Rahmat - thank you, Xayr - goodbye.","ru":"Salom - привет, Rahmat - спасибо, Xayr - до свидания."}'::jsonb),
