  ('languages.uzbek-basics.l1.c2', 'languages.uzbek-basics.l1', 'matching', '{"id":"languages.uzbek-basics.l1.c2","type":"matching","prompt":{"en":"Match the Uzbek number with the digit.","ru":"Соедини узбекское число с цифрой."},"pairs":[{"left":{"en":"bir","ru":"bir"},"right":{"en":"1","ru":"1"}},{"left":{"en":"ikki","ru":"ikki"},"right":{"en":"2","ru":"2"}},{"left":{"en":"uch","ru":"uch"},"right":{"en":"3","ru":"3"}},{"left":{"en":"besh","ru":"besh"},"right":{"en":"5","ru":"5"}}],"explanation":{"en":"bir 1, ikki 2, uch 3, besh 5.","ru":"bir 1, ikki 2, uch 3, besh 5."},"difficulty":1,"role":"check"}'::jsonb, 1, '{"en":"bir 1, ikki 2, uch 3, besh 5.","ru":"bir 1, ikki 2, uch 3, besh 5."}'::jsonb),
