  ('languages.russian-basics.l1.p1', 'languages.russian-basics.l1', 'audio_recognition', '{"id":"languages.russian-basics.l1.p1","type":"audio_recognition","prompt":{"en":"Listen to the Russian word (your device''s voice says it). Which word is it?","ru":"Послушай русское слово (его произнесёт голос твоего устройства). Какое это слово?"},"say":{"en":"Привет","ru":"Привет"},"options":[{"en":"Привет","ru":"Привет"},{"en":"Спасибо","ru":"Спасибо"},{"en":"Пока","ru":"Пока"}],"answer":0,"hint":{"en":"It sounds like \"pri-vyet\".","ru":"Звучит как «при-вет»."},"explanation":{"en":"Привет (privet) means hi.","ru":"Привет - так здороваются с друзьями."},"difficulty":1,"role":"practice"}'::jsonb, 1, '{"en":"Привет (privet) means hi.","ru":"Привет - так здороваются с друзьями."}'::jsonb),
  ('languages.russian-basics.l1.p2', 'languages.russian-basics.l1', 'matching', '{"id":"languages.russian-basics.l1.p2","type":"matching","prompt":{"en":"Match the Russian word with its meaning.","ru":"Соедини русское слово с тем, когда его говорят."},"pairs":[{"left":{"en":"Привет","ru":"Привет"},"right":{"en":"Hi 👋","ru":"👋 при встрече"}},{"left":{"en":"Спасибо","ru":"Спасибо"},"right":{"en":"Thank you 🎁","ru":"🎁 когда благодарят"}},{"left":{"en":"Пока","ru":"Пока"},"right":{"en":"Bye 🚪","ru":"🚪 при прощании"}}],"hint":{"en":"Спасибо (spasibo) is the polite word for a present.","ru":"Спасибо говорят, когда дарят подарок или помогают."},"explanation":{"en":"Привет - hi, Спасибо - thank you, Пока - bye.","ru":"Привет - при встрече, Спасибо - благодарность, Пока - при прощании."},"difficulty":1,"role":"practice"}'::jsonb, 1, '{"en":"Привет - hi, Спасибо - thank you, Пока - bye.","ru":"Привет - при встрече, Спасибо - благодарность, Пока - при прощании."}'::jsonb),
  ('languages.russian-basics.l1.p3', 'languages.russian-basics.l1', 'ordering', '{"id":"languages.russian-basics.l1.p3","type":"ordering","prompt":{"en":"Put the Russian numbers in order from 1 to 5.","ru":"Поставь числа по порядку от 1 до 5."},"items":[{"en":"один","ru":"один"},{"en":"два","ru":"два"},{"en":"три","ru":"три"},{"en":"четыре","ru":"четыре"},{"en":"пять","ru":"пять"}],"hint":{"en":"один (odin) is 1, пять (pyat) is 5.","ru":"один - это 1, пять - это 5."},"explanation":{"en":"один 1, два 2, три 3, четыре 4, пять 5.","ru":"один 1, два 2, три 3, четыре 4, пять 5."},"difficulty":1,"role":"practice"}'::jsonb, 1, '{"en":"один 1, два 2, три 3, четыре 4, пять 5.","ru":"один 1, два 2, три 3, четыре 4, пять 5."}'::jsonb),
  ('languages.russian-basics.l1.c1', 'languages.russian-basics.l1', 'single', '{"id":"languages.russian-basics.l1.c1","type":"single","prompt":{"en":"How do you say \"thank you\" in Russian?","ru":"Какое слово говорят, когда благодарят?"},"options":[{"en":"Пока","ru":"Пока"},{"en":"Спасибо","ru":"Спасибо"},{"en":"Да","ru":"Да"}],"answer":1,"explanation":{"en":"Спасибо (spasibo) means thank you.","ru":"Спасибо - слово благодарности."},"difficulty":1,"role":"check"}'::jsonb, 1, '{"en":"Спасибо (spasibo) means thank you.","ru":"Спасибо - слово благодарности."}'::jsonb),
  ('languages.russian-basics.l1.c2', 'languages.russian-basics.l1', 'matching', '{"id":"languages.russian-basics.l1.c2","type":"matching","prompt":{"en":"Match the Russian number with the digit.","ru":"Соедини число с цифрой."},"pairs":[{"left":{"en":"один","ru":"один"},"right":{"en":"1","ru":"1"}},{"left":{"en":"два","ru":"два"},"right":{"en":"2","ru":"2"}},{"left":{"en":"три","ru":"три"},"right":{"en":"3","ru":"3"}},{"left":{"en":"пять","ru":"пять"},"right":{"en":"5","ru":"5"}}],"explanation":{"en":"один 1, два 2, три 3, пять 5.","ru":"один 1, два 2, три 3, пять 5."},"difficulty":1,"role":"check"}'::jsonb, 1, '{"en":"один 1, два 2, три 3, пять 5.","ru":"один 1, два 2, три 3, пять 5."}'::jsonb),
  ('languages.russian-basics.l1.c3', 'languages.russian-basics.l1', 'fill_blank', '{"id":"languages.russian-basics.l1.c3","type":"fill_blank","prompt":{"en":"Finish the polite goodbye: До свидания (Goodbye).","ru":"Допиши вежливое прощание."},"text":{"en":"До ___!","ru":"До ___!"},"accepted":{"en":["свидания","svidaniya"],"ru":["свидания"]},"explanation":{"en":"До свидания! (Do svidaniya!) - Goodbye!","ru":"До свидания! - вежливое прощание."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"До свидания! (Do svidaniya!) - Goodbye!","ru":"До свидания! - вежливое прощание."}'::jsonb),
  ('languages.russian-basics.l1.c4', 'languages.russian-basics.l1', 'audio_recognition', '{"id":"languages.russian-basics.l1.c4","type":"audio_recognition","prompt":{"en":"Listen to the Russian word (your device''s voice says it). Which word is it?","ru":"Послушай русское слово (его произнесёт голос твоего устройства). Какое это слово?"},"say":{"en":"Да","ru":"Да"},"options":[{"en":"Нет","ru":"Нет"},{"en":"Да","ru":"Да"},{"en":"Пока","ru":"Пока"}],"answer":1,"explanation":{"en":"Да (da) means yes. Нет (nyet) means no.","ru":"Да - согласие, Нет - отказ."},"difficulty":1,"role":"check"}'::jsonb, 1, '{"en":"Да (da) means yes. Нет (nyet) means no.","ru":"Да - согласие, Нет - отказ."}'::jsonb),
  ('languages.russian-basics.l1.c5', 'languages.russian-basics.l1', 'single', '{"id":"languages.russian-basics.l1.c5","type":"single","prompt":{"en":"Which Cyrillic letter makes the sound D?","ru":"Какая буква обозначает звук [д]?"},"options":[{"en":"Б","ru":"Б"},{"en":"Д","ru":"Д"},{"en":"Ж","ru":"Ж"}],"answer":1,"explanation":{"en":"Д sounds like D, as in Да (da).","ru":"Буква Д - звук [д], как в слове «Да»."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Д sounds like D, as in Да (da).","ru":"Буква Д - звук [д], как в слове «Да»."}'::jsonb),
  ('tech.computer-basics.l1.p1', 'tech.computer-basics.l1', 'matching', '{"id":"tech.computer-basics.l1.p1","type":"matching","prompt":{"en":"Match each part with what it does.","ru":"Соедини часть компьютера с тем, что она делает."},"pairs":[{"left":{"en":"🖥️ Screen","ru":"🖥️ Экран"},"right":{"en":"Shows pictures and words","ru":"Показывает картинки и слова"}},{"left":{"en":"⌨️ Keyboard","ru":"⌨️ Клавиатура"},"right":{"en":"Types letters","ru":"Печатает буквы"}},{"left":{"en":"🖱️ Mouse","ru":"🖱️ Мышь"},"right":{"en":"Points and clicks","ru":"Показывает и нажимает"}},{"left":{"en":"🖨️ Printer","ru":"🖨️ Принтер"},"right":{"en":"Puts work on paper","ru":"Печатает на бумаге"}}],"hint":{"en":"Look at the pictures for clues.","ru":"Подсказки - на картинках."},"explanation":{"en":"Each part has its own job, and together they make the computer work.","ru":"У каждой части своя работа, а вместе они заставляют компьютер работать."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Each part has its own job, and together they make the computer work.","ru":"У каждой части своя работа, а вместе они заставляют компьютер работать."}'::jsonb),
  ('tech.computer-basics.l1.p2', 'tech.computer-basics.l1', 'image_selection', '{"id":"tech.computer-basics.l1.p2","type":"image_selection","prompt":{"en":"Which one is a keyboard?","ru":"Где клавиатура?"},"options":[{"emoji":"⌨️","label":{"en":"Keyboard","ru":"Клавиатура"}},{"emoji":"🖱️","label":{"en":"Mouse","ru":"Мышь"}},{"emoji":"🖥️","label":{"en":"Screen","ru":"Экран"}}],"answer":0,"hint":{"en":"It has lots of keys with letters.","ru":"На ней много кнопок с буквами."},"explanation":{"en":"The keyboard has keys for letters, numbers and more.","ru":"На клавиатуре есть клавиши с буквами, цифрами и другими знаками."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"The keyboard has keys for letters, numbers and more.","ru":"На клавиатуре есть клавиши с буквами, цифрами и другими знаками."}'::jsonb),
  ('tech.computer-basics.l1.p3', 'tech.computer-basics.l1', 'true_false', '{"id":"tech.computer-basics.l1.p3","type":"true_false","prompt":{"en":"A folder can hold many files.","ru":"В одной папке может быть много файлов."},"answer":true,"hint":{"en":"Think of a box that holds many toys.","ru":"Представь коробку, в которой много игрушек."},"explanation":{"en":"Yes! Folders keep our files tidy.","ru":"Да! Папки помогают держать файлы в порядке."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Yes! Folders keep our files tidy.","ru":"Да! Папки помогают держать файлы в порядке."}'::jsonb),
  ('tech.computer-basics.l1.c1', 'tech.computer-basics.l1', 'drag_drop', '{"id":"tech.computer-basics.l1.c1","type":"drag_drop","prompt":{"en":"Sort: input or output device?","ru":"Распредели: устройство ввода или вывода?"},"items":[{"id":"keyboard","label":{"en":"⌨️ Keyboard","ru":"⌨️ Клавиатура"}},{"id":"mouse","label":{"en":"🖱️ Mouse","ru":"🖱️ Мышь"}},{"id":"mic","label":{"en":"🎤 Microphone","ru":"🎤 Микрофон"}},{"id":"screen","label":{"en":"🖥️ Screen","ru":"🖥️ Экран"}},{"id":"printer","label":{"en":"🖨️ Printer","ru":"🖨️ Принтер"}},{"id":"speakers","label":{"en":"🔊 Speakers","ru":"🔊 Колонки"}}],"buckets":[{"id":"input","label":{"en":"Input (into the computer)","ru":"Ввод (в компьютер)"}},{"id":"output","label":{"en":"Output (out to us)","ru":"Вывод (к нам)"}}],"answer":{"keyboard":"input","mouse":"input","mic":"input","screen":"output","printer":"output","speakers":"output"},"explanation":{"en":"We give the computer information with the keyboard, mouse and microphone. It shows results on the screen, printer and speakers.","ru":"Мы передаём информацию клавиатурой, мышью и микрофоном. Компьютер выдаёт результат на экран, принтер и колонки."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"We give the computer information with the keyboard, mouse and microphone. It shows results on the screen, printer and speakers.","ru":"Мы передаём информацию клавиатурой, мышью и микрофоном. Компьютер выдаёт результат на экран, принтер и колонки."}'::jsonb),
  ('tech.computer-basics.l1.c2', 'tech.computer-basics.l1', 'single', '{"id":"tech.computer-basics.l1.c2","type":"single","prompt":{"en":"Which part is the computer''s \"brain\"?","ru":"Какая часть - «мозг» компьютера?"},"options":[{"en":"Processor","ru":"Процессор"},{"en":"Mouse","ru":"Мышь"},{"en":"Speaker","ru":"Колонка"}],"answer":0,"explanation":{"en":"The processor (CPU) does all the computer''s thinking.","ru":"Процессор выполняет все вычисления компьютера."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"The processor (CPU) does all the computer''s thinking.","ru":"Процессор выполняет все вычисления компьютера."}'::jsonb),
  ('tech.computer-basics.l1.c3', 'tech.computer-basics.l1', 'multiple', '{"id":"tech.computer-basics.l1.c3","type":"multiple","prompt":{"en":"What can you do with a mouse? Choose all.","ru":"Что можно делать мышкой? Выбери всё."},"options":[{"en":"Point","ru":"Показывать"},{"en":"Click","ru":"Нажимать"},{"en":"Drag things","ru":"Перетаскивать предметы"},{"en":"Print on paper","ru":"Печатать на бумаге"}],"answers":[0,1,2],"explanation":{"en":"A mouse points, clicks and drags. Printing on paper is the printer''s job.","ru":"Мышь показывает, нажимает и перетаскивает. Печатать на бумаге - работа принтера."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"A mouse points, clicks and drags. Printing on paper is the printer''s job.","ru":"Мышь показывает, нажимает и перетаскивает. Печатать на бумаге - работа принтера."}'::jsonb),
  ('tech.computer-basics.l1.c4', 'tech.computer-basics.l1', 'fill_blank', '{"id":"tech.computer-basics.l1.c4","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"Before you close your drawing, remember to ___ it.","ru":"Перед тем как закрыть рисунок, не забудь его ___."},"accepted":{"en":["save"],"ru":["сохранить"]},"explanation":{"en":"Saving keeps your work in a file so you can open it again.","ru":"Сохранение записывает работу в файл, чтобы её можно было открыть снова."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Saving keeps your work in a file so you can open it again.","ru":"Сохранение записывает работу в файл, чтобы её можно было открыть снова."}'::jsonb),
  ('tech.computer-basics.l1.c5', 'tech.computer-basics.l1', 'ordering', '{"id":"tech.computer-basics.l1.c5","type":"ordering","prompt":{"en":"Put the steps for making a computer drawing in order.","ru":"Расставь по порядку шаги создания рисунка на компьютере."},"items":[{"en":"Open the drawing program","ru":"Открыть программу для рисования"},{"en":"Draw a picture","ru":"Нарисовать картинку"},{"en":"Save the file","ru":"Сохранить файл"},{"en":"Close the program","ru":"Закрыть программу"}],"explanation":{"en":"Open, draw, save, close - and your picture is safe!","ru":"Открыть, нарисовать, сохранить, закрыть - и рисунок в безопасности!"},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Open, draw, save, close - and your picture is safe!","ru":"Открыть, нарисовать, сохранить, закрыть - и рисунок в безопасности!"}'::jsonb),
  ('tech.internet-safety.l1.p1', 'tech.internet-safety.l1', 'drag_drop', '{"id":"tech.internet-safety.l1.p1","type":"drag_drop","prompt":{"en":"OK to share in a game chat, or keep private?","ru":"Можно рассказать в игровом чате или это личное?"},"items":[{"id":"colour","label":{"en":"Your favourite colour","ru":"Твой любимый цвет"}},{"id":"animal","label":{"en":"Your favourite animal","ru":"Твоё любимое животное"}},{"id":"address","label":{"en":"Your home address","ru":"Твой домашний адрес"}},{"id":"password","label":{"en":"Your password","ru":"Твой пароль"}},{"id":"phone","label":{"en":"Your phone number","ru":"Твой номер телефона"}}],"buckets":[{"id":"ok","label":{"en":"OK to share","ru":"Можно рассказать"}},{"id":"private","label":{"en":"Keep private","ru":"Это личное"}}],"answer":{"colour":"ok","animal":"ok","address":"private","password":"private","phone":"private"},"hint":{"en":"Could a stranger use it to find you or get into your account?","ru":"Может ли незнакомец с помощью этого найти тебя или войти в твой аккаунт?"},"explanation":{"en":"Favourite things are fun to share. Address, password and phone number stay private.","ru":"О любимых вещах рассказывать можно. Адрес, пароль и телефон - это личное."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Favourite things are fun to share. Address, password and phone number stay private.","ru":"О любимых вещах рассказывать можно. Адрес, пароль и телефон - это личное."}'::jsonb),
  ('tech.internet-safety.l1.p2', 'tech.internet-safety.l1', 'single', '{"id":"tech.internet-safety.l1.p2","type":"single","prompt":{"en":"Someone in an online game asks for your home address. What should you do?","ru":"Кто-то в онлайн-игре спрашивает твой домашний адрес. Что нужно сделать?"},"options":[{"en":"Don''t answer and tell a trusted adult","ru":"Не отвечать и рассказать взрослому, которому доверяешь"},{"en":"Send the address","ru":"Отправить адрес"},{"en":"Ask for their address first","ru":"Сначала спросить их адрес"}],"answer":0,"hint":{"en":"Your address is private information.","ru":"Адрес - это личная информация."},"explanation":{"en":"Keep your address private and tell a parent, teacher or another trusted adult.","ru":"Не сообщай адрес и расскажи родителям, учителю или другому взрослому, которому доверяешь."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Keep your address private and tell a parent, teacher or another trusted adult.","ru":"Не сообщай адрес и расскажи родителям, учителю или другому взрослому, которому доверяешь."}'::jsonb),
  ('tech.internet-safety.l1.p3', 'tech.internet-safety.l1', 'true_false', '{"id":"tech.internet-safety.l1.p3","type":"true_false","prompt":{"en":"It''s fine to share your password with your best friend.","ru":"Можно сказать свой пароль лучшему другу."},"answer":false,"hint":{"en":"Who is the only person who may know your password?","ru":"Кто единственный может знать твой пароль?"},"explanation":{"en":"Passwords are only for you and your parent or guardian - even best friends shouldn''t know them.","ru":"Пароль знаешь только ты и твои родители или опекуны - даже лучшему другу его не говорят."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Passwords are only for you and your parent or guardian - even best friends shouldn''t know them.","ru":"Пароль знаешь только ты и твои родители или опекуны - даже лучшему другу его не говорят."}'::jsonb),
  ('tech.internet-safety.l1.c1', 'tech.internet-safety.l1', 'single', '{"id":"tech.internet-safety.l1.c1","type":"single","prompt":{"en":"Which password is the strongest?","ru":"Какой пароль самый надёжный?"},"options":[{"en":"cat","ru":"cat"},{"en":"12345","ru":"12345"},{"en":"Blue!Tiger7Jumps","ru":"Blue!Tiger7Jumps"}],"answer":2,"explanation":{"en":"Long passwords that mix letters, numbers and symbols are hardest to guess.","ru":"Длинный пароль из букв, цифр и символов труднее всего угадать."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Long passwords that mix letters, numbers and symbols are hardest to guess.","ru":"Длинный пароль из букв, цифр и символов труднее всего угадать."}'::jsonb),
  ('tech.internet-safety.l1.c2', 'tech.internet-safety.l1', 'multiple', '{"id":"tech.internet-safety.l1.c2","type":"multiple","prompt":{"en":"Which are kind ways to act online? Choose all.","ru":"Как можно вести себя в сети по-доброму? Выбери все варианты."},"options":[{"en":"Say nice things in comments","ru":"Писать приятные комментарии"},{"en":"Tell an adult if someone is being bullied","ru":"Рассказать взрослому, если кого-то обижают"},{"en":"Think before you post","ru":"Думать, прежде чем публиковать"},{"en":"Post a mean joke about a classmate","ru":"Выложить обидную шутку про одноклассника"}],"answers":[0,1,2],"explanation":{"en":"Kind words, helping others and thinking first make the internet better for everyone.","ru":"Добрые слова, помощь другим и умение подумать заранее делают интернет лучше для всех."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Kind words, helping others and thinking first make the internet better for everyone.","ru":"Добрые слова, помощь другим и умение подумать заранее делают интернет лучше для всех."}'::jsonb),
  ('tech.internet-safety.l1.c3', 'tech.internet-safety.l1', 'image_selection', '{"id":"tech.internet-safety.l1.c3","type":"image_selection","prompt":{"en":"Something online makes you feel worried. Who should you tell?","ru":"Что-то в интернете тебя встревожило. Кому нужно рассказать?"},"options":[{"emoji":"👨‍👩‍👧","label":{"en":"A parent or trusted adult","ru":"Родителям или взрослому, которому доверяешь"}},{"emoji":"🕵️","label":{"en":"A stranger online","ru":"Незнакомцу в интернете"}},{"emoji":"🤐","label":{"en":"Nobody","ru":"Никому"}}],"answer":0,"explanation":{"en":"A trusted adult can help. You will never be in trouble for asking for help.","ru":"Взрослый, которому ты доверяешь, поможет. Просить о помощи - это правильно."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"A trusted adult can help. You will never be in trouble for asking for help.","ru":"Взрослый, которому ты доверяешь, поможет. Просить о помощи - это правильно."}'::jsonb),
  ('tech.internet-safety.l1.c4', 'tech.internet-safety.l1', 'true_false', '{"id":"tech.internet-safety.l1.c4","type":"true_false","prompt":{"en":"People online are always who they say they are.","ru":"Люди в интернете всегда те, за кого себя выдают."},"answer":false,"explanation":{"en":"Anyone can pretend online, so keep private information private.","ru":"В сети кто угодно может притвориться другим, поэтому береги личные данные."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Anyone can pretend online, so keep private information private.","ru":"В сети кто угодно может притвориться другим, поэтому береги личные данные."}'::jsonb),
  ('tech.internet-safety.l1.c5', 'tech.internet-safety.l1', 'fill_blank', '{"id":"tech.internet-safety.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"Never share your ___ with anyone online, except your parents.","ru":"Никогда не сообщай свой ___ никому в интернете, кроме родителей."},"accepted":{"en":["password","passwords"],"ru":["пароль"]},"explanation":{"en":"Your password protects your account - keep it secret.","ru":"Пароль защищает твой аккаунт - держи его в секрете."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Your password protects your account - keep it secret.","ru":"Пароль защищает твой аккаунт - держи его в секрете."}'::jsonb),
  ('tech.algorithms.l1.p1', 'tech.algorithms.l1', 'ordering', '{"id":"tech.algorithms.l1.p1","type":"ordering","prompt":{"en":"Put the steps for brushing teeth in order.","ru":"Расставь по порядку шаги чистки зубов."},"items":[{"en":"Put toothpaste on the brush","ru":"Выдавить пасту на щётку"},{"en":"Brush your teeth","ru":"Почистить зубы"},{"en":"Rinse your mouth","ru":"Прополоскать рот"},{"en":"Put the brush away","ru":"Убрать щётку на место"}],"hint":{"en":"What do you need before you can brush?","ru":"Что нужно сделать до того, как начать чистить?"},"explanation":{"en":"That''s an algorithm: clear steps in the right order.","ru":"Это и есть алгоритм: понятные шаги в правильном порядке."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"That''s an algorithm: clear steps in the right order.","ru":"Это и есть алгоритм: понятные шаги в правильном порядке."}'::jsonb),
  ('tech.algorithms.l1.p2', 'tech.algorithms.l1', 'code_blocks', '{"id":"tech.algorithms.l1.p2","type":"code_blocks","prompt":{"en":"The robot faces right. Help it reach the flag!","ru":"Робот смотрит вправо. Помоги ему дойти до флажка!"},"grid":{"width":4,"height":4,"start":[0,3],"dir":1,"goal":[3,3],"walls":[]},"blocks":["forward","left","right"],"maxBlocks":4,"hint":{"en":"Count the squares between the robot and the flag.","ru":"Посчитай клетки между роботом и флажком."},"explanation":{"en":"Solution: forward, forward, forward. The flag is 3 squares to the right.","ru":"Решение: вперёд, вперёд, вперёд. Флажок в 3 клетках справа."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Solution: forward, forward, forward. The flag is 3 squares to the right.","ru":"Решение: вперёд, вперёд, вперёд. Флажок в 3 клетках справа."}'::jsonb),
  ('tech.algorithms.l1.p3', 'tech.algorithms.l1', 'single', '{"id":"tech.algorithms.l1.p3","type":"single","prompt":{"en":"What does the \"right\" block do?","ru":"Что делает блок «направо»?"},"options":[{"en":"Turns the robot to the right without moving","ru":"Поворачивает робота направо, не сдвигая его"},{"en":"Moves the robot one square to the right","ru":"Сдвигает робота на клетку вправо"},{"en":"Stops the robot","ru":"Останавливает робота"}],"answer":0,"hint":{"en":"Turning happens on the spot.","ru":"Поворот происходит на месте."},"explanation":{"en":"\"right\" only turns. To move, add a \"forward\" block.","ru":"«Направо» только поворачивает. Чтобы пойти, добавь блок «вперёд»."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"\"right\" only turns. To move, add a \"forward\" block.","ru":"«Направо» только поворачивает. Чтобы пойти, добавь блок «вперёд»."}'::jsonb),
  ('tech.algorithms.l1.c1', 'tech.algorithms.l1', 'code_blocks', '{"id":"tech.algorithms.l1.c1","type":"code_blocks","prompt":{"en":"The robot faces up. Guide it to the flag.","ru":"Робот смотрит вверх. Приведи его к флажку."},"grid":{"width":4,"height":4,"start":[0,3],"dir":0,"goal":[2,1],"walls":[[1,3],[1,2]]},"blocks":["forward","left","right"],"maxBlocks":6,"hint":{"en":"Go up first, then turn.","ru":"Сначала иди вверх, потом поверни."},"explanation":{"en":"Solution: forward, forward, right, forward, forward. Up two squares, turn right, then two more.","ru":"Решение: вперёд, вперёд, направо, вперёд, вперёд. Две клетки вверх, поворот направо и ещё две клетки."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Solution: forward, forward, right, forward, forward. Up two squares, turn right, then two more.","ru":"Решение: вперёд, вперёд, направо, вперёд, вперёд. Две клетки вверх, поворот направо и ещё две клетки."}'::jsonb),
  ('tech.algorithms.l1.c2', 'tech.algorithms.l1', 'code_blocks', '{"id":"tech.algorithms.l1.c2","type":"code_blocks","prompt":{"en":"The robot faces down. Walk around the wall to the flag.","ru":"Робот смотрит вниз. Обойди стену и дойди до флажка."},"grid":{"width":5,"height":5,"start":[0,0],"dir":2,"goal":[2,2],"walls":[[1,0],[1,1]]},"blocks":["forward","left","right"],"maxBlocks":6,"hint":{"en":"When the robot faces down, its left side is on your right.","ru":"Когда робот смотрит вниз, его левая сторона - справа от тебя."},"explanation":{"en":"Solution: forward, forward, left, forward, forward. Facing down, a left turn points the robot to the right side of the screen.","ru":"Решение: вперёд, вперёд, налево, вперёд, вперёд. Если робот смотрит вниз, поворот налево разворачивает его вправо на экране."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Solution: forward, forward, left, forward, forward. Facing down, a left turn points the robot to the right side of the screen.","ru":"Решение: вперёд, вперёд, налево, вперёд, вперёд. Если робот смотрит вниз, поворот налево разворачивает его вправо на экране."}'::jsonb),
  ('tech.algorithms.l1.c3', 'tech.algorithms.l1', 'true_false', '{"id":"tech.algorithms.l1.c3","type":"true_false","prompt":{"en":"In an algorithm, the order of the steps matters.","ru":"В алгоритме важен порядок шагов."},"answer":true,"explanation":{"en":"Yes! Putting on shoes before socks doesn''t work - order matters.","ru":"Да! Если надеть ботинки раньше носков, ничего не получится - порядок важен."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Yes! Putting on shoes before socks doesn''t work - order matters.","ru":"Да! Если надеть ботинки раньше носков, ничего не получится - порядок важен."}'::jsonb),
  ('tech.algorithms.l1.c4', 'tech.algorithms.l1', 'ordering', '{"id":"tech.algorithms.l1.c4","type":"ordering","prompt":{"en":"Put the steps for planting a seed in order.","ru":"Расставь по порядку шаги посадки семечка."},"items":[{"en":"Dig a small hole","ru":"Выкопать ямку"},{"en":"Put the seed in","ru":"Положить семечко"},{"en":"Cover it with soil","ru":"Засыпать землёй"},{"en":"Water it","ru":"Полить"}],"explanation":{"en":"Dig, plant, cover, water - a perfect algorithm!","ru":"Выкопать, посадить, засыпать, полить - отличный алгоритм!"},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Dig, plant, cover, water - a perfect algorithm!","ru":"Выкопать, посадить, засыпать, полить - отличный алгоритм!"}'::jsonb),
  ('tech.algorithms.l1.c5', 'tech.algorithms.l1', 'single', '{"id":"tech.algorithms.l1.c5","type":"single","prompt":{"en":"Finding and fixing a mistake in a program is called...","ru":"Поиск и исправление ошибки в программе называется..."},"options":[{"en":"Debugging","ru":"Отладка"},{"en":"Deleting","ru":"Удаление"},{"en":"Drawing","ru":"Рисование"}],"answer":0,"explanation":{"en":"Debugging! A \"bug\" is a mistake in a program.","ru":"Отладка! Ошибку в программе ещё называют «баг»."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Debugging! A \"bug\" is a mistake in a program.","ru":"Отладка! Ошибку в программе ещё называют «баг»."}'::jsonb),
  ('tech.loops.l1.p1', 'tech.loops.l1', 'number_input', '{"id":"tech.loops.l1.p1","type":"number_input","prompt":{"en":"The robot runs \"repeat 3: forward, end\". How many squares does it move?","ru":"Робот выполняет «повторить 3: вперёд, конец». На сколько клеток он продвинется?"},"answer":3,"hint":{"en":"\"forward\" happens once each time the loop repeats.","ru":"«Вперёд» выполняется один раз при каждом повторе."},"explanation":{"en":"The loop repeats \"forward\" 3 times, so the robot moves 3 squares.","ru":"Цикл повторяет «вперёд» 3 раза, значит, робот проходит 3 клетки."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"The loop repeats \"forward\" 3 times, so the robot moves 3 squares.","ru":"Цикл повторяет «вперёд» 3 раза, значит, робот проходит 3 клетки."}'::jsonb),
  ('tech.loops.l1.p2', 'tech.loops.l1', 'code_blocks', '{"id":"tech.loops.l1.p2","type":"code_blocks","prompt":{"en":"Climb the staircase! The robot faces up. Use a loop - you only have 6 blocks.","ru":"Поднимись по лесенке! Робот смотрит вверх. Используй цикл - у тебя всего 6 блоков."},"grid":{"width":6,"height":6,"start":[0,5],"dir":0,"goal":[3,2],"walls":[]},"blocks":["forward","left","right","repeat2","repeat3","end"],"maxBlocks":6,"hint":{"en":"One step of the staircase is: forward, right, forward, left. How many steps are there?","ru":"Одна ступенька: вперёд, направо, вперёд, налево. Сколько всего ступенек?"},"explanation":{"en":"Solution: repeat3, forward, right, forward, left, end. Each loop climbs one step; three steps reach the flag.","ru":"Решение: повторить 3, вперёд, направо, вперёд, налево, конец. Каждый повтор - одна ступенька, три ступеньки ведут к флажку."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Solution: repeat3, forward, right, forward, left, end. Each loop climbs one step; three steps reach the flag.","ru":"Решение: повторить 3, вперёд, направо, вперёд, налево, конец. Каждый повтор - одна ступенька, три ступеньки ведут к флажку."}'::jsonb),
  ('tech.loops.l1.p3', 'tech.loops.l1', 'true_false', '{"id":"tech.loops.l1.p3","type":"true_false","prompt":{"en":"A loop can make a program shorter.","ru":"Цикл может сделать программу короче."},"answer":true,"hint":{"en":"Compare \"forward\" written 3 times with \"repeat 3: forward\".","ru":"Сравни «вперёд» три раза и «повторить 3: вперёд»."},"explanation":{"en":"Yes! Loops save us from writing the same blocks again and again.","ru":"Да! Циклы избавляют от написания одних и тех же блоков снова и снова."},"difficulty":1,"audio":true,"role":"practice"}'::jsonb, 1, '{"en":"Yes! Loops save us from writing the same blocks again and again.","ru":"Да! Циклы избавляют от написания одних и тех же блоков снова и снова."}'::jsonb),
  ('tech.loops.l1.c1', 'tech.loops.l1', 'code_blocks', '{"id":"tech.loops.l1.c1","type":"code_blocks","prompt":{"en":"The robot faces right. Reach the flag with at most 8 blocks.","ru":"Робот смотрит вправо. Дойди до флажка, используя не больше 8 блоков."},"grid":{"width":5,"height":5,"start":[0,4],"dir":1,"goal":[4,0],"walls":[]},"blocks":["forward","left","right","repeat2","repeat3","end"],"maxBlocks":8,"hint":{"en":"Big steps: two forward, turn left, two forward, turn right. Repeat it!","ru":"Большие ступени: два вперёд, налево, два вперёд, направо. Повтори это!"},"explanation":{"en":"Solution: repeat2, forward, forward, left, forward, forward, right, end. Two big steps reach the top corner.","ru":"Решение: повторить 2, вперёд, вперёд, налево, вперёд, вперёд, направо, конец. Две большие ступени ведут в верхний угол."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Solution: repeat2, forward, forward, left, forward, forward, right, end. Two big steps reach the top corner.","ru":"Решение: повторить 2, вперёд, вперёд, налево, вперёд, вперёд, направо, конец. Две большие ступени ведут в верхний угол."}'::jsonb),
  ('tech.loops.l1.c2', 'tech.loops.l1', 'code_blocks', '{"id":"tech.loops.l1.c2","type":"code_blocks","prompt":{"en":"The robot faces up. Avoid the walls and reach the flag with at most 7 blocks.","ru":"Робот смотрит вверх. Обойди стены и дойди до флажка, используя не больше 7 блоков."},"grid":{"width":6,"height":6,"start":[0,5],"dir":0,"goal":[4,3],"walls":[[0,3],[3,5]]},"blocks":["forward","left","right","repeat2","repeat3","end"],"maxBlocks":7,"hint":{"en":"One step is: up 1, right 2. Do it twice.","ru":"Одна ступенька: 1 вверх, 2 вправо. Сделай так дважды."},"explanation":{"en":"Solution: repeat2, forward, right, forward, forward, left, end. Each loop goes up one square and right two.","ru":"Решение: повторить 2, вперёд, направо, вперёд, вперёд, налево, конец. За каждый повтор робот поднимается на клетку и проходит две вправо."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Solution: repeat2, forward, right, forward, forward, left, end. Each loop goes up one square and right two.","ru":"Решение: повторить 2, вперёд, направо, вперёд, вперёд, налево, конец. За каждый повтор робот поднимается на клетку и проходит две вправо."}'::jsonb),
  ('tech.loops.l1.c3', 'tech.loops.l1', 'number_input', '{"id":"tech.loops.l1.c3","type":"number_input","prompt":{"en":"The robot runs \"repeat 3: forward, forward, end\". How many squares does it move?","ru":"Робот выполняет «повторить 3: вперёд, вперёд, конец». На сколько клеток он продвинется?"},"answer":6,"explanation":{"en":"2 squares each time × 3 times = 6 squares.","ru":"По 2 клетки за раз × 3 раза = 6 клеток."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"2 squares each time × 3 times = 6 squares.","ru":"По 2 клетки за раз × 3 раза = 6 клеток."}'::jsonb),
  ('tech.loops.l1.c4', 'tech.loops.l1', 'single', '{"id":"tech.loops.l1.c4","type":"single","prompt":{"en":"Which loop means \"clap, clap, clap, clap\"?","ru":"Какой цикл означает «хлоп, хлоп, хлоп, хлоп»?"},"options":[{"en":"repeat 2: clap","ru":"повторить 2: хлоп"},{"en":"repeat 4: clap","ru":"повторить 4: хлоп"},{"en":"repeat 3: clap","ru":"повторить 3: хлоп"}],"answer":1,"explanation":{"en":"Four claps = repeat 4 times.","ru":"Четыре хлопка = повторить 4 раза."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Four claps = repeat 4 times.","ru":"Четыре хлопка = повторить 4 раза."}'::jsonb),
  ('tech.loops.l1.c5', 'tech.loops.l1', 'matching', '{"id":"tech.loops.l1.c5","type":"matching","prompt":{"en":"Match each loop with what it does.","ru":"Соедини цикл с тем, что он делает."},"pairs":[{"left":{"en":"repeat 2: hop","ru":"повторить 2: прыжок"},"right":{"en":"hop, hop","ru":"прыжок, прыжок"}},{"left":{"en":"repeat 3: hop","ru":"повторить 3: прыжок"},"right":{"en":"hop, hop, hop","ru":"прыжок, прыжок, прыжок"}},{"left":{"en":"repeat 2: hop, clap","ru":"повторить 2: прыжок, хлопок"},"right":{"en":"hop, clap, hop, clap","ru":"прыжок, хлопок, прыжок, хлопок"}}],"explanation":{"en":"Everything inside the loop is repeated, in the same order.","ru":"Всё внутри цикла повторяется в том же порядке."},"difficulty":1,"audio":true,"role":"check"}'::jsonb, 1, '{"en":"Everything inside the loop is repeated, in the same order.","ru":"Всё внутри цикла повторяется в том же порядке."}'::jsonb),
  ('tech.conditions.l1.p1', 'tech.conditions.l1', 'single', '{"id":"tech.conditions.l1.p1","type":"single","prompt":{"en":"Rule: if it is raining, then take an umbrella, else take sunglasses. Today it is sunny. What do you take?","ru":"Правило: если идёт дождь, то возьми зонт, иначе возьми солнечные очки. Сегодня солнечно. Что ты возьмёшь?"},"options":[{"en":"Umbrella","ru":"Зонт"},{"en":"Sunglasses","ru":"Солнечные очки"},{"en":"Both","ru":"И то и другое"}],"answer":1,"hint":{"en":"Is the condition \"it is raining\" true or false today?","ru":"Условие «идёт дождь» сегодня истинно или ложно?"},"explanation":{"en":"It isn''t raining, so the condition is false and we follow the \"else\" part: sunglasses.","ru":"Дождя нет - условие ложно, выполняем часть «иначе»: солнечные очки."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"It isn''t raining, so the condition is false and we follow the \"else\" part: sunglasses.","ru":"Дождя нет - условие ложно, выполняем часть «иначе»: солнечные очки."}'::jsonb),
  ('tech.conditions.l1.p2', 'tech.conditions.l1', 'code_blocks', '{"id":"tech.conditions.l1.p2","type":"code_blocks","prompt":{"en":"The robot faces right. Rule: if there is a wall ahead, turn. Plan the route to the flag.","ru":"Робот смотрит вправо. Правило: если впереди стена - поворачивай. Спланируй путь к флажку."},"grid":{"width":5,"height":5,"start":[0,0],"dir":1,"goal":[4,2],"walls":[[3,0],[2,3]]},"blocks":["forward","left","right"],"maxBlocks":9,"hint":{"en":"Move until a wall is ahead, then turn toward the flag.","ru":"Иди, пока впереди не окажется стена, затем поворачивай в сторону флажка."},"explanation":{"en":"Solution: forward, forward, right, forward, forward, left, forward, forward. At each wall the condition \"wall ahead\" is true, so the robot turns.","ru":"Решение: вперёд, вперёд, направо, вперёд, вперёд, налево, вперёд, вперёд. У каждой стены условие «впереди стена» истинно, и робот поворачивает."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Solution: forward, forward, right, forward, forward, left, forward, forward. At each wall the condition \"wall ahead\" is true, so the robot turns.","ru":"Решение: вперёд, вперёд, направо, вперёд, вперёд, налево, вперёд, вперёд. У каждой стены условие «впереди стена» истинно, и робот поворачивает."}'::jsonb),
  ('tech.conditions.l1.p3', 'tech.conditions.l1', 'true_false', '{"id":"tech.conditions.l1.p3","type":"true_false","prompt":{"en":"A condition is always either true or false.","ru":"Условие всегда либо истинно, либо ложно."},"answer":true,"hint":{"en":"Think of a yes/no question.","ru":"Вспомни вопрос с ответом «да» или «нет»."},"explanation":{"en":"Yes! That is how the program knows which way to go.","ru":"Да! Так программа понимает, какой путь выбрать."},"difficulty":2,"role":"practice"}'::jsonb, 2, '{"en":"Yes! That is how the program knows which way to go.","ru":"Да! Так программа понимает, какой путь выбрать."}'::jsonb),
  ('tech.conditions.l1.c1', 'tech.conditions.l1', 'code_blocks', '{"id":"tech.conditions.l1.c1","type":"code_blocks","prompt":{"en":"The robot faces up. If a wall is ahead, it must turn. Guide it to the flag.","ru":"Робот смотрит вверх. Если впереди стена, нужно повернуть. Приведи его к флажку."},"grid":{"width":5,"height":5,"start":[0,4],"dir":0,"goal":[3,0],"walls":[[0,1],[4,2]]},"blocks":["forward","left","right"],"maxBlocks":10,"hint":{"en":"Go up until the wall, turn right, go right until the wall, then turn left.","ru":"Иди вверх до стены, поверни направо, иди вправо до стены, затем поверни налево."},"explanation":{"en":"Solution: forward, forward, right, forward, forward, forward, left, forward, forward. Two walls, two turns.","ru":"Решение: вперёд, вперёд, направо, вперёд, вперёд, вперёд, налево, вперёд, вперёд. Две стены - два поворота."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"Solution: forward, forward, right, forward, forward, forward, left, forward, forward. Two walls, two turns.","ru":"Решение: вперёд, вперёд, направо, вперёд, вперёд, вперёд, налево, вперёд, вперёд. Две стены - два поворота."}'::jsonb),
  ('tech.conditions.l1.c2', 'tech.conditions.l1', 'matching', '{"id":"tech.conditions.l1.c2","type":"matching","prompt":{"en":"Match each condition with the right action.","ru":"Соедини условие с правильным действием."},"pairs":[{"left":{"en":"If the traffic light is red","ru":"Если светофор красный"},"right":{"en":"Stop","ru":"Стой"}},{"left":{"en":"If the traffic light is green","ru":"Если светофор зелёный"},"right":{"en":"Go","ru":"Иди"}},{"left":{"en":"If it is cold outside","ru":"Если на улице холодно"},"right":{"en":"Put on a coat","ru":"Надень куртку"}},{"left":{"en":"If you are hungry","ru":"Если ты голоден"},"right":{"en":"Eat a snack","ru":"Перекуси"}}],"explanation":{"en":"We use if-then rules every day!","ru":"Мы пользуемся правилами «если - то» каждый день!"},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"We use if-then rules every day!","ru":"Мы пользуемся правилами «если - то» каждый день!"}'::jsonb),
  ('tech.conditions.l1.c3', 'tech.conditions.l1', 'number_input', '{"id":"tech.conditions.l1.c3","type":"number_input","prompt":{"en":"x = 7. If x > 5 then score = 10, else score = 2. What is score?","ru":"x = 7. Если x > 5, то score = 10, иначе score = 2. Чему равен score?"},"answer":10,"visual":{"kind":"code","code":"x = 7\nif x > 5:\n    score = 10\nelse:\n    score = 2"},"explanation":{"en":"7 > 5 is true, so score = 10.","ru":"7 > 5 - истина, значит, score = 10."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"7 > 5 is true, so score = 10.","ru":"7 > 5 - истина, значит, score = 10."}'::jsonb),
  ('tech.conditions.l1.c4', 'tech.conditions.l1', 'drag_drop', '{"id":"tech.conditions.l1.c4","type":"drag_drop","prompt":{"en":"Is each condition true or false?","ru":"Каждое условие истинно или ложно?"},"items":[{"id":"a","label":{"en":"5 > 3","ru":"5 > 3"}},{"id":"b","label":{"en":"2 = 2","ru":"2 = 2"}},{"id":"c","label":{"en":"10 < 4","ru":"10 < 4"}},{"id":"d","label":{"en":"7 > 9","ru":"7 > 9"}}],"buckets":[{"id":"true","label":{"en":"True","ru":"Истина"}},{"id":"false","label":{"en":"False","ru":"Ложь"}}],"answer":{"a":"true","b":"true","c":"false","d":"false"},"explanation":{"en":"5 > 3 and 2 = 2 are true; 10 is not less than 4 and 7 is not more than 9.","ru":"5 > 3 и 2 = 2 - истина; 10 не меньше 4, а 7 не больше 9."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"5 > 3 and 2 = 2 are true; 10 is not less than 4 and 7 is not more than 9.","ru":"5 > 3 и 2 = 2 - истина; 10 не меньше 4, а 7 не больше 9."}'::jsonb),
  ('tech.conditions.l1.c5', 'tech.conditions.l1', 'fill_blank', '{"id":"tech.conditions.l1.c5","type":"fill_blank","prompt":{"en":"Fill in the missing word.","ru":"Вставь пропущенное слово."},"text":{"en":"if wall ahead then turn right, ___ move forward","ru":"если впереди стена, то повернуть направо, ___ идти вперёд"},"accepted":{"en":["else","otherwise"],"ru":["иначе"]},"explanation":{"en":"\"else\" tells the program what to do when the condition is false.","ru":"«Иначе» говорит программе, что делать, если условие ложно."},"difficulty":2,"role":"check"}'::jsonb, 2, '{"en":"\"else\" tells the program what to do when the condition is false.","ru":"«Иначе» говорит программе, что делать, если условие ложно."}'::jsonb),
  ('tech.html.l1.p1', 'tech.html.l1', 'single', '{"id":"tech.html.l1.p1","type":"single","prompt":{"en":"Which tag makes the biggest heading?","ru":"Какой тег создаёт самый крупный заголовок?"},"options":[{"en":"<h1>","ru":"<h1>"},{"en":"<h6>","ru":"<h6>"},{"en":"<p>","ru":"<p>"}],"answer":0,"hint":{"en":"Heading number 1 is the most important.","ru":"Заголовок номер 1 - самый главный."},"explanation":{"en":"<h1> is the main, biggest heading; <h6> is the smallest.","ru":"<h1> - главный и самый крупный заголовок, <h6> - самый мелкий."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"<h1> is the main, biggest heading; <h6> is the smallest.","ru":"<h1> - главный и самый крупный заголовок, <h6> - самый мелкий."}'::jsonb),
  ('tech.html.l1.p2', 'tech.html.l1', 'matching', '{"id":"tech.html.l1.p2","type":"matching","prompt":{"en":"Match each tag with what it creates.","ru":"Соедини тег с тем, что он создаёт."},"pairs":[{"left":{"en":"<p>","ru":"<p>"},"right":{"en":"Paragraph","ru":"Абзац"}},{"left":{"en":"<a>","ru":"<a>"},"right":{"en":"Link","ru":"Ссылка"}},{"left":{"en":"<img>","ru":"<img>"},"right":{"en":"Image","ru":"Изображение"}},{"left":{"en":"<ul>","ru":"<ul>"},"right":{"en":"Bulleted list","ru":"Маркированный список"}}],"hint":{"en":"\"a\" stands for anchor, \"ul\" for unordered list.","ru":"«a» - от anchor (якорь), «ul» - от unordered list (неупорядоченный список)."},"explanation":{"en":"These four tags appear on almost every web page.","ru":"Эти четыре тега есть почти на каждой веб-странице."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"These four tags appear on almost every web page.","ru":"Эти четыре тега есть почти на каждой веб-странице."}'::jsonb),
  ('tech.html.l1.p3', 'tech.html.l1', 'fill_blank', '{"id":"tech.html.l1.p3","type":"fill_blank","prompt":{"en":"Write the closing tag for the paragraph.","ru":"Напиши закрывающий тег для абзаца."},"text":{"en":"<p>Hello, world!___","ru":"<p>Привет, мир!___"},"accepted":{"en":["</p>"],"ru":["</p>"]},"hint":{"en":"A closing tag has a slash: </...>","ru":"В закрывающем теге есть косая черта: </...>"},"explanation":{"en":"The closing tag </p> ends the paragraph.","ru":"Закрывающий тег </p> завершает абзац."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"The closing tag </p> ends the paragraph.","ru":"Закрывающий тег </p> завершает абзац."}'::jsonb),
  ('tech.html.l1.c1', 'tech.html.l1', 'single', '{"id":"tech.html.l1.c1","type":"single","prompt":{"en":"What will the browser show for this code?","ru":"Что покажет браузер для этого кода?"},"visual":{"kind":"code","code":"<h1>Hi</h1>\n<p>Bye</p>"},"options":[{"en":"A big heading \"Hi\" and below it the paragraph \"Bye\"","ru":"Крупный заголовок «Hi», а под ним абзац «Bye»"},{"en":"The text <h1>Hi</h1> exactly as written","ru":"Текст <h1>Hi</h1> в точности как написано"},{"en":"Only the word \"Bye\"","ru":"Только слово «Bye»"}],"answer":0,"explanation":{"en":"Tags are not shown; they tell the browser how to display the text.","ru":"Теги не отображаются - они говорят браузеру, как показать текст."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Tags are not shown; they tell the browser how to display the text.","ru":"Теги не отображаются - они говорят браузеру, как показать текст."}'::jsonb),
  ('tech.html.l1.c2', 'tech.html.l1', 'true_false', '{"id":"tech.html.l1.c2","type":"true_false","prompt":{"en":"The <img> tag needs a closing </img> tag.","ru":"Тегу <img> нужен закрывающий тег </img>."},"answer":false,"explanation":{"en":"<img> is an empty (void) element: all its info is in attributes like src and alt.","ru":"<img> - пустой элемент: вся информация в атрибутах src и alt."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"<img> is an empty (void) element: all its info is in attributes like src and alt.","ru":"<img> - пустой элемент: вся информация в атрибутах src и alt."}'::jsonb),
  ('tech.html.l1.c3', 'tech.html.l1', 'multiple', '{"id":"tech.html.l1.c3","type":"multiple","prompt":{"en":"Which lines are correct HTML? Choose all.","ru":"Какие строки - правильный HTML? Выбери все."},"options":[{"en":"<p>Text</p>","ru":"<p>Текст</p>"},{"en":"<a href=\"page.html\">Go</a>","ru":"<a href=\"page.html\">Перейти</a>"},{"en":"<h1>Title</h2>","ru":"<h1>Заголовок</h2>"},{"en":"<img src=\"cat.png\" alt=\"A cat\">","ru":"<img src=\"cat.png\" alt=\"Кошка\">"}],"answers":[0,1,3],"explanation":{"en":"<h1> must be closed with </h1>, not </h2>. The other lines are correct.","ru":"<h1> нужно закрывать тегом </h1>, а не </h2>. Остальные строки верны."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"<h1> must be closed with </h1>, not </h2>. The other lines are correct.","ru":"<h1> нужно закрывать тегом </h1>, а не </h2>. Остальные строки верны."}'::jsonb),
  ('tech.html.l1.c4', 'tech.html.l1', 'ordering', '{"id":"tech.html.l1.c4","type":"ordering","prompt":{"en":"Put the parts of an HTML page in order from top to bottom.","ru":"Расставь части HTML-страницы по порядку сверху вниз."},"items":[{"en":"<!DOCTYPE html>","ru":"<!DOCTYPE html>"},{"en":"<html>","ru":"<html>"},{"en":"<head>…</head>","ru":"<head>…</head>"},{"en":"<body>…</body>","ru":"<body>…</body>"},{"en":"</html>","ru":"</html>"}],"explanation":{"en":"DOCTYPE first, then <html> holding <head> and <body>, then </html> closes the page.","ru":"Сначала DOCTYPE, затем <html> с <head> и <body> внутри, и </html> закрывает страницу."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"DOCTYPE first, then <html> holding <head> and <body>, then </html> closes the page.","ru":"Сначала DOCTYPE, затем <html> с <head> и <body> внутри, и </html> закрывает страницу."}'::jsonb),
  ('tech.html.l1.c5', 'tech.html.l1', 'number_input', '{"id":"tech.html.l1.c5","type":"number_input","prompt":{"en":"How many bullet points will this list show?","ru":"Сколько пунктов будет в этом списке?"},"visual":{"kind":"code","code":"<ul>\n  <li>Apples</li>\n  <li>Pears</li>\n  <li>Plums</li>\n  <li>Grapes</li>\n</ul>"},"answer":4,"explanation":{"en":"Each <li> is one list item: 4 items.","ru":"Каждый <li> - один пункт списка: всего 4."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Each <li> is one list item: 4 items.","ru":"Каждый <li> - один пункт списка: всего 4."}'::jsonb),
  ('tech.css.l1.p1', 'tech.css.l1', 'single', '{"id":"tech.css.l1.p1","type":"single","prompt":{"en":"Which property changes the text colour?","ru":"Какое свойство меняет цвет текста?"},"options":[{"en":"color","ru":"color"},{"en":"background-color","ru":"background-color"},{"en":"font-size","ru":"font-size"}],"answer":0,"hint":{"en":"background-color changes the colour behind the text.","ru":"background-color меняет цвет фона за текстом."},"explanation":{"en":"color sets the text colour.","ru":"color задаёт цвет текста."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"color sets the text colour.","ru":"color задаёт цвет текста."}'::jsonb),
  ('tech.css.l1.p2', 'tech.css.l1', 'matching', '{"id":"tech.css.l1.p2","type":"matching","prompt":{"en":"Match each selector with what it selects.","ru":"Соедини селектор с тем, что он выбирает."},"pairs":[{"left":{"en":"p","ru":"p"},"right":{"en":"All paragraphs","ru":"Все абзацы"}},{"left":{"en":".card","ru":".card"},"right":{"en":"Elements with class=\"card\"","ru":"Элементы с class=\"card\""}},{"left":{"en":"#menu","ru":"#menu"},"right":{"en":"The element with id=\"menu\"","ru":"Элемент с id=\"menu\""}},{"left":{"en":"*","ru":"*"},"right":{"en":"Every element","ru":"Все элементы"}}],"hint":{"en":"Dot = class, hash = id.","ru":"Точка - класс, решётка - id."},"explanation":{"en":"Element, class, id and the universal selector * are the basics.","ru":"Тег, класс, id и универсальный селектор * - основы CSS."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"Element, class, id and the universal selector * are the basics.","ru":"Тег, класс, id и универсальный селектор * - основы CSS."}'::jsonb),
  ('tech.css.l1.p3', 'tech.css.l1', 'fill_blank', '{"id":"tech.css.l1.p3","type":"fill_blank","prompt":{"en":"Make all <h1> headings red. Write the missing property.","ru":"Сделай все заголовки <h1> красными. Впиши пропущенное свойство."},"text":{"en":"h1 { ___: red; }","ru":"h1 { ___: red; }"},"accepted":{"en":["color"],"ru":["color"]},"hint":{"en":"CSS uses American spelling.","ru":"В CSS используется американское написание слова «цвет»."},"explanation":{"en":"h1 { color: red; } makes the heading text red.","ru":"h1 { color: red; } делает текст заголовка красным."},"difficulty":3,"role":"practice"}'::jsonb, 3, '{"en":"h1 { color: red; } makes the heading text red.","ru":"h1 { color: red; } делает текст заголовка красным."}'::jsonb),
  ('tech.css.l1.c1', 'tech.css.l1', 'single', '{"id":"tech.css.l1.c1","type":"single","prompt":{"en":"What colour will the paragraphs be?","ru":"Какого цвета будут абзацы?"},"visual":{"kind":"code","code":"p { color: red; }\np { color: green; }"},"options":[{"en":"Red","ru":"Красного"},{"en":"Green","ru":"Зелёного"},{"en":"Black","ru":"Чёрного"}],"answer":1,"explanation":{"en":"Both selectors are equally specific, so the later rule wins: green.","ru":"Селекторы одинаково специфичны, поэтому побеждает правило, записанное позже: зелёный."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Both selectors are equally specific, so the later rule wins: green.","ru":"Селекторы одинаково специфичны, поэтому побеждает правило, записанное позже: зелёный."}'::jsonb),
  ('tech.css.l1.c2', 'tech.css.l1', 'number_input', '{"id":"tech.css.l1.c2","type":"number_input","prompt":{"en":"A box has width: 100px, padding: 10px and border: 2px (on every side). How wide is it in total, without margin?","ru":"У блока width: 100px, padding: 10px и border: 2px (с каждой стороны). Какова его полная ширина без margin?"},"visual":{"kind":"code","code":".box {\n  width: 100px;\n  padding: 10px;\n  border: 2px solid black;\n}"},"answer":124,"unit":{"en":"px","ru":"px"},"explanation":{"en":"100 + 10 + 10 + 2 + 2 = 124px (with the default box-sizing: content-box).","ru":"100 + 10 + 10 + 2 + 2 = 124px (при стандартном box-sizing: content-box)."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"100 + 10 + 10 + 2 + 2 = 124px (with the default box-sizing: content-box).","ru":"100 + 10 + 10 + 2 + 2 = 124px (при стандартном box-sizing: content-box)."}'::jsonb),
  ('tech.css.l1.c3', 'tech.css.l1', 'true_false', '{"id":"tech.css.l1.c3","type":"true_false","prompt":{"en":"A class selector starts with a dot (.).","ru":"Селектор класса начинается с точки (.)."},"answer":true,"explanation":{"en":"Yes: .note selects class=\"note\". An id selector starts with #.","ru":"Да: .note выбирает class=\"note\". Селектор id начинается с #."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"Yes: .note selects class=\"note\". An id selector starts with #.","ru":"Да: .note выбирает class=\"note\". Селектор id начинается с #."}'::jsonb),
  ('tech.css.l1.c4', 'tech.css.l1', 'multiple', '{"id":"tech.css.l1.c4","type":"multiple","prompt":{"en":"Which are valid CSS declarations? Choose all.","ru":"Какие объявления CSS записаны правильно? Выбери все."},"options":[{"en":"color: blue;","ru":"color: blue;"},{"en":"font-size: 20px;","ru":"font-size: 20px;"},{"en":"colour: blue;","ru":"colour: blue;"},{"en":"margin: 10px;","ru":"margin: 10px;"}],"answers":[0,1,3],"explanation":{"en":"CSS only understands \"color\", not \"colour\".","ru":"CSS понимает только «color», а не «colour»."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"CSS only understands \"color\", not \"colour\".","ru":"CSS понимает только «color», а не «colour»."}'::jsonb),
  ('tech.css.l1.c5', 'tech.css.l1', 'single', '{"id":"tech.css.l1.c5","type":"single","prompt":{"en":"What colour will this paragraph be?","ru":"Какого цвета будет этот абзац?"},"visual":{"kind":"code","code":"<p id=\"intro\" class=\"big\">Hello</p>\n\n.big { color: red; }\n#intro { color: blue; }"},"options":[{"en":"Red","ru":"Красного"},{"en":"Blue","ru":"Синего"}],"answer":1,"explanation":{"en":"An id selector is more specific than a class selector, so blue wins.","ru":"Селектор id специфичнее селектора класса, поэтому побеждает синий."},"difficulty":3,"role":"check"}'::jsonb, 3, '{"en":"An id selector is more specific than a class selector, so blue wins.","ru":"Селектор id специфичнее селектора класса, поэтому побеждает синий."}'::jsonb),
  ('tech.javascript.l1.p1', 'tech.javascript.l1', 'single', '{"id":"tech.javascript.l1.p1","type":"single","prompt":{"en":"What does this program print?","ru":"Что выведет эта программа?"},"visual":{"kind":"code","code":"let score = 5;\nscore = score + 3;\nif (score > 7) {\n  console.log(\"Great!\");\n} else {\n  console.log(\"Keep going!\");\n}"},"options":[{"en":"Great!","ru":"Great!"},{"en":"Keep going!","ru":"Keep going!"},{"en":"8","ru":"8"}],"answer":0,"hint":{"en":"Work out score first, then check the condition.","ru":"Сначала вычисли score, затем проверь условие."},"explanation":{"en":"score = 8 and 8 > 7 is true, so \"Great!\" is printed.","ru":"score = 8, условие 8 > 7 истинно - выводится \"Great!\"."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"score = 8 and 8 > 7 is true, so \"Great!\" is printed.","ru":"score = 8, условие 8 > 7 истинно - выводится \"Great!\"."}'::jsonb),
  ('tech.javascript.l1.p2', 'tech.javascript.l1', 'number_input', '{"id":"tech.javascript.l1.p2","type":"number_input","prompt":{"en":"What number does this print?","ru":"Какое число выведет программа?"},"visual":{"kind":"code","code":"let a = 4;\nlet b = a * 3;\nconsole.log(b - 2);"},"answer":10,"hint":{"en":"b = 4 × 3.","ru":"b = 4 × 3."},"explanation":{"en":"b = 12, and 12 - 2 = 10.","ru":"b = 12, а 12 - 2 = 10."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"b = 12, and 12 - 2 = 10.","ru":"b = 12, а 12 - 2 = 10."}'::jsonb),
  ('tech.javascript.l1.p3', 'tech.javascript.l1', 'true_false', '{"id":"tech.javascript.l1.p3","type":"true_false","prompt":{"en":"A variable declared with const can be reassigned later.","ru":"Переменную, объявленную через const, можно потом переприсвоить."},"answer":false,"hint":{"en":"const is short for \"constant\".","ru":"const - сокращение от «constant» (постоянная)."},"explanation":{"en":"const values cannot be reassigned. Use let for values that change.","ru":"Значение const нельзя переприсвоить. Для изменяемых значений используй let."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"const values cannot be reassigned. Use let for values that change.","ru":"Значение const нельзя переприсвоить. Для изменяемых значений используй let."}'::jsonb),
  ('tech.javascript.l1.c1', 'tech.javascript.l1', 'number_input', '{"id":"tech.javascript.l1.c1","type":"number_input","prompt":{"en":"What number does this print?","ru":"Какое число выведет программа?"},"visual":{"kind":"code","code":"function double(n) {\n  return n * 2;\n}\nconsole.log(double(6) + 1);"},"answer":13,"explanation":{"en":"double(6) returns 12, and 12 + 1 = 13.","ru":"double(6) возвращает 12, а 12 + 1 = 13."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"double(6) returns 12, and 12 + 1 = 13.","ru":"double(6) возвращает 12, а 12 + 1 = 13."}'::jsonb),
  ('tech.javascript.l1.c2', 'tech.javascript.l1', 'number_input', '{"id":"tech.javascript.l1.c2","type":"number_input","prompt":{"en":"What number does this print?","ru":"Какое число выведет программа?"},"visual":{"kind":"code","code":"let total = 0;\nfor (let i = 1; i <= 4; i++) {\n  total += i;\n}\nconsole.log(total);"},"answer":10,"explanation":{"en":"total = 1 + 2 + 3 + 4 = 10.","ru":"total = 1 + 2 + 3 + 4 = 10."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"total = 1 + 2 + 3 + 4 = 10.","ru":"total = 1 + 2 + 3 + 4 = 10."}'::jsonb),
  ('tech.javascript.l1.c3', 'tech.javascript.l1', 'single', '{"id":"tech.javascript.l1.c3","type":"single","prompt":{"en":"What does console.log(\"3\" + 2) print?","ru":"Что выведет console.log(\"3\" + 2)?"},"visual":{"kind":"code","code":"console.log(\"3\" + 2);"},"options":[{"en":"32","ru":"32"},{"en":"5","ru":"5"},{"en":"An error","ru":"Ошибку"}],"answer":0,"explanation":{"en":"\"3\" is a string, so + joins the text: \"32\".","ru":"\"3\" - строка, поэтому + склеивает текст: \"32\"."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"\"3\" is a string, so + joins the text: \"32\".","ru":"\"3\" - строка, поэтому + склеивает текст: \"32\"."}'::jsonb),
  ('tech.javascript.l1.c4', 'tech.javascript.l1', 'matching', '{"id":"tech.javascript.l1.c4","type":"matching","prompt":{"en":"Match each keyword with its meaning.","ru":"Соедини ключевое слово с его значением."},"pairs":[{"left":{"en":"let","ru":"let"},"right":{"en":"A variable that can change","ru":"Переменная, которую можно изменить"}},{"left":{"en":"const","ru":"const"},"right":{"en":"A variable that can''t be reassigned","ru":"Переменная, которую нельзя переприсвоить"}},{"left":{"en":"function","ru":"function"},"right":{"en":"A reusable block of code","ru":"Многоразовый блок кода"}},{"left":{"en":"console.log","ru":"console.log"},"right":{"en":"Prints a value","ru":"Выводит значение"}}],"explanation":{"en":"These are the building blocks of most JavaScript programs.","ru":"Это строительные блоки большинства программ на JavaScript."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"These are the building blocks of most JavaScript programs.","ru":"Это строительные блоки большинства программ на JavaScript."}'::jsonb),
  ('tech.javascript.l1.c5', 'tech.javascript.l1', 'fill_blank', '{"id":"tech.javascript.l1.c5","type":"fill_blank","prompt":{"en":"Complete the condition: run the code when x is greater than 10.","ru":"Допиши условие: код должен выполняться, когда x больше 10."},"text":{"en":"if (x ___ 10) { ... }","ru":"if (x ___ 10) { ... }"},"accepted":{"en":[">"],"ru":[">"]},"explanation":{"en":"> means \"greater than\": if (x > 10).","ru":"> означает «больше»: if (x > 10)."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"> means \"greater than\": if (x > 10).","ru":"> означает «больше»: if (x > 10)."}'::jsonb),
  ('tech.python.l1.p1', 'tech.python.l1', 'single', '{"id":"tech.python.l1.p1","type":"single","prompt":{"en":"What does the third line print?","ru":"Что выведет третья строка?"},"visual":{"kind":"code","code":"name = \"Bruno\"\nage = 12\nprint(\"Hi,\", name)"},"options":[{"en":"Hi, Bruno","ru":"Hi, Bruno"},{"en":"Hi, name","ru":"Hi, name"},{"en":"\"Hi,\" name","ru":"\"Hi,\" name"}],"answer":0,"hint":{"en":"name without quotes is a variable - Python uses its value.","ru":"name без кавычек - это переменная, Python подставит её значение."},"explanation":{"en":"print joins its arguments with a space: Hi, Bruno.","ru":"print соединяет аргументы пробелом: Hi, Bruno."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"print joins its arguments with a space: Hi, Bruno.","ru":"print соединяет аргументы пробелом: Hi, Bruno."}'::jsonb),
  ('tech.python.l1.p2', 'tech.python.l1', 'number_input', '{"id":"tech.python.l1.p2","type":"number_input","prompt":{"en":"What number does this print?","ru":"Какое число выведет программа?"},"visual":{"kind":"code","code":"x = 7\nx = x * 2 - 4\nprint(x)"},"answer":10,"hint":{"en":"Multiplication comes before subtraction.","ru":"Умножение выполняется раньше вычитания."},"explanation":{"en":"7 × 2 = 14, and 14 - 4 = 10.","ru":"7 × 2 = 14, а 14 - 4 = 10."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"7 × 2 = 14, and 14 - 4 = 10.","ru":"7 × 2 = 14, а 14 - 4 = 10."}'::jsonb),
  ('tech.python.l1.p3', 'tech.python.l1', 'true_false', '{"id":"tech.python.l1.p3","type":"true_false","prompt":{"en":"In Python, indentation shows which lines belong to an if block.","ru":"В Python отступы показывают, какие строки входят в блок if."},"answer":true,"hint":{"en":"Python has no curly braces { } for blocks.","ru":"В Python нет фигурных скобок { } для блоков."},"explanation":{"en":"Yes - lines indented under if belong to it.","ru":"Да - строки с отступом под if относятся к нему."},"difficulty":4,"role":"practice"}'::jsonb, 4, '{"en":"Yes - lines indented under if belong to it.","ru":"Да - строки с отступом под if относятся к нему."}'::jsonb),
  ('tech.python.l1.c1', 'tech.python.l1', 'number_input', '{"id":"tech.python.l1.c1","type":"number_input","prompt":{"en":"How many times is \"hi\" printed?","ru":"Сколько раз будет напечатано \"hi\"?"},"visual":{"kind":"code","code":"for i in range(3):\n    print(\"hi\")"},"answer":3,"explanation":{"en":"range(3) gives 0, 1, 2 - three times.","ru":"range(3) даёт 0, 1, 2 - три раза."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"range(3) gives 0, 1, 2 - three times.","ru":"range(3) даёт 0, 1, 2 - три раза."}'::jsonb),
  ('tech.python.l1.c2', 'tech.python.l1', 'number_input', '{"id":"tech.python.l1.c2","type":"number_input","prompt":{"en":"What number does this print?","ru":"Какое число выведет программа?"},"visual":{"kind":"code","code":"total = 0\nfor n in range(1, 6):\n    total = total + n\nprint(total)"},"answer":15,"explanation":{"en":"range(1, 6) is 1, 2, 3, 4, 5, and their sum is 15.","ru":"range(1, 6) - это 1, 2, 3, 4, 5, их сумма равна 15."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"range(1, 6) is 1, 2, 3, 4, 5, and their sum is 15.","ru":"range(1, 6) - это 1, 2, 3, 4, 5, их сумма равна 15."}'::jsonb),
  ('tech.python.l1.c3', 'tech.python.l1', 'single', '{"id":"tech.python.l1.c3","type":"single","prompt":{"en":"What does this program print?","ru":"Что выведет эта программа?"},"visual":{"kind":"code","code":"temp = 25\nif temp > 30:\n    print(\"Hot\")\nelif temp > 20:\n    print(\"Warm\")\nelse:\n    print(\"Cold\")"},"options":[{"en":"Hot","ru":"Hot"},{"en":"Warm","ru":"Warm"},{"en":"Cold","ru":"Cold"}],"answer":1,"explanation":{"en":"25 > 30 is false, 25 > 20 is true, so \"Warm\" is printed.","ru":"25 > 30 - ложь, 25 > 20 - истина, поэтому выводится \"Warm\"."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"25 > 30 is false, 25 > 20 is true, so \"Warm\" is printed.","ru":"25 > 30 - ложь, 25 > 20 - истина, поэтому выводится \"Warm\"."}'::jsonb),
  ('tech.python.l1.c4', 'tech.python.l1', 'matching', '{"id":"tech.python.l1.c4","type":"matching","prompt":{"en":"Match each piece of Python with what it does.","ru":"Соедини элемент Python с тем, что он делает."},"pairs":[{"left":{"en":"print()","ru":"print()"},"right":{"en":"Shows text on the screen","ru":"Выводит текст на экран"}},{"left":{"en":"len(\"cat\")","ru":"len(\"cat\")"},"right":{"en":"Counts characters: 3","ru":"Считает символы: 3"}},{"left":{"en":"input()","ru":"input()"},"right":{"en":"Reads text the user types","ru":"Читает текст, который вводит пользователь"}},{"left":{"en":"#","ru":"#"},"right":{"en":"Starts a comment","ru":"Начинает комментарий"}}],"explanation":{"en":"These are some of the first tools every Python coder learns.","ru":"Это одни из первых инструментов, которые осваивает каждый программист на Python."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"These are some of the first tools every Python coder learns.","ru":"Это одни из первых инструментов, которые осваивает каждый программист на Python."}'::jsonb),
  ('tech.python.l1.c5', 'tech.python.l1', 'fill_blank', '{"id":"tech.python.l1.c5","type":"fill_blank","prompt":{"en":"Write the missing function name.","ru":"Впиши пропущенное имя функции."},"text":{"en":"___(\"Hello!\")  # shows Hello! on the screen","ru":"___(\"Hello!\")  # выводит Hello! на экран"},"accepted":{"en":["print"],"ru":["print"]},"explanation":{"en":"print(\"Hello!\") shows Hello! on the screen.","ru":"print(\"Hello!\") выводит Hello! на экран."},"difficulty":4,"role":"check"}'::jsonb, 4, '{"en":"print(\"Hello!\") shows Hello! on the screen.","ru":"print(\"Hello!\") выводит Hello! на экран."}'::jsonb)
